namespace HeroEngine {





    export function __getHeroVisualInfo(hero: Sprite, nx: number, ny: number): number[] {

        const innerR = getStrengthInnerRadiusForHero(hero)

        const lead = findHeroLeadingEdgeDistance(hero, nx, ny)

        return [innerR, lead, 0, 0]

    }







    // Block-safe function type for student logic

    export type HeroLogicFn = (

        button: string,

        heroIndex: number,

        enemiesArr: any[],

        heroesArr: any[]

    ) => number[];





    export type HeroAnimFn = (

        hero: Sprite,

        animKey: string,

        timeMs: number,

        direction: string

    ) => void;





    function defaultHeroLogic(

        button: string,

        heroIndex: number,

        enemiesArr: any[],

        heroesArr: any[]

    ): number[] {

        return [FAMILY.STRENGTH, 0, 0, 0, 0, ELEM.NONE, ANIM.ID.IDLE];

    }





    function defaultHeroAnim(
        hero: Sprite,
        animKey: string,
        timeMs: number,
        direction: string
    ): void {
        // Phaser handles hero visuals; keep a no-op default to avoid Arcade placeholders.
    }







    // Blockly-only logic (profile-driven). Legacy hero1..4 hooks removed.

    export type HeroAnimByProfileHook = (
        profile: string,
        hero: Sprite,
        animKey: string,
        timeMs: number,
        direction: string
    ) => void;

    export let animateHeroByProfileHook: HeroAnimByProfileHook | null = null;





    export let animateHero1Hook: HeroAnimFn = defaultHeroAnim;

    export let animateHero2Hook: HeroAnimFn = defaultHeroAnim;

    export let animateHero3Hook: HeroAnimFn = defaultHeroAnim;

    export let animateHero4Hook: HeroAnimFn = defaultHeroAnim;





    let _started = false;



    export function _isStarted(): boolean {

        return _started;

    }

    export function setPaused(flag: boolean, reason?: string): void {
        _engineSetPaused(flag, reason)
    }

    export function isPaused(): boolean {
        return _engineIsPaused()
    }



    //% blockId=heroEngine_start

    //% block="start hero engine"

    //% group="Setup"

    //% weight=100

    export function start() {

        if (_started) return;

        _started = true;



        // Legacy: clear any old canvas HUD remnants (DOM-only now)

        teamCoins = 0

        if (teamCoinsHud && !(teamCoinsHud.flags & sprites.Flag.Destroyed)) teamCoinsHud.destroy()

        teamCoinsHud = null



        ensureHeroSpriteKinds();



        initWorldTileMap()

        scene.setBackgroundColor(1);

        tiles.setCurrentTilemap(tilemap`level1`)

        setupHeroes();



        // NEW: per-hero coins start at 0 (or keep if you later want persistence)

        for (let hi = 0; hi < heroes.length; hi++) {

            const h = heroes[hi]

            if (!h || (h.flags & sprites.Flag.Destroyed)) continue

            setHeroCoins(hi, 0)

        }



        // Shop boot (single path)

        installShopInputHandlers()



        // NEW: start dungeon run

        dungeonStartRun(game.runtime() | 0)

    }

}





