function _heroSpellEffectOffsetFor(
    skinId: string,
    dir: string,
    family: number,
    moveType?: string
): HeroEffectOffset {
    let x = 0;
    let y = 0;
    const add = (o?: HeroEffectOffset) => {
        if (!o) return;
        x = (x + (o.x | 0)) | 0;
        y = (y + (o.y | 0)) | 0;
    };
    if ((family | 0) === (FAMILY.STRENGTH | 0)) add(HERO_SPELL_EFFECT_DEFAULT_OFFSETS.strength);
    else if ((family | 0) === (FAMILY.AGILITY | 0)) add(HERO_SPELL_EFFECT_DEFAULT_OFFSETS.agility);
    else if ((family | 0) === (FAMILY.INTELLECT | 0)) add(HERO_SPELL_EFFECT_DEFAULT_OFFSETS.intellect);

    const def = HERO_SPELL_EFFECT_OFFSETS[skinId];
    if (!def) return { x, y };
    const d = (dir || "").toLowerCase() as "up" | "down" | "left" | "right";
    const mv = (moveType || "").trim();

    add(def.base);
    if ((family | 0) === (FAMILY.STRENGTH | 0)) add(def.strength);
    else if ((family | 0) === (FAMILY.AGILITY | 0)) add(def.agility);
    else if ((family | 0) === (FAMILY.INTELLECT | 0)) add(def.intellect);

    if (mv && def.move && def.move[mv]) add(def.move[mv]);
    if (d && def.dir && def.dir[d]) add(def.dir[d]);
    if (mv && d && def.moveDir && def.moveDir[mv] && def.moveDir[mv]![d]) {
        add(def.moveDir[mv]![d]);
    }
    return { x, y };
}

function _heroElementFromRenderStyle(hero: Sprite): number {
    if (!hero) return ELEM.NONE;
    const mask = sprites.readDataNumber(hero, HERO_DATA.RenderStyleMask) | 0;
    if (!mask) return ELEM.NONE;
    for (let e = 1; e <= (ELEM_MAX | 0); e++) {
        if (mask & (1 << e)) return e;
    }
    return ELEM.NONE;
}

function _heroSpellEffectPick(
    element: number,
    dir: string,
    mode?: HeroElementEffectMode
): { skinId: string; dir?: string } | null {
    let cfg: HeroElementEffectConfig | null = null;
    if (mode === "defense") {
        cfg =
            HERO_SPELL_ELEMENT_DEFENSE_EFFECTS[element] ||
            HERO_SPELL_ELEMENT_OFFENSE_EFFECTS[element] ||
            HERO_SPELL_ELEMENT_DEFENSE_EFFECTS[ELEM.NONE] ||
            HERO_SPELL_ELEMENT_OFFENSE_EFFECTS[ELEM.NONE] ||
            null;
    } else {
        cfg =
            HERO_SPELL_ELEMENT_OFFENSE_EFFECTS[element] ||
            HERO_SPELL_ELEMENT_OFFENSE_EFFECTS[ELEM.NONE] ||
            null;
    }
    if (!cfg) return null;
    const d = (dir || "down").toLowerCase();
    if (cfg.dirIds) {
        const pick = (cfg.dirIds as any)[d] || cfg.dirIds.down || cfg.dirIds.up || "";
        if (!pick) return null;
        return { skinId: pick };
    }
    if (!cfg.baseId) return null;
    if (cfg.useDir) return { skinId: cfg.baseId, dir: d };
    return { skinId: cfg.baseId };
}

function _applyHeroSpellElementEffect(
    spell: Sprite,
    element: number,
    dir: string,
    mode?: HeroElementEffectMode
): boolean {
    if (!spell || (spell.flags & sprites.Flag.Destroyed)) return false;
    const pick = _heroSpellEffectPick(element | 0, dir || "", mode);
    if (!pick || !pick.skinId) return false;
    const curSkin = sprites.readDataString(spell, "effectSkin") || "";
    const curDir = sprites.readDataString(spell, "effectDir") || "";
    const nextDir = pick.dir || "";
    if (curSkin === pick.skinId && curDir === nextDir) return true;
    if (!pick.dir && curDir) sprites.setDataString(spell, "effectDir", "");
    const fitRadius = sprites.readDataNumber(spell, INT_RADIUS_KEY) | 0;
    const opts: EffectApplyOpts = { mode: "full" };
    if (fitRadius > 0) opts.fitRadiusPx = fitRadius | 0;
    if (pick.dir) applyEffectToSprite(spell, pick.skinId, { ...opts, dir: pick.dir });
    else applyEffectToSprite(spell, pick.skinId, opts);
    return true;
}

function _heroBodyEffectElement(hero: Sprite, element: number): number {
    if ((element | 0) > 0) return element | 0;
    const fromStyle = _heroElementFromRenderStyle(hero) | 0;
    return (fromStyle > 0) ? fromStyle : (element | 0);
}

function _heroBodyFxAlphaForFamily(family: number): number {
    if ((family | 0) === (FAMILY.AGILITY | 0)) return HERO_BODY_FX_ALPHA_AGILITY;
    return HERO_BODY_FX_ALPHA_DEFAULT;
}

function _heroBodyFxBlendForFamily(family: number): string {
    if ((family | 0) === (FAMILY.AGILITY | 0)) return HERO_BODY_FX_BLEND_AGILITY;
    return HERO_BODY_FX_BLEND_DEFAULT;
}

function _heroBodyFxZBiasForFamily(family: number): number {
    if ((family | 0) === (FAMILY.AGILITY | 0)) return HERO_BODY_FX_Z_BIAS_AGILITY;
    return HERO_BODY_FX_Z_BIAS_DEFAULT;
}

let __effectDummyImage: Image | null = null;
function _getEffectDummyImage(): Image {
    if (!__effectDummyImage) {
        const img = image.create(1, 1);
        img.fill(0);
        __effectDummyImage = img;
    }
    return __effectDummyImage!;
}

function _heroBodyFxMaskRadiusForHero(hero: Sprite): number {
    if (!hero || (hero.flags & sprites.Flag.Destroyed)) return 0;
    let r = HERO_BODY_FX_MASK_RADIUS | 0;
    if (r < 0) {
        const auraR = sprites.readDataNumber(hero, HERO_DATA.AURA_RADIUS);
        if (Number.isFinite(auraR)) r = auraR | 0;
        else r = AURA_RADIUS_NEUTRAL | 0;
    }
    if (r < 0) r = 0;
    return r | 0;
}

function _agiThrustOffsets(nx: number, ny: number): { ox: number; oy: number } {
    const dir = _enemyDirFromVector(nx, ny);
    switch (dir) {
        case "left":
        case "right":
            return { ox: 0, oy: AGI_THRUST_OFFS_Y_SIDE };
        case "up":
            return { ox: AGI_THRUST_OFFS_X_UP, oy: 0 };
        case "down":
            return { ox: AGI_THRUST_OFFS_X_DOWN, oy: 0 };
        default:
            return { ox: 0, oy: 0 };
    }
}

function _spawnHeroBodyPaintFxForMove(
    heroIndex: number,
    hero: Sprite,
    family: number,
    element: number,
    nx: number,
    ny: number,
    lifespanMs: number,
    moveType?: string
): Sprite | null {
    if (AGI_DISABLE_LEGACY_AGI_TRAIL_FX && ((family | 0) === (FAMILY.AGILITY | 0))) return null;
    if (!ENABLE_HERO_BODY_FX) return null;
    if (!hero || (hero.flags & sprites.Flag.Destroyed)) return null;
    const dir = _enemyDirFromVector(nx, ny);
    const elem = _heroBodyEffectElement(hero, element | 0);
    const pick = _heroSpellEffectPick(elem | 0, dir, "offense");
    if (!pick || !pick.skinId) return null;
    const frameWindowMs =
        ((family | 0) === (FAMILY.AGILITY | 0) && (lifespanMs | 0) > 0)
            ? (lifespanMs | 0)
            : 0;
    const offset = _heroSpellEffectOffsetFor(pick.skinId, pick.dir || dir, family | 0, moveType || "");

    const fx = sprites.create(_getEffectDummyImage(), SpriteKind.HeroEffect);
    fx.setFlag(SpriteFlag.Ghost, true);
    fx.x = hero.x;
    fx.y = hero.y;
    fx.z = (hero.z | 0) + (_heroBodyFxZBiasForFamily(family) | 0);
    if ((lifespanMs | 0) > 0) fx.lifespan = lifespanMs | 0;

    sprites.setDataNumber(fx, PROJ_DATA.HERO_INDEX, heroIndex | 0);
    sprites.setDataNumber(fx, PROJ_DATA.FAMILY, family | 0);
    sprites.setDataNumber(fx, EFFECT_MASK_INVERT_DATA_KEY, HERO_BODY_FX_MASK_INVERT ? 1 : 0);
    sprites.setDataNumber(fx, EFFECT_MASK_RADIUS_DATA_KEY, _heroBodyFxMaskRadiusForHero(hero));
    sprites.setDataNumber(fx, EFFECT_MASK_RADIUS_PX_DATA_KEY, HERO_BODY_FX_MASK_RADIUS_PX | 0);
    sprites.setDataSprite(fx, EFFECT_HERO_REF_DATA_KEY, hero);

    const alpha = _heroBodyFxAlphaForFamily(family);
    const blend = _heroBodyFxBlendForFamily(family);

    if (pick.dir) {
        applyEffectToSprite(fx, pick.skinId, {
            dir: pick.dir,
            mode: HERO_BODY_FX_MODE,
            alpha,
            blend,
            forceTop: HERO_BODY_FX_FORCE_TOP,
            frameWindowMs,
            offsetX: offset.x,
            offsetY: offset.y
        });
    } else {
        applyEffectToSprite(fx, pick.skinId, {
            mode: HERO_BODY_FX_MODE,
            alpha,
            blend,
            forceTop: HERO_BODY_FX_FORCE_TOP,
            frameWindowMs,
            offsetX: offset.x,
            offsetY: offset.y
        });
    }
    if (DEBUG_EFFECT_MASKS) {
        try {
            const fxId = (fx as any).id | 0;
            if (!__effectMaskSpawnOnce.has(fxId)) {
                __effectMaskSpawnOnce.add(fxId);
                const auraR = sprites.readDataNumber(hero, HERO_DATA.AURA_RADIUS) | 0;
                const maskR = _heroBodyFxMaskRadiusForHero(hero) | 0;
                console.log(
                    "[EFFECT][MASK][HERO]" +
                    " fx=" + (fxId | 0) +
                    " hero=" + (heroIndex | 0) +
                    " family=" + (family | 0) +
                    " elem=" + (elem | 0) +
                    " skin=" + pick.skinId +
                    " dir=" + (pick.dir || "") +
                    " mode=" + HERO_BODY_FX_MODE +
                    " maskR=" + (maskR | 0) +
                    " maskRpx=" + (HERO_BODY_FX_MASK_RADIUS_PX | 0) +
                    " auraR=" + (auraR | 0)
                );
            }
        } catch { /* ignore */ }
    }
    return fx;
}

function _updateHeroBodyPaintFxForProj(proj: Sprite, hero: Sprite): void {
    if (!proj || !hero) return;
    const fx = sprites.readDataSprite(proj, HERO_BODY_FX_KEY);
    if (!fx || (fx.flags & sprites.Flag.Destroyed)) return;
    fx.x = hero.x;
    fx.y = hero.y;
    const family = sprites.readDataNumber(fx, PROJ_DATA.FAMILY) | 0;
    fx.z = (hero.z | 0) + (_heroBodyFxZBiasForFamily(family) | 0);
}

function _destroyHeroBodyPaintFxForProj(proj: Sprite): void {
    if (!proj) return;
    const fx = sprites.readDataSprite(proj, HERO_BODY_FX_KEY);
    if (fx && !(fx.flags & sprites.Flag.Destroyed)) {
        fx.destroy();
    }
    sprites.setDataSprite(proj, HERO_BODY_FX_KEY, null as any);
}

function _projectileMaskFitRadiusPx(proj: Sprite, hero?: Sprite): number {
    let w = (proj.width | 0);
    let h = (proj.height | 0);
    if ((w | 0) <= 0 || (h | 0) <= 0) {
        try {
            const img = (proj as any).image;
            if (img) {
                w = (img.width | 0);
                h = (img.height | 0);
            }
        } catch { /* ignore */ }
    }
    if ((w | 0) <= 0 || (h | 0) <= 0) {
        if (hero) {
            w = (hero.width | 0);
            h = (hero.height | 0);
        }
    }
    const maxDim = Math.max(w | 0, h | 0);
    if (maxDim <= 0) return 1;
    return Math.max(1, Math.idiv(maxDim, 2) | 0);
}

function _ensureProjectileMaskSprite(proj: Sprite, img: Image): Sprite | null {
    if (!proj || !img) return null;
    let mask = sprites.readDataSprite(proj, PROJ_MASK_SPRITE_KEY);
    if (!mask || (mask.flags & sprites.Flag.Destroyed)) {
        mask = sprites.create(img.clone(), SpriteKind.HeroWeaponMask);
        mask.setFlag(SpriteFlag.Ghost, true);
        mask.setFlag(SpriteFlag.Invisible, true);
        mask.z = (proj.z | 0) - 1;
        sprites.setDataSprite(proj, PROJ_MASK_SPRITE_KEY, mask);
    }
    return mask;
}

function _updateProjectileMaskSpriteForProj(proj: Sprite, img: Image): void {
    if (!proj || !img) return;
    const mask = _ensureProjectileMaskSprite(proj, img);
    if (!mask) return;
    mask.setImage(img.clone());
    mask.x = proj.x;
    mask.y = proj.y;
    mask.z = (proj.z | 0) - 1;
    mask.setFlag(SpriteFlag.Ghost, true);
    mask.setFlag(SpriteFlag.Invisible, true);
}

function _destroyProjectileMaskSpriteForProj(proj: Sprite): void {
    if (!proj) return;
    const mask = sprites.readDataSprite(proj, PROJ_MASK_SPRITE_KEY);
    if (mask && !(mask.flags & sprites.Flag.Destroyed)) {
        mask.destroy();
    }
    sprites.setDataSprite(proj, PROJ_MASK_SPRITE_KEY, null as any);
}

function _spawnProjectileMaskFxForMove(
    proj: Sprite,
    heroIndex: number,
    hero: Sprite,
    family: number,
    element: number,
    nx: number,
    ny: number,
    lifespanMs: number,
    moveType?: string
): Sprite | null {
    if (AGI_DISABLE_LEGACY_AGI_TRAIL_FX && ((family | 0) === (FAMILY.AGILITY | 0))) return null;
    if (!proj || !hero) return null;
    if (proj.flags & sprites.Flag.Destroyed) return null;
    const dir = _enemyDirFromVector(nx, ny);
    const elem = _heroBodyEffectElement(hero, element | 0);
    const pick = _heroSpellEffectPick(elem | 0, dir, "offense");
    if (!pick || !pick.skinId) return null;

    const offset = _heroSpellEffectOffsetFor(pick.skinId, pick.dir || dir, family | 0, moveType || "");
    const fitRadius = _projectileMaskFitRadiusPx(proj, hero);
    const scale = _effectPickScaleForRadius(pick.skinId, pick.dir || dir, fitRadius | 0);

    const fx = sprites.create(_getEffectDummyImage(), SpriteKind.HeroEffect);
    fx.setFlag(SpriteFlag.Ghost, true);
    fx.x = proj.x;
    fx.y = proj.y;
    fx.z = (proj.z | 0) + (PROJ_MASK_FX_Z_BIAS | 0);
    if ((lifespanMs | 0) > 0) fx.lifespan = lifespanMs | 0;

    sprites.setDataNumber(fx, PROJ_DATA.HERO_INDEX, heroIndex | 0);
    sprites.setDataNumber(fx, PROJ_DATA.FAMILY, family | 0);
    sprites.setDataNumber(fx, PROJ_MASK_FX_FIT_RADIUS_KEY, fitRadius | 0);

    const maskSprite = _ensureProjectileMaskSprite(proj, proj.image as any);
    const opts: EffectApplyOpts = {
        mode: PROJ_MASK_FX_MODE,
        alpha: PROJ_MASK_FX_ALPHA,
        blend: PROJ_MASK_FX_BLEND,
        repeat: PROJ_MASK_FX_REPEAT,
        forceTop: PROJ_MASK_FX_FORCE_TOP,
        scale,
        offsetX: offset.x,
        offsetY: offset.y,
        maskSprite: maskSprite || proj
    };
    if (pick.dir) opts.dir = pick.dir;
    applyEffectToSprite(fx, pick.skinId, opts);
    sprites.setDataSprite(proj, PROJ_MASK_FX_KEY, fx);

    if (DEBUG_EFFECT_MASKS) {
        try {
            const fxId = (fx as any).id | 0;
            const projId = (proj as any).id | 0;
            const maskSpriteId = (maskSprite ? (maskSprite as any).id : (proj as any).id) | 0;
            console.log(
                "[EFFECT][MASK][PROJ]" +
                " fx=" + (fxId | 0) +
                " proj=" + (projId | 0) +
                " hero=" + (heroIndex | 0) +
                " family=" + (family | 0) +
                " elem=" + (elem | 0) +
                " skin=" + pick.skinId +
                " dir=" + (pick.dir || "") +
                " mode=" + PROJ_MASK_FX_MODE +
                " maskSprite=" + (maskSpriteId | 0) +
                " fitR=" + (fitRadius | 0)
            );
        } catch { /* ignore */ }
    }

    return fx;
}

function _updateProjectileMaskFxForProj(proj: Sprite, hero?: Sprite): void {
    if (!proj) return;
    const fx = sprites.readDataSprite(proj, PROJ_MASK_FX_KEY);
    if (!fx || (fx.flags & sprites.Flag.Destroyed)) return;
    fx.x = proj.x;
    fx.y = proj.y;
    fx.z = (proj.z | 0) + (PROJ_MASK_FX_Z_BIAS | 0);
    fx.setFlag(SpriteFlag.Invisible, !!(proj.flags & sprites.Flag.Invisible));

    const fitRadius = _projectileMaskFitRadiusPx(proj, hero);
    const lastFit = sprites.readDataNumber(fx, PROJ_MASK_FX_FIT_RADIUS_KEY) | 0;
    if ((fitRadius | 0) > 0 && (fitRadius | 0) !== (lastFit | 0)) {
        const skinId = sprites.readDataString(fx, "effectSkin") || "";
        if (skinId) {
            const dir = sprites.readDataString(fx, "effectDir") || "";
            const scale = _effectPickScaleForRadius(skinId, dir, fitRadius | 0);
            sprites.setDataNumber(fx, EFFECT_SCALE_DATA_KEY, scale);
            sprites.setDataNumber(fx, PROJ_MASK_FX_FIT_RADIUS_KEY, fitRadius | 0);
        }
    }
}

function _destroyProjectileMaskFxForProj(proj: Sprite): void {
    if (!proj) return;
    const fx = sprites.readDataSprite(proj, PROJ_MASK_FX_KEY);
    if (fx && !(fx.flags & sprites.Flag.Destroyed)) {
        fx.destroy();
    }
    sprites.setDataSprite(proj, PROJ_MASK_FX_KEY, null as any);
}

function _strengthSwingFxSegKey(i: number): string {
    return STR_FX_SEG_BASE_KEY + (i | 0);
}

function _strengthSwingFxSegmentCount(totalArcDeg: number, outerR: number): number {
    const arcDegAbs = Math.abs(totalArcDeg | 0);
    const arcRad = arcDegAbs * (Math.PI / 180);
    const arcLen = Math.max(1, Math.round(Math.max(1, outerR | 0) * arcRad));
    const spacing = Math.max(8, STR_FX_SEG_SPACING_PX | 0);
    let count = Math.ceil(arcLen / spacing);
    const minByArc = Math.round((arcDegAbs / 180) * STR_FX_SEG_MIN);
    if (minByArc > count) count = minByArc;
    if (!Number.isFinite(count) || count <= 0) count = STR_FX_SEG_MIN;
    if (count < STR_FX_SEG_MIN) count = STR_FX_SEG_MIN;
    if (count > STR_FX_SEG_MAX) count = STR_FX_SEG_MAX;
    if (count % 2 !== 0) count += 1;
    if (count > STR_FX_SEG_MAX) count = STR_FX_SEG_MAX;
    return count | 0;
}

function _strengthFxUpdateDir(fx: Sprite, dir: string): void {
    if (!fx || (fx.flags & sprites.Flag.Destroyed)) return;
    const d = (dir || "").trim();
    if (!d) return;
    const cur = sprites.readDataString(fx, "effectDir") || "";
    if (cur !== d) sprites.setDataString(fx, "effectDir", d);
}

function _spawnStrengthSwingFxSegments(
    proj: Sprite,
    heroIndex: number,
    hero: Sprite,
    element: number,
    nx: number,
    ny: number,
    inner0: number,
    reachFromFront: number,
    totalArcDeg: number,
    swingDurationMs: number
): void {
    if (!proj || !hero) return;
    if (!ENABLE_STR_FX_SEGMENTS) {
        _destroyStrengthSwingFxSegments(proj);
        if (STR_FX_HIDE_BASE_PROJECTILE) proj.setFlag(SpriteFlag.Invisible, true);
        return;
    }
    const dir = _enemyDirFromVector(nx, ny);
    const elem = _heroBodyEffectElement(hero, element | 0);
    const pick = _heroSpellEffectPick(elem | 0, dir, "offense");
    if (!pick || !pick.skinId) return;

    const maskSprite = _ensureProjectileMaskSprite(proj, proj.image as any);
    const baseSkin = pick.skinId;
    const sizedSkin = _effectSkinIdWithSize(baseSkin, WEAPON_TILE_FX_SIZE_PX | 0, pick.dir || dir);
    const offset = _heroSpellEffectOffsetFor(baseSkin, pick.dir || dir, FAMILY.STRENGTH | 0, "strengthTrail");

    const outerR = (inner0 | 0) + (reachFromFront | 0);
    const segCount = _strengthSwingFxSegmentCount(totalArcDeg | 0, outerR | 0);
    if (segCount <= 0) return;

    for (let i = 0; i < segCount; i++) {
        const fx = sprites.create(_getEffectDummyImage(), SpriteKind.HeroEffect);
        fx.setFlag(SpriteFlag.Ghost, true);
        fx.x = hero.x;
        fx.y = hero.y;
        fx.z = (hero.z | 0) + (STR_FX_SEG_Z_BIAS | 0);
        if ((swingDurationMs | 0) > 0) fx.lifespan = swingDurationMs | 0;

        sprites.setDataNumber(fx, PROJ_DATA.HERO_INDEX, heroIndex | 0);
        sprites.setDataNumber(fx, PROJ_DATA.FAMILY, FAMILY.STRENGTH | 0);

        const opts: EffectApplyOpts = {
            mode: "projectile",
            alpha: STR_FX_SEG_ALPHA,
            blend: STR_FX_SEG_BLEND,
            repeat: -1,
            offsetX: offset.x,
            offsetY: offset.y,
            maskPadOutPx: WEAPON_TILE_FX_MASK_OUT_PX,
            maskSprite: maskSprite || proj,
            flipX: WEAPON_TILE_FX_MIRROR && ((i % 2) === 1) && (Math.abs(nx) >= Math.abs(ny)),
            flipY: WEAPON_TILE_FX_MIRROR && ((i % 2) === 1) && (Math.abs(ny) > Math.abs(nx))
        };
        if (pick.dir) opts.dir = pick.dir;
        applyEffectToSprite(fx, sizedSkin, opts);
        sprites.setDataSprite(proj, _strengthSwingFxSegKey(i), fx);
    }

    sprites.setDataNumber(proj, STR_FX_SEG_COUNT_KEY, segCount | 0);
    if (STR_FX_HIDE_BASE_PROJECTILE) proj.setFlag(SpriteFlag.Invisible, true);
}

function _destroyStrengthSwingFxSegments(proj: Sprite): void {
    if (!proj) return;
    const count = sprites.readDataNumber(proj, STR_FX_SEG_COUNT_KEY) | 0;
    for (let i = 0; i < count; i++) {
        const fx = sprites.readDataSprite(proj, _strengthSwingFxSegKey(i));
        if (fx && !(fx.flags & sprites.Flag.Destroyed)) fx.destroy();
        sprites.setDataSprite(proj, _strengthSwingFxSegKey(i), null as any);
    }
    sprites.setDataNumber(proj, STR_FX_SEG_COUNT_KEY, 0);
}

function _destroyStrengthArcFxForProj(proj: Sprite): void {
    if (!proj) return;
    const keys = [
        STR_ARC_MASK_FX_KEY,
        STR_ARC_FILL_FX_KEY,
        STR_ARC_OUTLINE_FX_KEY,
        STR_ARC_SOFT_HALO_FX_KEY,
        STR_ARC_EDGE_FX_KEY,
        STR_ARC_EDGE_AURA_FX_KEY,
        STR_ARC_AURA_R1_FX_KEY,
        STR_ARC_AURA_R2_FX_KEY,
        STR_ARC_AURA_R3_FX_KEY
    ];
    for (const key of keys) {
        const fx = sprites.readDataSprite(proj, key);
        if (fx && !(fx.flags & sprites.Flag.Destroyed)) fx.destroy();
        sprites.setDataSprite(proj, key, null as any);
    }
    _destroyStrengthArcTrailsForProj(proj);
    sprites.setDataSprite(proj, PROJ_COLLIDER_SPRITE_KEY, null as any);
}

function _spawnStrengthArcFxForProj(
    proj: Sprite,
    heroIndex: number,
    hero: Sprite,
    element: number,
    nx: number,
    ny: number,
    lifespanMs: number
): void {
    if (!proj || !hero) return;
    _destroyStrengthArcFxForProj(proj);

    const zBase = (hero.z | 0) + 12;
    const showFill = !DEBUG_STR_ARC_NO_FILL;
    const dir = _enemyDirFromVector(nx, ny) || "down";
    const auraIdxR1 = (sprites.readDataNumber(proj, WPN_AURA_COL_R1_KEY) | 0) || 1;
    const auraIdxR2 = (sprites.readDataNumber(proj, WPN_AURA_COL_R2_KEY) | 0) || auraIdxR1;
    const auraIdxR3 = (sprites.readDataNumber(proj, WPN_AURA_COL_R3_KEY) | 0) || auraIdxR2;
    const highlight = _strengthArcHighlightTints(element | 0, auraIdxR1, auraIdxR2, auraIdxR3);
    const fillTint = 0;
    let fillSkinId = "";
    let fillDir = "";
    let edgeSkinId = "";
    let edgeDir = "";
    let edgeAuraSkinId = "";
    const auraSkinIds: string[] = [];
    const maskFx = sprites.create(_getEffectDummyImage(), SpriteKind.HeroEffect);
    maskFx.setFlag(SpriteFlag.Ghost, true);
    // Hide the mask only when a fill will render through it.
    maskFx.setFlag(SpriteFlag.Invisible, showFill);
    maskFx.x = hero.x;
    maskFx.y = hero.y;
    maskFx.z = zBase;
    if ((lifespanMs | 0) > 0) maskFx.lifespan = lifespanMs | 0;

    applyEffectToSprite(maskFx, STR_ARC_SKIN_ID, { mode: "full", repeat: -1, frameIndex: 0, alpha: STR_ARC_FILL_ALPHA });
    sprites.setDataSprite(proj, STR_ARC_MASK_FX_KEY, maskFx);
    sprites.setDataSprite(proj, PROJ_COLLIDER_SPRITE_KEY, maskFx);
    sprites.setDataNumber(proj, PROJ_COLLIDER_SCALE_X1000_KEY, STR_ARC_COLLIDER_SCALE_X1000 | 0);

    if (showFill) {
        const ellipseFillPick = _strengthArcEllipseTexturePick(element | 0, dir || "down");
        if (ellipseFillPick && ellipseFillPick.skinId) {
            fillSkinId = ellipseFillPick.skinId;
            fillDir = ellipseFillPick.dir || dir || "";
            const fillFx = sprites.create(_getEffectDummyImage(), SpriteKind.HeroEffect);
            fillFx.setFlag(SpriteFlag.Ghost, true);
            fillFx.x = hero.x;
            fillFx.y = hero.y;
            fillFx.z = zBase + 1;
            if ((lifespanMs | 0) > 0) fillFx.lifespan = lifespanMs | 0;

            const opts: EffectApplyOpts = {
                mode: "projectile",
                repeat: -1,
                frameIndex: 0,
                maskSprite: maskFx,
                alpha: STR_ARC_FILL_ALPHA
            };
            opts.dir = ellipseFillPick.dir || dir;
            applyEffectToSprite(fillFx, ellipseFillPick.skinId, opts);
            sprites.setDataNumber(fillFx, STR_ARC_FILL_ROW_KEY, -1);
            sprites.setDataSprite(proj, STR_ARC_FILL_FX_KEY, fillFx);
        }

        if (STR_ARC_SOFT_HALO_ENABLED) {
            const haloFx = sprites.create(_getEffectDummyImage(), SpriteKind.HeroEffect);
            haloFx.setFlag(SpriteFlag.Ghost, true);
            haloFx.x = hero.x;
            haloFx.y = hero.y;
            haloFx.z = zBase + (STR_ARC_SOFT_HALO_Z_OFFSET | 0);
            if ((lifespanMs | 0) > 0) haloFx.lifespan = lifespanMs | 0;
            const haloTint = _strengthArcSoftHaloTint(highlight.primary || highlight.secondary || 0);
            applyEffectToSprite(haloFx, STR_ARC_SKIN_ID, {
                mode: "full",
                repeat: -1,
                frameIndex: 0,
                tint: haloTint | 0,
                alpha: STR_ARC_SOFT_HALO_ALPHA,
                blend: STR_ARC_SOFT_HALO_BLEND
            });
            sprites.setDataNumber(haloFx, EFFECT_SCALE_DATA_KEY, _strengthArcSlashScaleCap() * STR_ARC_SOFT_HALO_SCALE);
            sprites.setDataSprite(proj, STR_ARC_SOFT_HALO_FX_KEY, haloFx);
        } else {
            sprites.setDataSprite(proj, STR_ARC_SOFT_HALO_FX_KEY, null as any);
        }

        if (!STR_ARC_EDGE_ENABLED) {
            sprites.setDataSprite(proj, STR_ARC_EDGE_FX_KEY, null as any);
            sprites.setDataSprite(proj, STR_ARC_EDGE_AURA_FX_KEY, null as any);
        }

        if (!STR_ARC_AURA_ENABLED) {
            const auraKeys = [STR_ARC_AURA_R1_FX_KEY, STR_ARC_AURA_R2_FX_KEY, STR_ARC_AURA_R3_FX_KEY];
            for (const key of auraKeys) {
                sprites.setDataSprite(proj, key, null as any);
            }
        }
    } else {
        sprites.setDataSprite(proj, STR_ARC_FILL_FX_KEY, null as any);
        sprites.setDataSprite(proj, STR_ARC_SOFT_HALO_FX_KEY, null as any);
    }

    const outlineId = STR_ARC_OUTLINE_ENABLED ? _strengthArcOutlineSkinId() : null;
    if (outlineId) {
        const outlineFx = sprites.create(_getEffectDummyImage(), SpriteKind.HeroEffect);
        outlineFx.setFlag(SpriteFlag.Ghost, true);
        outlineFx.x = hero.x;
        outlineFx.y = hero.y;
        outlineFx.z = zBase + (STR_ARC_OUTLINE_Z_OFFSET | 0);
        if ((lifespanMs | 0) > 0) outlineFx.lifespan = lifespanMs | 0;
        const outlineTint = highlight.secondary || highlight.primary;

        applyEffectToSprite(outlineFx, outlineId, {
            mode: "full",
            repeat: -1,
            frameIndex: 0,
            tint: outlineTint | 0,
            alpha: STR_ARC_OUTLINE_ALPHA
        });
        sprites.setDataSprite(proj, STR_ARC_OUTLINE_FX_KEY, outlineFx);
    } else {
        sprites.setDataSprite(proj, STR_ARC_OUTLINE_FX_KEY, null as any);
    }

    if (DEBUG_STR_PROJECTILE_METRICS) {
        const atlas = _getEffectAtlasAny();
        const atlasOn = atlas ? 1 : 0;
        const resolve = (skin: string, dirKey: string): number => {
            if (!atlas || !skin) return 0;
            return _resolveEffectEntry(atlas, skin, dirKey || "") ? 1 : 0;
        };
        const fillOk = resolve(fillSkinId, fillDir || dir || "");
        const edgeOk = resolve(edgeSkinId, edgeDir || dir || "");
        const edgeAuraOk = resolve(edgeAuraSkinId, "");
        const outlineOk = resolve(outlineId || "", "");
        const auraOkList = auraSkinIds.map((skin) => resolve(skin, ""));
        const auraList = auraSkinIds.length ? auraSkinIds.join(",") : "none";
        const auraOk = auraOkList.length ? auraOkList.join(",") : "0";
        console.log(
            "[STR][ARC][FX]" +
            " hero=" + (heroIndex | 0) +
            " elem=" + (element | 0) +
            " dir=" + (dir || "") +
            " showFill=" + (showFill ? 1 : 0) +
            " atlas=" + atlasOn +
            " mask=" + STR_ARC_SKIN_ID +
            " fill=" + (fillSkinId || "") +
            " fillDir=" + (fillDir || dir || "") +
            " fillAlpha=" + STR_ARC_FILL_ALPHA +
            " fillTint=" + (fillTint | 0) +
            " fillOk=" + fillOk +
            " edge=" + (edgeSkinId || "") +
            " edgeDir=" + (edgeDir || dir || "") +
            " edgeOk=" + edgeOk +
            " edgeAura=" + (edgeAuraSkinId || "") +
            " edgeAuraOk=" + edgeAuraOk +
            " aura=" + auraList +
            " auraOk=" + auraOk +
            " outline=" + (outlineId || "") +
            " outlineOk=" + outlineOk
        );
    }
}

function _updateStrengthArcFxForProj(
    proj: Sprite,
    hero: Sprite,
    heroIndex: number,
    nowMs: number,
    segName: string,
    frameCol: number,
    segElapsed: number,
    segDur: number,
    t: number,
    nx: number,
    ny: number,
    totalArcDeg: number,
    frontStart: number,
    reachFromFront: number
): boolean {
    if (!proj || !hero) return true;
    let maskFx = sprites.readDataSprite(proj, STR_ARC_MASK_FX_KEY);
    if (!maskFx || (maskFx.flags & sprites.Flag.Destroyed)) {
        _spawnStrengthArcFxForProj(proj, heroIndex, hero, sprites.readDataNumber(proj, PROJ_DATA.ELEMENT) | 0, nx, ny, proj.lifespan | 0);
        maskFx = sprites.readDataSprite(proj, STR_ARC_MASK_FX_KEY);
        if (!maskFx || (maskFx.flags & sprites.Flag.Destroyed)) return true;
    }

    const arcSideRaw = sprites.readDataNumber(proj, STR_ARC_SIDE_KEY) | 0;
    const arcSide = arcSideRaw === 0 ? 1 : arcSideRaw;
    const flipX = arcSide < 0;
    const anchorX = (sprites.readDataNumber(proj, PROJ_DATA.START_HERO_X) | 0) || hero.x;
    const anchorY = (sprites.readDataNumber(proj, PROJ_DATA.START_HERO_Y) | 0) || hero.y;
    const reach = Math.max(0, reachFromFront | 0);
    const ringR = Math.max(1, (frontStart | 0) + (reach | 0));
    const slashT = segName === "strengthSlash"
        ? Math.max(0, Math.min(1, (segDur | 0) > 0 ? (segElapsed / Math.max(1, segDur)) : 1))
        : 1;
    const resetT = segName === "strengthReset"
        ? Math.max(0, Math.min(1, (segDur | 0) > 0 ? (segElapsed / Math.max(1, segDur)) : 1))
        : 0;
    const sweepT = resetT;
    const isSlashSeg = segName === "strengthSlash";

    const arcAbs = Math.abs(totalArcDeg | 0);
    const halfArcRad = (arcAbs * 0.5) * (Math.PI / 180);
    const arcSign = (totalArcDeg | 0) < 0 ? -1 : 1;
    const sx = -ny;
    const sy = nx;

    let posX = anchorX;
    let posY = anchorY;
    let moveDx = nx;
    let moveDy = ny;
    let travelR = ringR;

    if (segName === "strengthReset") {
        const ang = arcSide * arcSign * halfArcRad * sweepT;
        const cosA = Math.cos(ang);
        const sinA = Math.sin(ang);
        const dxDir = (nx * cosA) + (sx * sinA);
        const dyDir = (ny * cosA) + (sy * sinA);
        posX = anchorX + dxDir * ringR;
        posY = anchorY + dyDir * ringR;
        moveDx = (-nx * sinA) + (sx * cosA);
        moveDy = (-ny * sinA) + (sy * cosA);
    } else {
        const introPx = Math.max(0, Math.min(STR_ARC_INTRO_TRAVEL_PX | 0, ((frontStart | 0) - 1) | 0));
        let travelT = slashT;
        const holdFrac = Math.max(0, Math.min(0.9, STR_ARC_INTRO_HOLD_FRAC));
        const introTravelFrac = Math.max(0, Math.min(1, STR_ARC_INTRO_TRAVEL_FRAC));
        if (holdFrac > 0) {
            if (slashT <= holdFrac) {
                const u = slashT / Math.max(0.0001, holdFrac);
                travelT = u * introTravelFrac;
            } else {
                const u = (slashT - holdFrac) / Math.max(0.0001, 1 - holdFrac);
                travelT = introTravelFrac + (u * (1 - introTravelFrac));
            }
        }
        travelT = Math.max(0, Math.min(1, travelT));
        const endR = ringR | 0;
        const baseSpan = Math.max(0, ((reach | 0) + (introPx | 0)) | 0);
        const minSpan = Math.max(0, STR_ARC_MIN_TRAVEL_PX | 0);
        let startR = 1;
        let span = 0;
        if (baseSpan < minSpan) {
            // No space to animate: pull the origin inward to the hero center.
            startR = 0;
            span = Math.max(0, endR | 0);
        } else {
            const targetSpan = Math.max(baseSpan, minSpan);
            startR = Math.max(1, (endR | 0) - targetSpan);
            span = Math.max(0, (endR | 0) - (startR | 0));
        }
        travelR = startR + Math.round(span * travelT);
        posX = anchorX + (nx * travelR);
        posY = anchorY + (ny * travelR);
        moveDx = nx;
        moveDy = ny;
    }
    const edgeRadius = isSlashSeg ? travelR : ringR;

    proj.x = posX;
    proj.y = posY;
    proj.z = (hero.z | 0) + 12;
    proj.setFlag(SpriteFlag.Invisible, true);

    const moveAngle = Math.atan2(moveDy, moveDx);
    const arcTurns = STR_ARC_BASE_TURNS_AT_360 * (arcAbs / 360);

    // Pick raw frames using your canonical #N references and sequences.
    let rawFrame = STR_ARC_SEQ_CLIMAX_RAW[0] | 0;
    if (segName === "strengthSlash") {
        rawFrame = _strengthArcPickFromSequence(STR_ARC_SEQ_WISPY_RAW, slashT, 1, false);
    } else {
        if (sweepT <= STR_ARC_MEDIUM_END_T) {
            const localT = STR_ARC_MEDIUM_END_T > 0 ? (sweepT / STR_ARC_MEDIUM_END_T) : 1;
            rawFrame = _strengthArcPickFromSequence(STR_ARC_SEQ_MEDIUM_RAW, localT, 1, false);
        } else if (sweepT >= STR_ARC_FADE_START_T) {
            const denom = Math.max(0.0001, 1 - STR_ARC_FADE_START_T);
            const localT = (sweepT - STR_ARC_FADE_START_T) / denom;
            rawFrame = _strengthArcPickFromSequence(STR_ARC_SEQ_WISPY_RAW, localT, 1, true);
        } else {
            const midSpan = Math.max(0.0001, STR_ARC_FADE_START_T - STR_ARC_MEDIUM_END_T);
            const midT = (sweepT - STR_ARC_MEDIUM_END_T) / midSpan;
            const loops = Math.max(1, Math.round(arcTurns * STR_ARC_CLIMAX_LOOPS_PER_TURN));
            rawFrame = _strengthArcPickFromSequence(STR_ARC_SEQ_CLIMAX_RAW, midT, loops, false);
        }
    }
    const spineAngle = _strengthArcSpineAngleForRaw(rawFrame, flipX, moveAngle);

    const crossStart = 0.6;
    let crossStrength = 0;
    if (segName === "strengthSlash") {
        crossStrength = Math.max(0, Math.min(1, (slashT - crossStart) / Math.max(0.0001, 1 - crossStart)));
    } else {
        const decay = 0.35;
        crossStrength = Math.max(0, Math.min(1, 1 - (resetT / Math.max(0.0001, decay))));
    }
    const crossRot = (STR_ARC_CROSS_ROT_DEG * (Math.PI / 180)) * crossStrength * (arcSide >= 0 ? 1 : -1);

    let spinRot = 0;
    if (segName === "strengthReset" && (arcAbs | 0) > 0) {
        const spinDir = arcSign * (arcSide >= 0 ? 1 : -1);
        spinRot = spinDir * arcTurns * Math.PI * 2 * sweepT;
    }

    const rot = _strengthArcNormalizeAngle(moveAngle - spineAngle + crossRot + spinRot);

    const slashScale = _strengthArcSlashScaleCap();
    const resetScale = (Math.abs(slashScale - 1) > 0.001)
        ? slashScale
        : (1 + ((STR_ARC_END_SCALE - 1) * sweepT));
    let scale = (segName === "strengthReset")
        ? resetScale
        : slashScale;

    const frameIdx = _strengthArcFrameIndexFromRaw(STR_ARC_SKIN_ID, rawFrame);
    scale = _strengthArcScaleToOpaqueCap(frameIdx | 0, scale);
    sprites.setDataNumber(maskFx, EFFECT_FRAME_INDEX_DATA_KEY, frameIdx | 0);
    sprites.setDataNumber(maskFx, EFFECT_ROT_DATA_KEY, rot);
    sprites.setDataNumber(maskFx, EFFECT_SCALE_DATA_KEY, scale);
    sprites.setDataNumber(maskFx, EFFECT_FLIP_X_DATA_KEY, flipX ? 1 : 0);
    sprites.setDataNumber(maskFx, EFFECT_ALPHA_DATA_KEY, STR_ARC_FILL_ALPHA);
    maskFx.x = posX;
    maskFx.y = posY;
    maskFx.z = (hero.z | 0) + 12;

    if (DEBUG_STR_PROJECTILE_METRICS && _wpnTraceShouldLog(proj, nowMs | 0)) {
        const atlas = _getEffectAtlasAny();
        const resolved = atlas ? _resolveEffectEntry(atlas, STR_ARC_SKIN_ID, "") : null;
        const frameW = resolved?.frameW ? (resolved.frameW | 0) : 0;
        const frameH = resolved?.frameH ? (resolved.frameH | 0) : 0;
        const bounds = (resolved && resolved.textureKey && frameW > 0 && frameH > 0)
            ? _computeTextureFrameBounds(resolved.textureKey, frameW | 0, frameH | 0, frameIdx | 0)
            : null;
        const bboxW = bounds ? (bounds.w | 0) : 0;
        const bboxH = bounds ? (bounds.h | 0) : 0;
        const capPx = Math.max(1, STR_ARC_OPAQUE_CAP_PX | 0);
        const step = Number.isFinite(STR_ARC_SCALE_STEP) ? STR_ARC_SCALE_STEP : 0;
        const scaledW = frameW > 0 ? Math.round(frameW * scale) : 0;
        const scaledH = frameH > 0 ? Math.round(frameH * scale) : 0;
        const stamp = `${frameIdx | 0}|${scale.toFixed(3)}|${frameW | 0}|${frameH | 0}|${bboxW | 0}|${bboxH | 0}|${capPx | 0}`;
        const lastStamp = sprites.readDataString(proj, STR_ARC_SIZE_LOG_KEY) || "";
        if (stamp !== lastStamp) {
            sprites.setDataString(proj, STR_ARC_SIZE_LOG_KEY, stamp);
            console.log(
                "[STR][ARC][SIZE]" +
                " hero=" + (heroIndex | 0) +
                " seg=" + segName +
                " col=" + (frameCol | 0) +
                " raw=" + (rawFrame | 0) +
                " frame=" + (frameIdx | 0) +
                " scale=" + scale.toFixed(3) +
                " slashScale=" + slashScale.toFixed(3) +
                " frameW=" + (frameW | 0) +
                " frameH=" + (frameH | 0) +
                " bboxW=" + (bboxW | 0) +
                " bboxH=" + (bboxH | 0) +
                " capPx=" + (capPx | 0) +
                " step=" + (step ? step.toFixed(3) : "0") +
                " scaledW=" + (scaledW | 0) +
                " scaledH=" + (scaledH | 0)
            );
        }
    }

    const phase = isSlashSeg ? 0 : (sweepT >= STR_ARC_FILL_END_START ? 2 : 1);
    let phaseMs = Math.max(1, segDur | 0);
    if (!isSlashSeg) {
        if (phase === 2) {
            phaseMs = Math.max(1, (segDur | 0) - Math.round((segDur | 0) * STR_ARC_FILL_END_START));
        } else {
            phaseMs = Math.max(1, Math.round((segDur | 0) * STR_ARC_FILL_END_START));
        }
    }
    const endFadeT = (!isSlashSeg && sweepT >= STR_ARC_FILL_END_START)
        ? Math.max(0, Math.min(1, (sweepT - STR_ARC_FILL_END_START) / Math.max(0.0001, 1 - STR_ARC_FILL_END_START)))
        : 0;
    const leadWeight = _strengthArcLeadWeight(slashT, endFadeT, isSlashSeg);

    let fillFx = sprites.readDataSprite(proj, STR_ARC_FILL_FX_KEY);
    if (DEBUG_STR_ARC_NO_FILL) {
        if (fillFx && !(fillFx.flags & sprites.Flag.Destroyed)) fillFx.destroy();
        sprites.setDataSprite(proj, STR_ARC_FILL_FX_KEY, null as any);
        fillFx = null as any;
        const haloFx = sprites.readDataSprite(proj, STR_ARC_SOFT_HALO_FX_KEY);
        if (haloFx && !(haloFx.flags & sprites.Flag.Destroyed)) haloFx.destroy();
        sprites.setDataSprite(proj, STR_ARC_SOFT_HALO_FX_KEY, null as any);
    }
    if (fillFx && !(fillFx.flags & sprites.Flag.Destroyed)) {
        const fillRadius = _strengthArcFillRadiusPx(scale);
        const fillRowInfo = _strengthArcEdgeRowForRadius(fillRadius | 0);
        const fillRow = fillRowInfo.row | 0;
        const lastRow = sprites.readDataNumber(fillFx, STR_ARC_FILL_ROW_KEY) | 0;
        if (fillRow !== lastRow) {
            const list = _strengthArcEdgeFrameListRaw(fillRow);
            const listCount = _strengthArcFillListCount(list);
            const baseFps = (phaseMs > 0 && listCount > 0) ? (listCount / (phaseMs / 1000)) : 30;
            const fps = Math.max(1, Math.round(baseFps * Math.max(1, STR_ARC_FILL_SPEED_MULT | 0)));
            sprites.setDataString(fillFx, EFFECT_FRAME_LIST_DATA_KEY, list);
            sprites.setDataNumber(fillFx, EFFECT_FRAME_LIST_IS_RAW_DATA_KEY, 1);
            sprites.setDataNumber(fillFx, EFFECT_FRAME_INDEX_DATA_KEY, -1);
            sprites.setDataNumber(fillFx, EFFECT_YOYO_DATA_KEY, 0);
            sprites.setDataNumber(fillFx, EFFECT_FRAME_WINDOW_MS_DATA_KEY, 0);
            sprites.setDataNumber(fillFx, EFFECT_FRAME_WINDOW_START_DATA_KEY, 0);
            sprites.setDataNumber(fillFx, EFFECT_ANIM_DELAY_MS_DATA_KEY, 0);
            sprites.setDataNumber(fillFx, EFFECT_ANIM_DELAY_START_MS_DATA_KEY, 0);
            sprites.setDataNumber(fillFx, EFFECT_FPS_DATA_KEY, fps | 0);
            sprites.setDataNumber(fillFx, EFFECT_REPEAT_DATA_KEY, 0);
            sprites.setDataNumber(fillFx, STR_ARC_FILL_ROW_KEY, fillRow | 0);
        }
        sprites.setDataNumber(fillFx, EFFECT_ROT_DATA_KEY, rot);
        sprites.setDataNumber(fillFx, EFFECT_SCALE_DATA_KEY, scale);
        sprites.setDataNumber(fillFx, EFFECT_FLIP_X_DATA_KEY, flipX ? 1 : 0);
        sprites.setDataNumber(fillFx, EFFECT_ALPHA_DATA_KEY, STR_ARC_FILL_ALPHA);
        fillFx.x = posX;
        fillFx.y = posY;
        fillFx.z = (hero.z | 0) + 13;
    }

    const element = sprites.readDataNumber(proj, PROJ_DATA.ELEMENT) | 0;
    const auraIdxR1 = (sprites.readDataNumber(proj, WPN_AURA_COL_R1_KEY) | 0) || 1;
    const auraIdxR2 = (sprites.readDataNumber(proj, WPN_AURA_COL_R2_KEY) | 0) || auraIdxR1;
    const auraIdxR3 = (sprites.readDataNumber(proj, WPN_AURA_COL_R3_KEY) | 0) || auraIdxR2;
    let highlight = _strengthArcHighlightTints(element | 0, auraIdxR1, auraIdxR2, auraIdxR3);
    const fillSkin = (fillFx && !(fillFx.flags & sprites.Flag.Destroyed))
        ? (sprites.readDataString(fillFx, "effectSkin") || "")
        : "";
    const fillSkinDir = (fillFx && !(fillFx.flags & sprites.Flag.Destroyed))
        ? (sprites.readDataString(fillFx, "effectDir") || "")
        : "";
    const fillSkinTint = fillSkin ? _effectTintForSkin(fillSkin, fillSkinDir || "") : 0;
    if (fillSkinTint) {
        highlight = { primary: fillSkinTint | 0, secondary: fillSkinTint | 0 };
    }

    _strengthArcTrailMaybeSpawn(
        proj,
        hero,
        nowMs | 0,
        isSlashSeg,
        slashT,
        frameIdx | 0,
        rot,
        scale,
        flipX,
        posX,
        posY,
        (highlight.primary || highlight.secondary || 0) | 0,
        fillSkin,
        fillSkinDir,
        fillFx
    );
    _strengthArcTrailTick(proj, nowMs | 0);

    const haloFx = sprites.readDataSprite(proj, STR_ARC_SOFT_HALO_FX_KEY);
    if (!STR_ARC_SOFT_HALO_ENABLED) {
        if (haloFx && !(haloFx.flags & sprites.Flag.Destroyed)) haloFx.destroy();
        sprites.setDataSprite(proj, STR_ARC_SOFT_HALO_FX_KEY, null as any);
    } else if (haloFx && !(haloFx.flags & sprites.Flag.Destroyed)) {
        const maskScale = sprites.readDataNumber(maskFx, EFFECT_SCALE_DATA_KEY);
        const haloScale = (Number.isFinite(maskScale) && maskScale > 0) ? maskScale : scale;
        sprites.setDataNumber(haloFx, EFFECT_FRAME_INDEX_DATA_KEY, frameIdx | 0);
        sprites.setDataNumber(haloFx, EFFECT_ROT_DATA_KEY, rot);
        sprites.setDataNumber(haloFx, EFFECT_SCALE_DATA_KEY, haloScale * STR_ARC_SOFT_HALO_SCALE);
        sprites.setDataNumber(haloFx, EFFECT_FLIP_X_DATA_KEY, flipX ? 1 : 0);
        sprites.setDataNumber(haloFx, EFFECT_ALPHA_DATA_KEY, STR_ARC_SOFT_HALO_ALPHA);
        const haloTint = _strengthArcSoftHaloTint(highlight.primary || highlight.secondary || 0);
        if (haloTint) sprites.setDataNumber(haloFx, EFFECT_TINT_DATA_KEY, haloTint | 0);
        haloFx.x = posX;
        haloFx.y = posY;
        haloFx.z = (hero.z | 0) + 12 + (STR_ARC_SOFT_HALO_Z_OFFSET | 0);
    }

    const edgeFx = sprites.readDataSprite(proj, STR_ARC_EDGE_FX_KEY);
    const edgeAuraFx = sprites.readDataSprite(proj, STR_ARC_EDGE_AURA_FX_KEY);
    if (DEBUG_STR_ARC_NO_FILL) {
        if (edgeFx && !(edgeFx.flags & sprites.Flag.Destroyed)) edgeFx.destroy();
        if (edgeAuraFx && !(edgeAuraFx.flags & sprites.Flag.Destroyed)) edgeAuraFx.destroy();
        sprites.setDataSprite(proj, STR_ARC_EDGE_FX_KEY, null as any);
        sprites.setDataSprite(proj, STR_ARC_EDGE_AURA_FX_KEY, null as any);
        const auraKeys = [STR_ARC_AURA_R1_FX_KEY, STR_ARC_AURA_R2_FX_KEY, STR_ARC_AURA_R3_FX_KEY];
        for (const key of auraKeys) {
            const auraFx = sprites.readDataSprite(proj, key);
            if (auraFx && !(auraFx.flags & sprites.Flag.Destroyed)) auraFx.destroy();
            sprites.setDataSprite(proj, key, null as any);
        }
    } else {
        if (!STR_ARC_EDGE_ENABLED) {
            if (edgeFx && !(edgeFx.flags & sprites.Flag.Destroyed)) edgeFx.destroy();
            if (edgeAuraFx && !(edgeAuraFx.flags & sprites.Flag.Destroyed)) edgeAuraFx.destroy();
            sprites.setDataSprite(proj, STR_ARC_EDGE_FX_KEY, null as any);
            sprites.setDataSprite(proj, STR_ARC_EDGE_AURA_FX_KEY, null as any);
        }
        if (!STR_ARC_AURA_ENABLED) {
            const auraKeys = [STR_ARC_AURA_R1_FX_KEY, STR_ARC_AURA_R2_FX_KEY, STR_ARC_AURA_R3_FX_KEY];
            for (const key of auraKeys) {
                const auraFx = sprites.readDataSprite(proj, key);
                if (auraFx && !(auraFx.flags & sprites.Flag.Destroyed)) auraFx.destroy();
                sprites.setDataSprite(proj, key, null as any);
            }
        }
        if (edgeFx && !(edgeFx.flags & sprites.Flag.Destroyed)) {
            const edgeRowInfo = _strengthArcEdgeRowForRadius(edgeRadius | 0);
            const edgeRow = edgeRowInfo.row | 0;
            const lastRow = sprites.readDataNumber(edgeFx, STR_ARC_EDGE_ROW_KEY) | 0;
            const lastPhase = sprites.readDataNumber(edgeFx, STR_ARC_EDGE_PHASE_KEY) | 0;
            if (edgeRow !== lastRow || phase !== lastPhase) {
                const list = _strengthArcEdgeFrameListRaw(edgeRow | 0);
                const listCount = _strengthArcFillListCount(list);
                const baseFps = (phaseMs > 0 && listCount > 0) ? (listCount / (phaseMs / 1000)) : 30;
                const fps = Math.max(1, Math.round(baseFps * STR_ARC_EDGE_SPEED_MULT));
                sprites.setDataString(edgeFx, EFFECT_FRAME_LIST_DATA_KEY, list);
                sprites.setDataNumber(edgeFx, EFFECT_FRAME_LIST_IS_RAW_DATA_KEY, 1);
                sprites.setDataNumber(edgeFx, EFFECT_FRAME_INDEX_DATA_KEY, -1);
                sprites.setDataNumber(edgeFx, EFFECT_YOYO_DATA_KEY, 0);
                sprites.setDataNumber(edgeFx, EFFECT_FRAME_WINDOW_MS_DATA_KEY, 0);
                sprites.setDataNumber(edgeFx, EFFECT_FRAME_WINDOW_START_DATA_KEY, 0);
                sprites.setDataNumber(edgeFx, EFFECT_ANIM_DELAY_MS_DATA_KEY, 0);
                sprites.setDataNumber(edgeFx, EFFECT_ANIM_DELAY_START_MS_DATA_KEY, 0);
                sprites.setDataNumber(edgeFx, EFFECT_FPS_DATA_KEY, fps | 0);
                sprites.setDataNumber(edgeFx, EFFECT_REPEAT_DATA_KEY, 0);
                sprites.setDataNumber(edgeFx, STR_ARC_EDGE_PHASE_KEY, phase | 0);
                sprites.setDataNumber(edgeFx, STR_ARC_EDGE_ROW_KEY, edgeRow | 0);
            }
            const edgeAlphaRaw = isSlashSeg
                ? (STR_ARC_EDGE_ALPHA_SLASH_MIN + ((STR_ARC_EDGE_ALPHA_SLASH_MAX - STR_ARC_EDGE_ALPHA_SLASH_MIN) * slashT))
                : (STR_ARC_EDGE_ALPHA_RESET * (1 - endFadeT) + (STR_ARC_EDGE_ALPHA_END_MIN * endFadeT));
            const edgeAlpha = Math.min(1, Math.max(0.001, edgeAlphaRaw * leadWeight));
            sprites.setDataNumber(edgeFx, EFFECT_ALPHA_DATA_KEY, edgeAlpha);
            sprites.setDataNumber(edgeFx, EFFECT_ROT_DATA_KEY, rot);
            sprites.setDataNumber(edgeFx, EFFECT_SCALE_DATA_KEY, scale);
            sprites.setDataNumber(edgeFx, EFFECT_FLIP_X_DATA_KEY, flipX ? 1 : 0);
            edgeFx.x = posX;
            edgeFx.y = posY;
            edgeFx.z = (hero.z | 0) + 14;
            edgeFx.setFlag(SpriteFlag.Invisible, !(leadWeight > 0.02));

            if (edgeAuraFx && !(edgeAuraFx.flags & sprites.Flag.Destroyed)) {
                const lastAuraRow = sprites.readDataNumber(edgeAuraFx, STR_ARC_EDGE_ROW_KEY) | 0;
                const lastAuraPhase = sprites.readDataNumber(edgeAuraFx, STR_ARC_EDGE_PHASE_KEY) | 0;
                if (edgeRow !== lastAuraRow || phase !== lastAuraPhase) {
                    const list = _strengthArcEdgeFrameListRaw(edgeRow | 0);
                    const listCount = _strengthArcFillListCount(list);
                    const baseFps = (phaseMs > 0 && listCount > 0) ? (listCount / (phaseMs / 1000)) : 30;
                    const fps = Math.max(1, Math.round(baseFps * STR_ARC_EDGE_SPEED_MULT));
                    sprites.setDataString(edgeAuraFx, EFFECT_FRAME_LIST_DATA_KEY, list);
                    sprites.setDataNumber(edgeAuraFx, EFFECT_FRAME_LIST_IS_RAW_DATA_KEY, 1);
                    sprites.setDataNumber(edgeAuraFx, EFFECT_FRAME_INDEX_DATA_KEY, -1);
                    sprites.setDataNumber(edgeAuraFx, EFFECT_YOYO_DATA_KEY, 0);
                    sprites.setDataNumber(edgeAuraFx, EFFECT_FRAME_WINDOW_MS_DATA_KEY, 0);
                    sprites.setDataNumber(edgeAuraFx, EFFECT_FRAME_WINDOW_START_DATA_KEY, 0);
                    sprites.setDataNumber(edgeAuraFx, EFFECT_ANIM_DELAY_MS_DATA_KEY, 0);
                    sprites.setDataNumber(edgeAuraFx, EFFECT_ANIM_DELAY_START_MS_DATA_KEY, 0);
                    sprites.setDataNumber(edgeAuraFx, EFFECT_FPS_DATA_KEY, fps | 0);
                    sprites.setDataNumber(edgeAuraFx, EFFECT_REPEAT_DATA_KEY, 0);
                    sprites.setDataNumber(edgeAuraFx, STR_ARC_EDGE_PHASE_KEY, phase | 0);
                    sprites.setDataNumber(edgeAuraFx, STR_ARC_EDGE_ROW_KEY, edgeRow | 0);
                }
                const edgeAuraAlpha = Math.min(1, Math.max(0.001, edgeAlpha * STR_ARC_EDGE_AURA_ALPHA_SCALE));
                sprites.setDataNumber(edgeAuraFx, EFFECT_ALPHA_DATA_KEY, edgeAuraAlpha);
                sprites.setDataNumber(edgeAuraFx, EFFECT_TINT_DATA_KEY, highlight.primary | 0);
                sprites.setDataNumber(edgeAuraFx, EFFECT_ROT_DATA_KEY, rot);
                sprites.setDataNumber(edgeAuraFx, EFFECT_SCALE_DATA_KEY, scale);
                sprites.setDataNumber(edgeAuraFx, EFFECT_FLIP_X_DATA_KEY, flipX ? 1 : 0);
                edgeAuraFx.x = posX;
                edgeAuraFx.y = posY;
                edgeAuraFx.z = (hero.z | 0) + 12 + (STR_ARC_EDGE_AURA_Z_OFFSET | 0);
                edgeAuraFx.setFlag(SpriteFlag.Invisible, !(leadWeight > 0.02));
            }
        }

        const auraTints = [highlight.primary];
        const auraKeys = [STR_ARC_AURA_R1_FX_KEY, STR_ARC_AURA_R2_FX_KEY, STR_ARC_AURA_R3_FX_KEY];
        const auraCount = Math.min(STR_ARC_AURA_RADII.length, auraKeys.length, STR_ARC_AURA_ALPHA_BY_RADIUS.length);
        for (let i = 0; i < auraCount; i++) {
            const auraFx = sprites.readDataSprite(proj, auraKeys[i]);
            if (!auraFx || (auraFx.flags & sprites.Flag.Destroyed)) continue;
            const auraSkin = sprites.readDataString(auraFx, "effectSkin") || STR_ARC_SKIN_ID;
            const auraIdx = _strengthArcFrameIndexFromRaw(auraSkin, rawFrame);
            const auraAlphaRaw = (STR_ARC_AURA_ALPHA_BY_RADIUS[i] || 0) * leadWeight;
            const auraAlpha = Math.min(1, Math.max(0.001, auraAlphaRaw));
            sprites.setDataNumber(auraFx, EFFECT_FRAME_INDEX_DATA_KEY, auraIdx | 0);
            sprites.setDataNumber(auraFx, EFFECT_ROT_DATA_KEY, rot);
            sprites.setDataNumber(auraFx, EFFECT_SCALE_DATA_KEY, scale);
            sprites.setDataNumber(auraFx, EFFECT_FLIP_X_DATA_KEY, flipX ? 1 : 0);
            sprites.setDataNumber(auraFx, EFFECT_TINT_DATA_KEY, auraTints[i] | 0);
            sprites.setDataNumber(auraFx, EFFECT_ALPHA_DATA_KEY, auraAlpha);
            auraFx.x = posX;
            auraFx.y = posY;
            auraFx.z = (hero.z | 0) + 12 + (STR_ARC_AURA_Z_OFFSET | 0) - i;
            auraFx.setFlag(SpriteFlag.Invisible, !(leadWeight > 0.02));
        }
    }

    // If no fill is present (or fill is disabled), show the raw arc mask sprite.
    const fillAlive = !!(fillFx && !(fillFx.flags & sprites.Flag.Destroyed));
    const maskVisible = DEBUG_STR_ARC_NO_FILL;
    maskFx.setFlag(SpriteFlag.Invisible, !maskVisible);

    const outlineFx = sprites.readDataSprite(proj, STR_ARC_OUTLINE_FX_KEY);
    if (!STR_ARC_OUTLINE_ENABLED) {
        if (outlineFx && !(outlineFx.flags & sprites.Flag.Destroyed)) outlineFx.destroy();
        sprites.setDataSprite(proj, STR_ARC_OUTLINE_FX_KEY, null as any);
    } else if (outlineFx && !(outlineFx.flags & sprites.Flag.Destroyed)) {
        const outlineSkin = sprites.readDataString(outlineFx, "effectSkin") || "";
        const outlineIdx = _strengthArcFrameIndexFromRaw(outlineSkin || STR_ARC_SKIN_ID, rawFrame);
        const outlineTint = highlight.secondary || highlight.primary;
        const outlineAlpha = Math.min(1, Math.max(0.01, STR_ARC_OUTLINE_ALPHA * leadWeight));
        sprites.setDataNumber(outlineFx, EFFECT_FRAME_INDEX_DATA_KEY, outlineIdx | 0);
        sprites.setDataNumber(outlineFx, EFFECT_ROT_DATA_KEY, rot);
        sprites.setDataNumber(outlineFx, EFFECT_SCALE_DATA_KEY, scale);
        sprites.setDataNumber(outlineFx, EFFECT_FLIP_X_DATA_KEY, flipX ? 1 : 0);
        sprites.setDataNumber(outlineFx, EFFECT_TINT_DATA_KEY, outlineTint | 0);
        sprites.setDataNumber(outlineFx, EFFECT_ALPHA_DATA_KEY, outlineAlpha);
        outlineFx.x = posX;
        outlineFx.y = posY;
        outlineFx.z = (hero.z | 0) + 12 + (STR_ARC_OUTLINE_Z_OFFSET | 0);
        outlineFx.setFlag(SpriteFlag.Invisible, !(leadWeight > 0.02));
    }

    return true;
}

function _agilityTrailFxSegKey(i: number): string {
    return AGI_FX_SEG_BASE_KEY + (i | 0);
}

function _spawnAgilityTrailFxSegments(
    proj: Sprite,
    heroIndex: number,
    hero: Sprite,
    element: number,
    nx: number,
    ny: number,
    lifespanMs: number,
    maxLen: number
): void {
    if (!proj || !hero) return;
    if (!ENABLE_AGI_FX_SEGMENTS) {
        _destroyAgilityTrailFxSegments(proj);
        return;
    }
    const dir = _enemyDirFromVector(nx, ny);
    const elem = _heroBodyEffectElement(hero, element | 0);
    const pick = _heroSpellEffectPick(elem | 0, dir, "offense");
    if (!pick || !pick.skinId) return;

    const maskSprite = _ensureProjectileMaskSprite(proj, proj.image as any);
    const baseSkin = pick.skinId;
    const sizedSkin = _effectSkinIdWithSize(baseSkin, WEAPON_TILE_FX_SIZE_PX | 0, pick.dir || dir);
    const offset = _heroSpellEffectOffsetFor(baseSkin, pick.dir || dir, FAMILY.AGILITY | 0, "agilityTrail");
    const spacing = Math.max(8, AGI_FX_SEG_SPACING_PX | 0);
    const segCount = Math.max(2, Math.min(AGI_FX_SEG_MAX | 0, Math.ceil((maxLen | 0) / spacing)));
    const horiz = Math.abs(nx) >= Math.abs(ny);

    for (let i = 0; i < segCount; i++) {
        const fx = sprites.create(_getEffectDummyImage(), SpriteKind.HeroEffect);
        fx.setFlag(SpriteFlag.Ghost, true);
        fx.setFlag(SpriteFlag.Invisible, true);
        fx.x = hero.x;
        fx.y = hero.y;
        fx.z = (hero.z | 0) + (AGI_FX_SEG_Z_BIAS | 0);
        if ((lifespanMs | 0) > 0) fx.lifespan = lifespanMs | 0;

        sprites.setDataNumber(fx, PROJ_DATA.HERO_INDEX, heroIndex | 0);
        sprites.setDataNumber(fx, PROJ_DATA.FAMILY, FAMILY.AGILITY | 0);

        const opts: EffectApplyOpts = {
            mode: "projectile",
            alpha: AGI_FX_SEG_ALPHA,
            blend: AGI_FX_SEG_BLEND,
            repeat: -1,
            introMs: AGI_FX_INTRO_MS,
            introScale: AGI_FX_INTRO_SCALE,
            offsetX: offset.x,
            offsetY: offset.y,
            maskPadOutPx: WEAPON_TILE_FX_MASK_OUT_PX,
            maskSprite: maskSprite || proj,
            flipX: WEAPON_TILE_FX_MIRROR && horiz ? ((i % 2) === 1) : false,
            flipY: WEAPON_TILE_FX_MIRROR && !horiz ? ((i % 2) === 1) : false
        };
        if (pick.dir) opts.dir = pick.dir;
        applyEffectToSprite(fx, sizedSkin, opts);
        sprites.setDataNumber(fx, AGI_FX_SEG_ACTIVE_KEY, 0);
        sprites.setDataSprite(proj, _agilityTrailFxSegKey(i), fx);
    }

    sprites.setDataNumber(proj, AGI_FX_SEG_COUNT_KEY, segCount | 0);
}

function _hideAgilityTrailFxSegments(proj: Sprite): void {
    if (!proj) return;
    const count = sprites.readDataNumber(proj, AGI_FX_SEG_COUNT_KEY) | 0;
    for (let i = 0; i < count; i++) {
        const fx = sprites.readDataSprite(proj, _agilityTrailFxSegKey(i));
        if (fx && !(fx.flags & sprites.Flag.Destroyed)) {
            fx.setFlag(SpriteFlag.Invisible, true);
            sprites.setDataNumber(fx, AGI_FX_SEG_ACTIVE_KEY, 0);
        }
    }
}

function _destroyAgilityTrailFxSegments(proj: Sprite): void {
    if (!proj) return;
    const count = sprites.readDataNumber(proj, AGI_FX_SEG_COUNT_KEY) | 0;
    for (let i = 0; i < count; i++) {
        const fx = sprites.readDataSprite(proj, _agilityTrailFxSegKey(i));
        if (fx && !(fx.flags & sprites.Flag.Destroyed)) fx.destroy();
        sprites.setDataSprite(proj, _agilityTrailFxSegKey(i), null as any);
    }
    sprites.setDataNumber(proj, AGI_FX_SEG_COUNT_KEY, 0);
}

function _destroyAgilityCometFx(proj: Sprite): void {
    if (!proj) return;
    const fx = sprites.readDataSprite(proj, AGI_COMET_FX_KEY);
    if (fx && !(fx.flags & sprites.Flag.Destroyed)) {
        _destroyAxisDebugSprite(fx, AGI_COMET_AXIS_DEBUG_SPR_KEY);
        _destroyAgilityCometAurasForFx(fx);
        fx.destroy();
    }
    sprites.setDataSprite(proj, AGI_COMET_FX_KEY, null as any);
    const squareFx = sprites.readDataSprite(proj, AGI_SQUARE_COMET_FX_KEY);
    const fillFx = sprites.readDataSprite(proj, AGI_SQUARE_COMET_FILL_FX_KEY);
    if (fillFx && !(fillFx.flags & sprites.Flag.Destroyed)) {
        fillFx.destroy();
    }
    sprites.setDataSprite(proj, AGI_SQUARE_COMET_FILL_FX_KEY, null as any);
    if (squareFx && !(squareFx.flags & sprites.Flag.Destroyed)) {
        _destroyAxisDebugSprite(squareFx, AGI_COMET_AXIS_DEBUG_SPR_KEY);
        _destroyAgilityCometAurasForFx(squareFx);
        squareFx.destroy();
    }
    sprites.setDataSprite(proj, AGI_SQUARE_COMET_FX_KEY, null as any);
}

function _destroyAgilityCometAurasForFx(fx: Sprite): void {
    if (!fx) return;
    const blendFx = sprites.readDataSprite(fx, AGI_COMET_BLEND_FX_KEY);
    if (blendFx && !(blendFx.flags & sprites.Flag.Destroyed)) blendFx.destroy();
    sprites.setDataSprite(fx, AGI_COMET_BLEND_FX_KEY, null as any);
    const auraKeys = [AGI_COMET_AURA_R1_FX_KEY, AGI_COMET_AURA_R2_FX_KEY, AGI_COMET_AURA_R3_FX_KEY];
    for (const key of auraKeys) {
        const auraFx = sprites.readDataSprite(fx, key);
        if (auraFx && !(auraFx.flags & sprites.Flag.Destroyed)) auraFx.destroy();
        sprites.setDataSprite(fx, key, null as any);
    }
}

function _setAgilityCometAurasVisible(fx: Sprite, visible: boolean): void {
    if (!fx) return;
    const blendFx = sprites.readDataSprite(fx, AGI_COMET_BLEND_FX_KEY);
    if (blendFx && !(blendFx.flags & sprites.Flag.Destroyed)) {
        blendFx.setFlag(SpriteFlag.Invisible, !visible);
    }
    const auraKeys = [AGI_COMET_AURA_R1_FX_KEY, AGI_COMET_AURA_R2_FX_KEY, AGI_COMET_AURA_R3_FX_KEY];
    for (const key of auraKeys) {
        const auraFx = sprites.readDataSprite(fx, key);
        if (auraFx && !(auraFx.flags & sprites.Flag.Destroyed)) {
            auraFx.setFlag(SpriteFlag.Invisible, !visible);
        }
    }
}

function _ensureAgilityCometAurasForFx(
    fx: Sprite,
    auraTints: number[],
    zBase: number
): void {
    if (AGI_DISABLE_LEGACY_AGI_TRAIL_FX) {
        _destroyAgilityCometAurasForFx(fx);
        return;
    }
    if (!fx) return;
    const auraKeys = [AGI_COMET_AURA_R1_FX_KEY, AGI_COMET_AURA_R2_FX_KEY, AGI_COMET_AURA_R3_FX_KEY];
    const auraCount = Math.min(STR_ARC_AURA_RADII.length, auraKeys.length, auraTints.length);
    for (let i = 0; i < auraCount; i++) {
        const key = auraKeys[i];
        const existing = sprites.readDataSprite(fx, key);
        if (existing && !(existing.flags & sprites.Flag.Destroyed)) continue;
        const radius = STR_ARC_AURA_RADII[i] | 0;
        const skinId = _strengthArcAuraSkinId(radius);
        if (!skinId) continue;
        const auraFx = sprites.create(_getEffectDummyImage(), SpriteKind.HeroEffect);
        auraFx.setFlag(SpriteFlag.Ghost, true);
        auraFx.x = fx.x;
        auraFx.y = fx.y;
        auraFx.z = (zBase | 0) + i;
        if ((fx.lifespan | 0) > 0) auraFx.lifespan = fx.lifespan | 0;
        const auraOpts: EffectApplyOpts = {
            mode: "full",
            repeat: -1,
            frameIndex: 0,
            blend: STR_ARC_AURA_BLEND,
            tint: auraTints[i] | 0,
            alpha: 0.001
        };
        applyEffectToSprite(auraFx, skinId, auraOpts);
        sprites.setDataSprite(fx, key, auraFx);
    }
}

function _ensureAgilityCometFx(
    proj: Sprite,
    heroIndex: number,
    hero: Sprite,
    element: number,
    dashMs: number
): Sprite | null {
    if (!proj || !hero) return null;
    let fx = sprites.readDataSprite(proj, AGI_COMET_FX_KEY);
    if (fx && (fx.flags & sprites.Flag.Destroyed)) fx = null;
    if (fx) return fx;

    fx = sprites.create(_getEffectDummyImage(), SpriteKind.HeroEffect);
    fx.setFlag(SpriteFlag.Ghost, true);
    fx.setFlag(SpriteFlag.Invisible, false);
    fx.x = hero.x;
    fx.y = hero.y;
    fx.z = (hero.z | 0) + (AGI_COMET_Z_BIAS | 0);

    const dash = dashMs | 0;
    if (dash > 0) {
        const lifeMs = Math.max(300, (dash + 350) | 0);
        fx.lifespan = lifeMs | 0;
    }

    sprites.setDataNumber(fx, PROJ_DATA.HERO_INDEX, heroIndex | 0);
    sprites.setDataNumber(fx, PROJ_DATA.FAMILY, FAMILY.AGILITY | 0);
    sprites.setDataNumber(fx, PROJ_DATA.ELEMENT, element | 0);

    const elem = _heroBodyEffectElement(hero, element | 0);
    const tint = _elementTintForMode(elem | 0, "offense") | 0;
    const opts: EffectApplyOpts = {
        mode: "full",
        alpha: AGI_COMET_ALPHA,
        blend: "normal",
        repeat: -1,
        tint: tint || undefined
    };
    applyEffectToSprite(fx, AGI_SQUARE_COMET_SKIN_ID, opts);
    sprites.setDataString(fx, EFFECT_FRAME_LIST_DATA_KEY, "");
    sprites.setDataNumber(fx, EFFECT_FRAME_INDEX_DATA_KEY, 0);
    sprites.setDataNumber(fx, EFFECT_FRAME_INDEX_IS_RAW_DATA_KEY, 0);
    sprites.setDataNumber(fx, EFFECT_FRAME_LIST_IS_RAW_DATA_KEY, 0);

    sprites.setDataSprite(proj, AGI_COMET_FX_KEY, fx);
    return fx;
}

function _ensureAgilitySquareCometFx(
    proj: Sprite,
    heroIndex: number,
    hero: Sprite,
    element: number,
    dashMs: number
): Sprite | null {
    if (!proj || !hero) return null;
    let fx = sprites.readDataSprite(proj, AGI_SQUARE_COMET_FX_KEY);
    if (fx && (fx.flags & sprites.Flag.Destroyed)) fx = null;
    if (fx) return fx;

    fx = sprites.create(_getEffectDummyImage(), SpriteKind.HeroEffect);
    fx.setFlag(SpriteFlag.Ghost, true);
    fx.setFlag(SpriteFlag.Invisible, true);
    fx.x = hero.x;
    fx.y = hero.y;
    fx.z = (hero.z | 0) + (AGI_SQUARE_COMET_Z_BIAS | 0);

    const dash = dashMs | 0;
    if (dash > 0) {
        const lifeMs = Math.max(300, (dash + 350) | 0);
        fx.lifespan = lifeMs | 0;
    }

    const opts: EffectApplyOpts = {
        mode: "full",
        alpha: AGI_SQUARE_COMET_ALPHA,
        blend: "normal",
        repeat: -1
    };
    applyEffectToSprite(fx, AGI_SQUARE_COMET_SKIN_ID, opts);
    sprites.setDataString(fx, EFFECT_FRAME_LIST_DATA_KEY, "");
    sprites.setDataNumber(fx, EFFECT_FRAME_INDEX_DATA_KEY, 0);
    sprites.setDataNumber(fx, EFFECT_FRAME_INDEX_IS_RAW_DATA_KEY, 0);
    sprites.setDataNumber(fx, EFFECT_FRAME_LIST_IS_RAW_DATA_KEY, 0);

    sprites.setDataSprite(proj, AGI_SQUARE_COMET_FX_KEY, fx);
    return fx;
}

function _agiDashSquareCometCarrier(hero: Sprite): Sprite | null {
    if (!hero) return null;
    let spr = sprites.readDataSprite(hero, AGI_SQUARE_COMET_CARRIER_KEY);
    if (spr && (spr.flags & sprites.Flag.Destroyed)) spr = null as any;
    if (!spr) {
        spr = sprites.create(_getEffectDummyImage(), SpriteKind.HeroEffect);
        spr.setFlag(SpriteFlag.Ghost, true);
        spr.setFlag(SpriteFlag.Invisible, true);
        sprites.setDataSprite(hero, AGI_SQUARE_COMET_CARRIER_KEY, spr as any);
    }
    return spr;
}

function _agiDashSquareCometClear(hero: Sprite): void {
    if (!hero) return;
    const spr = sprites.readDataSprite(hero, AGI_SQUARE_COMET_CARRIER_KEY);
    if (spr && !(spr.flags & sprites.Flag.Destroyed)) {
        _destroyAgilityCometFx(spr);
        spr.destroy();
    }
    sprites.setDataSprite(hero, AGI_SQUARE_COMET_CARRIER_KEY, null as any);
}

function _agiCometPreT(preActive: boolean, activateAt: number, nowMs: number): number {
    if (!preActive) return 1;
    const actAt = activateAt | 0;
    if (!(actAt > 0)) return 0;
    const remain = Math.max(0, actAt - (nowMs | 0));
    if (remain >= (AGI_COMET_PRE_MS | 0)) return 0;
    const t = 1 - (remain / Math.max(1, AGI_COMET_PRE_MS));
    return Math.max(0, Math.min(1, t));
}

function _agiCometTipDistance(sBack: number, sFront: number, maxLen: number, reelT: number): number {
    const sb = sBack;
    const sf = sFront;
    if (reelT > 0) {
        const backOff = (Math.max(0, maxLen | 0) * Math.max(0, Math.min(1, reelT)) * (AGI_COMET_REEL_BACK_PCT_X1000 / 1000));
        const tip = sf - backOff;
        return Math.max(sb, tip);
    }
    return Math.max(sb, sf - (AGI_COMET_TIP_BACK_PX | 0));
}

function _agiCometPickRawFrame(
    preActive: boolean,
    preT: number,
    growthT: number,
    reelT: number,
    nowMs: number,
    startMs: number
): number {
    const reel = Math.max(0, Math.min(1, reelT));
    if (preActive) {
        const t = Math.max(0, Math.min(1, preT));
        return _strengthArcPickFromSequence(AGI_COMET_PRE_RAW, t, 1, false);
    }
    if (reel > 0) {
        return _strengthArcPickFromSequence(AGI_COMET_REEL_RAW, reel, 1, false);
    }
    const growNorm = Math.max(0, Math.min(1, growthT / Math.max(0.0001, AGI_COMET_GROW_END_T)));
    const growEase = Math.pow(growNorm, AGI_COMET_GROW_EXP);
    if (growthT < AGI_COMET_GROW_END_T) {
        return _strengthArcPickFromSequence(AGI_COMET_GROW_RAW, growEase, 1, false);
    }
    return (AGI_COMET_HOLD_RAW && AGI_COMET_HOLD_RAW.length) ? (AGI_COMET_HOLD_RAW[0] | 0) : 0;
}

function _agiHookCometPickRawFrame(
    preActive: boolean,
    preT: number,
    growthT: number,
    reelT: number
): number {
    const reel = Math.max(0, Math.min(1, reelT));
    if (preActive) {
        const t = Math.max(0, Math.min(1, preT));
        return _strengthArcPickFromSequence(AGI_HOOK_COMET_GROW_RAW, t, 1, false);
    }
    if (reel > 0) {
        return _strengthArcPickFromSequence(AGI_HOOK_COMET_REEL_RAW, reel, 1, false);
    }
    const growNorm = Math.max(0, Math.min(1, growthT / Math.max(0.0001, AGI_COMET_GROW_END_T)));
    const growEase = Math.pow(growNorm, AGI_COMET_GROW_EXP);
    if (growthT < AGI_COMET_GROW_END_T) {
        return _strengthArcPickFromSequence(AGI_HOOK_COMET_GROW_RAW, growEase, 1, false);
    }
    return (AGI_HOOK_COMET_HOLD_RAW && AGI_HOOK_COMET_HOLD_RAW.length) ? (AGI_HOOK_COMET_HOLD_RAW[0] | 0) : 0;
}

function _agiSquareCometPickRawFrame(
    preActive: boolean,
    preT: number,
    growthT: number,
    reelT: number
): number {
    const reel = Math.max(0, Math.min(1, reelT));
    if (preActive) {
        const t = Math.max(0, Math.min(1, preT));
        return _strengthArcPickFromSequence(AGI_SQUARE_COMET_GROW_RAW, t, 1, false);
    }
    if (reel > 0) {
        return _strengthArcPickFromSequence(AGI_SQUARE_COMET_REEL_RAW, reel, 1, false);
    }
    const growNorm = Math.max(0, Math.min(1, growthT / Math.max(0.0001, AGI_COMET_GROW_END_T)));
    const growEase = Math.pow(growNorm, AGI_COMET_GROW_EXP);
    if (growthT < AGI_COMET_GROW_END_T) {
        return _strengthArcPickFromSequence(AGI_SQUARE_COMET_GROW_RAW, growEase, 1, false);
    }
    return (AGI_SQUARE_COMET_HOLD_RAW && AGI_SQUARE_COMET_HOLD_RAW.length)
        ? (AGI_SQUARE_COMET_HOLD_RAW[0] | 0)
        : 0;
}

function _agiCometFrameMetricsForDir(
    skinId: string,
    rawFrame: number,
    dirX: number,
    dirY: number
): EffectFrameMetrics | null {
    const atlas = _getEffectAtlasAny();
    const resolved = atlas ? _resolveEffectEntry(atlas, skinId, "") : null;
    if (!resolved || !resolved.textureKey) return null;
    const frameW = (resolved.frameW | 0) || 0;
    const frameH = (resolved.frameH | 0) || 0;
    if (frameW <= 0 || frameH <= 0) return null;
    return _computeTextureFrameMetrics(
        resolved.textureKey,
        frameW,
        frameH,
        rawFrame | 0,
        dirX,
        dirY
    );
}

function _agiCometFrameMetrics(skinId: string, rawFrame: number): EffectFrameMetrics | null {
    return _agiCometFrameMetricsForDir(skinId, rawFrame | 0, AGI_COMET_BASE_DIR_X, AGI_COMET_BASE_DIR_Y);
}

function _agiCometTipOffsetForRaw(skinId: string, rawFrame: number): { dx: number; dy: number } | null {
    const metrics = _agiCometFrameMetrics(skinId, rawFrame | 0);
    if (!metrics) return null;
    let dx = metrics.tipDx | 0;
    let dy = metrics.tipDy | 0;
    if (skinId === AGI_SQUARE_COMET_SKIN_ID) {
        const off = AGI_SQUARE_COMET_RAW_OFFSET_DY[rawFrame | 0] | 0;
        if (off) dy += off;
    }
    return { dx, dy };
}

function _agiCometTailOffsetForRaw(skinId: string, rawFrame: number): { dx: number; dy: number } | null {
    const metrics = _agiCometFrameMetricsForDir(
        skinId,
        rawFrame | 0,
        -(AGI_COMET_BASE_DIR_X | 0),
        -(AGI_COMET_BASE_DIR_Y | 0)
    );
    if (!metrics) return null;
    return { dx: metrics.tipDx | 0, dy: metrics.tipDy | 0 };
}

function _agiCometAxisScaleForTipOffset(tipOffset?: { dx: number; dy: number } | null): { sx: number; sy: number } {
    const lenScale = Number(AGI_COMET_LENGTH_SCALE);
    if (!Number.isFinite(lenScale) || lenScale <= 0) return { sx: 1, sy: 1 };
    if (!tipOffset) return { sx: 1, sy: 1 };
    const ax = Math.abs(tipOffset.dx || 0);
    const ay = Math.abs(tipOffset.dy || 0);
    if (ax === 0 && ay === 0) return { sx: 1, sy: 1 };
    if (ax >= ay) return { sx: lenScale, sy: 1 };
    return { sx: 1, sy: lenScale };
}

function _agiCometAxisScaleForWeaponLen(
    tipOffset: { dx: number; dy: number } | null,
    weaponLen: number
): { sx: number; sy: number } | null {
    if (!tipOffset) return null;
    let len = Math.max(1, weaponLen | 0);
    const padPct = AGI_COMET_ALIGN_LEN_PAD_PCT_X1000 | 0;
    if (padPct > 0) len = Math.max(1, Math.round((len * padPct) / 1000));
    const ax = Math.abs(tipOffset.dx || 0);
    const ay = Math.abs(tipOffset.dy || 0);
    if (ax === 0 && ay === 0) return null;
    const dominant = Math.max(ax, ay);
    if (dominant <= 0) return null;
    let s = len / dominant;
    if (!Number.isFinite(s)) return null;
    s = Math.max(AGI_COMET_ALIGN_LEN_MIN, Math.min(AGI_COMET_ALIGN_LEN_MAX, s));
    if (ax >= ay) return { sx: s, sy: 1 };
    return { sx: 1, sy: s };
}

function _agiCometAxisScaleForWeaponLenWithTail(
    tipOffset: { dx: number; dy: number } | null,
    tailOffset: { dx: number; dy: number } | null,
    weaponLen: number
): { sx: number; sy: number } | null {
    if (!tipOffset || !tailOffset) return null;
    let len = Math.max(1, weaponLen | 0);
    const padPct = AGI_COMET_ALIGN_LEN_PAD_PCT_X1000 | 0;
    if (padPct > 0) len = Math.max(1, Math.round((len * padPct) / 1000));
    const dx = (tipOffset.dx || 0) - (tailOffset.dx || 0);
    const dy = (tipOffset.dy || 0) - (tailOffset.dy || 0);
    const ax = Math.abs(dx);
    const ay = Math.abs(dy);
    const dominant = Math.max(ax, ay);
    if (dominant <= 0) return null;
    let s = len / dominant;
    if (!Number.isFinite(s)) return null;
    s = Math.max(AGI_COMET_ALIGN_LEN_MIN, Math.min(AGI_COMET_ALIGN_LEN_MAX, s));
    if (ax >= ay) return { sx: s, sy: 1 };
    return { sx: 1, sy: s };
}

function _agiCometAxisScaleForArtAxis(
    tipOffset: { dx: number; dy: number } | null,
    desiredLen: number
): { sx: number; sy: number } | null {
    if (!tipOffset) return null;
    const dx = tipOffset.dx || 0;
    const dy = tipOffset.dy || 0;
    const baseLen = Math.hypot(dx, dy);
    if (!(baseLen > 0)) return null;
    let target = desiredLen;
    if (!(target > 0)) return null;
    let s = target / baseLen;
    if (!Number.isFinite(s)) return null;
    s = Math.max(AGI_COMET_ALIGN_LEN_MIN, Math.min(AGI_COMET_ALIGN_LEN_MAX, s));
    const ax = Math.abs(dx);
    const ay = Math.abs(dy);
    if (ax >= ay) return { sx: s, sy: 1 };
    return { sx: 1, sy: s };
}

function _agiCometAxisScaleForWeaponDir(
    nx: number,
    ny: number,
    baseLen: number,
    desiredLen: number
): { sx: number; sy: number } | null {
    if (!(baseLen > 0) || !(desiredLen > 0)) return null;
    let s = desiredLen / baseLen;
    if (!Number.isFinite(s)) return null;
    s = Math.max(AGI_COMET_ALIGN_LEN_MIN, Math.min(AGI_COMET_ALIGN_LEN_MAX, s));
    const ax = Math.abs(nx);
    const ay = Math.abs(ny);
    if (ax >= ay) return { sx: s, sy: 1 };
    return { sx: 1, sy: s };
}

function _agiCometElementTexturePick(element: number, dir: string): { skinId: string; dir?: string } | null {
    const pick = _strengthArcTexturePick(element | 0, dir || "");
    if (!pick || !pick.skinId) return null;
    return pick;
}

function _agiSquareCometFillHide(proj: Sprite): void {
    if (!proj) return;
    const fx = sprites.readDataSprite(proj, AGI_SQUARE_COMET_FILL_FX_KEY);
    if (fx && !(fx.flags & sprites.Flag.Destroyed)) {
        fx.setFlag(SpriteFlag.Invisible, true);
    }
}

function _ensureAgilitySquareCometFillFx(
    proj: Sprite,
    maskFx: Sprite,
    element: number,
    dir: string
): Sprite | null {
    if (!proj || !maskFx) return null;
    const pick = _agiCometElementTexturePick(element | 0, dir || "");
    let fx = sprites.readDataSprite(proj, AGI_SQUARE_COMET_FILL_FX_KEY);
    if (!pick || !pick.skinId) {
        if (fx && !(fx.flags & sprites.Flag.Destroyed)) fx.setFlag(SpriteFlag.Invisible, true);
        return null;
    }
    if (fx && (fx.flags & sprites.Flag.Destroyed)) fx = null;
    if (!fx) {
        fx = sprites.create(_getEffectDummyImage(), SpriteKind.HeroEffect);
        fx.setFlag(SpriteFlag.Ghost, true);
        fx.setFlag(SpriteFlag.Invisible, true);
        sprites.setDataSprite(proj, AGI_SQUARE_COMET_FILL_FX_KEY, fx);
    }
    const skinId = pick.skinId;
    const dirKey = pick.dir || "";
    const curSkin = sprites.readDataString(fx, "effectSkin") || "";
    const curDir = sprites.readDataString(fx, "effectDir") || "";
    if (curSkin !== skinId || curDir !== dirKey) {
        const opts: EffectApplyOpts = {
            mode: "projectile",
            repeat: -1,
            alpha: 1,
            blend: "normal",
            frameIndex: 0,
            maskSprite: maskFx
        };
        if (dirKey) opts.dir = dirKey;
        applyEffectToSprite(fx, skinId, opts);
    } else {
        sprites.setDataSprite(fx, EFFECT_MASK_SPRITE_REF_DATA_KEY, maskFx as any);
    }
    return fx;
}

function _agiCometAlignDirOffset(nx: number, ny: number, isSquare: boolean): { dx: number; dy: number } {
    const dirKey = _weaponDirKeyFromVector(nx, ny);
    const map = isSquare ? AGI_SQUARE_COMET_ALIGN_DIR_OFFSETS : AGI_COMET_ALIGN_DIR_OFFSETS;
    const off = map[dirKey];
    if (off) return off;
    return { dx: 0, dy: 0 };
}

function _agiCometHoldBlend(nowMs: number, startMs: number): number {
    const baseMs = (startMs | 0) > 0 ? (startMs | 0) : (nowMs | 0);
    const period = Math.max(1, AGI_COMET_HOLD_LOOP_MS | 0);
    const t = ((((nowMs | 0) - baseMs) / period) % 1 + 1) % 1;
    return 0.5 - 0.5 * Math.cos(t * Math.PI * 2);
}

function _agiCometEnsureBlendSprite(baseFx: Sprite): Sprite {
    let fx = sprites.readDataSprite(baseFx, AGI_COMET_BLEND_FX_KEY);
    if (fx && (fx.flags & sprites.Flag.Destroyed)) fx = null;
    if (!fx) {
        fx = sprites.create(_getEffectDummyImage(), SpriteKind.HeroEffect);
        fx.setFlag(SpriteFlag.Ghost, true);
        fx.setFlag(SpriteFlag.Invisible, true);
        fx.x = baseFx.x;
        fx.y = baseFx.y;
        fx.z = baseFx.z + 1;
        if ((baseFx.lifespan | 0) > 0) fx.lifespan = baseFx.lifespan | 0;
        const tint = sprites.readDataNumber(baseFx, EFFECT_TINT_DATA_KEY) | 0;
        const opts: EffectApplyOpts = {
            mode: "full",
            alpha: 0.001,
            blend: "normal",
            repeat: -1
        };
        if (tint) opts.tint = tint;
        applyEffectToSprite(fx, STR_ARC_SKIN_ID, opts);
        sprites.setDataSprite(baseFx, AGI_COMET_BLEND_FX_KEY, fx as any);
    }
    return fx;
}

function _agiCometAxisInfo(
    skinId: string,
    rawFrame?: number
): { frameW: number; frameH: number; axisX: number; axisY: number; axisPxX: number; axisPxY: number; axisSrc: string } {
    const key = `${String(skinId || "") || STR_ARC_SKIN_ID}|${Number.isFinite(rawFrame) ? (rawFrame as number) : "base"}`;
    const cached = __agiCometAxisCache[key];
    if (cached) return cached;
    const atlas = _getEffectAtlasAny();
    const resolved = atlas ? _resolveEffectEntry(atlas, skinId, "") : null;
    let frameW = (resolved?.frameW | 0) || 0;
    let frameH = (resolved?.frameH | 0) || 0;
    let axisPxX = frameW > 0 ? Math.round((frameW - 1) / 2) : 0;
    let axisPxY = frameH > 0 ? Math.round((frameH - 1) / 2) : 0;
    let axisSrc = "frame_center";

    if (Number.isFinite(rawFrame)) {
        const metrics = _agiCometFrameMetrics(skinId, rawFrame as number);
        if (metrics) {
            frameW = metrics.frameW | 0;
            frameH = metrics.frameH | 0;
            axisPxX = metrics.centerX | 0;
            axisPxY = metrics.centerY | 0;
            axisSrc = "frame_scan";
        }
    }

    const axisX = frameW > 1 ? (axisPxX / (frameW - 1)) : 0.5;
    const axisY = frameH > 1 ? (axisPxY / (frameH - 1)) : 0.5;
    const info = { frameW, frameH, axisX, axisY, axisPxX, axisPxY, axisSrc };
    __agiCometAxisCache[key] = info;
    return info;
}

function _agiCometDirOffset(nx: number, ny: number): { dx: number; dy: number } {
    const dirKey = _weaponDirKeyFromVector(nx, ny);
    const hit = AGI_COMET_DIR_OFFSETS[dirKey];
    if (hit) return { dx: hit.dx | 0, dy: hit.dy | 0 };
    const fallback = AGI_COMET_DIR_OFFSETS.none || { dx: 0, dy: 0 };
    return { dx: fallback.dx | 0, dy: fallback.dy | 0 };
}

function _agiCometShouldLog(fx: Sprite, nowMs: number): boolean {
    if (!DEBUG_AGI_COMET_LOGS) return false;
    const throttle = DEBUG_AGI_COMET_LOG_THROTTLE_MS | 0;
    const now = nowMs | 0;
    if (throttle > 0) {
        const last = sprites.readDataNumber(fx, AGI_COMET_LOG_LAST_MS_KEY) | 0;
        if (last > 0 && (now - last) < throttle) return false;
    }
    sprites.setDataNumber(fx, AGI_COMET_LOG_LAST_MS_KEY, now | 0);
    return true;
}

function _agiSquareCometShouldLog(fx: Sprite, nowMs: number): boolean {
    if (!DEBUG_AGI_SQUARE_COMET_LOGS) return false;
    const throttle = DEBUG_AGI_SQUARE_COMET_LOG_THROTTLE_MS | 0;
    const now = nowMs | 0;
    if (throttle > 0) {
        const last = sprites.readDataNumber(fx, AGI_SQUARE_COMET_LOG_LAST_MS_KEY) | 0;
        if (last > 0 && (now - last) < throttle) return false;
    }
    sprites.setDataNumber(fx, AGI_SQUARE_COMET_LOG_LAST_MS_KEY, now | 0);
    return true;
}

function _agiCometAlignShouldLog(fx: Sprite, nowMs: number): boolean {
    if (!DEBUG_AGI_COMET_ALIGN_LOGS) return false;
    const throttle = DEBUG_AGI_COMET_ALIGN_LOG_THROTTLE_MS | 0;
    const now = nowMs | 0;
    if (throttle > 0) {
        const last = sprites.readDataNumber(fx, AGI_COMET_ALIGN_LOG_LAST_MS_KEY) | 0;
        if (last > 0 && (now - last) < throttle) return false;
    }
    sprites.setDataNumber(fx, AGI_COMET_ALIGN_LOG_LAST_MS_KEY, now | 0);
    return true;
}

function _agiCometLogLine(payload: {
    kind: string;
    heroIndex: number;
    ghost: boolean;
    rawFrame: number;
    frameIdx: number;
    moveAngle: number;
    rot: number;
    tipX: number;
    tipY: number;
    baseX: number;
    baseY: number;
    nx: number;
    ny: number;
    scale: number;
    alpha: number;
    preActive: boolean;
    growthT: number;
    reelT: number;
    skinId: string;
}): void {
    if (!(DEBUG_AGI_COMET_LOGS || DEBUG_AGI_SQUARE_COMET_LOGS)) return;
    const deg = 180 / Math.PI;
    const axis = _agiCometAxisInfo(payload.skinId || STR_ARC_SKIN_ID, payload.rawFrame | 0);
    let line =
        "[AGI][COMET] msg=we_found_the_comet_frame_and_are_displaying_it_now" +
        " display=1" +
        " kind=" + payload.kind +
        " hero=" + (payload.heroIndex | 0) +
        " ghost=" + (payload.ghost ? 1 : 0) +
        " raw=" + (payload.rawFrame | 0) +
        " idx=" + (payload.frameIdx | 0) +
        " frame=" + (axis.frameW | 0) + "x" + (axis.frameH | 0) +
        " axis=" + axis.axisX.toFixed(3) + "," + axis.axisY.toFixed(3) +
        " axisPx=" + axis.axisPxX.toFixed(1) + "," + axis.axisPxY.toFixed(1) +
        " moveDeg=" + (payload.moveAngle * deg).toFixed(1) +
        " rotDeg=" + (payload.rot * deg).toFixed(1) +
        " tip=" + payload.tipX.toFixed(1) + "," + payload.tipY.toFixed(1) +
        " base=" + payload.baseX.toFixed(1) + "," + payload.baseY.toFixed(1) +
        " dir=" + payload.nx.toFixed(3) + "," + payload.ny.toFixed(3) +
        " scale=" + payload.scale.toFixed(3) +
        " alpha=" + payload.alpha.toFixed(3) +
        " pre=" + (payload.preActive ? 1 : 0) +
        " growT=" + payload.growthT.toFixed(3) +
        " reelT=" + payload.reelT.toFixed(3);
    if (DEBUG_AGI_COMET_LOG_VERBOSE || DEBUG_AGI_SQUARE_COMET_LOG_VERBOSE) {
        line += " skin=" + (payload.skinId || STR_ARC_SKIN_ID) + " axisSrc=" + (axis.axisSrc || "frame_center");
    }
    // eslint-disable-next-line no-console
    console.log(line);
}

function _agiCometAlignLogLine(payload: {
    kind: string;
    heroIndex: number;
    weaponTipX: number;
    weaponTipY: number;
    cometTipX: number;
    cometTipY: number;
    baseX: number;
    baseY: number;
    alignX: number;
    alignY: number;
    nx: number;
    ny: number;
    weaponLen: number;
    tipDist: number;
    scale: number;
    axisScaleX: number;
    axisScaleY: number;
    rawFrame: number;
    weaponBoxW?: number;
    weaponBoxH?: number;
    cometLen?: number;
}): void {
    if (!DEBUG_AGI_COMET_ALIGN_LOGS) return;
    const dx = payload.cometTipX - payload.weaponTipX;
    const dy = payload.cometTipY - payload.weaponTipY;
    let line =
        "[AGI][COMET][ALIGN]" +
        " kind=" + payload.kind +
        " hero=" + (payload.heroIndex | 0) +
        " wTip=" + payload.weaponTipX.toFixed(1) + "," + payload.weaponTipY.toFixed(1) +
        " cTip=" + payload.cometTipX.toFixed(1) + "," + payload.cometTipY.toFixed(1) +
        " d=" + dx.toFixed(2) + "," + dy.toFixed(2) +
        " base=" + payload.baseX.toFixed(1) + "," + payload.baseY.toFixed(1) +
        " align=" + payload.alignX.toFixed(1) + "," + payload.alignY.toFixed(1) +
        " dir=" + payload.nx.toFixed(3) + "," + payload.ny.toFixed(3) +
        " wLen=" + payload.weaponLen.toFixed(1) +
        " tipDist=" + payload.tipDist.toFixed(1) +
        " scale=" + payload.scale.toFixed(3) +
        " axis=" + payload.axisScaleX.toFixed(3) + "," + payload.axisScaleY.toFixed(3) +
        " raw=" + (payload.rawFrame | 0);
    if (Number.isFinite(payload.weaponBoxW) && Number.isFinite(payload.weaponBoxH)) {
        line += " wBox=" + (payload.weaponBoxW || 0).toFixed(1) + "x" + (payload.weaponBoxH || 0).toFixed(1);
    }
    if (Number.isFinite(payload.cometLen)) {
        line += " cLen=" + (payload.cometLen || 0).toFixed(1);
    }
    if (DEBUG_AGI_COMET_ALIGN_LOG_VERBOSE) {
        line += " t=" + (game.runtime() | 0);
    }
    console.log(line);
}

function _updateAgilityCometFx(
    proj: Sprite,
    heroIndex: number,
    hero: Sprite,
    element: number,
    nx: number,
    ny: number,
    anchorX: number,
    anchorY: number,
    sBack: number,
    sFront: number,
    maxLen: number,
    growthT: number,
    reelT: number,
    preActive: boolean,
    activateAt: number,
    nowMs: number,
    startMs: number,
    dashMs: number
): void {
    const fx = _ensureAgilityCometFx(proj, heroIndex, hero, element | 0, dashMs | 0);
    if (!fx || (fx.flags & sprites.Flag.Destroyed)) return;

    const preT = _agiCometPreT(preActive, activateAt | 0, nowMs | 0);
    if (preActive && preT <= 0) {
        fx.setFlag(SpriteFlag.Invisible, true);
        _setAgilityCometAurasVisible(fx, false);
        return;
    }

    const tipDist = _agiCometTipDistance(sBack, sFront, maxLen, reelT);

    const moveAngle = Math.atan2(ny, nx);
    const rot = _strengthArcNormalizeAngle(moveAngle - AGI_COMET_SW_BASE_ANGLE + AGI_SQUARE_COMET_ROT_OFFSET);

    const growNorm = Math.max(0, Math.min(1, growthT / Math.max(0.0001, AGI_COMET_GROW_END_T)));
    const growEase = Math.pow(growNorm, AGI_COMET_GROW_EXP);

    let scale = AGI_COMET_SCALE * (0.55 + (0.45 * growEase));
    if (preActive) scale *= 0.75;
    if (reelT > 0) {
        const reelEase = Math.max(0, Math.min(1, reelT));
        scale *= Math.max(AGI_COMET_END_SCALE, 1 - (0.7 * reelEase));
    }

    let alpha = preActive ? (AGI_COMET_PREACTIVE_ALPHA * (0.4 + (0.6 * preT))) : (AGI_COMET_ALPHA * (0.6 + (0.4 * growEase)));
    if (reelT > 0) {
        const reelEase = Math.max(0, Math.min(1, reelT));
        alpha *= Math.max(0, 1 - reelEase);
    }
    if (alpha <= 0.01 || scale <= 0.01) {
        fx.setFlag(SpriteFlag.Invisible, true);
        _setAgilityCometAurasVisible(fx, false);
        return;
    }

    const rawFrame = _agiCometPickRawFrame(preActive, preT, growthT, reelT, nowMs, startMs);
    const frameIdx = _strengthArcFrameIndexFromRaw(AGI_SQUARE_COMET_SKIN_ID, rawFrame | 0);
    const tipOffset = _agiCometTipOffsetForRaw(AGI_SQUARE_COMET_SKIN_ID, rawFrame | 0);
    const tailOffset = _agiCometTailOffsetForRaw(AGI_SQUARE_COMET_SKIN_ID, rawFrame | 0);
    const fallbackOffset = _agiCometDirOffset(nx, ny);
    const vis = getHeroVisualInfoForStrength(hero, nx, ny);
    let wTipX = (vis[2] || 0);
    let wTipY = (vis[3] || 0);
    let wTipProj = (wTipX * nx) + (wTipY * ny);
    if (wTipProj < 0) {
        wTipX = -wTipX;
        wTipY = -wTipY;
        wTipProj = -wTipProj;
    }
    let weaponLen = Math.max(0, wTipProj);
    if (weaponLen <= 0) {
        const lead = (vis[1] || 0);
        if (lead > 0) {
            weaponLen = lead;
            wTipX = nx * weaponLen;
            wTipY = ny * weaponLen;
        }
    }
    const weaponTipX = hero.x + wTipX;
    const weaponTipY = hero.y + wTipY;
    let baseX = anchorX;
    let baseY = anchorY;
    if (weaponLen > 0 && (wTipX || wTipY)) {
        baseX = weaponTipX - (nx * weaponLen);
        baseY = weaponTipY - (ny * weaponLen);
    }
    if (weaponLen <= 0) weaponLen = 1;
    const axisScale =
        _agiCometAxisScaleForWeaponLenWithTail(tipOffset, tailOffset, weaponLen) ||
        _agiCometAxisScaleForWeaponLen(tipOffset, weaponLen) ||
        _agiCometAxisScaleForTipOffset(tipOffset) ||
        { sx: 1, sy: 1 };

    sprites.setDataNumber(fx, EFFECT_FRAME_INDEX_DATA_KEY, frameIdx | 0);
    sprites.setDataNumber(fx, EFFECT_ROT_DATA_KEY, rot);
    sprites.setDataNumber(fx, EFFECT_SCALE_DATA_KEY, scale);
    sprites.setDataNumber(fx, EFFECT_SCALE_X_DATA_KEY, axisScale.sx);
    sprites.setDataNumber(fx, EFFECT_SCALE_Y_DATA_KEY, axisScale.sy);
    sprites.setDataNumber(fx, EFFECT_ALPHA_DATA_KEY, Math.max(0, Math.min(1, alpha)));
    sprites.setDataNumber(fx, EFFECT_FLIP_X_DATA_KEY, AGI_SQUARE_COMET_FLIP_X | 0);
    sprites.setDataNumber(fx, EFFECT_FLIP_Y_DATA_KEY, AGI_SQUARE_COMET_FLIP_Y | 0);

    let tipAnchorX = baseX;
    let tipAnchorY = baseY;
    const dirOff = _agiCometAlignDirOffset(nx, ny, false);
    tipAnchorX += (AGI_COMET_ALIGN_OFF_X | 0) + (dirOff.dx | 0);
    tipAnchorY += (AGI_COMET_ALIGN_OFF_Y | 0) + (dirOff.dy | 0);

    let tipX = tipAnchorX;
    let tipY = tipAnchorY;
    const flipX = (AGI_SQUARE_COMET_FLIP_X | 0) !== 0;
    const flipY = (AGI_SQUARE_COMET_FLIP_Y | 0) !== 0;
    const anchorOffset = tailOffset || tipOffset;
    if (anchorOffset) {
        const cos = Math.cos(rot);
        const sin = Math.sin(rot);
        const offDx = (flipX ? -anchorOffset.dx : anchorOffset.dx);
        const offDy = (flipY ? -anchorOffset.dy : anchorOffset.dy);
        const offX = (offDx * scale * (axisScale.sx || 1));
        const offY = (offDy * scale * (axisScale.sy || 1));
        const rotX = (offX * cos) - (offY * sin);
        const rotY = (offX * sin) + (offY * cos);
        tipX = tipAnchorX - rotX;
        tipY = tipAnchorY - rotY;
    } else {
        const fbX = flipX ? -(fallbackOffset.dx | 0) : (fallbackOffset.dx | 0);
        const fbY = flipY ? -(fallbackOffset.dy | 0) : (fallbackOffset.dy | 0);
        tipX = tipAnchorX + fbX;
        tipY = tipAnchorY + fbY;
    }

    fx.x = tipX;
    fx.y = tipY;
    fx.z = (hero.z | 0) + (AGI_COMET_Z_BIAS | 0);
    fx.setFlag(SpriteFlag.Invisible, false);

    _updateWeaponAxisDebugForHero(heroIndex | 0, hero, baseX, baseY, nx, ny, weaponLen | 0);
    _updateCometAxisDebugForFx(
        heroIndex | 0,
        fx,
        baseX,
        baseY,
        rot,
        tipOffset,
        tailOffset,
        axisScale,
        scale
    );

    if (_agiCometAlignShouldLog(fx, nowMs | 0)) {
        let weaponBoxW = 0;
        let weaponBoxH = 0;
        const info = _getHeroWeaponFgInfo(hero);
        if (info && info.frameRef) {
            const ref: any = info.frameRef as any;
            const frameW =
                (typeof ref.width === "number" ? ref.width : undefined) ??
                (typeof ref.realWidth === "number" ? ref.realWidth : undefined) ??
                (typeof ref.cutWidth === "number" ? ref.cutWidth : undefined) ??
                (typeof ref.sourceSizeW === "number" ? ref.sourceSizeW : undefined) ??
                0;
            const frameH =
                (typeof ref.height === "number" ? ref.height : undefined) ??
                (typeof ref.realHeight === "number" ? ref.realHeight : undefined) ??
                (typeof ref.cutHeight === "number" ? ref.cutHeight : undefined) ??
                (typeof ref.sourceSizeH === "number" ? ref.sourceSizeH : undefined) ??
                0;
            if (frameW > 0 && frameH > 0) {
                const sx = Math.abs(info.scaleX || 1);
                const sy = Math.abs(info.scaleY || 1);
                weaponBoxW = frameW * sx;
                weaponBoxH = frameH * sy;
            }
        }
        let cometLen = 0;
        if (tipOffset) {
            const ax = Math.abs(tipOffset.dx || 0);
            const ay = Math.abs(tipOffset.dy || 0);
            const dominant = Math.max(ax, ay);
            const axisS = (ax >= ay) ? (axisScale.sx || 1) : (axisScale.sy || 1);
            cometLen = dominant * 2 * scale * axisS;
        }
        const vis = getHeroVisualInfoForStrength(hero, nx, ny);
        const wTipX = (vis[2] || 0);
        const wTipY = (vis[3] || 0);
        const weaponTipX = hero.x + wTipX;
        const weaponTipY = hero.y + wTipY;
        _agiCometAlignLogLine({
            kind: "dash",
            heroIndex: heroIndex | 0,
            weaponTipX,
            weaponTipY,
            cometTipX: tipX,
            cometTipY: tipY,
            baseX: anchorX,
            baseY: anchorY,
            alignX: tipAnchorX,
            alignY: tipAnchorY,
            nx,
            ny,
            weaponLen: weaponLen | 0,
            tipDist: tipDist | 0,
            scale,
            axisScaleX: axisScale.sx || 1,
            axisScaleY: axisScale.sy || 1,
            rawFrame: rawFrame | 0,
            weaponBoxW,
            weaponBoxH,
            cometLen
        });
    }

    // Aura outlines (r1/r2/r3) around the comet.
    let auraIdxR1 = sprites.readDataNumber(proj, WPN_AURA_COL_R1_KEY) | 0;
    let auraIdxR2 = sprites.readDataNumber(proj, WPN_AURA_COL_R2_KEY) | 0;
    let auraIdxR3 = sprites.readDataNumber(proj, WPN_AURA_COL_R3_KEY) | 0;
    if (!(auraIdxR1 > 0)) {
        const dirKey = _weaponDirKeyFromVector(nx, ny);
        const palette = _weaponAuraPaletteForElement(element | 0, dirKey, "offense");
        auraIdxR1 = palette.r1 | 0;
        auraIdxR2 = palette.r2 | 0;
        auraIdxR3 = palette.r3 | 0;
    }
    const auraTints = [
        _arcadeColorIndexToTint(auraIdxR1 | 0),
        _arcadeColorIndexToTint((auraIdxR2 | 0) || (auraIdxR1 | 0)),
        _arcadeColorIndexToTint((auraIdxR3 | 0) || (auraIdxR2 | 0) || (auraIdxR1 | 0))
    ];
    _ensureAgilityCometAurasForFx(fx, auraTints, (hero.z | 0) + (AGI_COMET_Z_BIAS | 0) + 1);
    const auraKeys = [AGI_COMET_AURA_R1_FX_KEY, AGI_COMET_AURA_R2_FX_KEY, AGI_COMET_AURA_R3_FX_KEY];
    const auraCount = Math.min(STR_ARC_AURA_RADII.length, auraKeys.length, STR_ARC_AURA_ALPHA_BY_RADIUS.length);
    for (let i = 0; i < auraCount; i++) {
        const auraFx = sprites.readDataSprite(fx, auraKeys[i]);
        if (!auraFx || (auraFx.flags & sprites.Flag.Destroyed)) continue;
        const auraSkin = sprites.readDataString(auraFx, "effectSkin") || STR_ARC_SKIN_ID;
        const auraIdx = _strengthArcFrameIndexFromRaw(auraSkin, rawFrame | 0);
        const auraAlpha = Math.min(1, Math.max(0.01, alpha * (STR_ARC_AURA_ALPHA_BY_RADIUS[i] || 0) * AGI_COMET_AURA_ALPHA_MULT));
        sprites.setDataNumber(auraFx, EFFECT_FRAME_INDEX_DATA_KEY, auraIdx | 0);
        sprites.setDataNumber(auraFx, EFFECT_ROT_DATA_KEY, rot);
        sprites.setDataNumber(auraFx, EFFECT_SCALE_DATA_KEY, scale);
        sprites.setDataNumber(auraFx, EFFECT_SCALE_X_DATA_KEY, axisScale.sx);
        sprites.setDataNumber(auraFx, EFFECT_SCALE_Y_DATA_KEY, axisScale.sy);
        sprites.setDataNumber(auraFx, EFFECT_ALPHA_DATA_KEY, auraAlpha);
        sprites.setDataNumber(auraFx, EFFECT_TINT_DATA_KEY, auraTints[i] | 0);
        auraFx.x = tipX;
        auraFx.y = tipY;
        auraFx.z = (hero.z | 0) + (AGI_COMET_Z_BIAS | 0) + 1 + i;
        auraFx.setFlag(SpriteFlag.Invisible, false);
    }

    if (_agiCometShouldLog(fx, nowMs | 0)) {
        _agiCometLogLine({
            kind: "thrust",
            heroIndex: heroIndex | 0,
            ghost: false,
            rawFrame: rawFrame | 0,
            frameIdx: frameIdx | 0,
            moveAngle,
            rot,
            tipX,
            tipY,
            baseX: anchorX,
            baseY: anchorY,
            nx,
            ny,
            scale,
            alpha,
            preActive,
            growthT,
            reelT,
            skinId: AGI_SQUARE_COMET_SKIN_ID
        });
    }

    _updateWeaponTipDebugForHero(heroIndex | 0, hero, nx, ny);
}

function _updateAgilitySquareCometFx(
    proj: Sprite,
    heroIndex: number,
    hero: Sprite,
    element: number,
    nx: number,
    ny: number,
    anchorX: number,
    anchorY: number,
    sBack: number,
    sFront: number,
    maxLen: number,
    growthT: number,
    reelT: number,
    preActive: boolean,
    activateAt: number,
    nowMs: number,
    startMs: number,
    dashMs: number
): void {
    const fx = _ensureAgilitySquareCometFx(proj, heroIndex, hero, element | 0, dashMs | 0);
    if (!fx || (fx.flags & sprites.Flag.Destroyed)) return;

    const preT = _agiCometPreT(preActive, activateAt | 0, nowMs | 0);
    if (preActive && preT <= 0) {
        fx.setFlag(SpriteFlag.Invisible, true);
        _agiSquareCometFillHide(proj);
        if (_agiSquareCometShouldLog(fx, nowMs | 0)) {
            console.log(
                "[AGI][COMET][SQUARE] skip=pre_t0 hero=" + (heroIndex | 0) +
                " pre=1 t=" + (nowMs | 0)
            );
        }
        return;
    }

    const tipDist = _agiCometTipDistance(sBack, sFront, maxLen, reelT);
    const baseTipX = anchorX + nx * tipDist;
    const baseTipY = anchorY + ny * tipDist;

    const moveAngle = Math.atan2(ny, nx);
    const rot = _strengthArcNormalizeAngle(moveAngle - AGI_COMET_SW_BASE_ANGLE);

    const growNorm = Math.max(0, Math.min(1, growthT / Math.max(0.0001, AGI_COMET_GROW_END_T)));
    const growEase = Math.pow(growNorm, AGI_COMET_GROW_EXP);

    let scale = AGI_SQUARE_COMET_SCALE * (0.55 + (0.45 * growEase));
    if (preActive) scale *= 0.75;
    if (reelT > 0) {
        const reelEase = Math.max(0, Math.min(1, reelT));
        scale *= Math.max(AGI_COMET_END_SCALE, 1 - (0.7 * reelEase));
    }

    let alpha = preActive ? (AGI_COMET_PREACTIVE_ALPHA * (0.4 + (0.6 * preT))) : (AGI_SQUARE_COMET_ALPHA * (0.6 + (0.4 * growEase)));
    if (reelT > 0) {
        const reelEase = Math.max(0, Math.min(1, reelT));
        alpha *= Math.max(0, 1 - reelEase);
    }
    if (alpha <= 0.01 || scale <= 0.01) {
        fx.setFlag(SpriteFlag.Invisible, true);
        _agiSquareCometFillHide(proj);
        if (_agiSquareCometShouldLog(fx, nowMs | 0)) {
            console.log(
                "[AGI][COMET][SQUARE] skip=alpha_scale hero=" + (heroIndex | 0) +
                " alpha=" + alpha.toFixed(3) +
                " scale=" + scale.toFixed(3) +
                " t=" + (nowMs | 0)
            );
        }
        return;
    }

    const partRaw = (sprites.readDataString(hero, HERO_DATA.PhasePartName) || "").trim().toLowerCase();
    const partProgRaw = sprites.readDataNumber(hero, HERO_DATA.PhasePartProgress) | 0;
    const partT = (partProgRaw > 0) ? Math.max(0, Math.min(1, (partProgRaw | 0) / PHASE_PROGRESS_MAX)) : 0;
    const pick = (seq: number[], t: number): number => _strengthArcPickFromSequence(seq, t, 1, false);

    let rawFrame = 0;
    if (preActive || partRaw === "windup") {
        const t = (partRaw === "windup" && partProgRaw > 0) ? partT : Math.max(0, Math.min(1, preT));
        rawFrame = pick(AGI_SQUARE_COMET_GROW_RAW, t);
    } else if (partRaw === "forward") {
        const t = (partProgRaw > 0) ? partT : Math.max(0, Math.min(1, growthT));
        rawFrame = pick([3, 4], t);
    } else if (partRaw === "landing") {
        const t = (partProgRaw > 0) ? partT : Math.max(0, Math.min(1, reelT));
        rawFrame = pick(AGI_SQUARE_COMET_REEL_RAW, t);
    } else {
        if (reelT > 0) rawFrame = pick(AGI_SQUARE_COMET_REEL_RAW, Math.max(0, Math.min(1, reelT)));
        else rawFrame = pick(AGI_SQUARE_COMET_GROW_RAW, Math.max(0, Math.min(1, growthT)));
    }

    const frameIdx = _strengthArcFrameIndexFromRaw(AGI_SQUARE_COMET_SKIN_ID, rawFrame | 0);
    const tipOffset = _agiCometTipOffsetForRaw(AGI_SQUARE_COMET_SKIN_ID, rawFrame | 0);
    const fallbackOffset = _agiCometDirOffset(nx, ny);
    const info = _getHeroWeaponFgInfo(hero);
    let baseX = hero.x;
    let baseY = hero.y;
    let weaponLen = 0;
    let weaponTipX = hero.x;
    let weaponTipY = hero.y;
    if (info) {
        baseX = hero.x + (info.offX || 0);
        baseY = hero.y + (info.offY || 0);
        const lead = _weaponLeadingEdgeForFrameIndex(info, STR_WPN_AURA_OUTLINE_RADIUS | 0, nx, ny, 0);
        if (Number.isFinite(lead) && lead > 0) {
            weaponLen = Math.round(lead);
            weaponTipX = baseX + nx * weaponLen;
            weaponTipY = baseY + ny * weaponLen;
        }
    }
    if (weaponLen <= 0) {
        const vis = getHeroVisualInfoForStrength(hero, nx, ny);
        let wTipX = (vis[2] || 0);
        let wTipY = (vis[3] || 0);
        let wTipProj = (wTipX * nx) + (wTipY * ny);
        if (wTipProj < 0) {
            wTipX = -wTipX;
            wTipY = -wTipY;
            wTipProj = -wTipProj;
        }
        if (wTipProj > 0) {
            weaponLen = Math.round(wTipProj);
            weaponTipX = hero.x + wTipX;
            weaponTipY = hero.y + wTipY;
            baseX = weaponTipX - nx * weaponLen;
            baseY = weaponTipY - ny * weaponLen;
        } else {
            const lead = (vis[1] || 0);
            if (lead > 0) {
                weaponLen = Math.round(lead);
                baseX = hero.x;
                baseY = hero.y;
                weaponTipX = baseX + nx * weaponLen;
                weaponTipY = baseY + ny * weaponLen;
            }
        }
    }
    if (weaponLen <= 0) weaponLen = 1;
    const tailOffset = _agiCometTailOffsetForRaw(AGI_SQUARE_COMET_SKIN_ID, rawFrame | 0);
    const axisScale =
        _agiCometAxisScaleForWeaponLenWithTail(tipOffset, tailOffset, weaponLen) ||
        _agiCometAxisScaleForWeaponLen(tipOffset, weaponLen) ||
        _agiCometAxisScaleForTipOffset(tipOffset) ||
        { sx: 1, sy: 1 };
    sprites.setDataNumber(fx, EFFECT_FRAME_INDEX_DATA_KEY, frameIdx | 0);
    sprites.setDataNumber(fx, EFFECT_ROT_DATA_KEY, rot);
    sprites.setDataNumber(fx, EFFECT_SCALE_DATA_KEY, scale);
    sprites.setDataNumber(fx, EFFECT_SCALE_X_DATA_KEY, axisScale.sx);
    sprites.setDataNumber(fx, EFFECT_SCALE_Y_DATA_KEY, axisScale.sy);
    sprites.setDataNumber(fx, EFFECT_ALPHA_DATA_KEY, Math.max(0, Math.min(1, alpha)));
    sprites.setDataNumber(fx, EFFECT_FLIP_X_DATA_KEY, 0);
    sprites.setDataNumber(fx, EFFECT_FLIP_Y_DATA_KEY, 0);
    const elemTint = _elementTintForMode(_heroBodyEffectElement(hero, element | 0) | 0, "offense") | 0;

    const dirOff = _agiCometAlignDirOffset(nx, ny, true);
    const sideX = -ny;
    const sideY = nx;
    let tipAnchorX = baseX +
        (AGI_SQUARE_COMET_ALIGN_OFF_X | 0) +
        (dirOff.dx | 0) +
        (nx * (AGI_SQUARE_COMET_ALIGN_FWD_PX | 0)) +
        (sideX * (AGI_SQUARE_COMET_ALIGN_SIDE_PX | 0));
    let tipAnchorY = baseY +
        (AGI_SQUARE_COMET_ALIGN_OFF_Y | 0) +
        (dirOff.dy | 0) +
        (ny * (AGI_SQUARE_COMET_ALIGN_FWD_PX | 0)) +
        (sideY * (AGI_SQUARE_COMET_ALIGN_SIDE_PX | 0));
    const anchorOffset = tailOffset || tipOffset;
    let tipX = tipAnchorX;
    let tipY = tipAnchorY;
    if (anchorOffset) {
        const cos = Math.cos(rot);
        const sin = Math.sin(rot);
        const offX = (anchorOffset.dx * scale * (axisScale.sx || 1));
        const offY = (anchorOffset.dy * scale * (axisScale.sy || 1));
        const rotX = (offX * cos) - (offY * sin);
        const rotY = (offX * sin) + (offY * cos);
        tipX = tipAnchorX - rotX;
        tipY = tipAnchorY - rotY;
    } else {
        tipX = tipAnchorX + (fallbackOffset.dx | 0);
        tipY = tipAnchorY + (fallbackOffset.dy | 0);
    }

    fx.x = tipX;
    fx.y = tipY;
    fx.z = (hero.z | 0) + (AGI_SQUARE_COMET_Z_BIAS | 0);
    fx.setFlag(SpriteFlag.Invisible, false);

    const fillDir = _enemyDirFromVector(nx, ny);
    const fillFx = _ensureAgilitySquareCometFillFx(proj, fx, element | 0, fillDir);
    if (fillFx && !(fillFx.flags & sprites.Flag.Destroyed)) {
        fillFx.x = tipX;
        fillFx.y = tipY;
        fillFx.z = (fx.z | 0) - 1;
        fillFx.setFlag(SpriteFlag.Invisible, false);
        sprites.setDataNumber(fillFx, EFFECT_ROT_DATA_KEY, rot);
        sprites.setDataNumber(fillFx, EFFECT_SCALE_DATA_KEY, scale);
        sprites.setDataNumber(fillFx, EFFECT_SCALE_X_DATA_KEY, axisScale.sx);
        sprites.setDataNumber(fillFx, EFFECT_SCALE_Y_DATA_KEY, axisScale.sy);
        sprites.setDataNumber(fillFx, EFFECT_ALPHA_DATA_KEY, Math.max(0, Math.min(1, alpha)));
        sprites.setDataNumber(fx, EFFECT_TINT_DATA_KEY, 0);
    } else {
        if (elemTint) sprites.setDataNumber(fx, EFFECT_TINT_DATA_KEY, elemTint | 0);
        else sprites.setDataNumber(fx, EFFECT_TINT_DATA_KEY, 0);
    }

    _updateWeaponAxisDebugForHero(heroIndex | 0, hero, baseX, baseY, nx, ny, weaponLen | 0);
    _updateCometAxisDebugForFx(
        heroIndex | 0,
        fx,
        baseX,
        baseY,
        rot,
        tipOffset,
        tailOffset,
        axisScale,
        scale
    );

    if (_agiCometAlignShouldLog(fx, nowMs | 0)) {
        _agiCometAlignLogLine({
            kind: "dash.square",
            heroIndex: heroIndex | 0,
            weaponTipX,
            weaponTipY,
            cometTipX: tipX,
            cometTipY: tipY,
            baseX: anchorX,
            baseY: anchorY,
            alignX: tipAnchorX,
            alignY: tipAnchorY,
            nx,
            ny,
            weaponLen: weaponLen | 0,
            tipDist: tipDist | 0,
            scale,
            axisScaleX: axisScale.sx || 1,
            axisScaleY: axisScale.sy || 1,
            rawFrame: rawFrame | 0
        });
    }

    if (_agiSquareCometShouldLog(fx, nowMs | 0)) {
        console.log(
            "[AGI][COMET][SQUARE] show=1 hero=" + (heroIndex | 0) +
            " raw=" + (rawFrame | 0) +
            " idx=" + (frameIdx | 0) +
            " pos=" + tipX.toFixed(1) + "," + tipY.toFixed(1) +
            " scale=" + scale.toFixed(3) +
            " alpha=" + alpha.toFixed(3)
        );
    }

    if (_agiSquareCometShouldLog(fx, nowMs | 0)) {
        _agiCometLogLine({
            kind: "thrust.square",
            heroIndex: heroIndex | 0,
            ghost: false,
            rawFrame: rawFrame | 0,
            frameIdx: frameIdx | 0,
            moveAngle,
            rot,
            tipX,
            tipY,
            baseX: anchorX,
            baseY: anchorY,
            nx,
            ny,
            scale,
            alpha,
            preActive,
            growthT,
            reelT,
            skinId: AGI_SQUARE_COMET_SKIN_ID
        });
    }

    _updateWeaponTipDebugForHero(heroIndex | 0, hero, nx, ny);
}

function _updateAgilityTrailFxSegments(
    proj: Sprite,
    hero: Sprite,
    anchorX: number,
    anchorY: number,
    nx: number,
    ny: number,
    sBackAtCast: number,
    revealFront: number,
    maxLen: number,
    nowMs: number
): void {
    if (AGI_DISABLE_LEGACY_AGI_TRAIL_FX) return;
    if (!proj || !hero) return;
    const count = sprites.readDataNumber(proj, AGI_FX_SEG_COUNT_KEY) | 0;
    if (count <= 0) return;
    const lenMax = Math.max(1, maxLen | 0);
    const curLen = Math.max(0, Math.min(lenMax, (revealFront - sBackAtCast)));
    if (!(curLen > 0)) {
        _hideAgilityTrailFxSegments(proj);
        return;
    }
    const lenActive = Math.max(1, curLen | 0);
    const tipSide = sprites.readDataNumber(proj, AGI_TIP_SIDE_PX_KEY);
    const sx = -ny;
    const sy = nx;
    const offX = Number.isFinite(tipSide) ? (sx * tipSide) : 0;
    const offY = Number.isFinite(tipSide) ? (sy * tipSide) : 0;

    for (let i = 0; i < count; i++) {
        const fx = sprites.readDataSprite(proj, _agilityTrailFxSegKey(i));
        if (!fx || (fx.flags & sprites.Flag.Destroyed)) continue;
        const s = sBackAtCast + (lenActive * ((i + 0.5) / count));
        const isActive = true;
        if (!isActive) {
            fx.setFlag(SpriteFlag.Invisible, true);
            sprites.setDataNumber(fx, AGI_FX_SEG_ACTIVE_KEY, 0);
            continue;
        }
        const wasActive = (sprites.readDataNumber(fx, AGI_FX_SEG_ACTIVE_KEY) | 0) !== 0;
        fx.setFlag(SpriteFlag.Invisible, false);
        if (!wasActive) {
            sprites.setDataNumber(fx, AGI_FX_SEG_ACTIVE_KEY, 1);
            sprites.setDataNumber(fx, EFFECT_INTRO_START_MS_DATA_KEY, nowMs | 0);
        }
        fx.x = (anchorX + (nx * s) + offX);
        fx.y = (anchorY + (ny * s) + offY);
        fx.z = (hero.z | 0) + (AGI_FX_SEG_Z_BIAS | 0);
        const scaleRaw = sprites.readDataNumber(fx, EFFECT_SCALE_DATA_KEY);
        const scale = (Number.isFinite(scaleRaw) && scaleRaw > 0) ? scaleRaw : 1;
        const topY = (anchorY + (sprites.readDataNumber(proj, AGI_TEX_MIN_Y_KEY) | 0)) | 0;
        const alignBottomY = topY + Math.round((WEAPON_TILE_FX_SIZE_PX | 0) * scale);
        sprites.setDataNumber(fx, EFFECT_ALIGN_BOTTOM_Y_DATA_KEY, alignBottomY | 0);
    }
}

function _updateStrengthSwingFxSegments(
    proj: Sprite,
    hero: Sprite,
    t: number,
    nx: number,
    ny: number,
    inner0: number,
    frontStartR: number,
    reachFromFront: number,
    totalArcDeg: number
): void {
    if (!proj || !hero) return;
    const count = sprites.readDataNumber(proj, STR_FX_SEG_COUNT_KEY) | 0;
    if (count <= 0) return;

    const baseX = (proj.x | 0);
    const baseY = (proj.y | 0);
    const baseZ = (proj.z | 0);

    const outerR = (inner0 | 0) + (reachFromFront | 0);
    const thickness = Math.max(1, (outerR - (inner0 | 0)) | 0);
    const rInner = (inner0 | 0) + Math.idiv(thickness * STR_FX_SEG_INNER_PCT_X1000, 1000);
    const rOuter = (inner0 | 0) + Math.idiv(thickness * STR_FX_SEG_OUTER_PCT_X1000, 1000);
    const sx = -ny;
    const sy = nx;

    const PHASE1_FRAC = 0.25;
    const tClamped = Math.max(0, Math.min(1, t));
    const dirForward = _enemyDirFromVector(nx, ny);

    if (tClamped <= PHASE1_FRAC) {
        const thrustT = tClamped / PHASE1_FRAC;
        const tipR = (inner0 | 0) + Math.round((reachFromFront | 0) * thrustT);
        const startR = Math.min(frontStartR | 0, tipR | 0);
        const len = Math.max(1, (tipR - startR) | 0);
        for (let i = 0; i < count; i++) {
            const fx = sprites.readDataSprite(proj, _strengthSwingFxSegKey(i));
            if (!fx || (fx.flags & sprites.Flag.Destroyed)) continue;
            const s = startR + Math.round(len * ((i + 0.5) / count));
            fx.x = baseX + nx * s;
            fx.y = baseY + ny * s;
            fx.z = baseZ + (STR_FX_SEG_Z_BIAS | 0);
            const distFrac = len > 0 ? Math.max(0, Math.min(1, (s - startR) / len)) : 0;
            const alpha = STR_FX_SEG_ALPHA * (STR_FX_TIP_ALPHA_MIN + ((1 - STR_FX_TIP_ALPHA_MIN) * (1 - distFrac)));
            sprites.setDataNumber(fx, EFFECT_ALPHA_DATA_KEY, alpha);
            _strengthFxUpdateDir(fx, dirForward);
            if (WEAPON_TILE_FX_MIRROR) {
                const mirror = ((i % 2) === 1);
                const horiz = Math.abs(nx) >= Math.abs(ny);
                sprites.setDataNumber(fx, EFFECT_FLIP_X_DATA_KEY, mirror && horiz ? 1 : 0);
                sprites.setDataNumber(fx, EFFECT_FLIP_Y_DATA_KEY, mirror && !horiz ? 1 : 0);
            }
        }
        return;
    }

    const sweepT = (tClamped - PHASE1_FRAC) / (1 - PHASE1_FRAC);
    const halfArcRadMax = ((totalArcDeg | 0) * 0.5) * (Math.PI / 180);
    const travelRad = halfArcRadMax * sweepT;
    const perArc = Math.max(1, Math.idiv(count, 2) | 0);
    const spread = Math.max(0.02, (halfArcRadMax * (STR_FX_SEG_CLUSTER_SPREAD_PCT_X1000 | 0) / 1000));
    const step = (perArc > 1) ? (spread / (perArc - 1)) : 0;

    for (let i = 0; i < count; i++) {
        const fx = sprites.readDataSprite(proj, _strengthSwingFxSegKey(i));
        if (!fx || (fx.flags & sprites.Flag.Destroyed)) continue;

        const arcIdx = (i < perArc) ? 0 : 1;
        const local = (arcIdx === 0) ? i : (i - perArc);
        const arcSign = (arcIdx === 0) ? -1 : 1;
        const baseAng = arcSign * travelRad;
        const offset = (local - ((perArc - 1) / 2)) * step;
        const a = baseAng + offset;

        const cosA = Math.cos(a);
        const sinA = Math.sin(a);
        const dxDir = nx * cosA + sx * sinA;
        const dyDir = ny * cosA + sy * sinA;
        const r = (local % 2 === 0) ? rOuter : rInner;
        fx.x = baseX + dxDir * r;
        fx.y = baseY + dyDir * r;
        fx.z = baseZ + (STR_FX_SEG_Z_BIAS | 0);
        const distFrac = (rOuter > rInner) ? Math.max(0, Math.min(1, (r - rInner) / (rOuter - rInner))) : 0;
        const alpha = STR_FX_SEG_ALPHA * (STR_FX_TIP_ALPHA_MIN + ((1 - STR_FX_TIP_ALPHA_MIN) * (1 - distFrac)));
        sprites.setDataNumber(fx, EFFECT_ALPHA_DATA_KEY, alpha);
        _strengthFxUpdateDir(fx, _enemyDirFromVector(dxDir, dyDir));
        if (WEAPON_TILE_FX_MIRROR) {
            const mirror = ((i % 2) === 1);
            const horiz = Math.abs(dxDir) >= Math.abs(dyDir);
            sprites.setDataNumber(fx, EFFECT_FLIP_X_DATA_KEY, mirror && horiz ? 1 : 0);
            sprites.setDataNumber(fx, EFFECT_FLIP_Y_DATA_KEY, mirror && !horiz ? 1 : 0);
        }
    }
}

function _setStrengthSwingFxSegmentsVisible(proj: Sprite, visible: boolean): void {
    if (!proj) return;
    const count = sprites.readDataNumber(proj, STR_FX_SEG_COUNT_KEY) | 0;
    if (count <= 0) return;
    const hide = !visible;
    for (let i = 0; i < count; i++) {
        const fx = sprites.readDataSprite(proj, _strengthSwingFxSegKey(i));
        if (!fx || (fx.flags & sprites.Flag.Destroyed)) continue;
        fx.setFlag(SpriteFlag.Invisible, hide);
    }
}

