function _getEffectAtlasAny(): any {
    const g: any = globalThis as any;
    return (
        (g && g.__effectAtlas) ||
        (g && g.__phaserScene && g.__phaserScene.registry?.get?.("effectAtlas")) ||
        null
    );
}

function _resolveEffectEntry(atlas: any, skinId: string, dir?: string): any {
    if (!atlas || !skinId) return null;
    let resolved = atlas[skinId] || null;
    if (!resolved && dir) {
        const dirLower = String(dir || "").trim().toLowerCase();
        const suffixes = [`_${dirLower}`, `-${dirLower}`, ` ${dirLower}`];
        for (const suffix of suffixes) {
            const candidate = `${skinId}${suffix}`;
            if (atlas[candidate]) {
                resolved = atlas[candidate];
                break;
            }
        }
    }
    return resolved;
}

let __strengthArcRawToLogicalCache: { [k: string]: number } = Object.create(null);
let __strengthArcFrameIndexCacheAtlasRef: any = null;
const __strengthArcTexturePickCache: { [k: string]: { skinId: string; dir?: string } | null } = Object.create(null);
const __strengthArcEllipsePickCache: { [k: string]: { skinId: string; dir?: string } | null } = Object.create(null);
const __strengthArcEdgeFrameListCache: { [row: number]: string } = Object.create(null);
const STR_ARC_EDGE_COL_YOYO = [0, 1, 2, 3, 4, 5, 4, 3, 2, 1, 0];

type StrengthArcFramePick = { row: number; col: number; baseAngle: number };

const STR_ARC_FULL_FRAME_CANDIDATES: StrengthArcFramePick[] = [
    { row: 0, col: 0, baseAngle: Math.PI / 2 },           // down
    { row: 0, col: 1, baseAngle: Math.PI / 4 },           // down-right
    { row: 0, col: 2, baseAngle: -Math.PI / 4 },          // up-right
    { row: 0, col: 3, baseAngle: -3 * Math.PI / 4 },      // up-left
    { row: 0, col: 4, baseAngle: Math.PI },               // left
    { row: 1, col: 1, baseAngle: 3 * Math.PI / 4 },       // down-left
    { row: 1, col: 3, baseAngle: 0 },                     // right
    { row: 1, col: 2, baseAngle: Math.PI / 2 }            // almost down
];

const STR_ARC_WISPY_FRAME_CANDIDATES: StrengthArcFramePick[] = [
    { row: 2, col: 0, baseAngle: Math.PI },               // left
    { row: 2, col: 1, baseAngle: Math.PI / 4 },           // down-right
    { row: 2, col: 2, baseAngle: Math.PI / 2.6 },         // down-ish
    { row: 2, col: 3, baseAngle: Math.PI / 2 },           // down
    { row: 2, col: 4, baseAngle: Math.PI / 2 },           // down
    { row: 2, col: 5, baseAngle: Math.PI / 2 }            // down
];

const STR_ARC_PRECURSOR_LEFT: StrengthArcFramePick = { row: 1, col: 5, baseAngle: -Math.PI / 4 };
const STR_ARC_PRECURSOR_RIGHT: StrengthArcFramePick = { row: 1, col: 0, baseAngle: Math.PI / 2 };

function _strengthArcPickNearestFrame(angleRad: number, candidates: StrengthArcFramePick[]): StrengthArcFramePick {
    let best = candidates[0];
    let bestDiff = 999;
    const ang = angleRad;
    for (const cand of candidates) {
        let diff = Math.abs(ang - cand.baseAngle);
        if (diff > Math.PI) diff = (Math.PI * 2) - diff;
        if (diff < bestDiff) {
            bestDiff = diff;
            best = cand;
        }
    }
    return best;
}

function _strengthArcFrameIndexForCell(skinId: string, row: number, col: number): number {
    const rawIndex = (row * STR_ARC_SHEET_COLS) + col;
    return _strengthArcFrameIndexFromRaw(skinId, rawIndex);
}

function _strengthArcFrameIndexFromRaw(skinId: string, rawIndex: number): number {
    const raw = Math.max(0, rawIndex | 0);
    const atlas = _getEffectAtlasAny();
    if (atlas && atlas !== __strengthArcFrameIndexCacheAtlasRef) {
        __strengthArcRawToLogicalCache = Object.create(null);
        __strengthArcFrameIndexCacheAtlasRef = atlas;
    }
    const rawCacheKey = `${skinId}|raw|${raw}`;
    if (Object.prototype.hasOwnProperty.call(__strengthArcRawToLogicalCache, rawCacheKey)) {
        return __strengthArcRawToLogicalCache[rawCacheKey] | 0;
    }
    if (!atlas) {
        __strengthArcRawToLogicalCache[rawCacheKey] = raw;
        return raw;
    }
    const resolved = _resolveEffectEntry(atlas, skinId, "");
    const frames = resolved?.frameIndices as number[] | undefined;
    if (!frames || !frames.length) {
        __strengthArcRawToLogicalCache[rawCacheKey] = raw;
        return raw;
    }
    const found = frames.indexOf(raw);
    const idx = (found >= 0) ? found : Math.max(0, Math.min(frames.length - 1, raw));
    __strengthArcRawToLogicalCache[rawCacheKey] = idx | 0;
    return idx | 0;
}

type StrengthArcCompassDir = "N" | "NE" | "E" | "SE" | "S" | "SW" | "W" | "NW";

// Canonical raw-frame spine directions (based on your on-screen #N references).
const __strengthArcSpineByRaw: Record<number, StrengthArcCompassDir> = {
    30: "S",
    35: "SW",
    100: "E",
    105: "SE",
    31: "E",
    36: "NW",
    101: "NE",
    106: "SE",
    32: "NE",
    37: "SW",
    102: "SE",
    107: "SE",
    33: "NW",
    38: "S",
    103: "SE",
    108: "SE"
};

function _strengthArcCompassAngle(dir: StrengthArcCompassDir): number {
    switch (dir) {
        case "N": return -Math.PI / 2;
        case "NE": return -Math.PI / 4;
        case "E": return 0;
        case "SE": return Math.PI / 4;
        case "S": return Math.PI / 2;
        case "SW": return (3 * Math.PI) / 4;
        case "W": return Math.PI;
        case "NW": return (-3 * Math.PI) / 4;
        default: return 0;
    }
}

function _strengthArcNormalizeAngle(rad: number): number {
    let out = rad;
    while (out > Math.PI) out -= Math.PI * 2;
    while (out < -Math.PI) out += Math.PI * 2;
    return out;
}

function _strengthArcSpineAngleForRaw(rawFrame: number, flipX: boolean, fallbackAngle: number): number {
    const dir = __strengthArcSpineByRaw[rawFrame | 0];
    let ang = dir ? _strengthArcCompassAngle(dir) : fallbackAngle;
    if (flipX) ang = Math.PI - ang;
    return _strengthArcNormalizeAngle(ang);
}

function _strengthArcPickFromSequence(seq: number[], t: number, loops: number, reverse: boolean): number {
    if (!seq.length) return 0;
    const clampedT = Math.max(0, Math.min(1, Number.isFinite(t) ? t : 0));
    const loopCount = Math.max(1, Number.isFinite(loops) ? loops : 1);
    const span = seq.length;
    let idx = 0;
    if (loopCount <= 1) {
        idx = Math.min(span - 1, Math.floor(clampedT * span));
    } else {
        const steps = Math.floor(clampedT * span * loopCount);
        idx = steps % span;
    }
    if (reverse) idx = (span - 1 - idx);
    return seq[idx] | 0;
}

function _strengthArcResolveVariantSkin(baseId: string, dir: string, variant: string): { skinId: string; dir?: string } | null {
    if (!baseId) return null;
    const atlas = _getEffectAtlasAny();
    const useDir = String(dir || "").trim().toLowerCase();
    const baseNorm = baseId.includes("_") ? baseId.replace(/_/g, " ") : baseId;
    const baseCandidates = baseNorm && baseNorm !== baseId ? [baseNorm, baseId] : [baseId];

    if (!atlas) {
        const base = baseCandidates[0];
        const dirInfixId = useDir ? `${base} ${useDir} ${variant}`.trim() : "";
        if (dirInfixId) return { skinId: dirInfixId };
        const variantId = `${base} ${variant}`.trim();
        return variantId ? { skinId: variantId, dir: useDir || undefined } : null;
    }

    for (const base of baseCandidates) {
        const dirInfixId = useDir ? `${base} ${useDir} ${variant}`.trim() : "";
        const variantId = `${base} ${variant}`.trim();
        if (dirInfixId && _resolveEffectEntry(atlas, dirInfixId, "")) {
            return { skinId: dirInfixId };
        }
        if (variantId && _resolveEffectEntry(atlas, variantId, useDir)) {
            return { skinId: variantId, dir: useDir || undefined };
        }
        if (_resolveEffectEntry(atlas, base, useDir)) {
            return { skinId: base, dir: useDir || undefined };
        }
    }
    return null;
}

function _strengthArcTexturePick(element: number, dir: string): { skinId: string; dir?: string } | null {
    const key = `${element | 0}|${dir || ""}`;
    if (Object.prototype.hasOwnProperty.call(__strengthArcTexturePickCache, key)) {
        return __strengthArcTexturePickCache[key];
    }
    const pick = _heroSpellEffectPick(element | 0, dir || "down", "offense");
    if (!pick || !pick.skinId) {
        __strengthArcTexturePickCache[key] = null;
        return null;
    }
    const resolved = _strengthArcResolveVariantSkin(pick.skinId, pick.dir || dir || "", "texture");
    __strengthArcTexturePickCache[key] = resolved;
    return resolved;
}

function _strengthArcEllipseTexturePick(element: number, dir: string): { skinId: string; dir?: string } | null {
    const key = `${element | 0}|${dir || ""}`;
    if (Object.prototype.hasOwnProperty.call(__strengthArcEllipsePickCache, key)) {
        return __strengthArcEllipsePickCache[key];
    }
    const pick = _heroSpellEffectPick(element | 0, dir || "down", "offense");
    if (!pick || !pick.skinId) {
        __strengthArcEllipsePickCache[key] = null;
        return null;
    }
    const resolved = _strengthArcResolveVariantSkin(pick.skinId, pick.dir || dir || "", "ellipses");
    if (resolved && !String(resolved.skinId).toLowerCase().includes("ellipses")) {
        __strengthArcEllipsePickCache[key] = null;
        return null;
    }
    __strengthArcEllipsePickCache[key] = resolved;
    return resolved;
}

function _strengthArcEdgeRowForRadius(radiusPx: number): { row: number; rowRadius: number } {
    const biased = Math.max(
        STR_ARC_EDGE_ELLIPSE_MIN_R,
        Math.min(STR_ARC_EDGE_ELLIPSE_MAX_R, (radiusPx + STR_ARC_EDGE_RADIUS_BIAS_PX))
    );
    let row = Math.round((biased - STR_ARC_EDGE_ELLIPSE_MIN_R) / STR_ARC_EDGE_ELLIPSE_STEP_R);
    if (row < 0) row = 0;
    if (row >= STR_ARC_EDGE_ELLIPSE_ROWS) row = STR_ARC_EDGE_ELLIPSE_ROWS - 1;
    let rowRadius = STR_ARC_EDGE_ELLIPSE_MIN_R + (row * STR_ARC_EDGE_ELLIPSE_STEP_R);
    if (rowRadius > biased && row > 0) {
        row -= 1;
        rowRadius -= STR_ARC_EDGE_ELLIPSE_STEP_R;
    }
    return { row: row | 0, rowRadius: rowRadius | 0 };
}

function _strengthArcEdgeFrameListRaw(row: number): string {
    const r = Math.max(0, Math.min(STR_ARC_EDGE_ELLIPSE_ROWS - 1, row | 0)) | 0;
    const cached = __strengthArcEdgeFrameListCache[r];
    if (cached) return cached;
    const base = (r * STR_ARC_EDGE_ELLIPSE_COLS) | 0;
    const raw = STR_ARC_EDGE_COL_YOYO.map((c) => base + (c | 0));
    const out = raw.join(",");
    __strengthArcEdgeFrameListCache[r] = out;
    return out;
}

function _strengthArcAuraSkinForEffect(baseSkinId: string, radius: number): string | null {
    const base = String(baseSkinId || "").trim();
    if (!base) return null;
    const r = Math.max(1, radius | 0);
    const auraId = `${base}_aura_r${r}`;
    const atlas = _getEffectAtlasAny();
    if (atlas && _resolveEffectEntry(atlas, auraId, "")) return auraId;
    return null;
}

function _strengthArcHighlightTints(
    element: number,
    auraIdxR1: number,
    auraIdxR2: number,
    auraIdxR3: number
): { primary: number; secondary: number } {
    const rawIdx = [auraIdxR1 | 0, auraIdxR2 | 0, auraIdxR3 | 0];
    const tints = rawIdx.map((v) => _arcadeColorIndexToTint(v));
    const isBad = (c: number) => (c | 0) === 0x000000 || (c | 0) === 0xffffff;
    let primary = tints.find((c) => !isBad(c)) || 0;
    if (!primary) {
        const elemTint = _elementTintForMode(element | 0, "offense") | 0;
        if (elemTint && !isBad(elemTint)) primary = elemTint;
    }
    if (!primary) primary = tints[0] || 0xff8135;

    let secondary = tints.find((c) => !isBad(c) && (c | 0) !== (primary | 0)) || 0;
    if (!secondary) {
        const elemTint = _elementTintForMode(element | 0, "offense") | 0;
        if (elemTint && !isBad(elemTint) && (elemTint | 0) !== (primary | 0)) secondary = elemTint;
    }
    return { primary: primary | 0, secondary: secondary | 0 };
}

function _strengthArcTerrainPaletteKey(): string {
    const raw = typeof _dunThemePalette === "string" ? _dunThemePalette : "";
    return String(raw || "").trim().toLowerCase();
}

function _strengthArcTerrainHue(palette: string): number {
    switch (String(palette || "").trim().toLowerCase()) {
        case "stone_light":
        case "stone_medium":
            return 210;
        case "volcanic":
            return 15;
        case "obsidian":
            return 260;
        case "void":
            return 280;
        case "desert":
        case "desert_oasis":
            return 45;
        case "meadow":
        case "forest":
        case "forest_dark":
            return 120;
        default:
            return -1;
    }
}

function _strengthArcTerrainIsDark(palette: string): boolean {
    switch (String(palette || "").trim().toLowerCase()) {
        case "volcanic":
        case "obsidian":
        case "void":
        case "forest_dark":
            return true;
        default:
            return false;
    }
}

function _strengthArcSoftHaloTint(baseTint: number): number {
    const fallback = baseTint | 0;
    if (!STR_ARC_SOFT_HALO_TERRAIN_CONTRAST_ENABLED) return fallback;
    const palette = _strengthArcTerrainPaletteKey();
    if (!palette) return fallback;
    const hue = _strengthArcTerrainHue(palette);
    if (hue < 0) return fallback;
    const light = _strengthArcTerrainIsDark(palette)
        ? STR_ARC_SOFT_HALO_TERRAIN_LIGHT_DARK
        : STR_ARC_SOFT_HALO_TERRAIN_LIGHT;
    const contrastHue = (hue + STR_ARC_SOFT_HALO_TERRAIN_CONTRAST_DEG) % 360;
    const tint = _hslToRgbHex(contrastHue, STR_ARC_SOFT_HALO_TERRAIN_SAT, light);
    return (tint | 0) || fallback;
}

function _strengthArcTrailListForProj(proj: Sprite): Sprite[] {
    const id = proj?.id ? (proj.id | 0) : 0;
    if (!id) return [];
    let list = __strengthArcTrailsByProjId.get(id);
    if (!list) {
        list = [];
        __strengthArcTrailsByProjId.set(id, list);
    }
    return list;
}

function _destroyStrengthArcTrailsForProj(proj: Sprite): void {
    const id = proj?.id ? (proj.id | 0) : 0;
    if (!id) return;
    const list = __strengthArcTrailsByProjId.get(id);
    if (list && list.length) {
        for (const fx of list) {
            if (fx && !(fx.flags & sprites.Flag.Destroyed)) fx.destroy();
            const mask = fx ? sprites.readDataSprite(fx, STR_ARC_TRAIL_MASK_FX_KEY) : null;
            if (mask && !(mask.flags & sprites.Flag.Destroyed)) mask.destroy();
        }
    }
    __strengthArcTrailsByProjId.delete(id);
    __strengthArcTrailLastPosByProjId.delete(id);
}

function _strengthArcTrailMaybeSpawn(
    proj: Sprite,
    hero: Sprite,
    nowMs: number,
    isSlashSeg: boolean,
    slashT: number,
    frameIdx: number,
    rot: number,
    scale: number,
    flipX: boolean,
    x: number,
    y: number,
    tint: number,
    fillSkin: string,
    fillDir: string,
    fillFx: Sprite | null
): void {
    if (!STR_ARC_TRAIL_ENABLED || !proj || !hero) return;
    if (!isSlashSeg) return;
    const id = proj.id | 0;
    if (!id) return;
    const lastPos = __strengthArcTrailLastPosByProjId.get(id);
    const step = Math.max(1, STR_ARC_TRAIL_STEP_PX | 0);
    const spawnAt = (sx: number, sy: number): void => {
        const lifeMs = (slashT <= STR_ARC_TRAIL_INTRO_T_MAX)
            ? Math.max(1, STR_ARC_TRAIL_INTRO_LIFESPAN_MS | 0)
            : Math.max(1, STR_ARC_TRAIL_LIFESPAN_MS | 0);

        const maskFx = sprites.create(_getEffectDummyImage(), SpriteKind.HeroEffect);
        maskFx.setFlag(SpriteFlag.Ghost, true);
        maskFx.setFlag(SpriteFlag.Invisible, true);
        maskFx.x = sx | 0;
        maskFx.y = sy | 0;
        maskFx.z = (hero.z | 0) + 12 + (STR_ARC_TRAIL_Z_OFFSET | 0);
        maskFx.lifespan = lifeMs | 0;
        applyEffectToSprite(maskFx, STR_ARC_SKIN_ID, {
            mode: "full",
            repeat: -1,
            frameIndex: frameIdx | 0,
            alpha: 1
        });
        sprites.setDataNumber(maskFx, EFFECT_ROT_DATA_KEY, rot);
        sprites.setDataNumber(maskFx, EFFECT_SCALE_DATA_KEY, scale * STR_ARC_TRAIL_SCALE);
        sprites.setDataNumber(maskFx, EFFECT_FLIP_X_DATA_KEY, flipX ? 1 : 0);

        const skin = (fillSkin || "").trim() ? fillSkin : STR_ARC_SKIN_ID;
        const fx = sprites.create(_getEffectDummyImage(), SpriteKind.HeroEffect);
        fx.setFlag(SpriteFlag.Ghost, true);
        fx.x = sx | 0;
        fx.y = sy | 0;
        fx.z = (hero.z | 0) + 13 + (STR_ARC_TRAIL_Z_OFFSET | 0);
        fx.lifespan = lifeMs | 0;

        const opts: EffectApplyOpts = {
            mode: "projectile",
            repeat: -1,
            frameIndex: 0,
            maskSprite: maskFx,
            alpha: STR_ARC_TRAIL_ALPHA_START
        };
        if (fillDir) opts.dir = fillDir;
        applyEffectToSprite(fx, skin, opts);

        if (fillFx && !(fillFx.flags & sprites.Flag.Destroyed)) {
            const list = sprites.readDataString(fillFx, EFFECT_FRAME_LIST_DATA_KEY) || "";
            const listRaw = sprites.readDataNumber(fillFx, EFFECT_FRAME_LIST_IS_RAW_DATA_KEY) | 0;
            const fps = sprites.readDataNumber(fillFx, EFFECT_FPS_DATA_KEY);
            const yoyo = sprites.readDataNumber(fillFx, EFFECT_YOYO_DATA_KEY) | 0;
            if (list) sprites.setDataString(fx, EFFECT_FRAME_LIST_DATA_KEY, list);
            sprites.setDataNumber(fx, EFFECT_FRAME_LIST_IS_RAW_DATA_KEY, listRaw | 0);
            if (Number.isFinite(fps)) sprites.setDataNumber(fx, EFFECT_FPS_DATA_KEY, fps);
            sprites.setDataNumber(fx, EFFECT_YOYO_DATA_KEY, yoyo | 0);
        }
        if (!fillSkin && tint) sprites.setDataNumber(fx, EFFECT_TINT_DATA_KEY, tint | 0);
        sprites.setDataNumber(fx, EFFECT_ROT_DATA_KEY, rot);
        sprites.setDataNumber(fx, EFFECT_SCALE_DATA_KEY, scale * STR_ARC_TRAIL_SCALE);
        sprites.setDataNumber(fx, EFFECT_FLIP_X_DATA_KEY, flipX ? 1 : 0);
        sprites.setDataNumber(fx, STR_ARC_TRAIL_BORN_MS_KEY, nowMs | 0);
        sprites.setDataNumber(fx, STR_ARC_TRAIL_LIFE_MS_KEY, lifeMs | 0);
        sprites.setDataSprite(fx, STR_ARC_TRAIL_MASK_FX_KEY, maskFx);

        const list = _strengthArcTrailListForProj(proj);
        list.push(fx);
        const cap = 14;
        if (list.length > cap) {
            const extra = list.length - cap;
            for (let i = 0; i < extra; i++) {
                const old = list.shift();
                if (old && !(old.flags & sprites.Flag.Destroyed)) old.destroy();
                const oldMask = old ? sprites.readDataSprite(old, STR_ARC_TRAIL_MASK_FX_KEY) : null;
                if (oldMask && !(oldMask.flags & sprites.Flag.Destroyed)) oldMask.destroy();
            }
        }
    };

    if (!lastPos) {
        spawnAt(x, y);
        __strengthArcTrailLastPosByProjId.set(id, { x: x | 0, y: y | 0 });
        return;
    }
    const dx = (x - lastPos.x);
    const dy = (y - lastPos.y);
    const dist = Math.sqrt((dx * dx) + (dy * dy));
    if (dist < step) return;
    const count = Math.floor(dist / step);
    for (let i = 1; i <= count; i++) {
        const t = (i * step) / dist;
        spawnAt(lastPos.x + (dx * t), lastPos.y + (dy * t));
    }
    __strengthArcTrailLastPosByProjId.set(id, { x: x | 0, y: y | 0 });
}

function _strengthArcTrailTick(proj: Sprite, nowMs: number): void {
    if (!STR_ARC_TRAIL_ENABLED || !proj) return;
    const id = proj.id | 0;
    if (!id) return;
    const list = __strengthArcTrailsByProjId.get(id);
    if (!list || !list.length) return;
    for (let i = list.length - 1; i >= 0; i--) {
        const fx = list[i];
        if (!fx || (fx.flags & sprites.Flag.Destroyed)) {
            list.splice(i, 1);
            continue;
        }
        const born = sprites.readDataNumber(fx, STR_ARC_TRAIL_BORN_MS_KEY) | 0;
        const life = Math.max(1, sprites.readDataNumber(fx, STR_ARC_TRAIL_LIFE_MS_KEY) | 0);
        const age = Math.max(0, (nowMs | 0) - (born | 0));
        const t = Math.max(0, Math.min(1, age / life));
        const alpha = STR_ARC_TRAIL_ALPHA_START + ((STR_ARC_TRAIL_ALPHA_END - STR_ARC_TRAIL_ALPHA_START) * t);
        sprites.setDataNumber(fx, EFFECT_ALPHA_DATA_KEY, Math.max(0, alpha));
        if (t >= 1) {
            const mask = sprites.readDataSprite(fx, STR_ARC_TRAIL_MASK_FX_KEY);
            if (mask && !(mask.flags & sprites.Flag.Destroyed)) mask.destroy();
        }
    }
}

function _strengthArcLeadWeight(slashT: number, endFadeT: number, isSlashSeg: boolean): number {
    const t = Math.max(0, Math.min(1, slashT));
    let lead = 1;
    if (isSlashSeg) {
        const start = STR_ARC_EDGE_LEAD_START;
        const span = Math.max(0.001, STR_ARC_EDGE_LEAD_SPAN);
        let v = Math.max(0, Math.min(1, (t - start) / span));
        v = v * v * (3 - 2 * v); // smoothstep
        lead = v;
    } else {
        lead = Math.max(0, Math.min(1, (1 - endFadeT) * STR_ARC_EDGE_LEAD_RESET_SCALE));
    }
    return Math.max(0, Math.min(1, lead));
}

function _strengthArcOutlineSkinId(): string | null {
    const id = `${STR_ARC_SKIN_ID}_aura_r${STR_ARC_OUTLINE_RADIUS | 0}`;
    const atlas = _getEffectAtlasAny();
    if (atlas && !_resolveEffectEntry(atlas, id, "")) return null;
    return id;
}

function _strengthArcSlashScaleCap(): number {
    const base = Math.max(0.01, Math.min(1, STR_ARC_SLASH_SCALE));
    const cap = Math.max(0, Math.min(0.9, STR_ARC_SLASH_SCALE_CAP_PCT));
    const capScale = Math.max(0.01, 1 - cap);
    return Math.max(0.01, Math.min(base, capScale));
}

function _strengthArcQuantizeScale(scale: number): number {
    if (!Number.isFinite(scale) || scale <= 0) return scale;
    const step = Number.isFinite(STR_ARC_SCALE_STEP) ? STR_ARC_SCALE_STEP : 0;
    if (!Number.isFinite(step) || step <= 0) return scale;
    const steps = Math.max(1, Math.floor(scale / step));
    return Math.max(step, steps * step);
}

function _strengthArcScaleToOpaqueCap(frameIdx: number, baseScale: number): number {
    if (!Number.isFinite(baseScale) || baseScale <= 0) return baseScale;
    const atlas = _getEffectAtlasAny();
    if (!atlas) return baseScale;
    const resolved = _resolveEffectEntry(atlas, STR_ARC_SKIN_ID, "");
    if (!resolved || !resolved.textureKey) return baseScale;
    const frameW = resolved.frameW | 0;
    const frameH = resolved.frameH | 0;
    if (frameW <= 0 || frameH <= 0) return baseScale;
    const bounds = _computeTextureFrameBounds(resolved.textureKey, frameW, frameH, frameIdx | 0);
    if (!bounds) return baseScale;
    const bboxMax = Math.max(bounds.w | 0, bounds.h | 0);
    if (bboxMax <= 0) return baseScale;
    const capPx = Math.max(1, STR_ARC_OPAQUE_CAP_PX | 0);
    const targetScale = capPx / bboxMax;
    const upPct = Math.max(0, STR_ARC_OPAQUE_CAP_UPSCALE_PCT);
    const maxUpscale = baseScale * (1 + upPct);
    let scale = baseScale;
    if (targetScale < scale) scale = targetScale;
    else if (targetScale > scale) scale = Math.min(targetScale, maxUpscale);
    scale = Math.max(0.01, scale);
    return _strengthArcQuantizeScale(scale);
}

function _strengthArcFillRadiusPx(scale: number): number {
    const base = Math.max(1, Math.round(Math.max(STR_ARC_FRAME_W_PX, STR_ARC_FRAME_H_PX) * 0.5));
    const scaled = Math.max(1, Math.round(base * Math.max(0.01, scale)));
    const cap = Math.max(0, Math.min(0.9, STR_ARC_FILL_INNER_EXPAND_PCT_CAP));
    const widened = Math.max(1, Math.round(scaled * (1 - cap)));
    const minR = Math.max(1, Math.round(STR_ARC_FILL_ELLIPSE_MIN_R * (1 - cap)));
    return Math.max(minR, widened);
}

function _strengthArcAuraSkinId(radius: number): string | null {
    const r = Math.max(1, radius | 0);
    const auraId = `${STR_ARC_SKIN_ID}_aura_r${r}`;
    const atlas = _getEffectAtlasAny();
    if (atlas && _resolveEffectEntry(atlas, auraId, "")) {
        return auraId;
    }
    return STR_ARC_AURA_FALLBACK_TO_BASE ? STR_ARC_SKIN_ID : null;
}

function _strengthArcFillFrameIndex(skinId: string, dir: string | undefined, t: number): number {
    const atlas = _getEffectAtlasAny();
    if (!atlas || !skinId) return 0;
    const resolved = _resolveEffectEntry(atlas, skinId, dir || "");
    const frameCount = resolved?.frameIndices ? (resolved.frameIndices.length | 0) : 0;
    if (frameCount <= 0) return 0;
    const clamped = Math.max(0, Math.min(1, t));
    let baseT = clamped;
    const speed = Math.max(1, STR_ARC_FILL_SPEED_MULT | 0);
    if (speed > 1) {
        const scaled = clamped * speed;
        const loop = Math.min(speed - 1, Math.floor(scaled));
        baseT = Math.min(1, scaled - loop);
    }
    if (frameCount > 1 && clamped >= STR_ARC_FILL_CLIMAX_START) {
        const denom = Math.max(0.0001, 1 - STR_ARC_FILL_CLIMAX_START);
        const localT = Math.max(0, Math.min(1, (clamped - STR_ARC_FILL_CLIMAX_START) / denom));
        const span = Math.max(1, Math.min(frameCount - 1, STR_ARC_FILL_CLIMAX_FRAMES | 0));
        const pulse = Math.sin(Math.PI * localT);
        const offset = Math.round(pulse * Math.max(0, span - 1));
        return Math.min(frameCount - 1, Math.max(0, (frameCount - span) + offset));
    }
    return Math.min(frameCount - 1, Math.max(0, Math.round(baseT * (frameCount - 1))));
}

function _strengthArcFillListCount(list: string): number {
    if (!list) return 0;
    const tokens = String(list).split(/[\s,]+/).filter((t) => !!t);
    return tokens.length | 0;
}

const EFFECT_SCALE_STEPS: number[] = [0.25, 0.5, 1, 2, 3];
const EFFECT_MIN_FIT_DIAM_PX = 64;
const EFFECT_MIN_FIT_RADIUS_PX = Math.idiv(EFFECT_MIN_FIT_DIAM_PX, 2) | 0;

function _effectPickScaleForRadius(skinId: string, dir: string | undefined, radiusPx: number): number {
    const atlas = _getEffectAtlasAny();
    if (!atlas) return 1;
    const resolved = _resolveEffectEntry(atlas, skinId, dir);
    if (!resolved) return 1;
    const frameW = resolved.frameW | 0;
    const frameH = resolved.frameH | 0;
    if (frameW <= 0 || frameH <= 0) return 1;
    if (!Number.isFinite(radiusPx) || radiusPx <= 0) return 1;
    const maxDim = Math.max(frameW, frameH);
    const targetScale = (radiusPx * 2) / Math.max(1, maxDim);
    let best = EFFECT_SCALE_STEPS[0] || 1;
    for (const s of EFFECT_SCALE_STEPS) {
        if (s <= targetScale + 1e-6) best = s;
    }
    if (!Number.isFinite(best) || best <= 0) best = 1;
    return best;
}

function _effectPickRadiusForSkin(skinId: string, dir: string | undefined, targetRadiusPx: number): number {
    const atlas = _getEffectAtlasAny();
    if (!atlas) return targetRadiusPx | 0;
    const resolved = _resolveEffectEntry(atlas, skinId, dir);
    if (!resolved) return targetRadiusPx | 0;
    const frameW = resolved.frameW | 0;
    const frameH = resolved.frameH | 0;
    if (frameW <= 0 || frameH <= 0) return targetRadiusPx | 0;
    const baseRadius = Math.max(1, targetRadiusPx | 0);
    const scale = _effectPickScaleForRadius(skinId, dir, baseRadius);
    const maxDim = Math.max(frameW, frameH);
    const radius = Math.round((maxDim * scale) / 2);
    return Math.max(1, radius | 0);
}

function _effectSkinIdWithSize(skinId: string, sizePx: number, dir?: string): string {
    if (!skinId) return skinId;
    const trimmed = String(skinId || "").trim();
    if (!trimmed) return trimmed;
    if (/\d+x\d+$/i.test(trimmed)) return trimmed;
    const atlas = _getEffectAtlasAny();
    if (!atlas) return trimmed;
    const dirRaw = String(dir || "").trim().toLowerCase();
    if (dirRaw) {
        const suffixes = [`_${dirRaw}`, `-${dirRaw}`, ` ${dirRaw}`];
        for (const suffix of suffixes) {
            const candidate = `${trimmed}${suffix} ${sizePx}x${sizePx}`;
            if (atlas[candidate]) return candidate;
        }
    }
    const candidate = `${trimmed} ${sizePx}x${sizePx}`;
    if (atlas[candidate]) return candidate;
    return trimmed;
}

function _effectTintForSkinInAtlas(atlas: any, skinId: string, dir?: string): number {
    const resolved = _resolveEffectEntry(atlas, skinId, dir);
    const tint = resolved?.palette?.tint;
    return (typeof tint === "number" && isFinite(tint) && tint > 0) ? (tint | 0) : 0;
}

function _effectTintForSkin(skinId: string, dir?: string): number {
    const atlas = _getEffectAtlasAny();
    if (!atlas) return 0;
    return _effectTintForSkinInAtlas(atlas, skinId, dir);
}

function _elementTintForMode(element: number, mode?: HeroElementEffectMode): number {
    const key = `${element | 0}|${mode || "offense"}`;
    if (Object.prototype.hasOwnProperty.call(_elementTintCache, key)) {
        return (_elementTintCache[key] | 0) || 0;
    }
    const atlas = _getEffectAtlasAny();
    if (!atlas) return 0;
    const pick = _heroSpellEffectPick(element | 0, "down", mode);
    let tint = 0;
    if (pick && pick.skinId) {
        tint = _effectTintForSkinInAtlas(atlas, pick.skinId, pick.dir || "");
    }
    _elementTintCache[key] = tint | 0;
    return tint | 0;
}

const HERO_ELEMENT_TRAIL_LAST_MS_KEY = "__heroElTrailAt";
const HERO_ELEMENT_TRAIL_INTERVAL_MS = 60;
const HERO_ELEMENT_TRAIL_LIFESPAN_MS = 220;
const HERO_ELEMENT_TRAIL_SPEED_PX = 18;
const HERO_ELEMENT_TRAIL_SIZE_PX = 2;

function _heroElementParticleColor(element: number): number {
    const e = element | 0;
    if (e === ELEM.FIRE) return 2;
    if (e === ELEM.WATER) return 9;
    if (e === ELEM.ICE) return 8;
    if (e === ELEM.ELECTRIC) return 5;
    if (e === ELEM.EARTH) return 6;
    if (e === ELEM.GRASS) return 7;
    if (e === ELEM.AIR) return 3;
    if (e === ELEM.NONE) return 0;
    return 1;
}

function _projectileEmergencyScalePx(px: number): number {
    const base = Number.isFinite(px) ? px : 0;
    const s = PROJECTILE_EMERGENCY_SCALE | 0;
    if (s <= 1) return base | 0;
    return Math.max(1, Math.round(base * s));
}

function _projectileEmergencyColors(element: number): number[] {
    const e = element | 0;
    switch (e) {
        case ELEM.FIRE: return [2, 4, 5];
        case ELEM.WATER: return [9, 8, 1];
        case ELEM.ICE: return [9, 1, 13];
        case ELEM.ELECTRIC: return [5, 1, 10];
        case ELEM.EARTH: return [14, 13, 4];
        case ELEM.GRASS: return [7, 6, 5];
        case ELEM.AIR: return [9, 1, 8];
        case ELEM.NONE: return [8, 9, 1];
        default: return [1, 13, 11];
    }
}

type WeaponAuraPalette = { r1: number; r2: number; r3: number; edge: number };
const __weaponAuraPaletteCache: { [k: string]: WeaponAuraPalette } = Object.create(null);

function _weaponAuraPaletteForElement(
    element: number,
    dir: string,
    mode?: HeroElementEffectMode
): WeaponAuraPalette {
    const pick = _heroSpellEffectPick(element | 0, dir || "", mode);
    const skinId = pick?.skinId || "";
    const pickDir = pick?.dir || "";
    const cacheKey = skinId ? `${skinId}|${pickDir}` : `elem:${element | 0}`;
    const cached = __weaponAuraPaletteCache[cacheKey];
    if (cached) return cached;

    let colors: number[] | null = null;
    if (skinId) {
        const g: any = globalThis as any;
        const hook = g && g.__HeroEngineHooks && g.__HeroEngineHooks.getEffectPaletteIndices;
        if (typeof hook === "function") {
            try { colors = hook(skinId, pickDir); } catch { /* ignore */ }
        }
    }
    if (!colors || colors.length === 0) colors = _projectileEmergencyColors(element | 0);

    const deduped: number[] = [];
    for (const c of colors) {
        const v = c | 0;
        if (!v) continue;
        if (deduped.indexOf(v) >= 0) continue;
        deduped.push(v);
    }
    if (!deduped.length) deduped.push(1);

    const base = deduped[0] | 0;
    const mid = (deduped[1] != null ? deduped[1] : base) | 0;
    const hi = (deduped[2] != null ? deduped[2] : mid) | 0;

    const out: WeaponAuraPalette = { r1: base, r2: mid, r3: hi, edge: hi };
    __weaponAuraPaletteCache[cacheKey] = out;
    return out;
}

function _projectileEmergencyFill(img: Image, element: number): void {
    if (!PROJECTILE_EMERGENCY_FILL) return;
    if (!img) return;
    const colors = _projectileEmergencyColors(element | 0);
    if (!colors || colors.length === 0) return;
    const base = colors[0] | 0;
    const accent = (colors[1] != null ? colors[1] : base) | 0;
    const highlight = (colors[2] != null ? colors[2] : accent) | 0;

    const w = img.width | 0;
    const h = img.height | 0;
    const fillA = STR_TIP_TRACE_COLOR | 0;
    const fillB = AGI_TIP_TRACE_COLOR | 0;
    const fillC = AGI_TRAIL_FILL_COLOR | 0;
    const fillD = AGI_DEBUG_TRAIL_MAIN_COLOR | 0;
    const edgeA = STR_TIP_TRACE_EDGE_COLOR | 0;
    const edgeB = AGI_TIP_TRACE_EDGE_COLOR | 0;
    const edgeC = AGI_DEBUG_TRAIL_EDGE_COLOR | 0;

    for (let x = 0; x < w; x++) {
        for (let y = 0; y < h; y++) {
            const v = img.getPixel(x, y) | 0;
            if (v === 0) continue;
            if (v === edgeA || v === edgeB || v === edgeC) continue;
            if (v !== fillA && v !== fillB && v !== fillC && v !== fillD) continue;
            const sel = (x + y) & 3;
            let color = base;
            if (sel === 0) color = highlight;
            else if (sel === 1) color = accent;
            img.setPixel(x, y, color | 0);
        }
    }
}

function _projectileClearImage(img: Image): void {
    if (!img) return;
    const w = img.width | 0;
    const h = img.height | 0;
    for (let x = 0; x < w; x++) {
        for (let y = 0; y < h; y++) {
            if (img.getPixel(x, y) !== 0) img.setPixel(x, y, 0);
        }
    }
}

function _projectileFadeTrailImage(img: Image, nowMs: number, fadeStartMs: number): void {
    if (!PROJECTILE_EMERGENCY_FADE) return;
    if (!img) return;
    if ((nowMs | 0) < (fadeStartMs | 0)) return;
    const elapsed = (nowMs | 0) - (fadeStartMs | 0);
    const stage = Math.min(
        (PROJECTILE_EMERGENCY_FADE_DIVS.length - 1) | 0,
        Math.idiv(Math.max(0, elapsed | 0), Math.max(1, PROJECTILE_EMERGENCY_FADE_STEP_MS | 0))
    );
    const divisor = (PROJECTILE_EMERGENCY_FADE_DIVS[stage] | 0) || 1;
    const phase = Math.idiv(nowMs | 0, Math.max(1, PROJECTILE_EMERGENCY_FADE_PHASE_MS | 0)) | 0;
    const w = img.width | 0;
    const h = img.height | 0;
    if (divisor <= 1) {
        for (let x = 0; x < w; x++) {
            for (let y = 0; y < h; y++) {
                if (img.getPixel(x, y) != 0) img.setPixel(x, y, 0);
            }
        }
        return;
    }
    for (let x = 0; x < w; x++) {
        for (let y = 0; y < h; y++) {
            const v = img.getPixel(x, y) | 0;
            if (v === 0) continue;
            if (((x + y + phase) % divisor) === 0) img.setPixel(x, y, 0);
        }
    }
}

function _spawnHeroElementTrailParticle(proj: Sprite, element: number, nowMs: number): void {
    if (!proj || (proj.flags & sprites.Flag.Destroyed)) return;
    const color = _heroElementParticleColor(element | 0);
    if (color <= 0) return;
    const lastAt = sprites.readDataNumber(proj, HERO_ELEMENT_TRAIL_LAST_MS_KEY) | 0;
    if (lastAt > 0 && (nowMs | 0) < (lastAt + HERO_ELEMENT_TRAIL_INTERVAL_MS)) return;
    sprites.setDataNumber(proj, HERO_ELEMENT_TRAIL_LAST_MS_KEY, nowMs | 0);

    const img = image.create(HERO_ELEMENT_TRAIL_SIZE_PX, HERO_ELEMENT_TRAIL_SIZE_PX);
    img.fill(color);

    const fx = sprites.create(img, SpriteKind.RelicEffect);
    fx.setFlag(SpriteFlag.Ghost, true);
    fx.z = proj.z - 1;
    fx.x = proj.x + randint(-2, 2);
    fx.y = proj.y + randint(-2, 2);
    const sp = HERO_ELEMENT_TRAIL_SPEED_PX | 0;
    fx.vx = randint(-sp, sp);
    fx.vy = randint(-sp, sp);
    fx.lifespan = HERO_ELEMENT_TRAIL_LIFESPAN_MS | 0;
}

function _spawnHeroElementDetonationFx(spell: Sprite, element: number, lifespanMs: number): boolean {
    if (!spell || (spell.flags & sprites.Flag.Destroyed)) return false;
    const isHeal = (sprites.readDataNumber(spell, PROJ_DATA.IS_HEAL) | 0) === 1;
    const family = sprites.readDataNumber(spell, PROJ_DATA.FAMILY) | 0;
    const mode: HeroElementEffectMode = (isHeal || family === FAMILY.HEAL) ? "defense" : "offense";
    const pick = _heroSpellEffectPick(element | 0, "down", mode);
    if (!pick || !pick.skinId) return false;
    const detRadius = sprites.readDataNumber(spell, INT_DET_VIS_RADIUS_KEY) | 0;
    const baseRadius = sprites.readDataNumber(spell, INT_RADIUS_KEY) | 0;
    const fitRadius = detRadius > 0 ? detRadius : baseRadius;
    const detDir = pick.dir || "down";
    const offset = _heroSpellEffectOffsetFor(pick.skinId, detDir, family | 0, "intellectDetonation");
    const fx = sprites.create(_getEffectDummyImage(), SpriteKind.RelicEffect);
    fx.setFlag(SpriteFlag.Ghost, true);
    fx.x = spell.x;
    fx.y = spell.y;
    fx.z = spell.z + 2;
    fx.lifespan = Math.max(200, lifespanMs | 0) | 0;
    const opts: EffectApplyOpts = { mode: "full" };
    if (fitRadius > 0) opts.fitRadiusPx = fitRadius | 0;
    opts.offsetX = offset.x;
    opts.offsetY = offset.y;
    if (family === (FAMILY.INTELLECT | 0)) {
        opts.introMs = 0;
        opts.introScale = 0;
        opts.animDelayMs = 0;
        opts.offsetX = INT_DET_FX_ALIGN_X_PX | 0;
    }
    if (pick.dir) applyEffectToSprite(fx, pick.skinId, { ...opts, dir: pick.dir });
    else applyEffectToSprite(fx, pick.skinId, opts);
    if (family === (FAMILY.INTELLECT | 0)) {
        const baseScaleRaw = sprites.readDataNumber(fx, EFFECT_SCALE_DATA_KEY);
        const baseScale = (baseScaleRaw > 0) ? baseScaleRaw : 1;
        sprites.setDataNumber(fx, INT_DET_FX_BASE_SCALE_KEY, baseScale);
        sprites.setDataNumber(fx, EFFECT_FRAME_INDEX_DATA_KEY, 0);
        sprites.setDataNumber(fx, EFFECT_SCALE_X_DATA_KEY, INT_DET_FX_CONE_SCALE_X);
        sprites.setDataNumber(fx, EFFECT_SCALE_Y_DATA_KEY, INT_DET_FX_CONE_SCALE_Y);
    }
    sprites.setDataSprite(spell, INT_DET_FX_SPRITE_KEY, fx);
    return true;
}



