interface TileCollisionShape {

    solid: boolean;

    offsetX: number;

    offsetY: number;

    width: number;

    height: number;

}



// Index by tile type (0, 1, 2, ...)

const TILE_COLLISION_DEFS: TileCollisionShape[] = [

    // 0: empty

    { solid: false, offsetX: 0, offsetY: 0, width: 0, height: 0 },



    // 1: full solid tile (current behavior of TILE_WALL)

    {

        solid: true,

        offsetX: 0,

        offsetY: 0,

        width: WORLD_TILE_SIZE,

        height: WORLD_TILE_SIZE,

    },

    // 2: bridge walkway (renders as wall but not solid)
    {
        solid: false,
        offsetX: 0,
        offsetY: 0,
        width: 0,
        height: 0,
    },

    // 3+: reserved for later (half-height walls, ledges, etc.)

    // Example (commented out for now):

    // {

    //     solid: true,

    //     offsetX: 0,

    //     offsetY: WORLD_TILE_SIZE - 12,

    //     width: WORLD_TILE_SIZE,

    //     height: 12,

    // },

];

function _tileIsSolidType(type: number): boolean {
    const t = type | 0
    const def = TILE_COLLISION_DEFS[t] || TILE_COLLISION_DEFS[0]
    return !!def.solid
}

