const _dunShrineStates = new Map<string, ShrineState>()
let _dunShrineSparkles: Sprite[] = []
let _dunShrineAmbientSparkles: Sprite[] = []
let _dunShrineAmbientNextMs = 0
let _dunAmbientMotes: Sprite[] = []
let _dunAmbientHaze: Sprite[] = []
let _dunAmbientRays: Sprite[] = []
let _dunAmbientWash: Sprite = null
let _dunAmbientMoteNextMs = 0
let _dunAmbientHazeNextMs = 0
let _dunAmbientRaysNextMs = 0

function _hslToRgbHex(h: number, s: number, l: number): number {
    const hue = ((h % 360) + 360) % 360
    const sat = Math.max(0, Math.min(1, s))
    const lit = Math.max(0, Math.min(1, l))
    const c = (1 - Math.abs(2 * lit - 1)) * sat
    const hp = hue / 60
    const x = c * (1 - Math.abs((hp % 2) - 1))
    let r1 = 0
    let g1 = 0
    let b1 = 0
    if (hp >= 0 && hp < 1) { r1 = c; g1 = x; b1 = 0 }
    else if (hp >= 1 && hp < 2) { r1 = x; g1 = c; b1 = 0 }
    else if (hp >= 2 && hp < 3) { r1 = 0; g1 = c; b1 = x }
    else if (hp >= 3 && hp < 4) { r1 = 0; g1 = x; b1 = c }
    else if (hp >= 4 && hp < 5) { r1 = x; g1 = 0; b1 = c }
    else { r1 = c; g1 = 0; b1 = x }
    const m = lit - c / 2
    const r = Math.max(0, Math.min(255, Math.round((r1 + m) * 255)))
    const g = Math.max(0, Math.min(255, Math.round((g1 + m) * 255)))
    const b = Math.max(0, Math.min(255, Math.round((b1 + m) * 255)))
    return ((r << 16) | (g << 8) | b) >>> 0
}

function _shrineOverlayPulse(nowMs: number, startMs: number): number {
    const cycle = Math.max(1000, SHRINE_OVERLAY_PULSE_MS | 0)
    const delta = Math.max(0, (nowMs | 0) - (startMs | 0)) | 0
    const t = ((delta % cycle) / cycle)
    return (1 - Math.cos(t * Math.PI * 2)) * 0.5
}

function _shrineOverlayTint(nowMs: number, startMs: number, lightness: number): number {
    const cycle = Math.max(1000, SHRINE_OVERLAY_CYCLE_MS | 0)
    const delta = ((nowMs | 0) - (startMs | 0)) | 0
    const t = ((delta % cycle) + cycle) % cycle
    const hue = (t / cycle) * 360
    return _hslToRgbHex(hue, SHRINE_OVERLAY_SAT, lightness)
}

function _shrineSparkleTint(nowMs: number, seedMs: number): number {
    const cycle = Math.max(1000, SHRINE_SPARKLE_CYCLE_MS | 0)
    const delta = ((nowMs | 0) + (seedMs | 0)) | 0
    const t = ((delta % cycle) + cycle) % cycle
    const hue = (t / cycle) * 360
    return _hslToRgbHex(hue, SHRINE_SPARKLE_SAT, SHRINE_SPARKLE_LIGHT)
}

function _shrineAmbientTint(nowMs: number, seedMs: number): number {
    const cycle = Math.max(1000, SHRINE_AMBIENT_CYCLE_MS | 0)
    const delta = ((nowMs | 0) + (seedMs | 0)) | 0
    const t = ((delta % cycle) + cycle) % cycle
    const hue = (t / cycle) * 360
    return _hslToRgbHex(hue, SHRINE_AMBIENT_SAT, SHRINE_AMBIENT_LIGHT)
}

function _shrineSparkleAlpha(nowMs: number, startMs: number, endMs: number): number {
    const start = startMs | 0
    const end = endMs | 0
    if (start <= 0 || end <= start) return SHRINE_SPARKLE_ALPHA
    const t = Math.max(0, Math.min(1, ((nowMs | 0) - start) / Math.max(1, (end - start))))
    const alpha = SHRINE_SPARKLE_ALPHA * (1 - t)
    return Math.max(SHRINE_SPARKLE_ALPHA_MIN, alpha)
}

function _shrineAmbientAlpha(nowMs: number, startMs: number, endMs: number): number {
    const start = startMs | 0
    const end = endMs | 0
    if (start <= 0 || end <= start) return SHRINE_AMBIENT_ALPHA
    const t = Math.max(0, Math.min(1, ((nowMs | 0) - start) / Math.max(1, (end - start))))
    const alpha = SHRINE_AMBIENT_ALPHA * (1 - t)
    return Math.max(SHRINE_AMBIENT_ALPHA_MIN, alpha)
}

function _shrineSparkleBaseXY(decor: Sprite | null, tileR: number, tileC: number): { x: number; y: number } {
    const x = (decor && typeof decor.x === "number") ? (decor.x | 0) : _dunColToX(tileC | 0)
    const y0 = (decor && typeof decor.y === "number") ? (decor.y | 0) : _dunRowToY(tileR | 0)
    const y = (y0 - (SHRINE_SPARKLE_OFFSET_Y_PX | 0)) | 0
    return { x: x | 0, y: y | 0 }
}

function _shrineSpawnSparkleAt(x: number, y: number, nowMs: number): void {
    if (!SHRINE_SPARKLE_SKIN_ID) return
    const now = nowMs | 0
    const fx = sprites.create(_getEffectDummyImage(), SpriteKind.HeroEffect)
    fx.setFlag(SpriteFlag.Ghost, true)
    fx.x = x | 0
    fx.y = y | 0
    fx.z = SHRINE_SPARKLE_Z_BIAS | 0
    if ((SHRINE_SPARKLE_LIFESPAN_MS | 0) > 0) fx.lifespan = SHRINE_SPARKLE_LIFESPAN_MS | 0
    const tintSeed = Math.randomRange(0, Math.max(0, (SHRINE_SPARKLE_CYCLE_MS | 0) - 1)) | 0
    const tint = _shrineSparkleTint(now | 0, tintSeed | 0)
    applyEffectToSprite(fx, SHRINE_SPARKLE_SKIN_ID, {
        tint,
        alpha: SHRINE_SPARKLE_ALPHA,
        blend: SHRINE_SPARKLE_BLEND,
        fitRadiusPx: SHRINE_SPARKLE_RADIUS_PX,
        popMs: SHRINE_SPARKLE_POP_MS,
        popScale: SHRINE_SPARKLE_POP_SCALE,
        repeat: 0,
    })
    const angleDeg = Math.randomRange(SHRINE_SPARKLE_ANGLE_MIN_DEG | 0, SHRINE_SPARKLE_ANGLE_MAX_DEG | 0) | 0
    const speed = Math.randomRange(SHRINE_SPARKLE_SPEED_MIN_PX | 0, SHRINE_SPARKLE_SPEED_MAX_PX | 0) | 0
    const rad = (angleDeg * Math.PI) / 180
    fx.vx = Math.round(Math.cos(rad) * speed)
    fx.vy = Math.round(Math.sin(rad) * speed)
    const fadeEnd = (now + Math.max(1, SHRINE_SPARKLE_LIFESPAN_MS | 0)) | 0
    sprites.setDataNumber(fx, SHRINE_SPARKLE_FADE_START_KEY, now | 0)
    sprites.setDataNumber(fx, SHRINE_SPARKLE_FADE_END_KEY, fadeEnd | 0)
    _dunShrineSparkles.push(fx)
}

function _dunSpawnShrineSparkles(
    decor: Sprite | null,
    tileR: number,
    tileC: number,
    count: number,
    spreadPx: number,
    nowMs: number
): void {
    const total = Math.max(0, count | 0)
    if (total <= 0) return
    const spread = Math.max(0, spreadPx | 0)
    const base = _shrineSparkleBaseXY(decor, tileR | 0, tileC | 0)
    for (let i = 0; i < total; i++) {
        const angleDeg = Math.randomRange(0, 359) | 0
        const rad = (angleDeg * Math.PI) / 180
        const radius = spread > 0 ? (Math.randomRange(0, spread | 0) | 0) : 0
        const ox = Math.round(Math.cos(rad) * radius)
        const oy = Math.round(Math.sin(rad) * radius * 0.7)
        _shrineSpawnSparkleAt((base.x + ox) | 0, (base.y + oy) | 0, nowMs | 0)
    }
}

function _dunUpdateShrineSparkles(nowMs: number): void {
    if (!_dunShrineSparkles || _dunShrineSparkles.length === 0) return
    const now = nowMs | 0
    let write = 0
    for (let i = 0; i < _dunShrineSparkles.length; i++) {
        const fx = _dunShrineSparkles[i]
        if (!fx || (fx.flags & sprites.Flag.Destroyed)) continue
        const endMs = sprites.readDataNumber(fx, SHRINE_SPARKLE_FADE_END_KEY) | 0
        if (endMs > 0 && (now | 0) >= (endMs | 0)) {
            fx.destroy()
            continue
        }
        const startMs = sprites.readDataNumber(fx, SHRINE_SPARKLE_FADE_START_KEY) | 0
        const alpha = _shrineSparkleAlpha(now | 0, startMs | 0, endMs | 0)
        sprites.setDataNumber(fx, EFFECT_ALPHA_DATA_KEY, alpha)
        _dunShrineSparkles[write++] = fx
    }
    if (write < _dunShrineSparkles.length) _dunShrineSparkles.length = write
}

function _shrineAmbientSpawnSparkle(nowMs: number): void {
    if (!SHRINE_AMBIENT_SKIN_ID) return
    const w = scene.screenWidth() | 0
    const h = scene.screenHeight() | 0
    if (w <= 0 || h <= 0) return
    const margin = Math.max(0, SHRINE_AMBIENT_MARGIN_PX | 0) | 0
    const minX = margin | 0
    const maxX = Math.max(minX | 0, (w - 1 - margin) | 0) | 0
    const minY = margin | 0
    const maxY = Math.max(minY | 0, (h - 1 - margin) | 0) | 0

    const fx = sprites.create(_getEffectDummyImage(), SpriteKind.HeroEffect)
    fx.setFlag(SpriteFlag.Ghost, true)
    fx.setFlag(SpriteFlag.RelativeToCamera, true)
    fx.x = Math.randomRange(minX | 0, maxX | 0) | 0
    fx.y = Math.randomRange(minY | 0, maxY | 0) | 0
    fx.z = SHRINE_AMBIENT_Z_BIAS | 0
    if ((SHRINE_AMBIENT_LIFESPAN_MS | 0) > 0) fx.lifespan = SHRINE_AMBIENT_LIFESPAN_MS | 0

    const now = nowMs | 0
    const tintSeed = Math.randomRange(0, Math.max(0, (SHRINE_AMBIENT_CYCLE_MS | 0) - 1)) | 0
    const tint = _shrineAmbientTint(now | 0, tintSeed | 0)
    applyEffectToSprite(fx, SHRINE_AMBIENT_SKIN_ID, {
        tint,
        alpha: SHRINE_AMBIENT_ALPHA,
        blend: SHRINE_AMBIENT_BLEND,
        fitRadiusPx: SHRINE_AMBIENT_RADIUS_PX,
        popMs: SHRINE_AMBIENT_POP_MS,
        popScale: SHRINE_AMBIENT_POP_SCALE,
        repeat: 0,
    })
    const angleDeg = Math.randomRange(SHRINE_AMBIENT_ANGLE_MIN_DEG | 0, SHRINE_AMBIENT_ANGLE_MAX_DEG | 0) | 0
    const speed = Math.randomRange(SHRINE_AMBIENT_SPEED_MIN_PX | 0, SHRINE_AMBIENT_SPEED_MAX_PX | 0) | 0
    const rad = (angleDeg * Math.PI) / 180
    fx.vx = Math.round(Math.cos(rad) * speed)
    fx.vy = Math.round(Math.sin(rad) * speed)
    const fadeEnd = (now + Math.max(1, SHRINE_AMBIENT_LIFESPAN_MS | 0)) | 0
    sprites.setDataNumber(fx, SHRINE_SPARKLE_FADE_START_KEY, now | 0)
    sprites.setDataNumber(fx, SHRINE_SPARKLE_FADE_END_KEY, fadeEnd | 0)
    _dunShrineAmbientSparkles.push(fx)
}

function _dunSpawnShrineAmbientSparkles(count: number, nowMs: number): void {
    const total = Math.max(0, count | 0)
    if (total <= 0) return
    for (let i = 0; i < total; i++) {
        _shrineAmbientSpawnSparkle(nowMs | 0)
    }
}

function _dunUpdateShrineAmbientSparkles(nowMs: number): void {
    if (!_dunShrineAmbientSparkles || _dunShrineAmbientSparkles.length === 0) return
    const now = nowMs | 0
    let write = 0
    for (let i = 0; i < _dunShrineAmbientSparkles.length; i++) {
        const fx = _dunShrineAmbientSparkles[i]
        if (!fx || (fx.flags & sprites.Flag.Destroyed)) continue
        const endMs = sprites.readDataNumber(fx, SHRINE_SPARKLE_FADE_END_KEY) | 0
        if (endMs > 0 && (now | 0) >= (endMs | 0)) {
            fx.destroy()
            continue
        }
        const startMs = sprites.readDataNumber(fx, SHRINE_SPARKLE_FADE_START_KEY) | 0
        const alpha = _shrineAmbientAlpha(now | 0, startMs | 0, endMs | 0)
        sprites.setDataNumber(fx, EFFECT_ALPHA_DATA_KEY, alpha)
        _dunShrineAmbientSparkles[write++] = fx
    }
    if (write < _dunShrineAmbientSparkles.length) _dunShrineAmbientSparkles.length = write
}

function _dunUpdateShrineAmbience(nowMs: number): void {
    const now = nowMs | 0
    const shrineActive =
        ((_dunShrineBlessingFloor | 0) === (_dunFloorIndex | 0)) &&
        ((_dunShrineBlessingUntilMs | 0) > (now | 0))

    if (!shrineActive) {
        if (_dunShrineAmbientSparkles && _dunShrineAmbientSparkles.length) {
            for (let i = 0; i < _dunShrineAmbientSparkles.length; i++) {
                const fx = _dunShrineAmbientSparkles[i]
                if (!fx || (fx.flags & sprites.Flag.Destroyed)) continue
                fx.destroy()
            }
            _dunShrineAmbientSparkles.length = 0
        }
        _dunShrineAmbientNextMs = 0
        return
    }

    _dunUpdateShrineAmbientSparkles(now | 0)

    if ((_dunShrineAmbientNextMs | 0) <= 0 || (now | 0) >= (_dunShrineAmbientNextMs | 0)) {
        const count = Math.randomRange(SHRINE_AMBIENT_SPAWN_MIN_COUNT | 0, SHRINE_AMBIENT_SPAWN_MAX_COUNT | 0) | 0
        _dunSpawnShrineAmbientSparkles(count | 0, now | 0)
        const nextMs = (now + Math.randomRange(SHRINE_AMBIENT_SPAWN_MIN_MS | 0, SHRINE_AMBIENT_SPAWN_MAX_MS | 0)) | 0
        _dunShrineAmbientNextMs = nextMs | 0
    }

    if (DEBUG_SHRINE_OBSERVER && _dunShrineBlessingKey) {
        const detail = `count=${_dunShrineAmbientSparkles.length | 0}`
        _shrineObsMark(_dunShrineBlessingKey, _dunFloorIndex | 0, "screen_ambience", true, detail, now | 0)
    }
}

function _ambientPulse(nowMs: number, cycleMs: number, offsetMs: number): number {
    const cycle = Math.max(1000, cycleMs | 0)
    const delta = ((nowMs | 0) + (offsetMs | 0)) | 0
    const t = ((delta % cycle) + cycle) % cycle
    return (1 - Math.cos((t / cycle) * Math.PI * 2)) * 0.5
}

function _ambientTint(nowMs: number, cycleMs: number, sat: number, light: number, offsetMs: number): number {
    const cycle = Math.max(1000, cycleMs | 0)
    const delta = ((nowMs | 0) + (offsetMs | 0)) | 0
    const t = ((delta % cycle) + cycle) % cycle
    const hue = (t / cycle) * 360
    return _hslToRgbHex(hue, sat, light)
}

function _ambientFadeAlpha(nowMs: number, startMs: number, endMs: number, alpha: number, alphaMin: number): number {
    const start = startMs | 0
    const end = endMs | 0
    if (start <= 0 || end <= start) return alpha
    const t = Math.max(0, Math.min(1, ((nowMs | 0) - start) / Math.max(1, (end - start))))
    const out = alpha * (1 - t)
    return Math.max(alphaMin, out)
}

function _ambientPickScreenPoint(marginPx: number): { x: number; y: number } | null {
    const w = scene.screenWidth() | 0
    const h = scene.screenHeight() | 0
    if (w <= 0 || h <= 0) return null
    const margin = Math.max(0, marginPx | 0) | 0
    const minX = margin | 0
    const maxX = Math.max(minX | 0, (w - 1 - margin) | 0) | 0
    const minY = margin | 0
    const maxY = Math.max(minY | 0, (h - 1 - margin) | 0) | 0
    return {
        x: Math.randomRange(minX | 0, maxX | 0) | 0,
        y: Math.randomRange(minY | 0, maxY | 0) | 0,
    }
}

function _ambientUpdateList(list: Sprite[], nowMs: number, alpha: number, alphaMin: number): void {
    if (!list || list.length === 0) return
    const now = nowMs | 0
    let write = 0
    for (let i = 0; i < list.length; i++) {
        const fx = list[i]
        if (!fx || (fx.flags & sprites.Flag.Destroyed)) continue
        const endMs = sprites.readDataNumber(fx, AMBIENT_FADE_END_KEY) | 0
        if (endMs > 0 && (now | 0) >= (endMs | 0)) {
            fx.destroy()
            continue
        }
        const startMs = sprites.readDataNumber(fx, AMBIENT_FADE_START_KEY) | 0
        const nextAlpha = _ambientFadeAlpha(now | 0, startMs | 0, endMs | 0, alpha, alphaMin)
        sprites.setDataNumber(fx, EFFECT_ALPHA_DATA_KEY, nextAlpha)
        list[write++] = fx
    }
    if (write < list.length) list.length = write
}

function _ambientSpawnMote(nowMs: number): void {
    if (!AMBIENT_MOTE_SKIN_ID) return
    const pt = _ambientPickScreenPoint(AMBIENT_MOTE_MARGIN_PX | 0)
    if (!pt) return
    const now = nowMs | 0
    const fx = sprites.create(_getEffectDummyImage(), SpriteKind.HeroEffect)
    fx.setFlag(SpriteFlag.Ghost, true)
    fx.setFlag(SpriteFlag.RelativeToCamera, true)
    fx.x = pt.x | 0
    fx.y = pt.y | 0
    fx.z = AMBIENT_MOTE_Z | 0
    if ((AMBIENT_MOTE_LIFESPAN_MS | 0) > 0) fx.lifespan = AMBIENT_MOTE_LIFESPAN_MS | 0
    const tintSeed = Math.randomRange(0, Math.max(0, (AMBIENT_MOTE_CYCLE_MS | 0) - 1)) | 0
    const tint = _ambientTint(now | 0, AMBIENT_MOTE_CYCLE_MS | 0, AMBIENT_MOTE_SAT, AMBIENT_MOTE_LIGHT, tintSeed | 0)
    applyEffectToSprite(fx, AMBIENT_MOTE_SKIN_ID, {
        tint,
        alpha: AMBIENT_MOTE_ALPHA,
        blend: AMBIENT_MOTE_BLEND,
        fitRadiusPx: AMBIENT_MOTE_RADIUS_PX,
        repeat: 0,
        forceTop: true,
    })
    const angleDeg = Math.randomRange(0, 359) | 0
    const speed = Math.randomRange(AMBIENT_MOTE_SPEED_MIN_PX | 0, AMBIENT_MOTE_SPEED_MAX_PX | 0) | 0
    const rad = (angleDeg * Math.PI) / 180
    fx.vx = Math.round(Math.cos(rad) * speed)
    fx.vy = Math.round(Math.sin(rad) * speed)
    const fadeEnd = (now + Math.max(1, AMBIENT_MOTE_LIFESPAN_MS | 0)) | 0
    sprites.setDataNumber(fx, AMBIENT_FADE_START_KEY, now | 0)
    sprites.setDataNumber(fx, AMBIENT_FADE_END_KEY, fadeEnd | 0)
    _dunAmbientMotes.push(fx)
}

