function _ambientEnsureWash(nowMs: number): void {
    if (!AMBIENT_WASH_SKIN_ID) return
    const w = scene.screenWidth() | 0
    const h = scene.screenHeight() | 0
    if (w <= 0 || h <= 0) return

    let wash = _dunAmbientWash
    if (!wash || (wash.flags & sprites.Flag.Destroyed)) {
        wash = sprites.create(_getEffectDummyImage(), SpriteKind.HeroEffect)
        wash.setFlag(SpriteFlag.Ghost, true)
        wash.setFlag(SpriteFlag.RelativeToCamera, true)
        wash.z = AMBIENT_WASH_Z | 0
        applyEffectToSprite(wash, AMBIENT_WASH_SKIN_ID, {
            alpha: AMBIENT_WASH_ALPHA_MIN,
            blend: AMBIENT_WASH_BLEND,
            repeat: 0,
            forceTop: true,
        })
        _dunAmbientWash = wash
    }

    wash.x = Math.idiv(w, 2)
    wash.y = Math.idiv(h, 2)

    const now = nowMs | 0
    const tint = _ambientTint(now | 0, AMBIENT_WASH_CYCLE_MS | 0, AMBIENT_WASH_SAT, AMBIENT_WASH_LIGHT, 0)
    const pulse = _ambientPulse(now | 0, AMBIENT_WASH_PULSE_MS | 0, 0)
    const alpha =
        AMBIENT_WASH_ALPHA_MIN +
        (AMBIENT_WASH_ALPHA_MAX - AMBIENT_WASH_ALPHA_MIN) * pulse
    const radius = (Math.max(w, h) + (AMBIENT_WASH_SCALE_PAD_PX | 0)) | 0
    const scale = _effectPickScaleForRadius(AMBIENT_WASH_SKIN_ID, "", radius | 0)
    if (Number.isFinite(scale) && scale > 0) {
        sprites.setDataNumber(wash, EFFECT_SCALE_DATA_KEY, scale)
    }
    sprites.setDataNumber(wash, EFFECT_TINT_DATA_KEY, tint | 0)
    sprites.setDataNumber(wash, EFFECT_ALPHA_DATA_KEY, alpha)
}

function _dunUpdateWorldAmbience(nowMs: number): void {
    if (!DUNGEON_MODE_ACTIVE || !AMBIENT_ENABLED) {
        _dunResetAmbientRuntime()
        return
    }
    if (DEBUG_EFFECTS_HALL_ON_START && DEBUG_EFFECTS_HALL_ONLY_ROWS && (_dunFloorKind || "") === DUNGEON_KIND_HALL) {
        _dunResetAmbientRuntime()
        return
    }
    const now = nowMs | 0

    _ambientUpdateList(_dunAmbientMotes, now | 0, AMBIENT_MOTE_ALPHA, AMBIENT_MOTE_ALPHA_MIN)
    _ambientUpdateList(_dunAmbientHaze, now | 0, AMBIENT_HAZE_ALPHA, AMBIENT_HAZE_ALPHA_MIN)
    _ambientUpdateList(_dunAmbientRays, now | 0, AMBIENT_RAYS_ALPHA, AMBIENT_RAYS_ALPHA_MIN)

    if ((_dunAmbientMoteNextMs | 0) <= 0 || (now | 0) >= (_dunAmbientMoteNextMs | 0)) {
        if ((_dunAmbientMotes.length | 0) < (AMBIENT_MOTE_MAX | 0)) _ambientSpawnMote(now | 0)
        _dunAmbientMoteNextMs =
            (now + Math.randomRange(AMBIENT_MOTE_SPAWN_MIN_MS | 0, AMBIENT_MOTE_SPAWN_MAX_MS | 0)) | 0
    }

    if ((_dunAmbientHazeNextMs | 0) <= 0 || (now | 0) >= (_dunAmbientHazeNextMs | 0)) {
        if ((_dunAmbientHaze.length | 0) < (AMBIENT_HAZE_MAX | 0)) _ambientSpawnHaze(now | 0)
        _dunAmbientHazeNextMs =
            (now + Math.randomRange(AMBIENT_HAZE_SPAWN_MIN_MS | 0, AMBIENT_HAZE_SPAWN_MAX_MS | 0)) | 0
    }

    if ((_dunAmbientRaysNextMs | 0) <= 0 || (now | 0) >= (_dunAmbientRaysNextMs | 0)) {
        if ((_dunAmbientRays.length | 0) < (AMBIENT_RAYS_MAX | 0)) _ambientSpawnRays(now | 0)
        _dunAmbientRaysNextMs =
            (now + Math.randomRange(AMBIENT_RAYS_SPAWN_MIN_MS | 0, AMBIENT_RAYS_SPAWN_MAX_MS | 0)) | 0
    }

    _ambientEnsureWash(now | 0)
}

function _shrineRitualFromInstance(instance: TrapInstance | null): ShrineRitualSpec | null {
    if (!instance) return null
    const inputs: any = (instance as any).inputs || null
    const raw: any = inputs ? inputs.ritual : null
    if (!raw || typeof raw !== "object") return null

    const kind = String(raw.kind || "")
    if (
        kind !== "strength_away" &&
        kind !== "wisdom_near" &&
        kind !== "enemy_near" &&
        kind !== "corner_touch"
    ) return null

    const description = String(raw.description || "")
    let radiusTiles = (raw.radiusTiles | 0)
    if (radiusTiles <= 0) radiusTiles = 2

    const ritual: ShrineRitualSpec = {
        kind: kind as ShrineRitualKind,
        description,
        radiusTiles,
    }

    return ritual
}

function _dunShrineIsRead(state: ShrineState): boolean {
    const decor = state?.decor
    if (!decor || (decor.flags & sprites.Flag.Destroyed)) return false
    return (sprites.readDataNumber(decor, SHRINE_READ_KEY) | 0) > 0
}

function _shrineHeroInRange(hero: Sprite, state: ShrineState, radiusTiles: number): boolean {
    if (!hero || (hero.flags & sprites.Flag.Destroyed)) return false
    if (!state) return false
    const h = _heroCollisionCenterXY(hero)
    const radius = Math.max(1, radiusTiles | 0) * (WORLD_TILE_SIZE | 0)
    const dx = (h.x | 0) - (state.centerX | 0)
    const dy = (h.y | 0) - (state.centerY | 0)
    return ((dx * dx + dy * dy) | 0) <= ((radius * radius) | 0)
}

function _dunEnsureShrineProgressArrays(state: ShrineState): void {
    void state
}

function _dunResetShrineProgress(state: ShrineState): void {
    void state
}

function _dunAdoptShrineInstance(state: ShrineState, next: TrapInstance): void {
    if (!state || !next) return
    if (!state.instance) {
        state.instance = next
        state.ritual = _shrineRitualFromInstance(next)
        state.ritualSeed = next.seed | 0
        _dunResetShrineProgress(state)
        return
    }

    const inst = state.instance
    inst.seed = next.seed | 0
    inst.inputs = next.inputs || {}
    inst.expectedOutput = next.expectedOutput
    inst.outputContract = next.outputContract
    inst.paletteOverride = next.paletteOverride
    inst.uiOverride = next.uiOverride
    inst.starterBlocksOverride = next.starterBlocksOverride
    inst.axes = next.axes
    inst.state = "fresh"
    inst.attempts = 0
    inst.disabledUntilMs = 0
    inst.failCooldownMs = next.failCooldownMs

    state.ritual = _shrineRitualFromInstance(inst)
    state.ritualSeed = inst.seed | 0
    _dunResetShrineProgress(state)
    if (state.ritual) {
        const now = game.runtime() | 0
        _shrineObsMark(state.key, _dunFloorIndex | 0, "ritual_loaded", true, _shrineObsRitualDetail(state.ritual), now | 0)
    }
}

function _dunRescanShrines(nowMs: number): void {
    if (!DUNGEON_MODE_ACTIVE) return
    const now = nowMs | 0
    if ((now | 0) < (_dunShrineStateRescanAtMs | 0)) return
    _dunShrineStateRescanAtMs = (now + (SHRINE_STATE_RESCAN_MS | 0)) | 0

    const seen: Record<string, 1> = Object.create(null)

    const scanList = (list: Sprite[] | null): void => {
        if (!list || list.length <= 0) return
        for (let i = 0; i < list.length; i++) {
            const s = list[i]
            if (!s || (s.flags & sprites.Flag.Destroyed)) continue
            const name = sprites.readDataString(s, DECOR_DATA.NAME) || ""
            if (propBaseNameFromKey(name) !== SHRINE_BASE) continue
            const r = sprites.readDataNumber(s, "decorTileR") | 0
            const c = sprites.readDataNumber(s, "decorTileC") | 0
            if (r < 0 || c < 0) continue
            const key = String(r | 0) + "," + String(c | 0)
            if (seen[key]) continue
            seen[key] = 1

            let state = _dunShrineStates.get(key)
            if (!state) {
                const centerX = _dunColToX(c | 0)
                const centerY = _dunRowToY(r | 0)
                const inst = registerTrapPropSpawn(SHRINE_BASE, _dunFloorIndex | 0, r | 0, c | 0, null)
                const ritual = _shrineRitualFromInstance(inst)
                state = {
                    key,
                    tileR: r | 0,
                    tileC: c | 0,
                    centerX,
                    centerY,
                    decor: s,
                    instance: inst,
                    ritual,
                    ritualSeed: inst ? (inst.seed | 0) : 1,
                    wasActive: (sprites.readDataNumber(s, SHRINE_ACTIVE_UNTIL_KEY) | 0) > (now | 0),
                }
                _dunResetShrineProgress(state)
                _dunShrineStates.set(key, state)
                if (!ritual && inst) {
                    const regen = generateTrapInstanceById(inst.specId, Math.max(1, inst.seed | 0) | 0)
                    if (regen) _dunAdoptShrineInstance(state, regen)
                }
            } else {
                state.decor = s
                state.tileR = r | 0
                state.tileC = c | 0
                state.centerX = _dunColToX(c | 0)
                state.centerY = _dunRowToY(r | 0)
                if (!state.instance) {
                    state.instance = registerTrapPropSpawn(SHRINE_BASE, _dunFloorIndex | 0, r | 0, c | 0, null)
                    if (!state.ritual) state.ritual = _shrineRitualFromInstance(state.instance)
                }
                _dunEnsureShrineProgressArrays(state)
            }
            _shrineObsMark(key, _dunFloorIndex | 0, "decor_present", true, `r=${r | 0} c=${c | 0} floor=${_dunFloorIndex | 0}`, now | 0)
            if (state && state.ritual) {
                _shrineObsMark(key, _dunFloorIndex | 0, "ritual_loaded", true, _shrineObsRitualDetail(state.ritual), now | 0)
            }
        }
    }

    scanList(_engineDecorSolids)
    scanList(_engineDecorTriggers)

    if (_dunShrineStates.size > 0) {
        for (const [key] of _dunShrineStates) {
            if (!seen[key]) _dunShrineStates.delete(key)
        }
    }
}

function _dunRerollShrineRitual(state: ShrineState): void {
    const inst = state.instance
    if (!inst) return
    const nextSeed = Math.max(1, ((state.ritualSeed | 0) + 1) | 0) | 0
    const next = generateTrapInstanceById(inst.specId, nextSeed | 0)
    if (!next) return
    _dunAdoptShrineInstance(state, next)
    if (DEBUG_TRAP_LOGS) {
        console.log("[SHRINE] reroll", { key: state.key, seed: nextSeed | 0 })
    }
}

function _dunShrineFlash(state: ShrineState, nowMs: number): void {
    if (!state || !state.decor) return
    const now = nowMs | 0
    const cur = sprites.readDataNumber(state.decor, SHRINE_FLASH_UNTIL_KEY) | 0
    const until = Math.max(cur | 0, (now + (SHRINE_FLASH_MS | 0)) | 0) | 0
    sprites.setDataNumber(state.decor, SHRINE_FLASH_UNTIL_KEY, until | 0)
}

function _dunShrineTryActivate(state: ShrineState, nowMs: number): void {
    if (!state || !state.decor) return
    const now = nowMs | 0
    const ritualKind = state.ritual ? state.ritual.kind : ""
    _shrineObsMark(state.key, _dunFloorIndex | 0, "ritual_satisfied", true, `kind=${ritualKind || "none"}`, now)
    _shrineObsMark(state.key, _dunFloorIndex | 0, "activation_triggered", true, `kind=${ritualKind || "none"}`, now)
    _dunActivateShrineDecor(state.decor, now | 0, SHRINE_ACTIVE_DEFAULT_MS)
    _dunShrineFlash(state, now | 0)
    state.wasActive = true
    _dunResetShrineProgress(state)
    if (DEBUG_TRAP_LOGS) {
        console.log("[SHRINE] activated", {
            key: state.key,
            ritual: state.ritual ? state.ritual.kind : "",
        })
    }
}

function _shrineHeroFacingAwayFromShrine(heroIndex: number, hero: Sprite, state: ShrineState): boolean {
    if (!hero || !state) return false
    const fx = _getHeroFacingX(heroIndex) | 0
    const fy = _getHeroFacingY(heroIndex) | 0
    if ((fx | 0) === 0 && (fy | 0) === 0) return false
    const h = _heroCollisionCenterXY(hero)
    const dx = (state.centerX | 0) - (h.x | 0)
    const dy = (state.centerY | 0) - (h.y | 0)
    if ((dx | 0) === 0 && (dy | 0) === 0) return false
    const dot = ((fx | 0) * (dx | 0) + (fy | 0) * (dy | 0)) | 0
    return (dot | 0) < 0
}

function _dunShrineCheckEnemyNear(state: ShrineState, nowMs: number): boolean {
    if (!state || !state.ritual) return false
    const radiusTiles = state.ritual.radiusTiles == null ? 2 : (state.ritual.radiusTiles | 0)
    const radius = Math.max(1, radiusTiles | 0) * (WORLD_TILE_SIZE | 0)
    const maxDistSq = (radius * radius) | 0
    const now = nowMs | 0
    for (let i = 0; i < enemies.length; i++) {
        const e = enemies[i]
        if (!e || (e.flags & sprites.Flag.Destroyed)) continue
        const hp = sprites.readDataNumber(e, ENEMY_DATA.HP) | 0
        if ((hp | 0) <= 0) continue
        const deathUntil = sprites.readDataNumber(e, ENEMY_DATA.DEATH_UNTIL) | 0
        if ((deathUntil | 0) > 0 && (deathUntil | 0) > (now | 0)) continue
        const dx = ((e.x | 0) - (state.centerX | 0)) | 0
        const dy = ((e.y | 0) - (state.centerY | 0)) | 0
        const distSq = ((dx * dx + dy * dy) | 0)
        if ((distSq | 0) <= (maxDistSq | 0)) return true
    }
    return false
}

function _dunShrineCheckCornerTouch(): boolean {
    const rows = _dunWorldRows() | 0
    const cols = _dunWorldCols() | 0
    if (rows <= 0 || cols <= 0) return false
    const minR = 0
    const minC = 0
    const maxR = (rows - 1) | 0
    const maxC = (cols - 1) | 0
    for (let hi = 0; hi < heroes.length; hi++) {
        const hero = heroes[hi]
        if (!hero || (hero.flags & sprites.Flag.Destroyed)) continue
        const r = sprites.readDataNumber(hero, HERO_DATA.TILE_R) | 0
        const c = sprites.readDataNumber(hero, HERO_DATA.TILE_C) | 0
        if ((r | 0) === (minR | 0) || (r | 0) === (maxR | 0)) {
            if ((c | 0) === (minC | 0) || (c | 0) === (maxC | 0)) return true
        }
    }
    return false
}

function _dunUpdateShrineRituals(nowMs: number): void {
    if (!DUNGEON_MODE_ACTIVE) return
    const now = nowMs | 0
    _dunRescanShrines(now)
    if (_dunShrineStates.size <= 0) return

    for (const state of _dunShrineStates.values()) {
        const decor = state.decor
        if (!decor || (decor.flags & sprites.Flag.Destroyed)) continue
        const activeUntil = sprites.readDataNumber(decor, SHRINE_ACTIVE_UNTIL_KEY) | 0
        const isActive = (activeUntil | 0) > (now | 0)

        if (isActive) {
            state.wasActive = true
            continue
        }

        if (state.wasActive) {
            state.wasActive = false
            sprites.setDataNumber(decor, SHRINE_ACTIVE_UNTIL_KEY, 0)
            sprites.setDataNumber(decor, SHRINE_ACTIVE_START_KEY, 0)
            sprites.setDataNumber(decor, SHRINE_READ_KEY, 0)
            _dunRerollShrineRitual(state)
        }

        const ritual = state.ritual
        if (!ritual) continue
        if (!_dunShrineIsRead(state)) continue
        if (ritual.kind === "enemy_near") {
            if (_dunShrineCheckEnemyNear(state, now | 0)) {
                _dunShrineTryActivate(state, now | 0)
            }
        } else if (ritual.kind === "corner_touch") {
            if (_dunShrineCheckCornerTouch()) {
                _dunShrineTryActivate(state, now | 0)
            }
        }
    }
}

function _dunShrineOnMoveCommitted(ctx: ShrineMoveCommittedContext): void {
    if (!DUNGEON_MODE_ACTIVE || !ctx) return
    const now = ctx.now | 0
    const hi = ctx.hi | 0
    if (hi < 0 || hi >= heroes.length) return
    _dunRescanShrines(now)
    if (_dunShrineStates.size <= 0) return
    const hero = ctx.hero
    if (!hero || (hero.flags & sprites.Flag.Destroyed)) return

    for (const state of _dunShrineStates.values()) {
        const decor = state.decor
        if (!decor || (decor.flags & sprites.Flag.Destroyed)) continue
        const ritual = state.ritual
        if (!ritual) continue
        if (!_dunShrineIsRead(state)) continue

        const activeUntil = sprites.readDataNumber(decor, SHRINE_ACTIVE_UNTIL_KEY) | 0
        if ((activeUntil | 0) > (now | 0)) continue

        if (ritual.kind === "strength_away") {
            if ((ctx.family | 0) !== (FAMILY.STRENGTH | 0)) continue
            const radiusTiles = ritual.radiusTiles == null ? 2 : (ritual.radiusTiles | 0)
            if (!_shrineHeroInRange(hero, state, radiusTiles | 0)) continue
            if (!_shrineHeroFacingAwayFromShrine(hi | 0, hero, state)) continue
            _dunShrineTryActivate(state, now | 0)
        } else if (ritual.kind === "wisdom_near") {
            if ((ctx.family | 0) !== (FAMILY.WISDOM | 0)) continue
            const radiusTiles = ritual.radiusTiles == null ? 2 : (ritual.radiusTiles | 0)
            if (!_shrineHeroInRange(hero, state, radiusTiles | 0)) continue
            _dunShrineTryActivate(state, now | 0)
        }
    }
}

function _trapTotemElementTint(): number {
    return _elementTintForMode(TRAP_TOTEM_ELEMENT, "offense");
}

function _trapTotemAuraStyle(base: PropAuraStyle): PropAuraStyle {
    const tint = _trapTotemElementTint();
    if (!tint) return base;
    if ((base.tint | 0) === (tint | 0)) return base;
    return { ...base, tint: tint | 0 };
}

function _trapTotemApplyPropTint(renderer?: any): void {
    const tint = _trapTotemElementTint();
    if (!tint) return;
    if ((_dunFireTotemTileR | 0) < 0 || (_dunFireTotemTileC | 0) < 0) return;

    let r: any = renderer;
    if (!r) {
        const g: any = globalThis as any;
        const sc: any = g ? g.__phaserScene : null;
        r = sc?.registry?.get?.("__worldTileRenderer");
    }
    if (!r || typeof r.tryGetPropDisplayAtAnchor !== "function") return;

    const propObj =
        r.tryGetPropDisplayAtAnchor(_dunFireTotemTileR | 0, _dunFireTotemTileC | 0) ||
        (typeof r.tryGetPropDisplayAt === "function"
            ? r.tryGetPropDisplayAt(_dunFireTotemTileR | 0, _dunFireTotemTileC | 0)
            : null);

    if (!propObj) return;
    const last = (propObj as any).__trapTintApplied | 0;
    if ((last | 0) === (tint | 0)) return;
    try {
        propObj.setTint?.(tint | 0);
        (propObj as any).__trapTintApplied = tint | 0;
    } catch { /* ignore */ }
}

type TrapSolveHandler = (target: Sprite, state: TrapInteractState) => void

const TRAP_SOLVE_HANDLERS: Record<string, TrapSolveHandler> = {
    [TRAP_TOTEM_BASE]: (target) => {
        _trapTotemActivate(target)
    },
}

type EffectApplyOpts = {
    dir?: string
    offsetX?: number
    offsetY?: number
    fps?: number
    repeat?: number
    tint?: number
    alpha?: number
    blend?: string
    mode?: "full" | "paint" | "silhouette" | "projectile"
    scale?: number
    rot?: number
    fitRadiusPx?: number
    brushPx?: number
    popMs?: number
    popScale?: number
    popStartMs?: number
    introMs?: number
    introScale?: number
    animDelayMs?: number
    forceTop?: boolean
    frameWindowMs?: number
    frameWindowStart?: number
    frameIndex?: number
    frameIndexIsRaw?: boolean
    frameList?: number[] | string
    frameListIsRaw?: boolean
    yoyo?: boolean
    maskSprite?: Sprite | null
    maskPadOutPx?: number
    maskUseNative?: boolean
    forceVisible?: boolean
    flipX?: boolean
    flipY?: boolean
}

function applyEffectToSprite(s: Sprite, skinId: string, opts?: EffectApplyOpts): void {
    if (!s || (s.flags & sprites.Flag.Destroyed)) return
    sprites.setDataString(s, "effectSkin", skinId)
    if (opts?.dir) sprites.setDataString(s, "effectDir", opts.dir)
    if (typeof opts?.offsetX === "number") sprites.setDataNumber(s, "effectOffX", opts.offsetX)
    if (typeof opts?.offsetY === "number") sprites.setDataNumber(s, "effectOffY", opts.offsetY)
    if (typeof opts?.fps === "number") sprites.setDataNumber(s, "effectFps", opts.fps)
    if (typeof opts?.repeat === "number") sprites.setDataNumber(s, "effectRepeat", opts.repeat)
    if (typeof opts?.tint === "number") sprites.setDataNumber(s, EFFECT_TINT_DATA_KEY, opts.tint | 0)
    if (typeof opts?.alpha === "number") sprites.setDataNumber(s, EFFECT_ALPHA_DATA_KEY, opts.alpha)
    else sprites.setDataNumber(s, EFFECT_ALPHA_DATA_KEY, 0)
    if (typeof opts?.rot === "number") sprites.setDataNumber(s, EFFECT_ROT_DATA_KEY, opts.rot)
    else sprites.setDataNumber(s, EFFECT_ROT_DATA_KEY, 0)
    if (typeof opts?.blend === "string") sprites.setDataString(s, EFFECT_BLEND_DATA_KEY, opts.blend)
    else sprites.setDataString(s, EFFECT_BLEND_DATA_KEY, "")
    sprites.setDataNumber(s, EFFECT_FORCE_TOP_DATA_KEY, opts?.forceTop ? 1 : 0)
    if (typeof opts?.forceVisible === "boolean") {
        sprites.setDataNumber(s, EFFECT_FORCE_VISIBLE_DATA_KEY, opts.forceVisible ? 1 : 0)
    } else {
        sprites.setDataNumber(s, EFFECT_FORCE_VISIBLE_DATA_KEY, 0)
    }
    if (typeof opts?.flipX === "boolean") sprites.setDataNumber(s, EFFECT_FLIP_X_DATA_KEY, opts.flipX ? 1 : 0)
    if (typeof opts?.flipY === "boolean") sprites.setDataNumber(s, EFFECT_FLIP_Y_DATA_KEY, opts.flipY ? 1 : 0)
    if (typeof opts?.frameWindowMs === "number") {
        sprites.setDataNumber(s, EFFECT_FRAME_WINDOW_MS_DATA_KEY, opts.frameWindowMs | 0)
    } else {
        sprites.setDataNumber(s, EFFECT_FRAME_WINDOW_MS_DATA_KEY, 0)
    }
    if (typeof opts?.frameWindowStart === "number") {
        sprites.setDataNumber(s, EFFECT_FRAME_WINDOW_START_DATA_KEY, opts.frameWindowStart | 0)
    } else {
        sprites.setDataNumber(s, EFFECT_FRAME_WINDOW_START_DATA_KEY, 0)
    }
    if (typeof opts?.frameIndex === "number") {
        sprites.setDataNumber(s, EFFECT_FRAME_INDEX_DATA_KEY, opts.frameIndex | 0)
    } else {
        sprites.setDataNumber(s, EFFECT_FRAME_INDEX_DATA_KEY, -1)
    }
    sprites.setDataNumber(s, EFFECT_FRAME_INDEX_IS_RAW_DATA_KEY, opts?.frameIndexIsRaw ? 1 : 0)
    if (opts && Object.prototype.hasOwnProperty.call(opts, "frameList")) {
        let listVal = opts.frameList as any;
        if (Array.isArray(listVal)) listVal = listVal.join(",");
        sprites.setDataString(s, EFFECT_FRAME_LIST_DATA_KEY, String(listVal || ""))
    } else {
        sprites.setDataString(s, EFFECT_FRAME_LIST_DATA_KEY, "")
    }
    sprites.setDataNumber(s, EFFECT_FRAME_LIST_IS_RAW_DATA_KEY, opts?.frameListIsRaw ? 1 : 0)
    if (typeof opts?.yoyo === "boolean") {
        sprites.setDataNumber(s, EFFECT_YOYO_DATA_KEY, opts.yoyo ? 1 : 0)
    } else {
        sprites.setDataNumber(s, EFFECT_YOYO_DATA_KEY, 0)
    }
    if (typeof opts?.maskPadOutPx === "number") {
        sprites.setDataNumber(s, EFFECT_MASK_PAD_OUT_PX_DATA_KEY, opts.maskPadOutPx | 0)
    } else {
        sprites.setDataNumber(s, EFFECT_MASK_PAD_OUT_PX_DATA_KEY, 0)
    }
    if (typeof opts?.maskUseNative === "boolean") {
        sprites.setDataNumber(s, EFFECT_MASK_USE_NATIVE_DATA_KEY, opts.maskUseNative ? 1 : 0)
    } else {
        sprites.setDataNumber(s, EFFECT_MASK_USE_NATIVE_DATA_KEY, 0)
    }
    if (opts && Object.prototype.hasOwnProperty.call(opts, "maskSprite")) {
        const maskSprite = opts.maskSprite || null;
        sprites.setDataSprite(s, EFFECT_MASK_SPRITE_REF_DATA_KEY, maskSprite as any);
    }

    const family = sprites.readDataNumber(s, PROJ_DATA.FAMILY) | 0
    let mode = (opts?.mode || "") as string
    if (!mode) {
        if (family === (FAMILY.STRENGTH | 0) || family === (FAMILY.AGILITY | 0)) mode = "paint"
        else mode = "full"
    }
    sprites.setDataString(s, EFFECT_MODE_DATA_KEY, mode)

    let scale = (typeof opts?.scale === "number") ? opts?.scale : NaN
    if (!Number.isFinite(scale)) {
        const fitRadiusRaw = opts?.fitRadiusPx
        if (typeof fitRadiusRaw === "number" && fitRadiusRaw > 0) {
            const fitRadius = Math.max(fitRadiusRaw | 0, EFFECT_MIN_FIT_RADIUS_PX | 0)
            scale = _effectPickScaleForRadius(skinId, opts?.dir || "", fitRadius)
        }
    }
    if (Number.isFinite(scale)) sprites.setDataNumber(s, EFFECT_SCALE_DATA_KEY, scale as number)
    else sprites.setDataNumber(s, EFFECT_SCALE_DATA_KEY, 0)

    if (typeof opts?.brushPx === "number") sprites.setDataNumber(s, EFFECT_BRUSH_PX_DATA_KEY, opts.brushPx)
    else sprites.setDataNumber(s, EFFECT_BRUSH_PX_DATA_KEY, 0)

    if (typeof opts?.popMs === "number") sprites.setDataNumber(s, EFFECT_POP_MS_DATA_KEY, opts.popMs)
    else sprites.setDataNumber(s, EFFECT_POP_MS_DATA_KEY, 0)

    if (typeof opts?.popScale === "number") sprites.setDataNumber(s, EFFECT_POP_SCALE_DATA_KEY, opts.popScale)
    else sprites.setDataNumber(s, EFFECT_POP_SCALE_DATA_KEY, 0)

    if (typeof opts?.popStartMs === "number") {
        sprites.setDataNumber(s, EFFECT_POP_START_MS_DATA_KEY, opts.popStartMs | 0)
    } else if (typeof opts?.popMs === "number" && opts.popMs > 0) {
        sprites.setDataNumber(s, EFFECT_POP_START_MS_DATA_KEY, game.runtime() | 0)
    } else {
        sprites.setDataNumber(s, EFFECT_POP_START_MS_DATA_KEY, 0)
    }

    if (typeof opts?.introMs === "number") sprites.setDataNumber(s, EFFECT_INTRO_MS_DATA_KEY, opts.introMs)
    else sprites.setDataNumber(s, EFFECT_INTRO_MS_DATA_KEY, 0)

    if (typeof opts?.introScale === "number") sprites.setDataNumber(s, EFFECT_INTRO_SCALE_DATA_KEY, opts.introScale)
    else sprites.setDataNumber(s, EFFECT_INTRO_SCALE_DATA_KEY, 0)

    if (typeof opts?.introMs === "number" && opts.introMs > 0) {
        sprites.setDataNumber(s, EFFECT_INTRO_START_MS_DATA_KEY, game.runtime() | 0)
    } else {
        sprites.setDataNumber(s, EFFECT_INTRO_START_MS_DATA_KEY, 0)
    }

    if (typeof opts?.animDelayMs === "number") sprites.setDataNumber(s, EFFECT_ANIM_DELAY_MS_DATA_KEY, opts.animDelayMs)
    else sprites.setDataNumber(s, EFFECT_ANIM_DELAY_MS_DATA_KEY, 0)

    if (typeof opts?.animDelayMs === "number" && opts.animDelayMs > 0) {
        sprites.setDataNumber(s, EFFECT_ANIM_DELAY_START_MS_DATA_KEY, game.runtime() | 0)
    } else {
        sprites.setDataNumber(s, EFFECT_ANIM_DELAY_START_MS_DATA_KEY, 0)
    }
    if (DEBUG_EFFECTS_DUMP_AFTER_N_APPLIES > 0) _heNoteEffectApplied()
}

let __vfxRegistry: VfxRegistry | null = null
let __vfxHelpers: VfxHelpers | null = null

function _registerVfxPresets(registry: VfxRegistry, helpers: VfxHelpers): void {
    applyStudentVfxPresets(registry, helpers)
    // Presets will live here (see VFX_SYSTEM.md). Keep empty until assets are chosen.
}

function _getVfxRegistry(): VfxRegistry {
    if (__vfxRegistry) return __vfxRegistry
    const created = createVfxRegistry({
        applyEffect: applyEffectToSprite,
        getEffectDummyImage: _getEffectDummyImage,
        nowMs: () => (game && typeof game.runtime === "function") ? (game.runtime() | 0) : (Date.now() | 0)
    })
    __vfxRegistry = created.registry
    __vfxHelpers = created.helpers
    _registerVfxPresets(__vfxRegistry, __vfxHelpers)
    return __vfxRegistry
}

function _getVfxHelpers(): VfxHelpers {
    if (!__vfxRegistry) _getVfxRegistry()
    return __vfxHelpers as VfxHelpers
}
const TRAP_PROMPT_INPUT_DEBOUNCE_MS = 200

function _dunReadInteractAction(it: Sprite): string {
    if (!it || (it.flags & sprites.Flag.Destroyed)) return ""
    const action = (sprites.readDataString(it, INTERACT_DATA.ACTION) || "").trim()
    if (action) return action
    const kind = (sprites.readDataString(it, INTERACT_DATA.KIND) || "").trim()
    return kind
}

function _dunReadInteractUsed(it: Sprite): number {
    if (!it || (it.flags & sprites.Flag.Destroyed)) return 0
    const disabled = sprites.readDataNumber(it, TRAP_DISABLED_KEY) | 0
    if (disabled) return 1
    const used = sprites.readDataNumber(it, INTERACT_DATA.USED) | 0
    const opened = sprites.readDataNumber(it, INTERACT_DATA.OPENED) | 0
    return ((used | 0) !== 0 || (opened | 0) !== 0) ? 1 : 0
}

function _dunSetInteractUsed(it: Sprite, used: boolean): void {
    if (!it || (it.flags & sprites.Flag.Destroyed)) return
    const v = used ? 1 : 0
    sprites.setDataNumber(it, INTERACT_DATA.USED, v)
    sprites.setDataNumber(it, INTERACT_DATA.OPENED, v)
}

function _dunHandleInteractable(it: Sprite, hero: Sprite, pid: number, hi: number, nowMs: number): boolean {
    if (!it || (it.flags & sprites.Flag.Destroyed)) return false
    let action = _dunReadInteractAction(it)
    if (!action) return false
    if (action === "chest") action = INTERACT_ACTION_RELIC_OFFER

    if (action === INTERACT_ACTION_RELIC_OFFER) {
        return _dunHandleInteractRelicOffer(it, hero, pid | 0, hi | 0, nowMs | 0)
    }

    return _dunHandleInteractProp(it, hero, pid | 0, hi | 0, nowMs | 0, action)
}

function _dunHandleInteractProp(it: Sprite, hero: Sprite, pid: number, hi: number, nowMs: number, action: string): boolean {
    if (!it || (it.flags & sprites.Flag.Destroyed)) return false
    const name = sprites.readDataString(it, DECOR_DATA.NAME) || ""
    const baseName = propBaseNameFromKey(name)
    const logInteract = (DEBUG_INTERACT_LOGS || DEBUG_CHEST_INTERACT_LOGS)
    const logProp = (DEBUG_PROP_INTERACT_LOGS || logInteract)
    if (logProp) {
        console.log("[INTERACT][PROP] trigger", {
            pid: pid | 0,
            hi: hi | 0,
            action: String(action || ""),
            name: String(name || ""),
            base: String(baseName || ""),
            x: it.x | 0,
            y: it.y | 0,
        })
    }
    if (action === INTERACT_ACTION_HEADSTONE || baseName === HERO_DEATH_HEADSTONE_PROP) {
        const profile = sprites.readDataString(it, "headstoneProfile") || ""
        if (profile) {
            _heroDeath_showDialog(hero, pid | 0, profile, HERO_DEATH_HEADSTONE_OWNER_PREFIX, true)
            return true
        }
    }
    if (baseName === TRAP_TOTEM_BASE) {
        _dunFireTotemTriggerActivation(nowMs | 0)
    }
    if (baseName === BOOK_MEMORIES_BASE) {
        _dunBookHandleInteract(it, hero, hi | 0, nowMs | 0)
    }

    try {
        const g: any = globalThis as any
        const hook = g?.dun_onPropInteract
        if (typeof hook === "function") {
            hook({
                pid: pid | 0,
                hi: hi | 0,
                hero,
                target: it,
                action: String(action || ""),
                name: String(name || ""),
                now: nowMs | 0,
            })
            if (logProp) {
                console.log("[INTERACT][PROP] hook", {
                    pid: pid | 0,
                    hi: hi | 0,
                    action: String(action || ""),
                    name: String(name || ""),
                })
            }
        } else if (logProp) {
            console.log("[INTERACT][PROP] no hook", {
                pid: pid | 0,
                hi: hi | 0,
                action: String(action || ""),
                name: String(name || ""),
                x: it.x | 0,
                y: it.y | 0,
            })
        }
    } catch (err) {
        if (logProp) {
            console.log("[INTERACT][PROP] hook error", {
                pid: pid | 0,
                hi: hi | 0,
                action: String(action || ""),
                name: String(name || ""),
                err: String((err as any) || ""),
            })
        }
    }

    try {
        dispatchStudentPropInteract({
            pid: pid | 0,
            hi: hi | 0,
            hero,
            target: it,
            action: String(action || ""),
            name: String(name || ""),
            base: String(baseName || ""),
            now: nowMs | 0,
            prop: getStudentProp(baseName),
        })
    } catch { /* ignore */ }

    return true
}

function _dunFindStudentNpcInRange(hero: Sprite): Sprite | null {
    if (!hero || (hero.flags & sprites.Flag.Destroyed)) return null
    for (let i = 0; i < npcActors.length; i++) {
        const npc = npcActors[i]
        if (!npc || (npc.flags & sprites.Flag.Destroyed)) continue
        const id = sprites.readDataString(npc, STUDENT_NPC_ID_KEY) || ""
        if (!id) continue
        if (_isHeroInInteractRange(hero, npc, NPC_INTERACT_EXTRA_X_PX, NPC_INTERACT_EXTRA_Y_PX)) return npc
    }
    return null
}

function _dunHandleStudentNpcInteract(hero: Sprite, pid: number, hi: number, nowMs: number): boolean {
    const npc = _dunFindStudentNpcInRange(hero)
    if (!npc) return false
    const npcId = sprites.readDataString(npc, STUDENT_NPC_ID_KEY) || ""
    if (!npcId) return false
    try {
        return dispatchStudentNpcInteract({
            pid: pid | 0,
            hi: hi | 0,
            hero,
            target: npc,
            action: INTERACT_ACTION_NPC,
            npcId: String(npcId || ""),
            now: nowMs | 0,
            npc: getStudentNpc(npcId),
        })
    } catch {
        return false
    }
}

type TrapInteractState = {
    mode: "prompt" | "editing"
    trapId: string
    instanceId: string
    instance: TrapInstance | null
    target: Sprite
    targetId: number
    inputs: Record<string, unknown>
    pid: number
    heroIndex: number
    prevLocked: boolean
    blockIntentsOwned: boolean
    inputIgnoreUntilMs: number
}

function _trapGetState(): TrapInteractState | null {
    const g: any = globalThis as any
    return (g && g.__heTrapInteractState) ? (g.__heTrapInteractState as TrapInteractState) : null
}

function _trapSetState(state: TrapInteractState | null): void {
    const g: any = globalThis as any
    if (!g) return
    g.__heTrapInteractState = state
}

function _trapClearState(): void {
    const state = _trapGetState()
    if (state) {
        if (!state.prevLocked && state.heroIndex >= 0) {
            unlockHeroControls(state.heroIndex)
        }
        if (state.blockIntentsOwned) {
            DUNGEON_BLOCK_INTENTS = false
        }
    }
    _dunSetFireTotemMenuActive(false)
    _trapSetState(null)
}


const _trapBoltImgCache: { [k: string]: Image } = Object.create(null);

function _trapTotemBoltImage(dir: string): Image {
    const key = (dir || "none").toLowerCase();
    const cached = _trapBoltImgCache[key];
    if (cached) return cached;

    const horiz = key === "left" || key === "right";
    const w = horiz ? 16 : 4;
    const h = horiz ? 4 : 16;
    const img = image.create(w, h);

    if (horiz) {
        const mid = (h >> 1) | 0;
        for (let x = 0; x < w; x++) {
            const jitter = (x % 4 === 0) ? 1 : ((x % 4 === 2) ? -1 : 0);
            let y = (mid + jitter) | 0;
            if (y < 0) y = 0;
            if (y >= h) y = (h - 1) | 0;
            img.setPixel(x, y, 1);
        }
    } else {
        const mid = (w >> 1) | 0;
        for (let y = 0; y < h; y++) {
            const jitter = (y % 4 === 0) ? 1 : ((y % 4 === 2) ? -1 : 0);
            let x = (mid + jitter) | 0;
            if (x < 0) x = 0;
            if (x >= w) x = (w - 1) | 0;
            img.setPixel(x, y, 1);
        }
    }

    _trapBoltImgCache[key] = img;
    return img;
}

function _trapFindNearestEnemy(cx: number, cy: number): Sprite | null {
    let best: Sprite = null as any;
    let bestD2 = 2147483647;
    for (let i = 0; i < enemies.length; i++) {
        const e = enemies[i];
        if (!e || (e.flags & sprites.Flag.Destroyed)) continue;
        const dx = (e.x - cx);
        const dy = (e.y - cy);
        const d2 = (dx * dx + dy * dy);
        if (d2 < bestD2) {
            bestD2 = d2;
            best = e;
        }
    }
    return best;
}

function _trapTotemSpawnBolt(x: number, y: number, vx: number, vy: number, dir: string, tint: number): void {
    const img = _trapTotemBoltImage(dir);
    const bolt = sprites.create(img, SpriteKind.RelicEffect);
    bolt.x = x;
    bolt.y = y;
    bolt.z = 200;
    bolt.vx = vx;
    bolt.vy = vy;
    bolt.lifespan = TRAP_TOTEM_LIFESPAN_MS | 0;

    if (tint) sprites.setDataNumber(bolt, EFFECT_TINT_DATA_KEY, tint | 0);
    sprites.setDataNumber(bolt, TRAP_TOTEM_DMG_KEY, TRAP_TOTEM_DAMAGE | 0);
    sprites.setDataNumber(bolt, TRAP_TOTEM_HIT_MASK_KEY, 0);

    if (DEBUG_TRAP_LOGS) {
        console.log("[TRAP][TOTEM] bolt", {
            x: bolt.x | 0,
            y: bolt.y | 0,
            dir: String(dir || ""),
        });
    }
}

function _trapTotemActivate(it: Sprite): void {
    if (!it || (it.flags & sprites.Flag.Destroyed)) return;

    const cx = it.x;
    const cy = it.y;
    const tint = _trapTotemElementTint();
    const target = _trapFindNearestEnemy(cx, cy);

    if (target) {
        const dx = (target.x - cx);
        const dy = (target.y - cy);
        const dist = Math.sqrt(dx * dx + dy * dy) || 1;
        const lifeSec = Math.max(0.2, (TRAP_TOTEM_LIFESPAN_MS | 0) / 1000);
        const speed = Math.max(TRAP_TOTEM_SPEED, dist / lifeSec);
        const dir = _enemyDirFromVector(dx, dy);
        const vx = (dx / dist) * speed;
        const vy = (dy / dist) * speed;
        const startX = cx + (dx / dist) * TRAP_TOTEM_BOLT_OFFSET_PX;
        const startY = cy + (dy / dist) * TRAP_TOTEM_BOLT_OFFSET_PX;

        if (DEBUG_TRAP_LOGS) {
            console.log("[TRAP][TOTEM] activate", {
                x: cx | 0,
                y: cy | 0,
                targetX: target.x | 0,
                targetY: target.y | 0,
                dir: String(dir || ""),
            });
        }

        _trapTotemSpawnBolt(startX, startY, vx, vy, dir, tint | 0);
    } else {
        const offset = Math.max(8, (WORLD_TILE_SIZE | 0) >> 1);
        if (DEBUG_TRAP_LOGS) {
            console.log("[TRAP][TOTEM] activate (no target)", {
                x: cx | 0,
                y: cy | 0,
                offset: offset | 0,
            });
        }
        _trapTotemSpawnBolt(cx, cy - offset, 0, -TRAP_TOTEM_SPEED, "up", tint | 0);
        _trapTotemSpawnBolt(cx, cy + offset, 0, TRAP_TOTEM_SPEED, "down", tint | 0);
        _trapTotemSpawnBolt(cx - offset, cy, -TRAP_TOTEM_SPEED, 0, "left", tint | 0);
        _trapTotemSpawnBolt(cx + offset, cy, TRAP_TOTEM_SPEED, 0, "right", tint | 0);
    }

    const txt = textsprite.create("LIGHTNING", 0, 2);
    txt.setMaxFontHeight(9);
    txt.setOutline(1, 15);
    txt.setPosition(cx, cy - 12);
    txt.lifespan = 800;
    txt.vy = -8;
}

function _trapOpenReadOnlyInstance(it: Sprite, instance: TrapInstance, pid: number, hi: number, nowMs: number): boolean {
    const g: any = globalThis as any
    const now = nowMs | 0

    const wasLocked = (hi >= 0 && hi < heroes.length)
        ? !!sprites.readDataBoolean(heroes[hi], HERO_DATA.INPUT_LOCKED)
        : false
    if (hi >= 0 && !wasLocked) lockHeroControls(hi)

    const blockOwned = !DUNGEON_BLOCK_INTENTS
    if (blockOwned) DUNGEON_BLOCK_INTENTS = true

    const inputs = instance.inputs || {}
    const state: TrapInteractState = {
        mode: "editing",
        trapId: instance.specId,
        instanceId: instance.instanceId,
        instance,
        target: it,
        targetId: it.id | 0,
        inputs,
        pid: pid | 0,
        heroIndex: hi | 0,
        prevLocked: wasLocked,
        blockIntentsOwned: blockOwned,
        inputIgnoreUntilMs: (now + (TRAP_PROMPT_INPUT_DEBOUNCE_MS | 0)) | 0,
    }

    _trapSetState(state)
    if (state.instanceId) setTrapInstanceState(state.instanceId, "editing")

    const openInstance = g ? g.__heOpenTrapBlocklyEditorInstance : null
    const open = g ? g.__heOpenTrapBlocklyEditor : null
    const markShrineRead = (): void => {
        const name = sprites.readDataString(it, DECOR_DATA.NAME) || ""
        if (propBaseNameFromKey(name) !== SHRINE_BASE) return
        const tileR = sprites.readDataNumber(it, "decorTileR") | 0
        const tileC = sprites.readDataNumber(it, "decorTileC") | 0
        const decor = _dunFindDecorAtTile(tileR | 0, tileC | 0, SHRINE_BASE) || _dunFindDecorAtTile(tileR | 0, tileC | 0, "")
        if (decor && !(decor.flags & sprites.Flag.Destroyed)) {
            sprites.setDataNumber(decor, SHRINE_READ_KEY, 1)
        }
        sprites.setDataNumber(it, SHRINE_READ_KEY, 1)
    }
    if (state.instance && typeof openInstance === "function") {
        try {
            openInstance(state.instance)
            markShrineRead()
            return true
        } catch (err) {
            if (DEBUG_TRAP_LOGS) {
                console.log("[TRAP][PROMPT] blockly open failed", { err: String((err as any) || "") })
            }
        }
    } else if (typeof open === "function") {
        try {
            open(state.trapId, state.inputs)
            markShrineRead()
            return true
        } catch (err) {
            if (DEBUG_TRAP_LOGS) {
                console.log("[TRAP][PROMPT] blockly open failed", { err: String((err as any) || "") })
            }
        }
    } else if (DEBUG_TRAP_LOGS) {
        console.log("[TRAP][PROMPT] missing blockly hook", { trapId: state.trapId })
    }

    _trapClearState()
    return false
}

function _trapShowPrompt(it: Sprite, baseName: string, pid: number, hi: number): boolean {
    const g: any = globalThis as any
    const dlg = g ? g.__heDialog : null
    if (!dlg || typeof dlg.show !== "function") {
        if (DEBUG_TRAP_LOGS) console.log("[TRAP][PROMPT] skip: no dialog")
        return false
    }

    // Ensure any prior dialog is closed before we set trap state.
    try { if (typeof dlg.hide === "function") dlg.hide() } catch { }

    // Clear any previous trap state before we show the dialog.
    _trapClearState()

    const net: any = g ? g.__net : null
    if (net && typeof net.playerId === "number" && (net.playerId | 0) > 0 && (net.playerId | 0) !== (pid | 0)) {
        if (DEBUG_TRAP_LOGS) {
            console.log("[TRAP][PROMPT] skip: not local", {
                pid: pid | 0,
                localPid: net.playerId | 0,
            })
        }
        return false
    }

    if (sprites.readDataNumber(it, TRAP_SOLVED_KEY) | 0) {
        if (DEBUG_TRAP_LOGS) console.log("[TRAP][PROMPT] skip: solved")
        return false
    }
    if (sprites.readDataNumber(it, TRAP_DISABLED_KEY) | 0) {
        if (DEBUG_TRAP_LOGS) console.log("[TRAP][PROMPT] skip: disabled")
        return false
    }

    const def = getTrapDefinitionForProp(baseName)
    if (!def) {
        if (DEBUG_TRAP_LOGS) console.log("[TRAP][PROMPT] skip: no trap def", { baseName })
        return false
    }

    const now = game.runtime() | 0
    const instance = spawnTrapInstanceForProp(baseName, it, _dunFloorIndex | 0)
    if (!instance) {
        if (DEBUG_TRAP_LOGS) console.log("[TRAP][PROMPT] skip: no instance", { baseName })
        return false
    }
    if (baseName === SHRINE_BASE) {
        if (DEBUG_SHRINE_FORCE_ACTIVATE) {
            const tileR = sprites.readDataNumber(it, "decorTileR") | 0
            const tileC = sprites.readDataNumber(it, "decorTileC") | 0
            const obsKey = _shrineObsKey(tileR | 0, tileC | 0)
            _shrineObsMark(
                obsKey,
                _dunFloorIndex | 0,
                "activation_triggered",
                true,
                "kind=debug",
                now | 0
            )
            const activated = _dunActivateShrineAt(tileR | 0, tileC | 0, now | 0, SHRINE_ACTIVE_DEFAULT_MS)
            if (DEBUG_TRAP_LOGS) {
                console.log("[SHRINE][DEBUG] force activate", {
                    r: tileR | 0,
                    c: tileC | 0,
                    ok: activated ? 1 : 0,
                })
            }
        }
        if (DEBUG_SHRINE_FORCE_OPEN_EDITOR) {
            return _trapOpenReadOnlyInstance(it, instance, pid | 0, hi | 0, now | 0)
        }
    }
    if (!canAttemptTrapInstance(instance, now | 0)) {
        if (DEBUG_TRAP_LOGS) {
            console.log("[TRAP][PROMPT] skip: attempts exhausted", {
                trapId: instance.specId,
                instanceId: instance.instanceId,
                attempts: instance.attempts | 0,
                maxAttempts: instance.maxAttempts | 0,
            })
        }
        sprites.setDataNumber(it, TRAP_DISABLED_KEY, 1)
        _dunSetInteractUsed(it, true)
        return false
    }

    if (baseName === SHRINE_BASE) {
        return _trapOpenReadOnlyInstance(it, instance, pid | 0, hi | 0, now | 0)
    }

    dlg.show({
        speaker: "Trap",
        text: "It's a trap! What do you want to do?",
        choices: [
            { id: "fix_trap", label: "Fix trap" },
            { id: "quit", label: "Quit" },
        ],
        hint: "Q: Fix trap  |  W: Quit",
    })

    const opened = (typeof dlg.isOpen === "function") ? !!dlg.isOpen() : true
    if (!opened) {
        if (DEBUG_TRAP_LOGS) console.log("[TRAP][PROMPT] skip: dialog not open")
        return false
    }

    const wasLocked = (hi >= 0 && hi < heroes.length)
        ? !!sprites.readDataBoolean(heroes[hi], HERO_DATA.INPUT_LOCKED)
        : false
    if (hi >= 0 && !wasLocked) lockHeroControls(hi)

    const blockOwned = !DUNGEON_BLOCK_INTENTS
    if (blockOwned) DUNGEON_BLOCK_INTENTS = true

    const inputs = instance.inputs || {}
    const state: TrapInteractState = {
        mode: "prompt",
        trapId: instance.specId,
        instanceId: instance.instanceId,
        instance: instance,
        target: it,
        targetId: it.id | 0,
        inputs,
        pid: pid | 0,
        heroIndex: hi | 0,
        prevLocked: wasLocked,
        blockIntentsOwned: blockOwned,
        inputIgnoreUntilMs: (now + (TRAP_PROMPT_INPUT_DEBOUNCE_MS | 0)) | 0,
    }

    _trapSetState(state)

    if (DEBUG_TRAP_LOGS) {
        console.log("[TRAP][PROMPT] show", {
            pid: pid | 0,
            trapId: state.trapId,
            instanceId: state.instanceId,
            inputs: state.inputs,
            x: it.x | 0,
            y: it.y | 0,
        })
    }

    return true
}

function _trapHandleDialogChoice(choiceId: string, choiceIndex?: number): void {
    const state = _trapGetState()
    if (!state || state.mode !== "prompt") return
    if (DEBUG_TRAP_LOGS) {
        console.log("[TRAP][PROMPT] choice", {
            choice: String(choiceId || ""),
            trapId: state.trapId,
        })
    }

    const g: any = globalThis as any
    const dlg = g ? g.__heDialog : null
    try { if (dlg && typeof dlg.hide === "function") dlg.hide() } catch { }

    const key = String(choiceId || "").trim().toLowerCase().replace(/\s+/g, "_")
    const isFix = key === "fix_trap" || key === "fix" || key === "fixtrap" || choiceIndex === 0
    const isQuit = key === "quit" || key === "cancel" || choiceIndex === 1

    if (isFix) {
        state.mode = "editing"
        _trapSetState(state)
        if (state.instanceId) setTrapInstanceState(state.instanceId, "editing")
        const open = g ? g.__heOpenTrapBlocklyEditor : null
        const openInstance = g ? g.__heOpenTrapBlocklyEditorInstance : null
        if (state.instance && typeof openInstance === "function") {
            if (DEBUG_TRAP_LOGS) {
                console.log("[TRAP][PROMPT] handoff -> blockly", {
                    trapId: state.trapId,
                    instanceId: state.instanceId,
                    inputs: state.inputs,
                })
            }
            try {
                openInstance(state.instance)
            } catch (err) {
                if (DEBUG_TRAP_LOGS) {
                    console.log("[TRAP][PROMPT] blockly open failed", { err: String((err as any) || "") })
                }
                _trapClearState()
            }
        } else if (typeof open === "function") {
            if (DEBUG_TRAP_LOGS) {
                console.log("[TRAP][PROMPT] handoff -> blockly", {
                    trapId: state.trapId,
                    inputs: state.inputs,
                })
            }
            try {
                open(state.trapId, state.inputs)
            } catch (err) {
                if (DEBUG_TRAP_LOGS) {
                    console.log("[TRAP][PROMPT] blockly open failed", { err: String((err as any) || "") })
                }
                _trapClearState()
            }
        } else {
            if (DEBUG_TRAP_LOGS) {
                console.log("[TRAP][PROMPT] missing blockly hook", { trapId: state.trapId })
            }
            _trapClearState()
        }
        return
    }

    if (isQuit) {
        if (state.instanceId) setTrapInstanceState(state.instanceId, "fresh")
        _trapClearState()
        return
    }

    _trapClearState()
}

function _trapDispatchSolveEffect(state: TrapInteractState): void {
    const target = state ? state.target : null
    if (!target || (target.flags & sprites.Flag.Destroyed)) return
    const name = sprites.readDataString(target, DECOR_DATA.NAME) || ""
    const base = propBaseNameFromKey(name)
    const handler = TRAP_SOLVE_HANDLERS[base]
    if (handler) {
        handler(target, state)
        return
    }
    if (DEBUG_TRAP_LOGS) {
        console.log("[TRAP][SOLVE] no handler", {
            base: String(base || ""),
            trapId: String(state.trapId || ""),
            instanceId: String(state.instanceId || ""),
        })
    }
}

function _trapHandleResult(detail: any): void {
    const state = _trapGetState()
    if (!state || state.mode !== "editing") return
    if (!detail) return
    const detailInstanceId = String(detail.instanceId || "")
    const detailTrapId = String(detail.trapId || "")
    if (detailInstanceId) {
        if (detailInstanceId !== state.instanceId) return
    } else if (detailTrapId !== state.trapId) {
        return
    }
    if (detail.ok) return

    const target = state.target
    if (!target || (target.flags & sprites.Flag.Destroyed)) return

    const now = game.runtime() | 0
    const attempt = recordTrapAttempt(state.instanceId, false, now)
    if (DEBUG_TRAP_LOGS) {
        console.log("[TRAP][PROMPT] wrong answer", {
            trapId: state.trapId,
            instanceId: state.instanceId,
            attempts: attempt ? (attempt.attempts | 0) : -1,
            maxAttempts: attempt ? (attempt.maxAttempts | 0) : -1,
            locked: attempt ? (attempt.locked ? 1 : 0) : 0,
        })
    }
    if (attempt && attempt.locked) {
        sprites.setDataNumber(target, TRAP_DISABLED_KEY, 1)
        _dunSetInteractUsed(target, true)
        const g: any = globalThis as any
        const close = g ? g.__heCloseTrapBlocklyEditor : null
        if (typeof close === "function") {
            try { close() } catch { }
        }
        _trapClearState()
    }
}

function _trapHandleSolved(detail: any): void {
    const state = _trapGetState()
    if (!state || state.mode !== "editing") return
    if (!detail) return
    const detailTrapId = String(detail.trapId || "")
    const detailInstanceId = String(detail.instanceId || "")
    if (detailInstanceId) {
        if (detailInstanceId !== state.instanceId) return
    } else if (detailTrapId !== state.trapId) {
        return
    }

    const target = state.target
    if (!target || (target.flags & sprites.Flag.Destroyed)) {
        _trapClearState()
        return
    }

    if (DEBUG_TRAP_LOGS) {
        console.log("[TRAP][PROMPT] solved", {
            trapId: state.trapId,
            targetId: state.targetId | 0,
        })
    }

    if (state.instanceId) setTrapInstanceState(state.instanceId, "solved")
    _trapDispatchSolveEffect(state)
    sprites.setDataNumber(target, TRAP_SOLVED_KEY, 1)
    _dunSetInteractUsed(target, true)

    const g: any = globalThis as any
    const close = g ? g.__heCloseTrapBlocklyEditor : null
    if (typeof close === "function") {
        try { close() } catch { }
    }

    _trapClearState()
}

function _trapOnPropInteract(payload: any): boolean {
    if (!payload) return false
    const name = String(payload.name || "")
    const baseName = propBaseNameFromKey(name)
    if (!getTrapDefinitionForProp(baseName)) return false
    const it = payload.target as Sprite
    if (!it || (it.flags & sprites.Flag.Destroyed)) return false
    if (baseName === SHRINE_BASE) {
        const tileR = sprites.readDataNumber(it, "decorTileR") | 0
        const tileC = sprites.readDataNumber(it, "decorTileC") | 0
        const obsKey = _shrineObsKey(tileR | 0, tileC | 0)
        _shrineObsMark(
            obsKey,
            _dunFloorIndex | 0,
            "interact_triggered",
            true,
            `pid=${payload.pid | 0} hi=${payload.hi | 0}`,
            game.runtime() | 0
        )
    }
    if (DEBUG_TRAP_LOGS) {
        console.log("[TRAP][PROMPT] interact", {
            pid: payload.pid | 0,
            hi: payload.hi | 0,
            name: String(name || ""),
            base: String(baseName || ""),
            x: it.x | 0,
            y: it.y | 0,
        })
    }
    return _trapShowPrompt(it, baseName, payload.pid | 0, payload.hi | 0)
}

function _trapPromptInputTick(): void {
    const state = _trapGetState()
    if (!state || state.mode !== "prompt") return

    const pid = state.pid | 0
    if (pid <= 0) return

    const now = game.runtime() | 0
    const profileKey = _resolveProfileKeyForPlayerId(pid)
    if (!profileKey) return
    const st = _getInputStateForProfile(profileKey)

    const prevKeyA = `__trapPrevA_${pid}`
    const prevKeyB = `__trapPrevB_${pid}`
    const wasA = (globalThis as any)[prevKeyA] ? 1 : 0
    const wasB = (globalThis as any)[prevKeyB] ? 1 : 0
    const isA = st.A ? 1 : 0
    const isB = st.B ? 1 : 0
    ;(globalThis as any)[prevKeyA] = (isA != 0)
    ;(globalThis as any)[prevKeyB] = (isB != 0)

    if ((state.inputIgnoreUntilMs | 0) > (now | 0)) {
        return
    }

    if (isA && !wasA) {
        if (DEBUG_TRAP_LOGS) console.log("[TRAP][PROMPT] A pressed")
        _trapHandleDialogChoice("fix_trap", 0)
        return
    }
    if (isB && !wasB) {
        if (DEBUG_TRAP_LOGS) console.log("[TRAP][PROMPT] B pressed")
        _trapHandleDialogChoice("quit", 1)
    }
}

function _dunHandleInteractRelicOffer(it: Sprite, hero: Sprite, pid: number, hi: number, nowMs: number): boolean {
    if (!it || (it.flags & sprites.Flag.Destroyed)) return false
    if (_dunReadInteractUsed(it)) return false

    _dunSetInteractUsed(it, true)

    const chestRole = sprites.readDataString(it, INTERACT_DATA.CHEST_ROLE) || ""
    const chestStyleBase = _dunChestGetStyleBase(it)
    const offerResult = chestRole
        ? _relicOfferStartFromChest(pid | 0, hi | 0, nowMs | 0, it, "chest:" + String(chestRole || ""))
        : _relicOfferStartFromChest(pid | 0, hi | 0, nowMs | 0, it, "chest")

    if (DEBUG_RELIC_LOGS) {
        if (offerResult.ok) {
            console.log("[RELIC][OFFER] chest handoff -> DOM", {
                pid: pid | 0,
                hi: hi | 0,
                role: chestRole || "",
                source: (_relicOfferSession && _relicOfferSession.source) ? _relicOfferSession.source : "chest",
            })
        } else {
            console.log("[RELIC][OFFER] chest handoff skipped", {
                pid: pid | 0,
                hi: hi | 0,
                role: chestRole || "",
                reason: offerResult.reason || "unknown",
            })
        }
    }



    // Capture pop coords BEFORE destroy so VFX has a stable origin.

    const popX = it.x

    const popY = it.y - 12



    // Flip the prop state so Phaser stamps the "open" frame.
    let chestR = sprites.readDataNumber(it, "decorTileR") | 0
    let chestC = sprites.readDataNumber(it, "decorTileC") | 0
    const chestOffX = sprites.readDataNumber(it, "decorOffX") | 0
    const chestOffY = sprites.readDataNumber(it, "decorOffY") | 0
    if (chestR < 0 || chestC < 0) {
        chestR = _dunChestTileR | 0
        chestC = _dunChestTileC | 0
    }

    _dunDestroySprite(it)

    if (chestR >= 0 && chestC >= 0) {

        _dunDecor_upsertChestSolid(chestR, chestC, true, chestStyleBase, chestOffX | 0, chestOffY | 0)

        _engineDecorRev = (_engineDecorRev + 1) | 0

    }



    // Reward + complete objective (this triggers COINFX enqueue)

    let coinsReward = 10

    // Relic chests: no coins; relic offer only.
    const chestRoleLower = (chestRole || "").toLowerCase()
    const noCoins = chestRoleLower.indexOf("starter") >= 0 || chestRoleLower.indexOf("boss") >= 0 || chestRoleLower.indexOf("relic") >= 0
    if (noCoins) coinsReward = 0



    // RELIC HOOK: chest opened (may modify reward / later open offers)

    try {

        const chestCtx: RelicChestOpenedContext = {

            now: nowMs | 0,

            pid: pid | 0,

            hi: hi | 0,

            hero,

            coinsReward: coinsReward | 0,

            popX: popX | 0,

            popY: popY | 0,

        }

        relic_onChestOpened(chestCtx)

        coinsReward = (chestCtx.coinsReward | 0)

        if (coinsReward < 0) coinsReward = 0

    } catch { }



    if (!offerResult.ok && _dunFloorKind === DUNGEON_KIND_ENTRANCE && chestRole === "starter_relic") {
        try { _relicOfferStartStarterChoice(pid | 0, hi | 0, nowMs | 0, "entrance-chest") } catch { }
    }

    if (coinsReward > 0) addHeroCoins(hi, coinsReward, popX, popY)



    const objectiveChestFloor = (_dunFloorKind === DUNGEON_KIND_ENTRANCE || _dunFloorKind === DUNGEON_KIND_TREASURE)
    if (objectiveChestFloor) {
        let pending = false
        if (_dunFloorKind === DUNGEON_KIND_TREASURE) {
            pending = _dunHasPendingChestObjectives()
        }
        if (!pending) {
            _dunObjectiveDone = true
            _dunSetPadPowered(true)
            _dunLog(`chest opened by P${pid}; pad powered`)
        }
    }

    return true
}



let DUNGEON_MODE_ACTIVE = false

let DUNGEON_BLOCK_INTENTS = false



let _dunFloorIndex = 0

let _dunFloorKind = DUNGEON_KIND_ENTRANCE

