function _buildSmokePingPongFrames(frameCount: number): number[] {
    const count = Math.max(1, frameCount | 0)
    const out: number[] = []
    for (let i = 0; i < count; i++) out.push(i | 0)
    for (let i = count - 2; i >= 1; i--) out.push(i | 0)
    return out
}
