function _dunResetShrineRuntime(): void {
    _dunShrineStates.clear()
    _dunShrineStateRescanAtMs = 0
    _dunShrineBlessingUntilMs = 0
    _dunShrineBlessingFloor = -1
    _dunShrineBlessingKey = ""
    _dunShrineTileR = -1
    _dunShrineTileC = -1
    _dunShrineInteractRescanAtMs = 0
    _shrineObsResetAll()
    _dunShrineSparkles = []
    _dunShrineAmbientSparkles = []
    _dunShrineAmbientNextMs = 0
}

function _dunResetAmbientRuntime(): void {
    if (_dunAmbientMotes && _dunAmbientMotes.length) {
        for (let i = 0; i < _dunAmbientMotes.length; i++) {
            const fx = _dunAmbientMotes[i]
            if (!fx || (fx.flags & sprites.Flag.Destroyed)) continue
            fx.destroy()
        }
    }
    if (_dunAmbientHaze && _dunAmbientHaze.length) {
        for (let i = 0; i < _dunAmbientHaze.length; i++) {
            const fx = _dunAmbientHaze[i]
            if (!fx || (fx.flags & sprites.Flag.Destroyed)) continue
            fx.destroy()
        }
    }
    if (_dunAmbientRays && _dunAmbientRays.length) {
        for (let i = 0; i < _dunAmbientRays.length; i++) {
            const fx = _dunAmbientRays[i]
            if (!fx || (fx.flags & sprites.Flag.Destroyed)) continue
            fx.destroy()
        }
    }
    if (_dunAmbientWash && !(_dunAmbientWash.flags & sprites.Flag.Destroyed)) {
        _dunAmbientWash.destroy()
    }
    _dunAmbientMotes = []
    _dunAmbientHaze = []
    _dunAmbientRays = []
    _dunAmbientWash = null
    _dunAmbientMoteNextMs = 0
    _dunAmbientHazeNextMs = 0
    _dunAmbientRaysNextMs = 0
}

function _dunFindDecorAtTile(tileR: number, tileC: number, baseName?: string): Sprite | null {
    const r = tileR | 0
    const c = tileC | 0
    const wantBase = (baseName || "").trim()

    function match(list: Sprite[] | null): Sprite | null {
        if (!list || list.length <= 0) return null
        for (let i = 0; i < list.length; i++) {
            const s = list[i]
            if (!s || (s.flags & sprites.Flag.Destroyed)) continue
            const sr = sprites.readDataNumber(s, "decorTileR") | 0
            const sc = sprites.readDataNumber(s, "decorTileC") | 0
            if ((sr | 0) !== (r | 0) || (sc | 0) !== (c | 0)) continue
            if (!wantBase) return s
            const nm = sprites.readDataString(s, DECOR_DATA.NAME) || ""
            if (propBaseNameFromKey(nm) === wantBase) return s
        }
        return null
    }

    return match(_engineDecorSolids) || match(_engineDecorTriggers) || null
}

function _dunActivateShrineDecor(decor: Sprite, nowMs: number, durationMs?: number): void {
    if (!decor || (decor.flags & sprites.Flag.Destroyed)) {
        if (DEBUG_TRAP_LOGS) {
            console.log("[SHRINE] activate failed: missing decor")
        }
        return
    }
    const now = nowMs | 0
    const dur = ((durationMs == null ? SHRINE_ACTIVE_DEFAULT_MS : durationMs) | 0)
    const until = (now + Math.max(0, dur)) | 0
    const tileR = sprites.readDataNumber(decor, "decorTileR") | 0
    const tileC = sprites.readDataNumber(decor, "decorTileC") | 0
    const obsKey = _shrineObsKey(tileR | 0, tileC | 0)
    sprites.setDataNumber(decor, SHRINE_ACTIVE_UNTIL_KEY, until | 0)
    sprites.setDataNumber(decor, SHRINE_ACTIVE_START_KEY, now | 0)
    if (dur > 0) {
        if (obsKey && DEBUG_SHRINE_OBSERVER) {
            const state = _shrineObsGetState(obsKey, _dunFloorIndex | 0, now | 0)
            _shrineObsStartActivation(state, now | 0, until | 0)
        }
        const prevUntil = _dunShrineBlessingUntilMs | 0
        const prevFloor = _dunShrineBlessingFloor | 0
        let applied = 0
        if ((prevUntil | 0) < (until | 0)) {
            _dunShrineBlessingUntilMs = until | 0
            _dunShrineBlessingFloor = _dunFloorIndex | 0
            applied = 1
        }
        if (applied && obsKey) _dunShrineBlessingKey = obsKey
        if (applied) {
            _dunSpawnShrineSparkles(
                decor,
                tileR | 0,
                tileC | 0,
                SHRINE_SPARKLE_BURST_COUNT,
                SHRINE_SPARKLE_BURST_SPREAD_PX,
                now | 0
            )
            const nextSparkle =
                (now + Math.randomRange(SHRINE_SPARKLE_IDLE_INTERVAL_MIN_MS, SHRINE_SPARKLE_IDLE_INTERVAL_MAX_MS)) | 0
            sprites.setDataNumber(decor, SHRINE_SPARKLE_NEXT_MS_KEY, nextSparkle | 0)
        }
        _shrineObsMark(
            obsKey,
            _dunFloorIndex | 0,
            "blessing_set",
            true,
            `applied=${applied | 0} until=${until | 0} dur=${dur | 0} floor=${_dunFloorIndex | 0}`,
            now | 0
        )
        if (DEBUG_TRAP_LOGS) {
            console.log("[SHRINE] blessing", {
                applied,
                floor: _dunFloorIndex | 0,
                r: tileR | 0,
                c: tileC | 0,
                now: now | 0,
                until: until | 0,
                durationMs: dur | 0,
                prevUntil: prevUntil | 0,
                prevFloor: prevFloor | 0,
            })
        }
    } else {
        _shrineObsMark(
            obsKey,
            _dunFloorIndex | 0,
            "blessing_set",
            false,
            `applied=0 until=${until | 0} dur=${dur | 0} floor=${_dunFloorIndex | 0}`,
            now | 0
        )
        if (!DEBUG_TRAP_LOGS) return
        console.log("[SHRINE] blessing skipped", {
            floor: _dunFloorIndex | 0,
            now: now | 0,
            durationMs: dur | 0,
        })
    }
}

function _dunActivateShrineAt(tileR: number, tileC: number, nowMs: number, durationMs?: number): boolean {
    const decor = _dunFindDecorAtTile(tileR | 0, tileC | 0, SHRINE_BASE)
    if (!decor || (decor.flags & sprites.Flag.Destroyed)) {
        if (DEBUG_TRAP_LOGS) {
            console.log("[SHRINE] activate failed: no decor at tile", {
                r: tileR | 0,
                c: tileC | 0,
            })
        }
        return false
    }
    _dunActivateShrineDecor(decor, nowMs | 0, durationMs)
    return true
}

try { (globalThis as any).dun_activateShrineAt = _dunActivateShrineAt } catch { /* ignore */ }

function _dunFireTotemSetState(state: string): void {
    if (!_dunFireTotemDecor || (_dunFireTotemDecor.flags & sprites.Flag.Destroyed)) {
        if ((_dunFireTotemTileR | 0) >= 0 && (_dunFireTotemTileC | 0) >= 0) {
            _dunFireTotemDecor = _dunFindDecorAtTile(_dunFireTotemTileR | 0, _dunFireTotemTileC | 0, "fire_totem")
        }
    }
    if (!_dunFireTotemDecor || (_dunFireTotemDecor.flags & sprites.Flag.Destroyed)) return
    const st = String(state || "").trim()
    if (!st) return
    if (_dunFireTotemState === st) return
    _dunFireTotemState = st
    _dunDecor_setName(_dunFireTotemDecor, `fire_totem#${st}`)
}

function _dunFireTotemTriggerActivation(nowMs: number): void {
    if ((_dunFireTotemTileR | 0) < 0 || (_dunFireTotemTileC | 0) < 0) return
    const now = nowMs | 0
    _dunFireTotemActiveUntilMs = Math.max(_dunFireTotemActiveUntilMs | 0, (now + (FIRE_TOTEM_ACTIVE_AURA_MS | 0)) | 0)
    _dunFireTotemAnimUntilMs = Math.max(_dunFireTotemAnimUntilMs | 0, (now + (FIRE_TOTEM_ANIM_MS | 0)) | 0)
    _dunFireTotemSetState("diag")
    if (DEBUG_TRAP_LOGS || DEBUG_PROP_INTERACT_LOGS) {
        console.log("[TRAP][TOTEM] activation", {
            r: _dunFireTotemTileR | 0,
            c: _dunFireTotemTileC | 0,
            activeUntilMs: _dunFireTotemActiveUntilMs | 0,
            animUntilMs: _dunFireTotemAnimUntilMs | 0,
        })
    }
}

function _dunSetFireTotemMenuActive(active: boolean): void {
    _dunFireTotemMenuActive = !!active
}

try { (globalThis as any).dun_setFireTotemMenuActive = _dunSetFireTotemMenuActive } catch { /* ignore */ }

const TRAP_CENTER_SEARCH_RADIUS = 6
const TRAP_ENTRANCE_USE_CENTER_SPAWN = false
const TRAP_SHRINE_MIN_CHEB = 2

function _dunFindShrineTile(): { r: number, c: number } | null {
    if ((_dunShrineTileR | 0) >= 0 && (_dunShrineTileC | 0) >= 0) {
        return { r: _dunShrineTileR | 0, c: _dunShrineTileC | 0 }
    }
    let found: { r: number, c: number } | null = null
    const scan = (list: Sprite[] | null): void => {
        if (!list || list.length <= 0 || found) return
        for (let i = 0; i < list.length; i++) {
            const s = list[i]
            if (!s || (s.flags & sprites.Flag.Destroyed)) continue
            const name = sprites.readDataString(s, DECOR_DATA.NAME) || ""
            if (propBaseNameFromKey(name) !== SHRINE_BASE) continue
            const r = sprites.readDataNumber(s, "decorTileR") | 0
            const c = sprites.readDataNumber(s, "decorTileC") | 0
            found = { r: r | 0, c: c | 0 }
            return
        }
    }
    scan(_engineDecorSolids)
    scan(_engineDecorTriggers)
    if (found) {
        _dunShrineTileR = found.r | 0
        _dunShrineTileC = found.c | 0
    }
    return found
}

function _dunSideFromPad(tileR: number, tileC: number, padR: number, padC: number): number {
    const pr = padR | 0
    const pc = padC | 0
    if (pr < 0 || pc < 0) return -1
    const dr = (tileR | 0) - pr
    const dc = (tileC | 0) - pc
    if ((dr | 0) === 0 && (dc | 0) === 0) return -1
    const ar = Math.abs(dr) | 0
    const ac = Math.abs(dc) | 0
    if (ar >= ac) return (dr < 0) ? 0 : 2 // top/bottom
    return (dc < 0) ? 3 : 1 // left/right
}

function _dunEnterFloor_spawnStarterFireTotem(defOverride?: TrapDefinition | null): void {
    const rows = _dunWorldRows() | 0
    const cols = _dunWorldCols() | 0
    if (rows <= 0 || cols <= 0) return

    const padR = _dunPadTileR | 0
    const padC = _dunPadTileC | 0
    const centerR = (padR >= 0 ? padR : (Math.idiv(rows, 2) | 0)) | 0
    const centerC = (padC >= 0 ? padC : (Math.idiv(cols, 2) | 0)) | 0
    const shrinePos = _dunFindShrineTile()
    const shrineR = shrinePos ? (shrinePos.r | 0) : -1
    const shrineC = shrinePos ? (shrinePos.c | 0) : -1
    const shrineSide = shrinePos ? _dunSideFromPad(shrineR | 0, shrineC | 0, padR | 0, padC | 0) : -1

    let r = Math.max(0, Math.min(rows - 1, (padR + 3) | 0)) | 0
    let c = Math.max(0, Math.min(cols - 1, (padC + 2) | 0)) | 0

    function hasDecorAt(rr: number, cc: number): boolean {
        if (_engineDecorSolids && _engineDecorSolids.length) {
            for (let i = 0; i < _engineDecorSolids.length; i++) {
                const s = _engineDecorSolids[i]
                if (!s || (s.flags & sprites.Flag.Destroyed)) continue
                const sr = sprites.readDataNumber(s, "decorTileR") | 0
                const sc = sprites.readDataNumber(s, "decorTileC") | 0
                if ((sr | 0) === (rr | 0) && (sc | 0) === (cc | 0)) return true
            }
        }
        if (_engineDecorTriggers && _engineDecorTriggers.length) {
            for (let i = 0; i < _engineDecorTriggers.length; i++) {
                const s = _engineDecorTriggers[i]
                if (!s || (s.flags & sprites.Flag.Destroyed)) continue
                const sr = sprites.readDataNumber(s, "decorTileR") | 0
                const sc = sprites.readDataNumber(s, "decorTileC") | 0
                if ((sr | 0) === (rr | 0) && (sc | 0) === (cc | 0)) return true
            }
        }
        return false
    }

    function isTileFree(rr: number, cc: number): boolean {
        if (!_engineWorldTileMap || !_engineWorldTileMap.length) return false
        if (rr < 0 || cc < 0 || rr >= rows || cc >= cols) return false
        if (_tileIsSolidType(_engineWorldTileMap[rr][cc] | 0)) return false
        if (hasDecorAt(rr, cc)) return false
        return true
    }

    function isTrapTileValid(rr: number, cc: number): boolean {
        if (!isTileFree(rr, cc)) return false
        if (_dunIsReservedSpawnTile(rr | 0, cc | 0)) return false
        if ((shrineR | 0) >= 0 && (shrineC | 0) >= 0) {
            const dr = Math.abs((rr | 0) - (shrineR | 0)) | 0
            const dc = Math.abs((cc | 0) - (shrineC | 0)) | 0
            if ((dr | 0) < (TRAP_SHRINE_MIN_CHEB | 0) && (dc | 0) < (TRAP_SHRINE_MIN_CHEB | 0)) return false
            if ((shrineSide | 0) >= 0) {
                const side = _dunSideFromPad(rr | 0, cc | 0, padR | 0, padC | 0) | 0
                if ((side | 0) === (shrineSide | 0)) return false
            }
        }
        return true
    }

    function pickNearCenter(r0: number, c0: number, maxRadius: number): { r: number, c: number } | null {
        const baseR = r0 | 0
        const baseC = c0 | 0
        if (isTrapTileValid(baseR, baseC)) return { r: baseR | 0, c: baseC | 0 }
        const cap = Math.max(0, maxRadius | 0) | 0
        for (let rad = 1; rad <= cap; rad++) {
            for (let dr = -rad; dr <= rad; dr++) {
                for (let dc = -rad; dc <= rad; dc++) {
                    if (Math.abs(dr) !== rad && Math.abs(dc) !== rad) continue
                    const rr = (baseR + (dr | 0)) | 0
                    const cc = (baseC + (dc | 0)) | 0
                    if (!isTrapTileValid(rr, cc)) continue
                    return { r: rr | 0, c: cc | 0 }
                }
            }
        }
        return null
    }

    function pickRandomTrapTile(minManhattan: number, maxTries: number): { r: number, c: number } | null {
        const minDist = Math.max(0, minManhattan | 0) | 0
        const tries = Math.max(1, maxTries | 0) | 0
        const minR = 1
        const maxR = Math.max(1, (rows - 2) | 0) | 0
        const minC = 1
        const maxC = Math.max(1, (cols - 2) | 0) | 0
        for (let i = 0; i < tries; i++) {
            const rr = Math.randomRange(minR | 0, maxR | 0) | 0
            const cc = Math.randomRange(minC | 0, maxC | 0) | 0
            if (minDist > 0 && (padR | 0) >= 0 && (padC | 0) >= 0) {
                const dist = (Math.abs((rr | 0) - (padR | 0)) + Math.abs((cc | 0) - (padC | 0))) | 0
                if ((dist | 0) < (minDist | 0)) continue
            }
            if (!isTrapTileValid(rr, cc)) continue
            return { r: rr | 0, c: cc | 0 }
        }
        for (let rr = minR | 0; rr <= (maxR | 0); rr++) {
            for (let cc = minC | 0; cc <= (maxC | 0); cc++) {
                if (minDist > 0 && (padR | 0) >= 0 && (padC | 0) >= 0) {
                    const dist = (Math.abs((rr | 0) - (padR | 0)) + Math.abs((cc | 0) - (padC | 0))) | 0
                    if ((dist | 0) < (minDist | 0)) continue
                }
                if (!isTrapTileValid(rr, cc)) continue
                return { r: rr | 0, c: cc | 0 }
            }
        }
        return null
    }

    if (TRAP_ENTRANCE_USE_CENTER_SPAWN && _dunFloorKind === DUNGEON_KIND_ENTRANCE) {
        const maxRadius = TRAP_CENTER_SEARCH_RADIUS | 0
        let pick: { r: number, c: number } | null = null
        const tries = Math.max(12, (maxRadius * maxRadius) | 0) | 0
        for (let i = 0; i < tries; i++) {
            const dr = Math.randomRange(-maxRadius, maxRadius) | 0
            const dc = Math.randomRange(-maxRadius, maxRadius) | 0
            const rr = (centerR + dr) | 0
            const cc = (centerC + dc) | 0
            if (!isTrapTileValid(rr, cc)) continue
            pick = { r: rr | 0, c: cc | 0 }
            break
        }
        if (!pick) pick = pickNearCenter(centerR, centerC, maxRadius)
        if (pick) {
            r = pick.r | 0
            c = pick.c | 0
        }
    }

    if (!isTrapTileValid(r, c)) {
        const pick = pickRandomTrapTile(4, 250)
        if (pick) {
            r = pick.r | 0
            c = pick.c | 0
        }
    }

    if (!isTrapTileValid(r, c)) return

    const it = _dunSpawnInteractableProp({
        name: "fire_totem",
        tileR: r | 0,
        tileC: c | 0,
        action: INTERACT_ACTION_PROP,
        role: DECOR_ROLE.SOLID,
        pxW: WORLD_TILE_SIZE,
        pxH: WORLD_TILE_SIZE,
    })

    if (it && !(it.flags & sprites.Flag.Destroyed)) {
        _dunFireTotemInteractable = it
        _dunFireTotemTileR = r | 0
        _dunFireTotemTileC = c | 0
        _dunFireTotemDecor = _dunFindDecorAtTile(r, c, "fire_totem")
        _dunFireTotemSetState("idle")
        _trapTotemApplyPropTint()

        const instance = registerTrapPropSpawn(TRAP_TOTEM_BASE, _dunFloorIndex | 0, r | 0, c | 0, it, defOverride || null)
        if (instance) {
            if (instance.state === "solved") {
                sprites.setDataNumber(it, TRAP_SOLVED_KEY, 1)
                _dunSetInteractUsed(it, true)
            } else if (!canAttemptTrapInstance(instance, game.runtime() | 0)) {
                sprites.setDataNumber(it, TRAP_DISABLED_KEY, 1)
                _dunSetInteractUsed(it, true)
            }
        }
    }
}

function _dunEnterFloor_spawnTrapsForFloor(nowMs: number): void {
    const def = pickTrapDefinitionForFloor(_dunFloorIndex | 0)
    if (!def) return
    if (def.propBase === TRAP_TOTEM_BASE) {
        _dunEnterFloor_spawnStarterFireTotem(def)
        return
    }
    if (DEBUG_TRAP_LOGS) {
        console.log("[TRAP][SPAWN] unhandled trap prop", { propBase: String(def.propBase || "") })
    }
}

function _dunConfigureChestRelicOffer(chest: Sprite, cfg: RelicChestOfferConfig): void {
    if (!chest || (chest.flags & sprites.Flag.Destroyed)) return
    const poolIds = cfg.poolIds || []
    if (poolIds.length > 0) sprites.setDataString(chest, INTERACT_DATA.RELIC_POOL, poolIds.join(","))
    if (cfg.fixedRelicId) sprites.setDataString(chest, INTERACT_DATA.RELIC_FIXED, String(cfg.fixedRelicId || ""))
    if (cfg.minRarity) sprites.setDataString(chest, INTERACT_DATA.RELIC_MIN_RARITY, String(cfg.minRarity || ""))
    if (cfg.maxRarity) sprites.setDataString(chest, INTERACT_DATA.RELIC_MAX_RARITY, String(cfg.maxRarity || ""))
    if (cfg.title) sprites.setDataString(chest, INTERACT_DATA.RELIC_TITLE, String(cfg.title || ""))
    if (cfg.flavorText) sprites.setDataString(chest, INTERACT_DATA.RELIC_FLAVOR, String(cfg.flavorText || ""))
    if (cfg.theme) sprites.setDataString(chest, INTERACT_DATA.RELIC_THEME, String(cfg.theme || ""))
    if (cfg.count != null) sprites.setDataNumber(chest, INTERACT_DATA.RELIC_COUNT, cfg.count | 0)
    if (cfg.minRarity) _dunChestSetStyle(chest, _dunChestStyleForRarity(cfg.minRarity))
}

function _dunConfigureChestRelicOfferBoss(chest: Sprite): void {
    _dunConfigureChestRelicOffer(chest, {
        poolIds: _relicBossOfferPool(),
        title: "Boss Relic",
        flavorText: "Claim a trophy of power.",
        theme: "boss",
        count: 3,
    })
    _dunChestSetStyle(chest, "chest_gold")
}

function _dunConfigureChestRelicOfferRandom(chest: Sprite, minRarity: string, maxRarity: string): void {
    _dunConfigureChestRelicOffer(chest, {
        poolIds: _relicCatalogIds(),
        minRarity: minRarity,
        maxRarity: maxRarity,
        title: "Relic Cache",
        flavorText: "Choose one relic from the cache.",
        theme: "random",
        count: 3,
    })
}



function _dunEnterFloor_setupEntranceFloor(nowMs: number): void {

    DUNGEON_BLOCK_INTENTS = false

    _dunObjectiveDone = false

    _dunSetPadPowered(true)

    _dunStampEntranceTower()

    _dunRuneSetName("teleport_rune")
    _dunEnterFloor_spawnStarterChest(nowMs)
    _dunEnterFloor_spawnMemoryBook(nowMs)

}



function _dunEnterFloor_setupTreasureFloor(nowMs: number): void {

    DUNGEON_BLOCK_INTENTS = true

    _dunEnterFloor_spawnRelicEventChests(nowMs)

}



function _dunEnterFloor_setupStoryFloor(nowMs: number, padX: number, padY: number): void {

    DUNGEON_BLOCK_INTENTS = true

    _dunObjectiveDone = false
    _dunSetPadPowered(false)

    const rows = _dunWorldRows() | 0
    const cols = _dunWorldCols() | 0
    let avoidR = _dunPadPlacedLastR | 0
    let avoidC = _dunPadPlacedLastC | 0
    if (avoidR < 0 || avoidR >= rows) avoidR = Math.idiv(rows, 2) | 0
    if (avoidC < 0 || avoidC >= cols) avoidC = Math.idiv(cols, 2) | 0

    const pick = _dunPickRandomWalkableTile({
        avoidR,
        avoidC,
        minManhattan: STORY_NPC_MIN_DIST_FROM_PAD | 0,
        maxTries: 200
    })

    const npc = _dunSpawnStoryNpc(
        nowMs,
        STORY_ANNOUNCER_NAME,
        STORY_ANNOUNCER_FAMILY,
        _dunColToX(pick.c | 0),
        _dunRowToY(pick.r | 0)
    )
    const idleMs = Math.randomRange(STORY_NPC_WANDER_IDLE_MIN_MS, STORY_NPC_WANDER_IDLE_MAX_MS) | 0
    sprites.setDataNumber(npc, STORY_NPC_WANDER_STATE_KEY, 0)
    sprites.setDataNumber(npc, STORY_NPC_WANDER_NEXT_MS_KEY, (nowMs + idleMs) | 0)
    sprites.setDataNumber(npc, STORY_NPC_WANDER_LAST_MS_KEY, nowMs | 0)

}



function _dunEnterFloor_setupShopFloor(padX: number, padY: number): void {

    DUNGEON_BLOCK_INTENTS = false



    SHOP_MODE_ACTIVE_MASTER = true

    SHOP_MODE_ACTIVE = false



    // ? Shop should NOT auto-complete objective:

    // Pad stays locked + rune stays hidden until you interact (A on shopkeeper) or buy.

    _dunObjectiveDone = false

    _dunSetPadPowered(false)



    shopInitPOC()



    // NEW: tile-driven layout (2x5 slots preferred; fallback 1x5)

    const nowMs = game.runtime() | 0

    _shopComputeAndApplyLayoutForShopFloor(padX, padY, nowMs)



    // NOTE: we intentionally do NOT do the old "padX-70" shove here anymore.

    // Layout picker handles "not on telepad" and chooses a clean rectangle.

    _dunSpawnShopEntryDoor(nowMs | 0)

}



function _dunEnterFloor_setupCombatFloor(nowMs: number): void {

    DUNGEON_BLOCK_INTENTS = false

    if (_dunIsBossFloor(_dunFloorIndex | 0)) {
        _dunBossSpawnRocks()
    }

    setupEnemySpawners()

    startEnemyWaves()

    _dunEnterFloor_spawnTreasureChest(nowMs)

    if (_dunFloorUsesDoorExit()) {
        _dunSpawnDoorExit(nowMs | 0)
        _dunSchedulePadSink(nowMs | 0, undefined, undefined, undefined, undefined, true)
    }

}

function _dunEnterFloor_setupHallFloor(nowMs: number): void {
    void nowMs
    DUNGEON_BLOCK_INTENTS = false

    _dunObjectiveDone = true
    _dunSetPadPowered(true)

    if (DEBUG_EFFECTS_HALL_ON_START) {
        const g: any = globalThis as any
        if (g && typeof g.__heSetZoom === "function") {
            g.__heSetZoom(0.5)
        }
        _dunEnterFloor_spawnEffectsHall(nowMs | 0)
        return
    }

    _dunEnterFloor_spawnHallEnemies()
}

