function _shopRingReadIdsSlotsFromShopkeeper(sk: Sprite): any {

    // Statue contract keys are the source of truth (ring system retired)

    const idsRawNew = (sprites.readDataString(sk, SHOP_STATUE_OFFER_IDS_KEY) || "").trim()

    const slotsRawNew = (sprites.readDataString(sk, SHOP_STATUE_OFFER_SLOTS_KEY) || "").trim()



    const idsRaw = idsRawNew || (SHOP_DEFAULT_RING_WEAPON_IDS || "").trim()

    const slotsRaw = slotsRawNew || (SHOP_DEFAULT_RING_WEAPON_SLOTS || "").trim()



    // IMPORTANT: keep empty segments so index 0..3 stays index-locked

    const ids = _shopSplitPipeKeepEmpty(idsRaw)

    const slots = _shopSplitPipeKeepEmpty(slotsRaw)



    const want = 4

    while (ids.length < want) ids.push("")

    while (ids.length > want) ids.pop()



    while (slots.length < want) slots.push("")

    while (slots.length > want) slots.pop()



    // Commit to statue keys if missing

    if (!idsRawNew) sprites.setDataString(sk, SHOP_STATUE_OFFER_IDS_KEY, ids.join("|"))

    if (!slotsRawNew) sprites.setDataString(sk, SHOP_STATUE_OFFER_SLOTS_KEY, slots.join("|"))



    return { ids, slots }

}







function _shopPixToTile(x: number): number {

    return Math.max(0, ((x / WORLD_TILE_SIZE) | 0) | 0)

}

// Extra empty row below the layout to account for hero collision Y offset.
const SHOP_LAYOUT_SAFE_EXTRA_ROWS = 1

function _shopTileHasDecorSolid(r: number, c: number): boolean {
    if (!_engineDecorSolids || _engineDecorSolids.length === 0) return false
    for (let i = 0; i < _engineDecorSolids.length; i++) {
        const s = _engineDecorSolids[i]
        if (!s || (s.flags & sprites.Flag.Destroyed)) continue
        const sr = sprites.readDataNumber(s, "decorTileR") | 0
        const sc = sprites.readDataNumber(s, "decorTileC") | 0
        if ((sr | 0) === (r | 0) && (sc | 0) === (c | 0)) return true
    }
    return false
}



function _shopTileIsEmpty(r: number, c: number): boolean {

    if (!_engineWorldTileMap || !_engineWorldTileMap.length) return false

    const rows = _engineWorldTileMap.length | 0

    const cols = (_engineWorldTileMap[0]?.length ?? 0) | 0

    if (r < 0 || c < 0 || r >= rows || c >= cols) return false

    if (_tileIsSolidType(_engineWorldTileMap[r][c] | 0)) return false
    if (_shopTileHasDecorSolid(r | 0, c | 0)) return false
    return true

}



function _shopRectAllEmpty(baseR: number, baseC: number, h: number, w: number): boolean {

    const r0 = baseR | 0

    const c0 = baseC | 0

    const hh = h | 0

    const ww = w | 0

    for (let r = 0; r < hh; r++) {

        for (let c = 0; c < ww; c++) {

            if (!_shopTileIsEmpty((r0 + r) | 0, (c0 + c) | 0)) return false

        }

    }

    return true

}



function _shopComputeTrialArea(
    rows: number,
    cols: number,
    padRect: { r: number; c: number; h: number; w: number },
    layoutRect: { r: number; c: number; h: number; w: number } | null
): { r: number; c: number; h: number; w: number } {
    const h = SHOP_TRIAL_AREA_H | 0
    const w = SHOP_TRIAL_AREA_W | 0
    const maxR = Math.max(0, (rows - h - 1) | 0)
    const maxC = Math.max(0, (cols - w - 1) | 0)
    const topRMax = Math.min(maxR | 0, Math.max(1, Math.idiv(rows | 0, 2) | 0)) | 0
    const rightCMin = Math.max(1, Math.idiv(cols | 0, 2) | 0) | 0

    for (let r = 1; r <= topRMax; r++) {
        for (let c = (maxC | 0); c >= rightCMin; c--) {
            const rr = r | 0
            const cc = c | 0
            if (_shopRectsOverlap(rr, cc, h, w, padRect.r, padRect.c, padRect.h, padRect.w)) continue
            if (layoutRect && _shopRectsOverlap(rr, cc, h, w, layoutRect.r, layoutRect.c, layoutRect.h, layoutRect.w)) continue
            if (!_shopRectAllEmpty(rr, cc, h, w)) continue
            const rr2 = Math.max(0, Math.min(maxR | 0, (rr + 2) | 0)) | 0
            const cc2 = Math.max(0, Math.min(maxC | 0, (cc - 1) | 0)) | 0
            return { r: rr2 | 0, c: cc2 | 0, h, w }
        }
    }

    const candidates = [
        { r: 1, c: maxC },
        { r: 1, c: 1 },
        { r: maxR, c: maxC },
        { r: maxR, c: 1 },
    ]
    for (let i = 0; i < candidates.length; i++) {
        const cand = candidates[i]
        const r = cand.r | 0
        const c = cand.c | 0
        if (r < 0 || c < 0 || r > maxR || c > maxC) continue
        if (_shopRectsOverlap(r, c, h, w, padRect.r, padRect.c, padRect.h, padRect.w)) continue
        if (layoutRect && _shopRectsOverlap(r, c, h, w, layoutRect.r, layoutRect.c, layoutRect.h, layoutRect.w)) continue
        if (!_shopRectAllEmpty(r, c, h, w)) continue
        const rr2 = Math.max(0, Math.min(maxR | 0, (r + 2) | 0)) | 0
        const cc2 = Math.max(0, Math.min(maxC | 0, (c - 1) | 0)) | 0
        return { r: rr2 | 0, c: cc2 | 0, h, w }
    }

    // Hard fallback: force a placement even if the area isn't empty.
    // Keeps the arena visible even when the pad/layout consumes the only valid slots.
    const fallbackR = Math.min(1, maxR | 0) | 0
    const fallbackC = Math.max(0, maxC | 0) | 0
    const rr2 = Math.max(0, Math.min(maxR | 0, (fallbackR + 2) | 0)) | 0
    const cc2 = Math.max(0, Math.min(maxC | 0, (fallbackC - 1) | 0)) | 0
    return { r: rr2 | 0, c: cc2 | 0, h: h | 0, w: w | 0 }
}



function _shopRectsOverlap(r0: number, c0: number, h0: number, w0: number,

                          r1: number, c1: number, h1: number, w1: number): boolean {

    const aTop = r0 | 0

    const aLeft = c0 | 0

    const aBot = (aTop + (h0 | 0) - 1) | 0

    const aRight = (aLeft + (w0 | 0) - 1) | 0



    const bTop = r1 | 0

    const bLeft = c1 | 0

    const bBot = (bTop + (h1 | 0) - 1) | 0

    const bRight = (bLeft + (w1 | 0) - 1) | 0



    if (aRight < bLeft) return false

    if (bRight < aLeft) return false

    if (aBot < bTop) return false

    if (bBot < aTop) return false

    return true

}



function _shopSlotCenterX(baseTileC: number): number {

    // slot is 2 base tiles wide (64px). center is +32px from slot top-left

    return ((baseTileC * WORLD_TILE_SIZE) + WORLD_TILE_SIZE) | 0

}



function _shopSlotCenterY(baseTileR: number): number {

    return ((baseTileR * WORLD_TILE_SIZE) + WORLD_TILE_SIZE) | 0

}


function _shopPlatformDestroy(): void {
    if (_shopPlatformAnchor && !(_shopPlatformAnchor.flags & sprites.Flag.Destroyed)) {
        _dunDestroySprite(_shopPlatformAnchor)
    }
    _shopPlatformAnchor = null

    if (_shopPlatformStairs && !(_shopPlatformStairs.flags & sprites.Flag.Destroyed)) {
        _dunDestroySprite(_shopPlatformStairs)
    }
    _shopPlatformStairs = null

    if (_shopPlatformSolids && _shopPlatformSolids.length) {
        for (let i = 0; i < _shopPlatformSolids.length; i++) {
            const s = _shopPlatformSolids[i]
            if (s && !(s.flags & sprites.Flag.Destroyed)) _dunDestroySprite(s)
        }
    }
    _shopPlatformSolids = []

    if (_engineDecorSolids && _engineDecorSolids.length) {
        _engineDecorSolids = _engineDecorSolids.filter(s => s && !(s.flags & sprites.Flag.Destroyed))
    }
    if (_engineDecorTriggers && _engineDecorTriggers.length) {
        _engineDecorTriggers = _engineDecorTriggers.filter(s => s && !(s.flags & sprites.Flag.Destroyed))
    }

    _engineDecorRev = (_engineDecorRev + 1) | 0
}


function _shopPlatformPlace(baseR: number, baseC: number): void {
    _shopPlatformDestroy()

    const tileSize = WORLD_TILE_SIZE | 0
    const anchorR = (baseR + (SHOP_PLATFORM_SIZE_TILES - 1)) | 0 // bottom-left tile of the 9x9 sheet
    const anchorC = baseC | 0

    _shopPlatformAnchor = _dunDecor_spawnAtTile({
        name: "shop_platform",
        role: DECOR_ROLE.TRIGGER,
        tileR: anchorR,
        tileC: anchorC,
        pxW: tileSize,
        pxH: tileSize,
    })

    const solids: Sprite[] = []
    const topR = (baseR + SHOP_PLATFORM_WALL_MIN) | 0
    const bottomR = (baseR + SHOP_PLATFORM_WALL_MAX) | 0
    const leftC = (baseC + SHOP_PLATFORM_WALL_MIN) | 0
    const rightC = (baseC + SHOP_PLATFORM_WALL_MAX) | 0
    const gapC = (baseC + SHOP_PLATFORM_SHOP_COL) | 0

    function addSolid(r: number, c: number): void {
        const s = _dunDecor_spawnAtTile({
            name: "shop_platform", // collision-only; skip prop grid render
            role: DECOR_ROLE.SOLID,
            tileR: r,
            tileC: c,
            pxW: tileSize,
            pxH: tileSize,
        })
        if (s) sprites.setDataNumber(s, "decorCollider", 1)
        if (s) {
            sprites.setDataNumber(s, "decorAnchorR", anchorR | 0)
            sprites.setDataNumber(s, "decorAnchorC", anchorC | 0)
            sprites.setDataNumber(s, "decorHasAnchor", 1)
        }
        if (s) {
            const localR = ((r - baseR) | 0)
            const localC = ((c - baseC) | 0)
            if (localR >= 0 && localR < (SHOP_PLATFORM_SIZE_TILES | 0) && localC >= 0 && localC < (SHOP_PLATFORM_SIZE_TILES | 0)) {
                const frameIndex = ((localR * (SHOP_PLATFORM_SIZE_TILES | 0)) + localC) | 0
                sprites.setDataNumber(s, DECOR_SOLID_FRAME_INDEX_KEY, frameIndex)
                sprites.setDataString(s, DECOR_SOLID_TEX_KEY, "tiles.shopPlatform")
            }
        }
        if (s) sprites.setDataNumber(s, DECOR_DATA.SOLID_BASE_PX, SHOP_PLATFORM_EDGE_BASE_PX | 0)
        if (s) sprites.setDataNumber(s, DECOR_DATA.SOLID_USE_AURA, 1)
        if (s) solids.push(s)
    }

    // Top edge
    for (let c = leftC; c <= rightC; c++) addSolid(topR, c)
    // Bottom edge (leave center gap for stairs; 3 tiles wide)
    for (let c = leftC; c <= rightC; c++) {
        if (c >= (gapC - 1) && c <= (gapC + 1)) continue
        addSolid(bottomR, c)
    }
    // Vertical edges (skip corners already covered)
    for (let r = (topR + 1); r <= (bottomR - 1); r++) {
        addSolid(r, leftC)
        addSolid(r, rightC)
    }

    _shopPlatformSolids = solids

    // Replace platform center tiles with the 2x2 fill pattern from shopPlatform.png.
    _shopPlatformStampCenterFill(baseR | 0, baseC | 0)

    // Stairs visual overlay (3 tiles wide, centered)
    const stairAnchorR = bottomR | 0
    const stairAnchorC = (baseC + (SHOP_PLATFORM_SHOP_COL - 1)) | 0 // covers cols 3,4,5 of the platform
    _shopPlatformStairs = _dunDecor_spawnAtTile({
        name: "shop_stairs",
        role: DECOR_ROLE.TRIGGER,
        tileR: stairAnchorR,
        tileC: stairAnchorC,
        pxW: tileSize,
        pxH: tileSize,
    })

    try {
        const g: any = globalThis as any
        const decor = g && g.__HeroEnginePhaserDecor
        if (decor && typeof decor.forceResync === "function") {
            decor.forceResync("shop_platform_place")
        }
    } catch { }
}



function _shopComputeAndApplyLayoutForShopFloor(padX: number, padY: number, nowMs: number): void {

    // Only recompute when world changes (new floor / rebuild)

    const wr = _engineWorldRev | 0

    if ((_shopLayout_worldRev | 0) === wr && (_shopLayout_kind | 0) !== 0) {

        // Still apply positions (idempotent)

    } else {

        _shopLayout_worldRev = wr
        _shopPlatformDestroy()



        // Pad anchor in BASE TILE coords (center)

        const padR = (_dunPadTileR | 0) > 0 ? (_dunPadTileR | 0) : _shopPixToTile(padY)

        const padC = (_dunPadTileC | 0) > 0 ? (_dunPadTileC | 0) : _shopPixToTile(padX)



        // Telepad occupies a 2x5 BASE TILE rect: rows padR..padR+1, cols (padC-2)..(padC+2)

        const padRectR = padR | 0

        const padRectC = (padC - 2) | 0

        const padRectH = 2

        const padRectW = 5



        const rows = (_engineWorldTileMap?.length ?? 0) | 0

        const cols = (_engineWorldTileMap?.[0]?.length ?? 0) | 0



        let bestKind = 0

        let bestBaseR = -1

        let bestBaseC = -1

        let bestScore = 999999999

        let tried = 0
        let forced = false



        function consider(kind: number, baseH: number, baseW: number, shopROffset: number, shopCOffset: number, step: number): void {

            baseH = baseH | 0

            baseW = baseW | 0

            const safeH = ((baseH | 0) + SHOP_LAYOUT_SAFE_EXTRA_ROWS) | 0
            const stepSize = Math.max(1, step | 0)



            // scan slot-grid (top-lefts aligned on even base tiles)

            const maxBaseR = (rows - 1 - safeH) | 0

            const maxBaseC = (cols - 1 - baseW) | 0



            for (let baseR = 0; baseR <= maxBaseR; baseR += stepSize) {

                for (let baseC = 0; baseC <= maxBaseC; baseC += stepSize) {

                    tried++



                    // quick edge margin

                    if (baseR <= 0 || baseC <= 0) continue



                    // must not overlap pad rect

                    if (_shopRectsOverlap(baseR, baseC, baseH, baseW, padRectR, padRectC, padRectH, padRectW)) continue



                    // must be fully empty

                    if (!_shopRectAllEmpty(baseR, baseC, safeH, baseW)) continue



                    // Score by distance from SHOPKEEPER slot to pad center (in base-tile space)

                    const shopBaseR = baseR + shopROffset

                    const shopBaseC = baseC + shopCOffset



                    const score = (Math.abs(shopBaseR - padR) + Math.abs(shopBaseC - padC))

                    if (score < bestScore) {

                        bestScore = score

                        bestKind = kind

                        bestBaseR = baseR

                        bestBaseC = baseC

                    }

                }

            }

        }



        if (rows > 0 && cols > 0) {

            const baseH = SHOP_PLATFORM_SIZE_TILES | 0
            const baseW = SHOP_PLATFORM_SIZE_TILES | 0
            const safeH = ((baseH | 0) + SHOP_LAYOUT_SAFE_EXTRA_ROWS) | 0
            const maxBaseR = (rows - 1 - safeH) | 0
            const maxBaseC = (cols - 1 - baseW) | 0

            if (maxBaseR >= 1 && maxBaseC >= 1) {
                const baseR = Math.max(1, Math.min(1, maxBaseR | 0)) | 0
                const baseC = Math.max(1, Math.min(1, maxBaseC | 0)) | 0
                if (!_shopRectsOverlap(baseR, baseC, baseH, baseW, padRectR, padRectC, padRectH, padRectW) &&
                    _shopRectAllEmpty(baseR, baseC, safeH, baseW)) {
                    forced = true
                    bestKind = 3
                    bestBaseR = baseR | 0
                    bestBaseC = baseC | 0
                    bestScore = 0
                }
            }

            // Preferred: dedicated platform (9x9 tiles)
            if (!forced) consider(3, SHOP_PLATFORM_SIZE_TILES, SHOP_PLATFORM_SIZE_TILES, SHOP_PLATFORM_SHOP_ROW, SHOP_PLATFORM_SHOP_COL, 1)

            // Legacy fallbacks
            if (bestKind === 0) consider(2, 4, 10, 2, 4, 2) // 2x5 slots => 4x10 base tiles

            if (bestKind === 0) consider(1, 2, 10, 0, 4, 2) // fallback 1x5 slots => 2x10 base tiles

        }



        _shopLayout_kind = bestKind | 0

        _shopLayout_baseR = bestBaseR | 0

        _shopLayout_baseC = bestBaseC | 0

        const padRect = { r: padRectR | 0, c: padRectC | 0, h: padRectH | 0, w: padRectW | 0 }
        let layoutRect: { r: number; c: number; h: number; w: number } | null = null
        if ((bestKind | 0) === 3) {
            layoutRect = { r: bestBaseR | 0, c: bestBaseC | 0, h: SHOP_PLATFORM_SIZE_TILES | 0, w: SHOP_PLATFORM_SIZE_TILES | 0 }
        } else if ((bestKind | 0) === 2) {
            layoutRect = { r: bestBaseR | 0, c: bestBaseC | 0, h: 4, w: 10 }
        } else if ((bestKind | 0) === 1) {
            layoutRect = { r: bestBaseR | 0, c: bestBaseC | 0, h: 2, w: 10 }
        }
        const trial = _shopComputeTrialArea(rows | 0, cols | 0, padRect, layoutRect)
        _shopTrialAreaR = trial.r | 0
        _shopTrialAreaC = trial.c | 0
        _shopTrialAreaH = trial.h | 0
        _shopTrialAreaW = trial.w | 0



        logShop(

            `[SHOP][LAYOUT] worldRev=${wr} tried=${tried} padRC=${padR},${padC} ` +

            `pickKind=${bestKind} baseRC=${bestBaseR},${bestBaseC} score=${bestScore}`

        )
        const pathLabel = (bestKind | 0) === 3 ? "platform" : ((bestKind | 0) === 0 ? "none" : "fallback")
        logShop(`[SHOP][LAYOUT_PATH] ${pathLabel} kind=${bestKind}`)

    }



    // Apply positions if we found a layout

    if ((_shopLayout_kind | 0) === 0) return

    if (!shopkeeperNpc || (shopkeeperNpc.flags & sprites.Flag.Destroyed)) return

    if (!shopTriggerZone || (shopTriggerZone.flags & sprites.Flag.Destroyed)) return



    const kind = _shopLayout_kind | 0

    const baseR = _shopLayout_baseR | 0

    const baseC = _shopLayout_baseC | 0

    if (baseR < 0 || baseC < 0) return



    const shopRowSlot = (kind === 2) ? 1 : 0

    const shopColSlot = 2



    let shopBaseR = (baseR + (shopRowSlot * 2)) | 0

    let shopBaseC = (baseC + (shopColSlot * 2)) | 0

    if (kind === 3) {

        shopBaseR = (baseR + SHOP_PLATFORM_SHOP_ROW)

        shopBaseC = (baseC + SHOP_PLATFORM_SHOP_COL)

    }



    const shopX = (_shopSlotCenterX(shopBaseC) + SHOP_PLATFORM_SHOP_OFFSET_X_PX) | 0

    const shopY = (_shopSlotCenterY(shopBaseR) + SHOP_PLATFORM_SHOP_OFFSET_Y_PX) | 0



    shopkeeperNpc.setPosition(shopX, shopY)



    // Trigger zone should be centered on shopkeeper for overlap interaction

    shopTriggerZone.setPosition(shopX, shopY)



    // Optional: ensure shopkeeper faces down immediately (visual)

    // (Keeps your existing behavior, doesn’t affect controls)

    sprites.setDataString(shopkeeperNpc, "dir", "down")

    sprites.setDataString(shopkeeperNpc, HERO_DATA.DIR, "down")



    if (kind === 3) _shopPlatformPlace(baseR, baseC)
    _shopTrialArenaEnsureStamped()

    // Statues will be positioned by _shopEnsureStatueRow using this layout

}

// ---------------------------------------------------------------------------
// Shop Trial arena stamping (decals + props)
// ---------------------------------------------------------------------------
