function _shopSplitPipeList(s: string): string[] {

    const raw = (s || "").trim()

    if (!raw) return []

    // Keep empty segments out

    const parts = raw.split("|")

    const out: string[] = []

    for (let i = 0; i < parts.length; i++) {

        const p = (parts[i] || "").trim()

        if (p) out.push(p)

    }

    return out

}



function _shopDegToRad(deg: number): number {

    return (deg * Math.PI) / 180

}



function _shopDestroyOfferItems(): void {

    for (let i = 0; i < _shopRingOfferItems.length; i++) {

        const s = _shopRingOfferItems[i]

        if (s && !(s.flags & sprites.Flag.Destroyed)) s.destroy()

    }

    _shopRingOfferItems = []

}



function _shopPublishWeaponRingContractOnShopkeeper(sk: Sprite): void {

    if (!sk) return



    // ---------------------------------------------------------

    // NEW: seed/sanitize statue-offer contract (index-locked 0..3)

    // ---------------------------------------------------------

    const rr = _shopRingReadIdsSlotsFromShopkeeper(sk)

    const ids: string[] = rr.ids

    const slots: string[] = rr.slots



    const want = 4

    while (ids.length < want) ids.push("")

    while (ids.length > want) ids.pop()

    while (slots.length < want) slots.push("")

    while (slots.length > want) slots.pop()



    let changed = false



    for (let si = 0; si < want; si++) {

        const old = _shopNormWeaponId(ids[si] || "")

        const list = _shopAllowedWeaponListForStatueIndex(si)

        const fallback = (list && list.length > 0) ? _shopNormWeaponId(list[0]) : ""



        const use = _shopSanitizeWeaponIdForStatueIndex(si, old, fallback)

        const wantSlot = ((SHOP_STATUE_RENDER_SLOT && SHOP_STATUE_RENDER_SLOT[si]) ? (SHOP_STATUE_RENDER_SLOT[si] || "") : "thrust").toLowerCase()



        if (use !== old) { ids[si] = use; changed = true } else { ids[si] = old }

        if ((slots[si] || "").toLowerCase() !== wantSlot) { slots[si] = wantSlot; changed = true }

    }



    if (changed) {

        sprites.setDataString(sk, SHOP_STATUE_OFFER_IDS_KEY, ids.join("|"))

        sprites.setDataString(sk, SHOP_STATUE_OFFER_SLOTS_KEY, slots.join("|"))



        const _k = "shStatueContractSanLogMs"

        const nowMs = game.runtime() | 0

        const last = (sprites.readDataNumber(sk, _k) | 0)

        if ((nowMs - last) >= 750) {

            sprites.setDataNumber(sk, _k, nowMs)

            logShop(`[SHOP][STATUE_CONTRACT][SEED/SAN] ids=${ids.join("|")} slots=${slots.join("|")}`)

        }

    }

}



try { (globalThis as any)._shopPublishWeaponRingContractOnShopkeeper = _shopPublishWeaponRingContractOnShopkeeper } catch {}





function _shopGameplayKindForRingIndex(i: number): string {

    // Aligned with SHOP_DEFAULT_RING_WEAPON_IDS order:

    // diamond (intellect staff), glowsword (strength), spear (agility), simple (wisdom)

    if (i === 0) return "intellect"

    if (i === 1) return "strength"

    if (i === 2) return "agility"

    if (i === 3) return "wisdom"

    return "unknown"

}



function _shopPriceForRingIndex(i: number): number {

    const floorIdx = Math.max(1, (_dunFloorIndex | 0)) | 0
    const base = BALANCE.SHOP.WEAPON_PRICE_BASE | 0
    const perFloor = BALANCE.SHOP.WEAPON_PRICE_PER_FLOOR | 0
    const scalePct = 100 + Math.max(0, (floorIdx - 1) * (BALANCE.SHOP.WEAPON_PRICE_SCALE_PER_FLOOR_PCT | 0))
    const ringBumpPct = 100 + Math.max(0, (i | 0) * (BALANCE.SHOP.WEAPON_PRICE_RING_DELTA_PCT | 0))

    let price = base + Math.max(0, (floorIdx - 1) * perFloor)
    price = Math.idiv(price * scalePct, 100)
    price = Math.idiv(price * ringBumpPct, 100)

    if (price < 1) price = 1
    return price

}





function shopRenderSlotForRingIndex(i: number): string {

    const idx = i | 0

    if (idx < 0) return "thrust"



    // Prefer canonical defaults (keeps behavior stable even if shopkeeper data is missing)

    const raw = (SHOP_DEFAULT_RING_SLOTS || "").trim()

    if (!raw) return "thrust"



    const parts = raw.split("|")

    if (idx >= 0 && idx < parts.length) {

        const s = (parts[idx] || "").trim().toLowerCase()

        if (s === "slash" || s === "cast" || s === "thrust") return s

    }



    return "thrust"

}



function _shopRingRadiusPxForShopkeeper(sk: Sprite): number {

    let r = 0

    try { r = (sprites.readDataNumber(sk, SHOP_WPN_RING_RADIUS_PX_KEY) | 0) } catch { r = 0 }

    if ((r | 0) <= 0) r = (SHOP_DEFAULT_RING_RADIUS_PX | 0)

    if ((r | 0) <= 0) r = 22

    return r | 0

}



function _shopRingBaseAngleDegForShopkeeper(sk: Sprite): number {

    let d = 0

    try { d = (sprites.readDataNumber(sk, SHOP_WPN_RING_ANGLE_DEG_KEY) | 0) } catch { d = 0 }

    return d | 0

}



function _shopRingOffsetForIndex(i: number, n: number, radiusPx: number, baseDeg: number): { ox: number; oy: number } {

    // NOTE: We intentionally render offers as a *line* (table/rug) instead of a circle ring.

    // The params radiusPx/baseDeg remain for compatibility with older callers.

    const nn = Math.max(1, n | 0)



    const spacing = (SHOP_OFFER_LINE_SPACING_PX | 0) || 40

    const yOff = (SHOP_OFFER_LINE_Y_OFFSET_PX | 0) || 28



    // Center the row around the shopkeeper.

    const startX = -Math.floor(((nn - 1) * spacing) / 2)

    const ox = (startX + ((i | 0) * spacing)) | 0

    const oy = yOff | 0

    return { ox, oy }

}



function shopGameplayKindForRingIndex(i: number): string {

    const idx = i | 0

    if (idx < 0) return "strength"



    // Optional: if shopInitPOC stamps a pipe list onto shopkeeper, use it.

    // Example value: "strength|agility|intellect|wisdom|strength|agility|intellect|wisdom"

    const KEY = "shopWpnRingGameplayKinds"



    try {

        if (shopkeeperNpc && !(shopkeeperNpc.flags & sprites.Flag.Destroyed)) {

            const raw = (sprites.readDataString(shopkeeperNpc, KEY) || "").trim()

            if (raw) {

                const parts = raw.split("|")

                if (idx >= 0 && idx < parts.length) {

                    const s = (parts[idx] || "").trim().toLowerCase()

                    if (s) return s

                }

            }

        }

    } catch { /* ignore */ }



    // Fallback: stable default by index (repeats every 4)

    const m = (idx & 3)

    if (m === 0) return "strength"

    if (m === 1) return "agility"

    if (m === 2) return "intellect"

    return "wisdom"

}





function _shopEnsureWeaponRingOffersForShopkeeper(sk: Sprite): void {

    if (!sk) return



    const idsStr = sprites.readDataString(sk, SHOP_WPN_RING_IDS_KEY) || ""

    const ids = _shopSplitPipeList(idsStr)



    const wantCount = ids.length | 0

    if (wantCount <= 0) return



    const cx = sk.x | 0

    const cy = sk.y | 0



    const radiusPx = _shopRingRadiusPxForShopkeeper(sk)

    const baseDeg = _shopRingBaseAngleDegForShopkeeper(sk)



    // Ensure array sized

    while (_shopRingOfferItems.length < wantCount) _shopRingOfferItems.push(null)

    while (_shopRingOfferItems.length > wantCount) _shopRingOfferItems.pop()



    // Create missing

    for (let i = 0; i < wantCount; i++) {

        if (_shopRingOfferItems[i]) continue

        const it = spawnShopItem(cx, cy, "") // weapon id stamped below

        _shopRingOfferItems[i] = it

    }



    // Stamp + position

    for (let i = 0; i < wantCount; i++) {

        const it = _shopRingOfferItems[i]!

        const weaponId = (ids[i] || "").trim()



        const slot = shopRenderSlotForRingIndex(i)
        const gameplayKind = shopGameplayKindForRingIndex(i)
        const equipSlot = _shopEquipSlotFromFamily(_shopFamilyFromGameplayKind(gameplayKind)) || ""
        const price = _shopPriceForRingIndex(i) | 0



        sprites.setDataNumber(it, SH_ITEM_RING_INDEX, i | 0)

        sprites.setDataString(it, SH_ITEM_RENDER_SLOT, slot)
        sprites.setDataString(it, SH_ITEM_GAMEPLAY_KIND, gameplayKind)
        sprites.setDataString(it, SH_ITEM_EQUIP_SLOT, equipSlot)



        sprites.setDataString(it, SH_ITEM_WEAPON_ID, weaponId)

        sprites.setDataString(it, SH_ITEM_LABEL, weaponId)

        sprites.setDataNumber(it, SH_ITEM_PRICE, price)



        // Always “available” (swap shop)

        sprites.setDataNumber(it, SH_ITEM_BOUGHT_BY_PID, 0)



        // Give it a rolled bonus if it doesn't already have one

        _shopEnsureOfferHasBonus(it)
        _shopStampOfferPresentation(it, equipSlot, slot, weaponId, i | 0)



        // Ring placement

        const off = _shopRingOffsetForIndex(i, wantCount, radiusPx, baseDeg)

        it.x = (cx + (off.ox | 0)) | 0

        it.y = (cy + (off.oy | 0)) | 0

    }

}







