function _shopMenuTextForNpc(npc: Sprite): string {

    const bought = (sprites.readDataNumber(npc, SHOP_DATA_ITEM_BOUGHT) | 0) ? true : false

    return bought ? "item bought" : "item not bought"

}



function _shopMakeBoxImage(w: number, h: number, borderCol: number, fillCol: number): Image {

    const img = image.create(w, h)

    img.fill(fillCol)

    img.drawRect(0, 0, w, h, borderCol)

    // tiny “face” dot so it reads as something (optional)

    img.setPixel((w >> 1) - 1, (h >> 1), borderCol)

    img.setPixel((w >> 1) + 1, (h >> 1), borderCol)

    return img

}



function _shopMakeDitherBg(w: number, h: number, col: number): Image {

    const img = image.create(w, h)

    // checkerboard “alpha”: color col on alternating pixels, transparent elsewhere

    for (let y = 0; y < h; y++) {

        for (let x = 0; x < w; x++) {

            if (((x + y) & 1) === 0) img.setPixel(x, y, col)

        }

    }

    img.drawRect(0, 0, w, h, 15)

    return img

}



function _shopEnsureUiForHero(hi: number): void {

    // Canvas overlay removed (DOM-only). Ensure nothing lingers.

    try { _shopDestroyUiForHero(hi) } catch {}

}



function _shopClearFocusDataForHeroIndex(hi: number): void {

    if (hi < 0 || hi > 3) return

    const hero = heroes[hi]

    if (!hero || (hero.flags & sprites.Flag.Destroyed)) return



    sprites.setDataNumber(hero, HERO_SHOP_FOCUS_ACTIVE_KEY, 0)

    sprites.setDataNumber(hero, HERO_SHOP_FOCUS_RING_KEY, -1)

    sprites.setDataString(hero, HERO_SHOP_FOCUS_WEAPON_ID_KEY, "")

    sprites.setDataString(hero, HERO_SHOP_FOCUS_WEAPON_LABEL_KEY, "")

    sprites.setDataString(hero, HERO_SHOP_FOCUS_SLOT_KEY, "")

    sprites.setDataNumber(hero, HERO_SHOP_FOCUS_PRICE_KEY, 0)

    sprites.setDataString(hero, HERO_SHOP_FOCUS_BONUS_KEY, "")
    sprites.setDataString(hero, HERO_SHOP_FOCUS_RARITY_KEY, "")
    sprites.setDataString(hero, HERO_SHOP_FOCUS_DESC_KEY, "")

    sprites.setDataNumber(hero, HERO_SHOP_FOCUS_OWNED_BY_KEY, 0)

    sprites.setDataNumber(hero, HERO_SHOP_FOCUS_CAN_AFFORD_KEY, 0)

}





function _shopDestroyUiForHero(hi: number): void {

    if (hi < 0 || hi > 3) return



    // Hard guards: if the arrays don't exist for some reason, do nothing.

    if (typeof shopUiBgByHero === "undefined") return

    if (typeof shopUiTextByHero === "undefined") return

    if (typeof shopUiStatsByHero === "undefined") return



    const bg = shopUiBgByHero[hi]

    const t = shopUiTextByHero[hi]

    const s = shopUiStatsByHero[hi]



    if (bg) { bg.destroy(); shopUiBgByHero[hi] = null }

    if (t) { t.destroy(); shopUiTextByHero[hi] = null }

    if (s) { s.destroy(); shopUiStatsByHero[hi] = null }

}



function _shopStatsPreviewText(hi: number): string {

    // For now: show “+0” baseline, then “+1” after purchase

    const bought = shopBoughtByHero[hi]

    const dmg = bought ? "+1" : "+0"

    const reach = bought ? "+0" : "+0"

    const time = bought ? "+0" : "+0"

    const status = bought ? "+0" : "+0"

    return "DMG " + dmg + "  REACH " + reach + "  TIME " + time + "  STATUS " + status

}







function _shopUpdateUiForHero(hi: number, nowMs: number): void {

    const now = nowMs | 0

    if (hi < 0) return

    // Always kill canvas UI (DOM-only)

    try { _shopDestroyUiForHero(hi) } catch {}



    const hero = heroes[hi]

    if (!hero || (hero.flags & sprites.Flag.Destroyed)) return



    const summary = _shopGetFocusedOfferSummaryForHero(hi, now)



    if (!summary || !summary.active) {

        _shopClearFocusDataForHeroIndex(hi)



        // If you are using the DOM dialog system, hide it when focus ends (host only)

        if (SHOP_USE_DOM_DIALOG && hi === 0 && _shopDomWasShowing) {

            const g: any = globalThis as any

            const dlg = g.__heDialog
            const focus = g.__heShopFocus

            dlg?.hide?.()
            focus?.hide?.()

            _shopDomWasShowing = false

            _shopDomLastSig = ""

        }

        return

    }



    // Ownership (even though focus validity already gates this)

    let ownedBy = 0

    try { ownedBy = sprites.readDataNumber(summary.offer, SH_ITEM_BOUGHT_BY_PID) | 0 } catch { ownedBy = 0 }



    const price = summary.price | 0

    const canAfford = ((getHeroCoins(hi) | 0) >= price) ? 1 : 0

    const slot = (summary.renderSlot || summary.equipSlot || "") + ""
    const rarity = (summary.rarity || "").toLowerCase()
    const desc = (summary.desc || summary.bonusDesc || "")



    // Publish focus data for DOM

    sprites.setDataNumber(hero, HERO_SHOP_FOCUS_ACTIVE_KEY, 1)

    sprites.setDataNumber(hero, HERO_SHOP_FOCUS_RING_KEY, summary.ringIndex | 0)

    sprites.setDataString(hero, HERO_SHOP_FOCUS_WEAPON_ID_KEY, summary.weaponId || "")

    sprites.setDataString(hero, HERO_SHOP_FOCUS_WEAPON_LABEL_KEY, summary.weaponLabel || "")

    sprites.setDataString(hero, HERO_SHOP_FOCUS_SLOT_KEY, slot || "")

    sprites.setDataNumber(hero, HERO_SHOP_FOCUS_PRICE_KEY, price)

    sprites.setDataString(hero, HERO_SHOP_FOCUS_BONUS_KEY, summary.bonusDesc || "")
    sprites.setDataString(hero, HERO_SHOP_FOCUS_RARITY_KEY, rarity || "")
    sprites.setDataString(hero, HERO_SHOP_FOCUS_DESC_KEY, desc || "")

    sprites.setDataNumber(hero, HERO_SHOP_FOCUS_OWNED_BY_KEY, ownedBy | 0)

    sprites.setDataNumber(hero, HERO_SHOP_FOCUS_CAN_AFFORD_KEY, canAfford)



    // Optional DOM “focus tooltip” (if your page actually installs __heShopFocus)
    if (SHOP_USE_DOM_DIALOG && hi === 0) {
        const offerSprite = summary.offer as any
        let anchor = "b"
        let sx = offerSprite?.x | 0
        let sy = offerSprite?.y | 0
        try {
            const sc: any = (globalThis as any).__phaserScene
            const cam = sc && sc.cameras && sc.cameras.main ? sc.cameras.main : null
            const zoom = cam && Number.isFinite(cam.zoom) ? Number(cam.zoom) : 1
            const camX = cam && Number.isFinite(cam.x) ? Number(cam.x) : 0
            const camY = cam && Number.isFinite(cam.y) ? Number(cam.y) : 0
            const scrollX = cam && Number.isFinite(cam.scrollX) ? Number(cam.scrollX) : 0
            const scrollY = cam && Number.isFinite(cam.scrollY) ? Number(cam.scrollY) : 0
            sx = Math.round(((offerSprite.x - scrollX) * zoom) + camX)
            sy = Math.round(((offerSprite.y - scrollY) * zoom) + camY)
        } catch { }
        const edgePad = 18
        const posX = sx | 0
        const posY = (sy - edgePad) | 0

        const sig = `${summary.ringIndex}|${summary.weaponId}|${summary.weaponLabel}|${desc}|${price}|${rarity}`
        const g: any = globalThis as any
        const focus = g.__heShopFocus
        if (focus && typeof focus.show === "function") {
            if (sig !== _shopDomLastSig) {
                _shopDomLastSig = sig
                _shopDomWasShowing = true
                focus.show({
                    name: summary.weaponLabel || summary.weaponId || "Weapon",
                    rarity: rarity || "uncommon",
                    desc: desc || "",
                    price: price | 0,
                    hint: `Interact: buy/swap`,
                    pos: { x: posX | 0, y: posY | 0, anchor }
                })
            }
            if (typeof focus.move === "function") {
                focus.move({ x: posX | 0, y: posY | 0, anchor })
            }
        } else {
            const dlg = g.__heDialog
            dlg?.show?.({
                speaker: "Shop",
                text: `${summary.weaponLabel}\n${desc}`,
                hint: `Interact: buy/swap`
            })
        }
    }

}







function shopModeUpdate(nowMs: number): void {

    const now = nowMs | 0



    // Guard: never run outside shop floors

    if (!DUNGEON_MODE_ACTIVE || _dunFloorKind !== DUNGEON_KIND_SHOP) {

        SHOP_MODE_ACTIVE_MASTER = false

        SHOP_MODE_ACTIVE = false



        // Kill any lingering canvas UI + clear focus data

        for (let hi = 0; hi < heroes.length; hi++) {

            try { _shopDestroyUiForHero(hi) } catch {}

            try { _shopClearFocusDataForHeroIndex(hi) } catch {}

        }

        return

    }



    // Focus computation + gate (unchanged)

    shopControlTick(now)

    _shopApplyFocusGateToShopUi(now)



    // Publish focus data (DOM), no canvas UI

    for (let hi = 0; hi < heroes.length; hi++) {

        _shopUpdateUiForHero(hi, now)

    }



    // Purchase/return controls (unchanged)

    shopHandleControls(now)



    // Debug (unchanged)

    shopDebugDump(now)

}







