function _shopInit_publishRingContractAndDestroyLegacyOffers(): void {

    _shopPublishWeaponRingContractOnShopkeeper(shopkeeperNpc)



    if (_shopRingOfferItems && _shopRingOfferItems.length > 0) {

        logShop(`[SHOP][INIT] destroying legacy ring offer sprites count=${_shopRingOfferItems.length | 0}`)

    }

    _shopDestroyOfferItems()

}



function _shopInit_rollStatueWeaponsOncePerFloor(floor: number): boolean {

    const rolledFloor = sprites.readDataNumber(shopkeeperNpc, "shShopOffersRolledFloor") | 0

    if (rolledFloor === (floor | 0)) return false



    const rr = _shopRingReadIdsSlotsFromShopkeeper(shopkeeperNpc)

    const ids: string[] = rr.ids

    const slots: string[] = rr.slots



    while (ids.length < 4) ids.push("")

    while (slots.length < ids.length) slots.push("")



    for (let si = 0; si < 4; si++) {

        const renderSlot = (SHOP_STATUE_RENDER_SLOT && SHOP_STATUE_RENDER_SLOT[si]) ? (SHOP_STATUE_RENDER_SLOT[si] || "") : ""

        const rdSlot = (renderSlot || "thrust").toLowerCase()



        const list = _shopAllowedWeaponListForStatueIndex(si)

        let pick = ""



        if (list && list.length > 0) {

            pick = list[((Math.random() * list.length) | 0)] || ""

        }

        pick = _shopNormWeaponId(pick)



        if (!pick || !_shopIsWeaponAllowedForStatueIndex(si, pick)) {

            pick = ""

            for (let j = 0; j < list.length; j++) {

                const c = _shopNormWeaponId(list[j] || "")

                if (_shopIsWeaponAllowedForStatueIndex(si, c)) { pick = c; break }

            }

        }



        if (!pick) {

            if (rdSlot === "slash") pick = DEFAULT_WEAPON_SLASH_ID

            else if (rdSlot === "cast") pick = DEFAULT_WEAPON_CAST_ID

            else pick = DEFAULT_WEAPON_THRUST_ID

            pick = _shopNormWeaponId(pick)

        }



        ids[si] = pick

        slots[si] = rdSlot

    }



    sprites.setDataString(shopkeeperNpc, SHOP_STATUE_OFFER_IDS_KEY, ids.join("|"))

    sprites.setDataString(shopkeeperNpc, SHOP_STATUE_OFFER_SLOTS_KEY, slots.join("|"))

    sprites.setDataNumber(shopkeeperNpc, "shShopOffersRolledFloor", floor | 0)



    logShop(`[SHOP][INIT][ROLL] floor=${floor | 0} ids=${ids.join("|")} slots=${slots.join("|")}`)

    return true

}



function _shopInit_clearOfferCacheIfRolled(didRoll: boolean): void {

    if (!didRoll || !shopStatues) return



    for (let si = 0; si < 4; si++) {

        const st = shopStatues[si]

        if (!st || (st.flags & sprites.Flag.Destroyed)) continue

        sprites.setDataString(st, SH_ITEM_BONUS_DESC, "")

        const p = sprites.readDataNumber(st, SH_ITEM_PRICE) | 0

        if (!(p > 0)) sprites.setDataNumber(st, SH_ITEM_PRICE, 10)

        sprites.setDataNumber(st, SH_ITEM_BOUGHT_BY_PID, 0)

    }

}



function _shopInit_sanitizeHeroesOnEntry(): void {

    for (let hi = 0; hi < heroes.length; hi++) {

        const hero = heroes[hi]

        if (!hero || (hero.flags & sprites.Flag.Destroyed)) continue



        const slotToSi: any = {}

        for (let si = 0; si < 4; si++) {

            const eq = (SHOP_STATUE_EQUIP_SLOT && SHOP_STATUE_EQUIP_SLOT[si]) ? (SHOP_STATUE_EQUIP_SLOT[si] || "") : ""

            const eqSlot = (eq || "thrust").toLowerCase()

            slotToSi[eqSlot] = si

        }



        const slotsToCheck = [

            SHOP_EQUIP_SLOT_STRENGTH,

            SHOP_EQUIP_SLOT_AGILITY,

            SHOP_EQUIP_SLOT_INTELLIGENCE,

            SHOP_EQUIP_SLOT_SUPPORT,

        ]

        for (let k = 0; k < slotsToCheck.length; k++) {

            const eqSlot = slotsToCheck[k]

            const si = (slotToSi[eqSlot] != null) ? (slotToSi[eqSlot] | 0) : -1

            if (si < 0) continue



            const cur = _shopNormWeaponId(_shopGetEquippedWeaponIdForHeroSlot(hero, eqSlot) || "")

            if (cur && _shopIsWeaponAllowedForStatueIndex(si, cur)) continue



            const list = _shopAllowedWeaponListForStatueIndex(si)

            let fix = ""

            for (let j = 0; j < list.length; j++) {

                const c = _shopNormWeaponId(list[j] || "")

                if (_shopIsWeaponAllowedForStatueIndex(si, c)) { fix = c; break }

            }

            if (!fix) {

                if (eqSlot === SHOP_EQUIP_SLOT_STRENGTH) fix = DEFAULT_WEAPON_STRENGTH_ID

                else if (eqSlot === SHOP_EQUIP_SLOT_AGILITY) fix = DEFAULT_WEAPON_AGILITY_ID

                else if (eqSlot === SHOP_EQUIP_SLOT_INTELLIGENCE) fix = DEFAULT_WEAPON_INTELLIGENCE_ID

                else if (eqSlot === SHOP_EQUIP_SLOT_SUPPORT) fix = DEFAULT_WEAPON_SUPPORT_ID

                else fix = DEFAULT_WEAPON_THRUST_ID

                fix = _shopNormWeaponId(fix)

            }



            const fixRarity = _shopRarityForWeaponId(fix, eqSlot)
            const fixVariant = _weaponPickVariantForRarity(fix, fixRarity, `${fix}|${eqSlot}|fix`)
            _shopEquipWeaponToHeroSlot(hero, eqSlot, fix, { rarity: fixRarity, variant: fixVariant })

            logShop(`[SHOP][INIT][HERO_SANITIZE] hi=${hi} slot=${eqSlot} old=${cur || "(empty)"} new=${fix} si=${si}`)

        }

    }

}





function shopInitPOC(): void {

    // _shopEnsurePerHeroStateArrays()



    const now = Math.max(1, game.runtime() | 0)

    const floor = (_dunFloorIndex | 0)



    _shopInit_ensureTriggerZone()



    _shopInit_ensureShopkeeper(now)



    if (!shopkeeperNpc || (shopkeeperNpc.flags & sprites.Flag.Destroyed)) return



    _shopInit_removePedestal()



    _shopInit_publishRingContractAndDestroyLegacyOffers()



    const didRoll = _shopInit_rollStatueWeaponsOncePerFloor(floor)



    _shopEnsureStatueRow(now)



    _shopInit_clearOfferCacheIfRolled(didRoll)



    _shopInit_sanitizeHeroesOnEntry()

}







function _near(a: Sprite, b: Sprite, r: number): boolean {

    if (!a || !b) return false

    const dx = (a.x - b.x)

    const dy = (a.y - b.y)

    return (dx*dx + dy*dy) <= (r*r)

}



function _shopCullDestroyed(list: Sprite[]): void {

    for (let i = list.length - 1; i >= 0; i--) {

        const s = list[i]

        if (!s) { list.removeAt(i); continue }

        if ((s.flags & sprites.Flag.Destroyed) != 0) { list.removeAt(i); continue }

    }

}



function _shopRegisterNpc(s: Sprite): void {

    sprites.setDataBoolean(s, SHOP_DATA.IS_SHOP_NPC, true)

    SHOP_NPCS.push(s)

}



function _shopRegisterItem(s: Sprite): void {

    sprites.setDataBoolean(s, SHOP_DATA.IS_SHOP_ITEM, true)

    SHOP_ITEMS.push(s)

}





function _shopInputs_isShopActiveForHero(hi: number, now: number): boolean {

    // Gate: shop active (Step 6 ties this to focus, but keep the gate anyway)

    return now <= (shopTouchUntilMsByHero[hi] | 0)

}



function _shopInputs_getHeroForIndex(hi: number): Sprite {

    const hero = heroes[hi]

    if (!hero || (hero.flags & sprites.Flag.Destroyed)) return null

    return hero

}



function _shopInputs_getPidForHeroIndex(hi: number): number {

    const hero = heroes[hi]
    if (!hero || (hero.flags & sprites.Flag.Destroyed)) return 0
    return sprites.readDataNumber(hero, HERO_DATA.OWNER) | 0

}



function _shopInputs_getFocusedOfferOrClearUi(hi: number, now: number): Sprite {

    const offer = _shopGetFocusedOfferForHero(hi, now)

    if (!offer) {

        // No offer focused => treat as not-bought for UI

        shopBoughtByHero[hi] = false

        return null

    }

    return offer

}



function _shopInputs_syncUiBoughtFlagFromOffer(hi: number, pid: number, offer: Sprite): void {

    _shopSetUiBoughtFlagFromOffer(hi, pid, offer)

}



function _shopInputs_readOfferMeta(offer: Sprite): any {

    const weaponId = sprites.readDataString(offer, SH_ITEM_WEAPON_ID) || ""

    const renderSlot = sprites.readDataString(offer, SH_ITEM_RENDER_SLOT) || "thrust"

    const equipSlot = sprites.readDataString(offer, SH_ITEM_EQUIP_SLOT) || ""

    const price = sprites.readDataNumber(offer, SH_ITEM_PRICE) | 0

    const ringIndex = sprites.readDataNumber(offer, SH_ITEM_RING_INDEX) | 0

    return { weaponId, renderSlot, equipSlot, price, ringIndex }

}



function _shopInputs_pollABNow(hi: number): any {
    const st = _getInputStateForHeroIndex(hi | 0)
    return { aNow: !!st.Interact, bNow: !!st.B }

}



function _shopInputs_edgeDetectAndStore(hi: number, aNow: boolean, bNow: boolean): any {

    const aPrev = shopPrevAByPlayer[hi]

    const bPrev = shopPrevBByPlayer[hi]

    shopPrevAByPlayer[hi] = aNow

    shopPrevBByPlayer[hi] = bNow



    const aEdge = aNow && !aPrev

    const bEdge = bNow && !bPrev

    return { aEdge, bEdge }

}



function _shopInputs_handleBuyIfEdge(

    aEdge: boolean,

    hi: number,

    pid: number,

    hero: Sprite,

    offer: Sprite,

    meta: any,

    now: number

): void {

    if (!aEdge) return



    const weaponId = meta.weaponId

    const renderSlot = meta.renderSlot

    const equipSlot = meta.equipSlot

    const price = meta.price | 0

    const ringIndex = meta.ringIndex | 0



    const boughtBy0 = sprites.readDataNumber(offer, SH_ITEM_BOUGHT_BY_PID) | 0



    // Already owned by this hero => no-op

    if (boughtBy0 === pid) {

        logShop("[SHOP][BUY] already-owned pid=" + pid + " hi=" + hi + " ring=" + ringIndex + " wid=" + weaponId + " slot=" + renderSlot)

    } else if (boughtBy0 !== 0) {

        // Owned by someone else => deny for now

        logShop("[SHOP][BUY] denied-owned-by-other pid=" + pid + " hi=" + hi + " ring=" + ringIndex + " ownedBy=" + boughtBy0)

    } else {

        // Check + spend PER HERO

        if (!trySpendHeroCoins(hi, price | 0)) {

            logShop("[SHOP][BUY] denied-insufficient pid=" + pid + " hi=" + hi + " ring=" + ringIndex + " price=" + price + " coins=" + (getHeroCoins(hi) | 0))
            _shopFlashCoinsInsufficient(hi)

        } else {

            // Mark + equip

            sprites.setDataNumber(offer, SH_ITEM_BOUGHT_BY_PID, pid)

            const takeRarity = (sprites.readDataString(offer, SH_ITEM_RARITY) || "").toLowerCase() || _shopRarityForWeaponId(weaponId, equipSlot)
            const takeSeed = `${weaponId}|${equipSlot}`
            const takeVariant = (sprites.readDataString(offer, SH_ITEM_VARIANT) || "").toLowerCase() || _weaponPickVariantForRarity(weaponId, takeRarity, takeSeed)

            _shopEquipWeaponToHeroSlot(hero, equipSlot, weaponId, { rarity: takeRarity, variant: takeVariant })



            logShop("[SHOP][BUY] ok pid=" + pid + " hi=" + hi + " ring=" + ringIndex + " wid=" + weaponId + " slot=" + equipSlot + " price=" + price + " coins=" + (getHeroCoins(hi) | 0))



            // UI flag follows focused offer

            _shopSetUiBoughtFlagFromOffer(hi, pid, offer)

            _shopUpdateUiForHero(hi, now)

        }

    }

}



function _shopInputs_handleReturnIfEdge(

    bEdge: boolean,

    hi: number,

    pid: number,

    hero: Sprite,

    offer: Sprite,

    meta: any,

    now: number

): void {

    if (!bEdge) return



    const weaponId = meta.weaponId

    const renderSlot = meta.renderSlot

    const equipSlot = meta.equipSlot

    const price = meta.price | 0

    const ringIndex = meta.ringIndex | 0



    const boughtBy0 = sprites.readDataNumber(offer, SH_ITEM_BOUGHT_BY_PID) | 0



    if (boughtBy0 !== pid) {

        logShop("[SHOP][RETURN] no-op pid=" + pid + " hi=" + hi + " ring=" + ringIndex + " ownedBy=" + boughtBy0)

    } else {

        // Refund + clear ownership (PER HERO)

        sprites.setDataNumber(offer, SH_ITEM_BOUGHT_BY_PID, 0)

        addHeroCoins(hi, price | 0, hero.x, hero.y)



        // Clear the hero slot ONLY if still matches this weaponId

        const cleared = _shopClearWeaponFromHeroSlotIfMatches(hero, equipSlot, weaponId)

        if (cleared) _shopClearWeaponModsForSlot(hi, equipSlot)



        logShop("[SHOP][RETURN] ok pid=" + pid + " hi=" + hi + " ring=" + ringIndex + " wid=" + weaponId + " slot=" + equipSlot + " refund=" + price + " coins=" + (getHeroCoins(hi) | 0))



        _shopSetUiBoughtFlagFromOffer(hi, pid, offer)

        _shopUpdateUiForHero(hi, now)

    }

}







function shopHandleInputs(nowMs: number): void {

    const now = nowMs | 0



    // Profile-backed input: iterate active heroes
    for (let hi = 0; hi < heroes.length; hi++) {

        if (!_shopInputs_isShopActiveForHero(hi, now)) continue



        const hero = _shopInputs_getHeroForIndex(hi)

        if (!hero) continue



        const pid = _shopInputs_getPidForHeroIndex(hi)



        const offer = _shopInputs_getFocusedOfferOrClearUi(hi, now)

        if (!offer) continue



        // Keep UI bought flag in sync with the focused offer

        _shopInputs_syncUiBoughtFlagFromOffer(hi, pid, offer)



        // Read offer metadata

        const meta = _shopInputs_readOfferMeta(offer)



        // ---------------------------------------------------------

        // Edge detect: A and B

        // ---------------------------------------------------------

        const abNow = _shopInputs_pollABNow(hi)

        const edges = _shopInputs_edgeDetectAndStore(hi, abNow.aNow, abNow.bNow)



        // ---------------------------------------------------------

        // A = BUY focused offer

        // ---------------------------------------------------------

        _shopInputs_handleBuyIfEdge(edges.aEdge, hi, pid, hero, offer, meta, now)



        // ---------------------------------------------------------

        // B = RETURN/UNDO focused offer (only if this hero bought it)

        // ---------------------------------------------------------

        _shopInputs_handleReturnIfEdge(edges.bEdge, hi, pid, hero, offer, meta, now)

    }

}







function spawnShopNpc(x: number, y: number, label: string): Sprite {

    const img = image.create(16, 16)

    img.fill(1)

    img.drawRect(0, 0, 16, 16, 15)



    const npc = sprites.create(img, SpriteKind.ShopNpc)

    npc.setPosition(x, y)

    npc.setFlag(SpriteFlag.Ghost, false)

    sprites.setDataString(npc, SHOP_DATA.LABEL, label || "NPC")



    _shopRegisterNpc(npc)

    return npc

}





function spawnShopItem(x: number, y: number, label: string): Sprite {

    // Invisible hitbox by default (you can temporarily make it visible while debugging)

    const img = image.create(12, 12)

    img.fill(0)

    img.drawRect(0, 0, 12, 12, 1)



    const it = sprites.create(img, SpriteKind.ShopItem)

    it.setPosition(x, y)

    it.setFlag(SpriteFlag.Ghost, true)

    it.setFlag(SpriteFlag.Invisible, true)



    // Keep legacy label field too

    sprites.setDataString(it, SHOP_DATA.LABEL, label || "Item")

    sprites.setDataBoolean(it, SHOP_DATA.BOUGHT, false)



    // New per-offer fields (some will be overwritten by ring builder)

    sprites.setDataString(it, SH_ITEM_LABEL, label || "Item")

    sprites.setDataString(it, SH_ITEM_WEAPON_ID, label || "")

    sprites.setDataString(it, SH_ITEM_RENDER_SLOT, "thrust")

    sprites.setDataString(it, SH_ITEM_GAMEPLAY_KIND, "unknown")

    sprites.setDataNumber(it, SH_ITEM_RING_INDEX, -1)

    sprites.setDataNumber(it, SH_ITEM_PRICE, 10)

    sprites.setDataNumber(it, SH_ITEM_BOUGHT_BY_PID, 0)

    sprites.setDataString(it, SH_ITEM_VARIANT, "")



    _shopRegisterItem(it)

    return it

}







// ------------------------------------------------------------

// SHOP HUD (shop-only overlay)

// Panel + big dialog + stats in bottom-left.

// Uses checkerboard transparency for "translucent" look.

// ------------------------------------------------------------



let _shopHudPanel: Sprite = null

let _shopHudDialog: TextSprite = null

let _shopHudStats: TextSprite = null



const SHOP_HUD_W = 150

const SHOP_HUD_H = 42



function _shopHudMakePanelImage(w: number, h: number): Image {

    const img = image.create(w, h)

    img.fill(0) // 0 is transparent



    // Border

    img.drawRect(0, 0, w, h, 1)



    // "Translucent" interior: checkerboard of transparent (0) and dark pixel (1)

    for (let y = 1; y < h - 1; y++) {

        for (let x = 1; x < w - 1; x++) {

            if (((x + y) & 1) === 0) {

                img.setPixel(x, y, 0) // transparent pixel

            } else {

                img.setPixel(x, y, 1) // dark pixel

            }

        }

    }



    return img

}



function ensureShopHud(): void {

    if (_shopHudPanel) return



    // Panel sprite

    _shopHudPanel = sprites.create(_shopHudMakePanelImage(SHOP_HUD_W, SHOP_HUD_H), SpriteKind.ShopUI)

    _shopHudPanel.setFlag(SpriteFlag.Ghost, true)

    _shopHudPanel.setFlag(SpriteFlag.RelativeToCamera, true)

    _shopHudPanel.setFlag(SpriteFlag.Invisible, true)

    _shopHudPanel.z = 10_000



    // Big dialog line

    _shopHudDialog = textsprite.create("", 0, 15) // fg=15 (white)

    _shopHudDialog.setMaxFontHeight(12)

    _shopHudDialog.setOutline(1, 1) // outline=dark

    _shopHudDialog.setFlag(SpriteFlag.RelativeToCamera, true)

    _shopHudDialog.setFlag(SpriteFlag.Ghost, true)

    _shopHudDialog.setFlag(SpriteFlag.Invisible, true)

    _shopHudDialog.z = 10_001



    // Stats line (slightly smaller)

    _shopHudStats = textsprite.create("", 0, 7) // fg=7 (light)

    _shopHudStats.setMaxFontHeight(9)

    _shopHudStats.setOutline(1, 1)

    _shopHudStats.setFlag(SpriteFlag.RelativeToCamera, true)

    _shopHudStats.setFlag(SpriteFlag.Ghost, true)

    _shopHudStats.setFlag(SpriteFlag.Invisible, true)

    _shopHudStats.z = 10_001

}



function _shopHudSetVisible(show: boolean): void {

    ensureShopHud()

    _shopHudPanel.setFlag(SpriteFlag.Invisible, !show)

    _shopHudDialog.setFlag(SpriteFlag.Invisible, !show)

    _shopHudStats.setFlag(SpriteFlag.Invisible, !show)

}



function _shopHudSetText(dialog: string, stats: string): void {

    ensureShopHud()

    ;(_shopHudDialog as any).setText(dialog || "")

    ;(_shopHudStats as any).setText(stats || "")

}



function _shopHudPositionBottomLeft(): void {

    ensureShopHud()



    const W = userconfig.ARCADE_SCREEN_WIDTH

    const H = userconfig.ARCADE_SCREEN_HEIGHT



    const pad = 2

    const cx = pad + (SHOP_HUD_W >> 1)

    const cy = H - pad - (SHOP_HUD_H >> 1)



    _shopHudPanel.x = cx

    _shopHudPanel.y = cy



    // dialog near top of panel

    _shopHudDialog.x = cx

    _shopHudDialog.y = cy - 10



    // stats near bottom of panel

    _shopHudStats.x = cx

    _shopHudStats.y = cy + 8

}



function shopHudShow(dialog: string, stats: string): void {

    _shopHudSetText(dialog, stats)

    _shopHudPositionBottomLeft()

    _shopHudSetVisible(true)

}



function shopHudHide(): void {

    if (!_shopHudPanel) return

    _shopHudSetVisible(false)

}



function _shopBuildStatsPreview(heroIndex: number): string {

    // TODO: replace with calculateMoveStats(...) once you pick an item model.

    // Keep it single-line for now so it reads cleanly.

    return "DMG:+0  REACH:+0  TIME:+0  STATUS:+0"

}





