// ================================================================

// SECTION 2.5 - TILEMAP AND WORLD GENERATION (improved)

// ================================================================

// Uses cellular automata to make nice blobby walls, then carves

// a central arena for the heroes.

// ================================================================



function _createTileMap2D_TestWorld(kind: "" | "PF_MIDWALL" | "PF_SINGLE_DOOR" | "PF_PAD_CAGE_TOP3"): number[][] {

    let cols = Math.max(WORLD_TILES_W, MIN_WORLD_TILES_W) | 0
    let rows = Math.max(WORLD_TILES_H, MIN_WORLD_TILES_H) | 0
    if (cols < 16) cols = 16
    if (rows < 12) rows = 12

    // start fully open
    const map: number[][] = []
    for (let r = 0; r < rows; r++) {
        const row: number[] = []
        for (let c = 0; c < cols; c++) row.push(TILE_EMPTY)
        map.push(row)
    }

    // solid outer border
    for (let r = 0; r < rows; r++) {
        map[r][0] = TILE_WALL
        map[r][cols - 1] = TILE_WALL
    }
    for (let c = 0; c < cols; c++) {
        map[0][c] = TILE_WALL
        map[rows - 1][c] = TILE_WALL
    }

    // helper carve
    const carveRect = (r0: number, c0: number, rh: number, cw: number) => {
        const r1 = Math.min(rows - 2, (r0 + rh - 1) | 0) | 0
        const c1 = Math.min(cols - 2, (c0 + cw - 1) | 0) | 0
        for (let r = Math.max(1, r0 | 0); r <= r1; r++) {
            for (let c = Math.max(1, c0 | 0); c <= c1; c++) map[r][c] = TILE_EMPTY
        }
    }

    // Helpful centers
    const centerR = Math.idiv(rows, 2) | 0
    const centerC = Math.idiv(cols, 2) | 0

    // Big open arena around center (keeps hero/enemies far from walls by default)
    carveRect((centerR - 4) | 0, (centerC - 7) | 0, 9, 15)

    if (kind === "PF_MIDWALL") {

        const wallC = (centerC - 4) | 0
        const topGapR = 1
        const botGapR = (rows - 2) | 0

        for (let r = 1; r <= (rows - 2); r++) {
            if (r === topGapR || r === botGapR) continue
            if (r >= (centerR - 4) && r <= (centerR + 4)) continue
            map[r][wallC] = TILE_WALL
        }

        // tiny nub to catch “wall-hugging”
        const nubR = (centerR + 2) | 0
        if (nubR >= 2 && nubR <= rows - 3 && (wallC - 2) >= 2) {
            map[nubR][(wallC - 1) | 0] = TILE_WALL
            map[nubR][(wallC - 2) | 0] = TILE_WALL
        }

    } else if (kind === "PF_SINGLE_DOOR") {

        const splitC = (centerC - 2) | 0
        const doorR = centerR | 0

        for (let r = 1; r <= rows - 2; r++) map[r][splitC] = TILE_WALL
        map[doorR][splitC] = TILE_EMPTY

        // keep spawn arena open
        carveRect((centerR - 4) | 0, (centerC - 7) | 0, 9, 15)

    } else if (kind === "PF_PAD_CAGE_TOP3") {

        // Goal: two *double-thick* vertical pillars flanking the teleport pad area.
        // Only bypass is at the TOP, with a 3-tile-tall open band.

        // Define the "top open band" height (3 tiles tall, excluding the border wall row=0)
        const openTopH = 3
        const wallStartR = (1 + openTopH) | 0     // walls begin below the open band
        const wallEndR = (rows - 2) | 0           // down to inner border

        // Put the “pad” notionally at the center of the arena.
        // We build pillars around it with a clear gap between pillars.
        const gapHalf = 3                        // gap half-width around pad
        const leftPillarC0 = (centerC - gapHalf - 2) | 0   // 2-thick
        const leftPillarC1 = (leftPillarC0 + 1) | 0
        const rightPillarC0 = (centerC + gapHalf + 1) | 0  // 2-thick
        const rightPillarC1 = (rightPillarC0 + 1) | 0

        // Sanity clamp into interior
        const clampC = (c: number) => {
            if (c < 1) return 1
            if (c > (cols - 2)) return (cols - 2) | 0
            return c | 0
        }

        const l0 = clampC(leftPillarC0)
        const l1 = clampC(leftPillarC1)
        const r0 = clampC(rightPillarC0)
        const r1 = clampC(rightPillarC1)

        // Build the pillars from wallStartR..wallEndR (so the top band is the ONLY bypass).
        for (let r = wallStartR; r <= wallEndR; r++) {
            map[r][l0] = TILE_WALL
            map[r][l1] = TILE_WALL
            map[r][r0] = TILE_WALL
            map[r][r1] = TILE_WALL
        }

        // Make the “pad plaza” inside the pillars extra open (so nobody can claim tightness).
        // This is just openness; your real telepad is placed by other logic.
        const plazaR0 = (centerR - 3) | 0
        const plazaC0 = (l1 + 1) | 0
        const plazaW = ((r0 - 1) - plazaC0 + 1) | 0
        carveRect(plazaR0, plazaC0, 7, plazaW)

        // Also ensure the entire top band is open across the arena width.
        carveRect(1, 1, openTopH, (cols - 2) | 0)

        // Optional: add a “tempting indentation” near the left pillar face to expose bad steering.
        // This makes a little notch that a dumb “push-right” behavior would jam into.
        const notchR = (centerR + 1) | 0
        const notchC = (l0 - 1) | 0
        if (notchR >= 2 && notchR <= rows - 3 && notchC >= 2) {
            map[notchR][notchC] = TILE_WALL
        }
    }

    return map
}


function _debugWorldSig01(map: number[][]): { rows: number, cols: number, walls: number, floors: number, sig: number } {
    const rows = (map && map.length) ? (map.length | 0) : 0
    const cols = (rows > 0 && map[0]) ? (map[0].length | 0) : 0
    let walls = 0, floors = 0, sig = 0
    for (let r = 0; r < rows; r++) {
        const row = map[r]
        for (let c = 0; c < cols; c++) {
            const v = row[c] | 0
            if (v === (TILE_WALL | 0)) walls++
            else floors++
            sig = (((sig << 5) - sig) + v + ((r + 1) * 131) + ((c + 1) * 17)) | 0
        }
    }
    return { rows, cols, walls, floors, sig }
}


type _WorldgenBridgePlacement = { anchorR: number; anchorC: number; kind: "bridge_h" | "bridge_v"; span: number };
type _WorldgenPathCell = { r: number; c: number; dir: "h" | "v"; wasWall: boolean };
type _WorldgenBridgeCandidate = { anchorR: number; anchorC: number; kind: "bridge_h" | "bridge_v"; score: number; span: number };

let _worldgenBridgePlacements: _WorldgenBridgePlacement[] = [];

function _worldgen_isFloor(v: number): boolean {
    return ((v | 0) !== (TILE_WALL | 0));
}

function _worldgen_forceIsland(map: number[][]): void {
    const rows = (map && map.length) ? (map.length | 0) : 0;
    const cols = (rows > 0 && map[0]) ? (map[0].length | 0) : 0;
    const islandH = 3;
    const islandW = 3;
    const moat = 3; // ensure a 3-tile wall span for bridge testing
    const minRows = islandH + (moat * 2) + 2;
    const minCols = islandW + (moat * 2) + 2;
    if (rows < minRows || cols < minCols) return;

    const minR0 = (moat + 1) | 0;
    const maxR0 = (rows - islandH - moat - 1) | 0;
    const minC0 = (moat + 1) | 0;
    const maxC0 = (cols - islandW - moat - 1) | 0;
    if (maxR0 < minR0 || maxC0 < minC0) return;

    const targetR0 = Math.max(minR0, Math.min(maxR0, (Math.idiv(rows, 4) | 0)));
    const targetC0 = Math.max(minC0, Math.min(maxC0, (Math.idiv(cols, 4) | 0)));
    let r0 = targetR0 | 0;
    let c0 = targetC0 | 0;
    // Prefer carving the island out of the main floor mass so it is clearly visible.
    const comp = _worldgen_computeFloorComponents(map);
    if (comp.comps.length) {
        const mainId = _worldgen_pickMainComponentId(comp.compId, comp.comps, rows, cols);
        if (mainId >= 0) {
            let bestScore = 999999;
            for (let rr = minR0; rr <= maxR0; rr++) {
                for (let cc = minC0; cc <= maxC0; cc++) {
                    let ok = true;
                    for (let r = (rr - moat); r <= (rr + islandH + moat - 1); r++) {
                        for (let c = (cc - moat); c <= (cc + islandW + moat - 1); c++) {
                            if ((map[r][c] | 0) === (TILE_WALL | 0)) { ok = false; break; }
                            if ((comp.compId[r][c] | 0) !== (mainId | 0)) { ok = false; break; }
                        }
                        if (!ok) break;
                    }
                    if (!ok) continue;
                    const score = (Math.abs((rr | 0) - (targetR0 | 0)) + Math.abs((cc | 0) - (targetC0 | 0))) | 0;
                    if (score < bestScore) {
                        bestScore = score;
                        r0 = rr | 0;
                        c0 = cc | 0;
                    }
                }
            }
            if (isOcclude) {
                const idx = sprites.readDataNumber(target, EFFECT_FRAME_INDEX_DATA_KEY)
                if (Number.isFinite(idx) && idx >= 0) {
                    sprites.setDataNumber(fx, EFFECT_FRAME_INDEX_DATA_KEY, Number(idx))
                }
            }
        }
    }

    // Ring of walls around the island (keep inside border).
    for (let r = (r0 - moat); r <= (r0 + islandH + moat - 1); r++) {
        if (r <= 0 || r >= rows - 1) continue;
        for (let c = (c0 - moat); c <= (c0 + islandW + moat - 1); c++) {
            if (c <= 0 || c >= cols - 1) continue;
            map[r][c] = TILE_WALL;
        }
    }

    // Carve the island interior back to floor.
    for (let r = r0; r < (r0 + islandH); r++) {
        for (let c = c0; c < (c0 + islandW); c++) {
            map[r][c] = TILE_EMPTY;
        }
    }
}

function _worldgen_computeFloorComponents(map: number[][]): {
    compId: number[][];
    comps: { id: number; tiles: { r: number; c: number }[]; size: number }[];
} {
    const rows = (map && map.length) ? (map.length | 0) : 0;
    const cols = (rows > 0 && map[0]) ? (map[0].length | 0) : 0;
    const compId: number[][] = [];
    for (let r = 0; r < rows; r++) {
        const row: number[] = [];
        for (let c = 0; c < cols; c++) row.push(-1);
        compId.push(row);
    }

    const comps: { id: number; tiles: { r: number; c: number }[]; size: number }[] = [];
    let nextId = 0;

    for (let r0 = 0; r0 < rows; r0++) {
        for (let c0 = 0; c0 < cols; c0++) {
            if (!_worldgen_isFloor(map[r0][c0] | 0)) continue;
            if (compId[r0][c0] >= 0) continue;

            const tiles: { r: number; c: number }[] = [];
            const qR: number[] = [r0];
            const qC: number[] = [c0];
            compId[r0][c0] = nextId;

            let head = 0;
            while (head < qR.length) {
                const r = qR[head];
                const c = qC[head];
                head++;
                tiles.push({ r, c });

                if (r > 0 && _worldgen_isFloor(map[r - 1][c] | 0) && compId[r - 1][c] < 0) {
                    compId[r - 1][c] = nextId; qR.push(r - 1); qC.push(c);
                }
                if (r < rows - 1 && _worldgen_isFloor(map[r + 1][c] | 0) && compId[r + 1][c] < 0) {
                    compId[r + 1][c] = nextId; qR.push(r + 1); qC.push(c);
                }
                if (c > 0 && _worldgen_isFloor(map[r][c - 1] | 0) && compId[r][c - 1] < 0) {
                    compId[r][c - 1] = nextId; qR.push(r); qC.push(c - 1);
                }
                if (c < cols - 1 && _worldgen_isFloor(map[r][c + 1] | 0) && compId[r][c + 1] < 0) {
                    compId[r][c + 1] = nextId; qR.push(r); qC.push(c + 1);
                }
            }

            comps.push({ id: nextId, tiles, size: tiles.length | 0 });
            nextId++;
        }
    }

    return { compId, comps };
}

function _worldgen_pickMainComponentId(
    compId: number[][],
    comps: { id: number; tiles: { r: number; c: number }[]; size: number }[],
    rows: number,
    cols: number
): number {
    if (!comps.length) return -1;
    const centerR = Math.idiv(rows, 2) | 0;
    const centerC = Math.idiv(cols, 2) | 0;
    const centerId = (compId[centerR] && compId[centerR][centerC] != null) ? (compId[centerR][centerC] | 0) : -1;
    if (centerId >= 0) return centerId;

    let bestId = comps[0].id | 0;
    let bestSize = comps[0].size | 0;
    for (let i = 1; i < comps.length; i++) {
        if ((comps[i].size | 0) > (bestSize | 0)) {
            bestSize = comps[i].size | 0;
            bestId = comps[i].id | 0;
        }
    }
    return bestId | 0;
}

function _worldgen_findNearestPair(
    tilesA: { r: number; c: number }[],
    tilesB: { r: number; c: number }[],
    rows: number,
    cols: number,
    preferAxis: "h" | "v" | "" = ""
): { r0: number; c0: number; r1: number; c1: number } | null {
    if (!tilesA.length || !tilesB.length) return null;

    const isInterior = (t: { r: number; c: number }) =>
        (t.r > 0 && t.c > 0 && t.r < (rows - 1) && t.c < (cols - 1));

    const aTiles = tilesA.filter(isInterior);
    const bTiles = tilesB.filter(isInterior);
    const aa = aTiles.length ? aTiles : tilesA;
    const bb = bTiles.length ? bTiles : tilesB;

    let bestDist = 999999;
    let bestAxisDelta = 999999;
    let best: { r0: number; c0: number; r1: number; c1: number } | null = null;

    for (let i = 0; i < aa.length; i++) {
        const a = aa[i];
        for (let j = 0; j < bb.length; j++) {
            const b = bb[j];
            const dr = Math.abs((a.r | 0) - (b.r | 0));
            const dc = Math.abs((a.c | 0) - (b.c | 0));
            const d = (dr + dc) | 0;
            if (d < bestDist) {
                bestDist = d;
                bestAxisDelta = (preferAxis === "v") ? dc : (preferAxis === "h") ? dr : 999999;
                best = { r0: a.r | 0, c0: a.c | 0, r1: b.r | 0, c1: b.c | 0 };
            } else if (preferAxis && d === bestDist) {
                const axisDelta = (preferAxis === "v") ? dc : dr;
                if (axisDelta < bestAxisDelta) {
                    bestAxisDelta = axisDelta;
                    best = { r0: a.r | 0, c0: a.c | 0, r1: b.r | 0, c1: b.c | 0 };
                }
            }
        }
    }

    return best;
}

function _worldgen_buildPath(
    map: number[][],
    r0: number,
    c0: number,
    r1: number,
    c1: number,
    order: "hv" | "vh"
): _WorldgenPathCell[] {
    const rows = (map && map.length) ? (map.length | 0) : 0;
    const cols = (rows > 0 && map[0]) ? (map[0].length | 0) : 0;
    const cells: _WorldgenPathCell[] = [];

    let r = r0 | 0;
    let c = c0 | 0;

    const step = (dr: number, dc: number, dir: "h" | "v"): void => {
        r = (r + dr) | 0;
        c = (c + dc) | 0;
        if (r < 0 || c < 0 || r >= rows || c >= cols) return;
        const wasWall = ((map[r][c] | 0) === (TILE_WALL | 0));
        cells.push({ r, c, dir, wasWall });
    };

    const dc = Math.sign((c1 | 0) - (c | 0));
    const dr = Math.sign((r1 | 0) - (r | 0));

    if (order === "hv") {
        while ((c | 0) !== (c1 | 0)) step(0, dc, "h");
        while ((r | 0) !== (r1 | 0)) step(dr, 0, "v");
    } else {
        while ((r | 0) !== (r1 | 0)) step(dr, 0, "v");
        while ((c | 0) !== (c1 | 0)) step(0, dc, "h");
    }

    return cells;
}

function _worldgen_isWallAt(map: number[][], r: number, c: number): boolean {
    const rows = (map && map.length) ? (map.length | 0) : 0;
    const cols = (rows > 0 && map[0]) ? (map[0].length | 0) : 0;
    if (r < 0 || c < 0 || r >= rows || c >= cols) return true;
    return ((map[r][c] | 0) === (TILE_WALL | 0));
}

function _worldgen_findBridgeCandidate(
    path: _WorldgenPathCell[],
    map: number[][],
    requireBottomRowWalls: boolean
): _WorldgenBridgeCandidate | null {
    let best: _WorldgenBridgeCandidate | null = null;

    let i = 0;
    while (i < path.length) {
        const cell = path[i];
        if (!cell.wasWall) { i++; continue; }

        const dir = cell.dir;
        let j = i;
        while (j < path.length && path[j].dir === dir && path[j].wasWall) j++;
        const len = (j - i) | 0;

        if (len >= 3) {
            if (dir === "h") {
                const row = path[i].r | 0;
                let leftMost = 999999;
                let rightMost = -999999;
                for (let k = i; k < j; k++) {
                    const c = path[k].c | 0;
                    if (c < leftMost) leftMost = c;
                    if (c > rightMost) rightMost = c;
                }

                let segLeft = leftMost;
                let segRight = rightMost;
                let segLen = (rightMost - leftMost + 1) | 0;

                if (requireBottomRowWalls) {
                    let bestLen = 0;
                    let bestMin = 0;
                    let bestMax = 0;
                    let curLen = 0;
                    let curMin = 0;
                    let curMax = 0;

                    for (let k = i; k < j; k++) {
                        const c = path[k].c | 0;
                        const ok = _worldgen_isWallAt(map, row + 1, c);
                        if (ok) {
                            if (curLen === 0) {
                                curLen = 1;
                                curMin = c;
                                curMax = c;
                            } else {
                                curLen = (curLen + 1) | 0;
                                if (c < curMin) curMin = c;
                                if (c > curMax) curMax = c;
                            }
                        } else if (curLen > 0) {
                            if (curLen > bestLen) {
                                bestLen = curLen;
                                bestMin = curMin;
                                bestMax = curMax;
                            }
                            curLen = 0;
                        }
                    }

                    if (curLen > 0 && curLen > bestLen) {
                        bestLen = curLen;
                        bestMin = curMin;
                        bestMax = curMax;
                    }

                    if (bestLen >= 3) {
                        segLeft = bestMin;
                        segRight = bestMax;
                        segLen = (bestMax - bestMin + 1) | 0;
                    } else {
                        segLen = 0;
                    }
                }

                if (segLen >= 3) {
                    const cand: _WorldgenBridgeCandidate = {
                        kind: "bridge_h",
                        anchorR: (row + 1) | 0,
                        anchorC: segLeft | 0,
                        score: segLen | 0,
                        span: segLen | 0
                    };
                    if (!best || (cand.score | 0) > (best.score | 0)) best = cand;
                }
            } else {
                const col = path[i].c | 0;
                let topMost = 999999;
                let botMost = -999999;
                for (let k = i; k < j; k++) {
                    const r = path[k].r | 0;
                    if (r < topMost) topMost = r;
                    if (r > botMost) botMost = r;
                }
                const span = (botMost - topMost + 1) | 0;
                const cand: _WorldgenBridgeCandidate = {
                    kind: "bridge_v",
                    anchorR: botMost | 0,
                    anchorC: col | 0,
                    score: span | 0,
                    span: span | 0
                };
                if (!best || (cand.score | 0) > (best.score | 0)) best = cand;
            }
        }

        i = j;
    }

    return best;
}

function _worldgen_isBridgeWalkwayTile(
    r: number,
    c: number,
    bridge: _WorldgenBridgeCandidate | null
): boolean {
    if (!bridge) return false;
    const span = Math.max(3, ((bridge.span | 0) || (bridge.score | 0) || 3));
    if (bridge.kind === "bridge_h") {
        const br = (bridge.anchorR - 1) | 0;
        const bc = bridge.anchorC | 0;
        return ((r | 0) === br && (c | 0) >= bc && (c | 0) <= (bc + (span - 1)));
    }
    const bc = bridge.anchorC | 0;
    const br0 = (bridge.anchorR - (span - 1)) | 0;
    return ((c | 0) === bc && (r | 0) >= br0 && (r | 0) <= (br0 + (span - 1)));
}

function _worldgen_carvePath(
    map: number[][],
    path: _WorldgenPathCell[],
    bridge: _WorldgenBridgeCandidate | null
): void {
    const rows = (map && map.length) ? (map.length | 0) : 0;
    const cols = (rows > 0 && map[0]) ? (map[0].length | 0) : 0;
    for (let i = 0; i < path.length; i++) {
        const r = path[i].r | 0;
        const c = path[i].c | 0;
        if (r <= 0 || c <= 0 || r >= rows - 1 || c >= cols - 1) continue;
        if (_worldgen_isBridgeWalkwayTile(r, c, bridge)) {
            if ((map[r][c] | 0) === (TILE_WALL | 0)) {
                map[r][c] = TILE_BRIDGE;
            }
            continue;
        }
        map[r][c] = TILE_EMPTY;
    }
}

function _worldgen_connectIslandsWithBridges(map: number[][]): _WorldgenBridgePlacement[] {
    const placements: _WorldgenBridgePlacement[] = [];
    const rows = (map && map.length) ? (map.length | 0) : 0;
    const cols = (rows > 0 && map[0]) ? (map[0].length | 0) : 0;
    if (rows <= 0 || cols <= 0) return placements;

    const usedAnchors = new Set<string>();
    let guard = 0;

    while (guard++ < 100) {
        const comp = _worldgen_computeFloorComponents(map);
        if (comp.comps.length <= 1) break;

        const mainId = _worldgen_pickMainComponentId(comp.compId, comp.comps, rows, cols);
        const main = comp.comps.find(c => (c.id | 0) === (mainId | 0)) || null;
        if (!main) break;

        let island: { id: number; tiles: { r: number; c: number }[]; size: number } | null = null;
        for (let i = 0; i < comp.comps.length; i++) {
            const c = comp.comps[i];
            if ((c.id | 0) === (mainId | 0)) continue;
            if (!island || ((c.size | 0) > (island.size | 0))) island = c;
        }
        if (!island) break;

        const preferAxis = DEBUG_WORLDGEN_FORCE_BRIDGE_VERTICAL ? "v" : "";
        const pair = _worldgen_findNearestPair(island.tiles, main.tiles, rows, cols, preferAxis);
        if (!pair) break;

        const pathHV = _worldgen_buildPath(map, pair.r0, pair.c0, pair.r1, pair.c1, "hv");
        const pathVH = _worldgen_buildPath(map, pair.r0, pair.c0, pair.r1, pair.c1, "vh");

        const candHV = _worldgen_findBridgeCandidate(pathHV, map, true);
        const candVH = _worldgen_findBridgeCandidate(pathVH, map, true);

        let chosenPath = pathHV;
        let chosenCand = candHV;

        if (DEBUG_WORLDGEN_FORCE_BRIDGE_VERTICAL) {
            if (candVH) {
                chosenPath = pathVH; chosenCand = candVH;
            } else if (candHV) {
                chosenPath = pathHV; chosenCand = candHV;
            } else {
                chosenPath = (pathHV.length <= pathVH.length) ? pathHV : pathVH;
                chosenCand = null;
            }
        } else {
            if (candHV && candVH) {
                if ((candVH.score | 0) > (candHV.score | 0)) {
                    chosenPath = pathVH; chosenCand = candVH;
                } else if ((candVH.score | 0) === (candHV.score | 0)) {
                    if ((pathVH.length | 0) < (pathHV.length | 0)) {
                        chosenPath = pathVH; chosenCand = candVH;
                    }
                }
            } else if (!candHV && candVH) {
                chosenPath = pathVH; chosenCand = candVH;
            } else if (!candHV && !candVH) {
                chosenPath = (pathHV.length <= pathVH.length) ? pathHV : pathVH;
                chosenCand = null;
            }
        }

        _worldgen_carvePath(map, chosenPath, chosenCand);

        if (chosenCand) {
            const key = String(chosenCand.anchorR | 0) + "," + String(chosenCand.anchorC | 0);
            if (!usedAnchors.has(key)) {
                usedAnchors.add(key);
                placements.push({
                    anchorR: chosenCand.anchorR | 0,
                    anchorC: chosenCand.anchorC | 0,
                    kind: chosenCand.kind,
                    span: chosenCand.span | 0
                });
            }
        }

        if (DEBUG_WORLDGEN_BRIDGE_LOGS) {
            console.log("[WORLDGEN][BRIDGE]", {
                islandSize: island.size | 0,
                mainId: mainId | 0,
                pathLen: chosenPath.length | 0,
                span: chosenCand ? (chosenCand.span | 0) : 0,
                bridge: chosenCand ? { kind: chosenCand.kind, r: chosenCand.anchorR | 0, c: chosenCand.anchorC | 0 } : null
            });
        }
    }

    return placements;
}

function _createTileMap2D(): number[][] {

    // Entrance floor: deterministic walkway + chasm walls.
    if ((_dunFloorKind || "") === DUNGEON_KIND_ENTRANCE) {
        _worldgenBridgePlacements = [];
        return _createEntranceFloorMap();
    }

    // Shop floors use a deterministic open layout so we can place the platform + stairs cleanly.
    if ((_dunFloorKind || "") === DUNGEON_KIND_SHOP) {
        _worldgenBridgePlacements = [];
        return _createShopFloorMap();
    }

    // Boss floors: open procedural arena (no interior walls) to prevent boss pathing jams.
    if ((_dunFloorKind || "") === DUNGEON_KIND_COMBAT && _dunIsBossFloor(_dunFloorIndex | 0)) {
        _worldgenBridgePlacements = [];
        return _createBossArenaMap();
    }

    // MakeCode and Phaser both see the same 0/1 logic grid.
    return _createBasicCaveMap();

}



function _createShopFloorMap(): number[][] {

    // Simple open box with border walls. Keeps the entire interior walkable for platform placement.
    _worldgenBridgePlacements = [];
    const cols = Math.max(SHOP_WORLD_TILES_W, MIN_WORLD_TILES_W)
    const rows = Math.max(SHOP_WORLD_TILES_H, MIN_WORLD_TILES_H)

    const map: number[][] = []
    for (let r = 0; r < rows; r++) {
        const row: number[] = []
        for (let c = 0; c < cols; c++) {
            const isBorder = (r === 0 || c === 0 || r === (rows - 1) || c === (cols - 1))
            row.push(isBorder ? TILE_WALL : TILE_EMPTY)
        }
        map.push(row)
    }

    return map
}

function _createEntranceFloorMap(): number[][] {
    _worldgenBridgePlacements = []
    const cols = Math.max(WORLD_TILES_W, MIN_WORLD_TILES_W)
    const rows = Math.max(WORLD_TILES_H, MIN_WORLD_TILES_H)
    const map: number[][] = []
    for (let r = 0; r < rows; r++) {
        const row: number[] = []
        for (let c = 0; c < cols; c++) row.push(TILE_WALL)
        map.push(row)
    }

    const centerC = Math.idiv(cols | 0, 2) | 0
    const walkwayLeft = Math.max(1, (centerC - 1) | 0) | 0
    const walkwayRight = Math.min((cols - 2) | 0, (centerC + 2) | 0) | 0
    const walkwayLeftWide = Math.max(1, (walkwayLeft - 2) | 0) | 0
    for (let r = 1; r <= (rows - 2); r++) {
        for (let c = walkwayLeftWide; c <= walkwayRight; c++) map[r][c] = TILE_EMPTY
    }

    // Entrance taper: rows 0-3 full ground, then 10-wide, then 8-wide, then 4-row zigzag to walkway.
    const baseTop = 1 // row 0 in your mental model
    const fullGroundRows = 3
    const midWidth20 = 20
    const midWidth18 = 18
    const zigRows = 4
    const walkwayWideW = ((walkwayRight - walkwayLeftWide + 1) | 0)

    const carveSpan = (r: number, left: number, right: number): void => {
        const l = Math.max(1, left | 0) | 0
        const rr = Math.min((cols - 2) | 0, right | 0) | 0
        for (let c = l; c <= rr; c++) map[r][c] = TILE_EMPTY
    }
    const carveCentered = (r: number, width: number): void => {
        const w = Math.max(1, width | 0) | 0
        let left = 0
        let right = 0
        if ((w & 1) === 0) {
            // Even width: center between the two middle columns.
            const centerLeft = ((centerC | 0) - 1) | 0
            const half = Math.idiv(w | 0, 2) | 0
            left = ((centerLeft - half + 1) | 0)
            right = ((left + w - 1) | 0)
        } else {
            // Odd width: center on the middle column.
            const half = Math.idiv((w - 1) | 0, 2) | 0
            left = ((centerC - half) | 0)
            right = ((left + w - 1) | 0)
        }
        carveSpan(r | 0, left | 0, right | 0)
    }

    // Rows 0-3 (full ground inside border)
    for (let i = 0; i < fullGroundRows; i++) {
        const r = (baseTop + i) | 0
        if (r < 1 || r > (rows - 2)) continue
        carveSpan(r | 0, 1, (cols - 2) | 0)
    }

    const row20 = (baseTop + fullGroundRows) | 0
    const row18 = (row20 + 1) | 0
    if (row20 >= 1 && row20 <= (rows - 2)) carveCentered(row20 | 0, midWidth20 | 0)
    if (row18 >= 1 && row18 <= (rows - 2)) carveCentered(row18 | 0, midWidth18 | 0)

    // Zigzag transition (4 rows) from width=18 down to walkway width.
    const zigTop = (row18 + 1) | 0
    const delta = Math.max(0, (midWidth18 - walkwayWideW) | 0) | 0
    for (let i = 1; i <= zigRows; i++) {
        const r = (zigTop + (i - 1)) | 0
        if (r < 1 || r > (rows - 2)) continue
        const dec = Math.idiv(((delta * i) + (zigRows - 1)) | 0, zigRows) | 0
        const width = Math.max(walkwayWideW | 0, (midWidth18 - dec) | 0) | 0
        carveCentered(r | 0, width | 0)
    }

    return map
}

function _createBossArenaMap(): number[][] {
    // Large open arena with border walls + randomized edge obstacles.
    let cols = Math.max(WORLD_TILES_W, MIN_WORLD_TILES_W) | 0
    let rows = Math.max(WORLD_TILES_H, MIN_WORLD_TILES_H) | 0
    if (cols < 16) cols = 16
    if (rows < 12) rows = 12

    const map: number[][] = []
    for (let r = 0; r < rows; r++) {
        const row: number[] = []
        for (let c = 0; c < cols; c++) {
            const isBorder = (r === 0 || c === 0 || r === (rows - 1) || c === (cols - 1))
            row.push(isBorder ? TILE_WALL : TILE_EMPTY)
        }
        map.push(row)
    }

    const centerR = Math.idiv(rows, 2) | 0
    const centerC = Math.idiv(cols, 2) | 0
    const clearHalfR = Math.max(4, Math.idiv(rows, 4)) | 0
    const clearHalfC = Math.max(4, Math.idiv(cols, 4)) | 0

    const clearTop = (centerR - clearHalfR) | 0
    const clearBottom = (centerR + clearHalfR) | 0
    const clearLeft = (centerC - clearHalfC) | 0
    const clearRight = (centerC + clearHalfC) | 0

    const canPlace = (r0: number, c0: number, rh: number, cw: number): boolean => {
        const r1 = (r0 + rh - 1) | 0
        const c1 = (c0 + cw - 1) | 0
        if (r0 <= 1 || c0 <= 1 || r1 >= (rows - 2) || c1 >= (cols - 2)) return false
        // Keep the center arena fully open.
        if (r1 >= clearTop && r0 <= clearBottom && c1 >= clearLeft && c0 <= clearRight) return false
        for (let r = r0; r <= r1; r++) {
            for (let c = c0; c <= c1; c++) {
                if ((map[r][c] | 0) !== (TILE_EMPTY | 0)) return false
            }
        }
        return true
    }

    const placeRect = (r0: number, c0: number, rh: number, cw: number) => {
        const r1 = (r0 + rh - 1) | 0
        const c1 = (c0 + cw - 1) | 0
        for (let r = r0; r <= r1; r++) {
            for (let c = c0; c <= c1; c++) map[r][c] = TILE_WALL
        }
    }

    // Random edge obstacles for variety (kept far from center).
    const blockCount = Math.randomRange(3, 6) | 0
    for (let i = 0; i < blockCount; i++) {
        const h = Math.randomRange(2, 4) | 0
        const w = Math.randomRange(2, 4) | 0
        let placed = false
        for (let tries = 0; tries < 80 && !placed; tries++) {
            const r0 = Math.randomRange(2, (rows - h - 2) | 0) | 0
            const c0 = Math.randomRange(2, (cols - w - 2) | 0) | 0
            if (!canPlace(r0, c0, h, w)) continue
            placeRect(r0, c0, h, w)
            placed = true
        }
    }

    return map
}

type BossRockPlacement = {
    name: string
    anchorR: number
    anchorC: number
    wTiles: number
    hTiles: number
}

const BOSS_ROCK_MIN_COUNT = 3
const BOSS_ROCK_MAX_COUNT = 6
const BOSS_ROCK_TRIES_PER = 120

let _bossRockPlacements: BossRockPlacement[] = []

function _bossRockReset(): void {
    _bossRockPlacements = []
}

function _bossRockComputeClearRect(rows: number, cols: number): { top: number; bottom: number; left: number; right: number } {
    const centerR = Math.idiv(rows | 0, 2) | 0
    const centerC = Math.idiv(cols | 0, 2) | 0
    const clearHalfR = Math.max(4, Math.idiv(rows | 0, 4)) | 0
    const clearHalfC = Math.max(4, Math.idiv(cols | 0, 4)) | 0
    return {
        top: (centerR - clearHalfR) | 0,
        bottom: (centerR + clearHalfR) | 0,
        left: (centerC - clearHalfC) | 0,
        right: (centerC + clearHalfC) | 0,
    }
}

function _bossRockFitsAt(
    anchorR: number,
    anchorC: number,
    wTiles: number,
    hTiles: number,
    rows: number,
    cols: number,
    clear: { top: number; bottom: number; left: number; right: number },
    occ: boolean[][]
): boolean {
    const w = Math.max(1, wTiles | 0) | 0
    const h = Math.max(1, hTiles | 0) | 0
    const r0 = ((anchorR | 0) - ((h | 0) - 1)) | 0
    const r1 = (anchorR | 0)
    const c0 = (anchorC | 0)
    const c1 = ((anchorC | 0) + (w | 0) - 1) | 0

    if (r0 <= 1 || c0 <= 1) return false
    if (r1 >= (rows - 2) || c1 >= (cols - 2)) return false

    // Keep the center arena fully open.
    if (r1 >= (clear.top | 0) && r0 <= (clear.bottom | 0) && c1 >= (clear.left | 0) && c0 <= (clear.right | 0)) return false

    for (let r = r0 | 0; r <= (r1 | 0); r++) {
        for (let c = c0 | 0; c <= (c1 | 0); c++) {
            if ((_engineWorldTileMap[r][c] | 0) !== (TILE_EMPTY | 0)) return false
            if (occ[r] && occ[r][c]) return false
            if (_dunFindDecorAtTile(r | 0, c | 0, "")) return false
        }
    }
    return true
}

function _bossRockStampAt(
    name: string,
    anchorR: number,
    anchorC: number,
    wTiles: number,
    hTiles: number,
    occ: boolean[][]
): void {
    // Visual anchor (single prop instance)
    _dunDecor_spawnAtTile({
        name: name || "",
        role: DECOR_ROLE.TRIGGER,
        tileR: anchorR | 0,
        tileC: anchorC | 0,
        pxW: WORLD_TILE_SIZE | 0,
        pxH: WORLD_TILE_SIZE | 0,
    })

    // Solid colliders for each occupied tile (aura-tightened later).
    const w = Math.max(1, wTiles | 0) | 0
    const h = Math.max(1, hTiles | 0) | 0
    for (let dy = 0; dy < (h | 0); dy++) {
        for (let dx = 0; dx < (w | 0); dx++) {
            const rr = ((anchorR | 0) - ((h | 0) - 1) + (dy | 0)) | 0
            const cc = ((anchorC | 0) + (dx | 0)) | 0
            const s = _dunDecor_spawnAtTile({
                name: name || "",
                role: DECOR_ROLE.SOLID,
                tileR: rr | 0,
                tileC: cc | 0,
                pxW: WORLD_TILE_SIZE | 0,
                pxH: WORLD_TILE_SIZE | 0,
            })
            if (s && !(s.flags & sprites.Flag.Destroyed)) {
                sprites.setDataNumber(s, DECOR_DATA.IS_COLLIDER, 1)
            }
            if (occ[rr]) occ[rr][cc] = true
        }
    }
}

function _dunBossSpawnRocks(): void {
    if (!_engineWorldTileMap || _engineWorldTileMap.length <= 0) return
    if (!BOSS_ROCK_POOL || BOSS_ROCK_POOL.length <= 0) return

    const rows = _engineWorldTileMap.length | 0
    const cols = _engineWorldTileMap[0] ? (_engineWorldTileMap[0].length | 0) : 0
    if (rows <= 0 || cols <= 0) return

    const clear = _bossRockComputeClearRect(rows | 0, cols | 0)
    const occ: boolean[][] = new Array(rows | 0)
    for (let r = 0; r < (rows | 0); r++) {
        const row: boolean[] = new Array(cols | 0)
        for (let c = 0; c < (cols | 0); c++) row[c] = false
        occ[r] = row
    }

    const target = Math.randomRange(BOSS_ROCK_MIN_COUNT | 0, BOSS_ROCK_MAX_COUNT | 0) | 0
    let placed = 0

    for (let i = 0; i < (target | 0); i++) {
        let done = false
        for (let t = 0; t < (BOSS_ROCK_TRIES_PER | 0) && !done; t++) {
            const pickIdx = Math.randomRange(0, (BOSS_ROCK_POOL.length - 1) | 0) | 0
            const def = BOSS_ROCK_POOL[pickIdx]
            if (!def) continue

            const w = Math.max(1, def.wTiles | 0) | 0
            const h = Math.max(1, def.hTiles | 0) | 0
            const minAnchorR = ((h | 0) - 1 + 2) | 0
            const maxAnchorR = (rows - 2) | 0
            const minAnchorC = 2
            const maxAnchorC = ((cols - 1) - (w | 0)) | 0
            if ((minAnchorR | 0) > (maxAnchorR | 0)) continue
            if ((minAnchorC | 0) > (maxAnchorC | 0)) continue

            const anchorR = Math.randomRange(minAnchorR | 0, maxAnchorR | 0) | 0
            const anchorC = Math.randomRange(minAnchorC | 0, maxAnchorC | 0) | 0

            if (!_bossRockFitsAt(anchorR, anchorC, w | 0, h | 0, rows | 0, cols | 0, clear, occ)) continue

            _bossRockPlacements.push({
                name: def.name || "",
                anchorR: anchorR | 0,
                anchorC: anchorC | 0,
                wTiles: w | 0,
                hTiles: h | 0,
            })
            _bossRockStampAt(def.name || "", anchorR | 0, anchorC | 0, w | 0, h | 0, occ)
            placed++
            done = true
        }
    }
    void placed
}



function _createBasicCaveMap(): number[][] {

    // 1) Decide world dimensions in tiles

    let cols = Math.max(WORLD_TILES_W, MIN_WORLD_TILES_W)

    let rows = Math.max(WORLD_TILES_H, MIN_WORLD_TILES_H)



    // Extra safety floor if you still want it

    if (cols < 10) cols = 10

    if (rows < 8) rows = 8



    // 2) Seed random map (0 = empty, 1 = wall)

    const wallChance = 45

    let map = _seedRandomMap(rows, cols, wallChance)



    // 3) Run a few smoothing steps (cellular automata)

    const smoothSteps = 5

    for (let i = 0; i < smoothSteps; i++) {

        map = _smoothMapStep(map)

    }



    // 4) Make outer border solid walls (flying-island feel & clean edges)

    for (let r = 0; r < rows; r++) {

        map[r][0] = TILE_WALL

        map[r][cols - 1] = TILE_WALL

    }

    for (let c = 0; c < cols; c++) {

        map[0][c] = TILE_WALL

        map[rows - 1][c] = TILE_WALL

    }



    // 5) Carve a central arena for the heroes (guaranteed open space)

    const centerR = Math.idiv(rows, 2)

    const centerC = Math.idiv(cols, 2)



    // Size of arena scales with map size

    const arenaHalfH = Math.max(2, Math.idiv(rows, 8))   // vertical half-size

    const arenaHalfW = Math.max(2, Math.idiv(cols, 8))   // horizontal half-size



    const topR = Math.max(1, centerR - arenaHalfH)

    const bottomR = Math.min(rows - 2, centerR + arenaHalfH)

    const leftC = Math.max(1, centerC - arenaHalfW)

    const rightC = Math.min(cols - 2, centerC + arenaHalfW)



    for (let r = topR; r <= bottomR; r++) {

        for (let c = leftC; c <= rightC; c++) {

            map[r][c] = TILE_EMPTY

        }

    }



    // 6) Carve L-shaped corridors from each corner into the arena (NOW 2 tiles wide).

    const CORRIDOR_WIDTH = 2



    // We target a 2-column “spine” at the arena center.

    const spineC0 = Math.max(1, Math.min(cols - 2, centerC - 1))

    const spineC1 = Math.max(1, Math.min(cols - 2, centerC))



    function carveRect(r0: number, c0: number, r1: number, c1: number) {

        const rStart = Math.max(1, Math.min(r0, r1))

        const rEnd   = Math.min(rows - 2, Math.max(r0, r1))

        const cStart = Math.max(1, Math.min(c0, c1))

        const cEnd   = Math.min(cols - 2, Math.max(c0, c1))



        for (let r = rStart; r <= rEnd; r++) {

            for (let c = cStart; c <= cEnd; c++) {

                map[r][c] = TILE_EMPTY

            }

        }

    }



    function carveCornerToArena(cornerR: number, cornerC: number) {

        // Horizontal segment (2 tiles tall):

        const hr0 = (cornerR <= centerR) ? cornerR : (cornerR - (CORRIDOR_WIDTH - 1))

        const hr1 = hr0 + (CORRIDOR_WIDTH - 1)



        carveRect(

            hr0,

            Math.min(cornerC, spineC0),

            hr1,

            Math.max(cornerC, spineC1)

        )



        // Vertical segment (2 tiles wide at the spine columns):

        carveRect(

            Math.min(cornerR, centerR),

            spineC0,

            Math.max(cornerR, centerR),

            spineC1

        )

    }



    // Inner spawn corners (leave outermost border walls intact at 0 / rows-1 / cols-1)

    const topRow = 1

    const bottomRow = rows - 2

    const leftCol = 1

    const rightCol = cols - 2



    carveCornerToArena(topRow, leftCol)

    carveCornerToArena(topRow, rightCol)

    carveCornerToArena(bottomRow, leftCol)

    carveCornerToArena(bottomRow, rightCol)



    // 7) Carve spawn pads that INCLUDE the actual outer corners.

    const SPAWN_PAD_RADIUS = 2 // 2 ? up to 5x5 pad; tune as needed



    function carveSpawnPad(centerR: number, centerC: number) {

        const rStart = Math.max(0, centerR - SPAWN_PAD_RADIUS)

        const rEnd   = Math.min(rows - 1, centerR + SPAWN_PAD_RADIUS)

        const cStart = Math.max(0, centerC - SPAWN_PAD_RADIUS)

        const cEnd   = Math.min(cols - 1, centerC + SPAWN_PAD_RADIUS)



        for (let r = rStart; r <= rEnd; r++) {

            for (let c = cStart; c <= cEnd; c++) {

                map[r][c] = TILE_EMPTY

            }

        }

    }



    carveSpawnPad(0, 0)

    carveSpawnPad(0, cols - 1)

    carveSpawnPad(rows - 1, 0)

    carveSpawnPad(rows - 1, cols - 1)



    // 8) Post-process for tile-art constraints:

    //    A) Walkways/corridors must not be 1-tile wide (widen to >=2).

    //    B) Wall blobs must be >=4 tiles OR true singletons (size==1).

    //    C) Non-singleton wall tiles must have >=2 cardinal wall neighbors (prune spurs).

    ;(function postProcessForArt() {

        const MIN_COMPONENT_SIZE = 4

        const MIN_CARDINAL_WALL_NEI = 2



        function copyGrid(src: number[][]): number[][] {

            const out: number[][] = []

            for (let r = 0; r < rows; r++) out.push((src[r] as number[]).slice())

            return out

        }



        function countCardinalSame(src: number[][], r: number, c: number, val: number): number {

            let n = 0

            if (r > 0 && src[r - 1][c] === val) n++

            if (r < rows - 1 && src[r + 1][c] === val) n++

            if (c > 0 && src[r][c - 1] === val) n++

            if (c < cols - 1 && src[r][c + 1] === val) n++

            return n

        }



        function computeComponents4(src: number[][], targetVal: number): { compId: number[][], sizes: number[], touchesBorder: boolean[] } {

            const compId: number[][] = []

            for (let r = 0; r < rows; r++) {

                const row: number[] = []

                for (let c = 0; c < cols; c++) row.push(-1)

                compId.push(row)

            }



            const sizes: number[] = []

            const touchesBorder: boolean[] = []



            let nextId = 0



            for (let r0 = 0; r0 < rows; r0++) {

                for (let c0 = 0; c0 < cols; c0++) {

                    if (src[r0][c0] !== targetVal) continue

                    if (compId[r0][c0] >= 0) continue



                    const qR: number[] = [r0]

                    const qC: number[] = [c0]

                    compId[r0][c0] = nextId



                    let head = 0

                    let size = 0

                    let touch = false



                    while (head < qR.length) {

                        const r = qR[head]

                        const c = qC[head]

                        head++



                        size++

                        if (r === 0 || c === 0 || r === rows - 1 || c === cols - 1) touch = true



                        // 4-neighborhood flood

                        if (r > 0 && src[r - 1][c] === targetVal && compId[r - 1][c] < 0) {

                            compId[r - 1][c] = nextId

                            qR.push(r - 1); qC.push(c)

                        }

                        if (r < rows - 1 && src[r + 1][c] === targetVal && compId[r + 1][c] < 0) {

                            compId[r + 1][c] = nextId

                            qR.push(r + 1); qC.push(c)

                        }

                        if (c > 0 && src[r][c - 1] === targetVal && compId[r][c - 1] < 0) {

                            compId[r][c - 1] = nextId

                            qR.push(r); qC.push(c - 1)

                        }

                        if (c < cols - 1 && src[r][c + 1] === targetVal && compId[r][c + 1] < 0) {

                            compId[r][c + 1] = nextId

                            qR.push(r); qC.push(c + 1)

                        }

                    }



                    sizes[nextId] = size

                    touchesBorder[nextId] = touch

                    nextId++

                }

            }



            return { compId, sizes, touchesBorder }

        }



        function widenThinCorridorsOnce(): boolean {

            const src = copyGrid(map)

            let changed = false



            for (let r = 1; r <= rows - 2; r++) {

                for (let c = 1; c <= cols - 2; c++) {

                    if (src[r][c] !== TILE_EMPTY) continue



                    // Vertical corridor that is 1-tile wide (walls on both sides)

                    if (src[r][c - 1] === TILE_WALL && src[r][c + 1] === TILE_WALL) {

                        const preferLeft = (((r + c) & 1) === 0)

                        const carveC = preferLeft ? (c - 1) : (c + 1)

                        if (carveC > 0 && carveC < cols - 1) {

                            map[r][carveC] = TILE_EMPTY

                            changed = true

                        }

                    }



                    // Horizontal corridor that is 1-tile wide (walls above/below)

                    if (src[r - 1][c] === TILE_WALL && src[r + 1][c] === TILE_WALL) {

                        const preferUp = (((r + c) & 1) === 0)

                        const carveR = preferUp ? (r - 1) : (r + 1)

                        if (carveR > 0 && carveR < rows - 1) {

                            map[carveR][c] = TILE_EMPTY

                            changed = true

                        }

                    }

                }

            }



            return changed

        }



        function fillSmallFloorPockets(): void {

            const src = copyGrid(map)

            const comp = computeComponents4(src, TILE_EMPTY)



            for (let r = 0; r < rows; r++) {

                for (let c = 0; c < cols; c++) {

                    if (src[r][c] !== TILE_EMPTY) continue

                    const id = comp.compId[r][c]

                    if (id < 0) continue

                    if (comp.sizes[id] < MIN_COMPONENT_SIZE && !comp.touchesBorder[id]) {

                        map[r][c] = TILE_WALL

                    }

                }

            }

        }



        function removeSmallWallClusters(): void {

            const src = copyGrid(map)

            const comp = computeComponents4(src, TILE_WALL)



            for (let r = 0; r < rows; r++) {

                for (let c = 0; c < cols; c++) {

                    if (src[r][c] !== TILE_WALL) continue

                    const id = comp.compId[r][c]

                    if (id < 0) continue

                    const size = comp.sizes[id] | 0



                    // Keep true singletons (these render via "decor" slots on the Phaser side).

                    if (size === 1) continue



                    // Enforce >=4 for any non-singleton cluster (don’t touch border clusters).

                    if (size < MIN_COMPONENT_SIZE && !comp.touchesBorder[id]) {

                        map[r][c] = TILE_EMPTY

                    }

                }

            }

        }



        function pruneWallSpursOnce(): boolean {

            const src = copyGrid(map)

            const comp = computeComponents4(src, TILE_WALL)



            let changed = false



            for (let r = 1; r <= rows - 2; r++) {

                for (let c = 1; c <= cols - 2; c++) {

                    if (src[r][c] !== TILE_WALL) continue



                    const id = comp.compId[r][c]

                    if (id < 0) continue

                    const size = comp.sizes[id] | 0



                    // Keep singleton walls (0-neighbor “rocks”).

                    if (size <= 1) continue



                    const n = countCardinalSame(src, r, c, TILE_WALL)

                    if (n < MIN_CARDINAL_WALL_NEI) {

                        map[r][c] = TILE_EMPTY

                        changed = true

                    }

                }

            }



            return changed

        }



        // (A) Widen walkways to avoid 1-tile corridors

        for (let i = 0; i < 3; i++) {

            if (!widenThinCorridorsOnce()) break

        }



        // (B) Remove tiny pockets / blobs (but keep true singleton walls)

        fillSmallFloorPockets()

        removeSmallWallClusters()



        // (C) Prune wall spurs (non-singletons must have >=2 cardinal neighbors)

        for (let i = 0; i < 2; i++) {

            const changed = pruneWallSpursOnce()

            removeSmallWallClusters()

            if (!changed) break

        }



        // Final widen pass (spur pruning can reintroduce narrow spots)

        for (let i = 0; i < 2; i++) {

            if (!widenThinCorridorsOnce()) break

        }

    })()



    if (DEBUG_WORLDGEN_FORCE_ISLAND) _worldgen_forceIsland(map);
    _worldgenBridgePlacements = _worldgen_connectIslandsWithBridges(map);

    if (DEBUG_WORLDGEN_LOGS) {
        console.log(
            ">>> [HeroEngine.worldgen] map size",
            rows,
            "x",
            cols,
            "arena=",
            { topR, bottomR, leftC, rightC }
        )
    }



    return map

}



// ------------------------------------------------------------

// Seed map with random walls / empty

// ------------------------------------------------------------

function _seedRandomMap(rows: number, cols: number, wallChancePercent: number): number[][] {

    const map: number[][] = []

    for (let r = 0; r < rows; r++) {

        const row: number[] = []

        for (let c = 0; c < cols; c++) {

            // Random wall vs empty

            if (randint(0, 99) < wallChancePercent) {

                row.push(TILE_WALL)

            } else {

                row.push(TILE_EMPTY)

            }

        }

        map.push(row)

    }

    return map

}



// ------------------------------------------------------------

// One cellular automata smoothing step

// ------------------------------------------------------------

function _smoothMapStep(oldMap: number[][]): number[][] {

    const rows = oldMap.length

    const cols = oldMap[0].length

    const newMap: number[][] = []



    for (let r = 0; r < rows; r++) {

        const newRow: number[] = []

        for (let c = 0; c < cols; c++) {

            const wallCount = _countWallNeighbors(oldMap, r, c)



            const current = oldMap[r][c]

            let next = current



            // Classic cave-style rules:

            // - If many walls around, this cell tends to become wall

            // - If few walls around, it tends to become empty

            if (current === TILE_WALL) {

                if (wallCount < 4) next = TILE_EMPTY

                else next = TILE_WALL

            } else { // TILE_EMPTY

                if (wallCount > 4) next = TILE_WALL

                else next = TILE_EMPTY

            }



            newRow.push(next)

        }

        newMap.push(newRow)

    }

    return newMap

}



// ------------------------------------------------------------

// Count walls in the 8 neighbors around (r,c).

// Out-of-bounds counts as wall to keep edges closed.

// ------------------------------------------------------------

function _countWallNeighbors(map: number[][], r: number, c: number): number {

    const rows = map.length

    const cols = map[0].length

    let count = 0



    for (let dr = -1; dr <= 1; dr++) {

        for (let dc = -1; dc <= 1; dc++) {

            if (dr === 0 && dc === 0) continue

            const nr = r + dr

            const nc = c + dc



            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {

                // Treat out-of-bounds as wall

                count++

            } else if (map[nr][nc] === TILE_WALL) {

                count++

            }

        }

    }



    return count

}





function _destroyAllInPlace(list: Sprite[]): void {

    for (let i = 0; i < list.length; i++) {

        const s = list[i]

        if (s && !(s.flags & sprites.Flag.Destroyed)) {

            s.destroy()

        }

    }

    list.length = 0

}



function _createDecorColliderImage(w: number, h: number): Image {

    // Invisible colliders still need a real image for width/height in overlap math.

    const img = image.create(w, h)

    img.fill(0)

    return img

}



