    // Weapon display offsets (pixels)

//    HERO_WPN_OFF_X: "wpnOffX",

//    HERO_WPN_OFF_Y: "wpnOffY",



    sprites.setDataNumber(hero, HERO_DATA.HERO_WPN_OFF_X, 0)

    sprites.setDataString(hero, HERO_DATA.HERO_WPN_OFF_Y, 0)



