function _doHeroMoveValidateHookOut(heroIndex: number, button: string, out: any[] | null): out is any[] {

    if (!out || out.length < 7) {

        console.log(

            "[MOVE] heroIndex=" + heroIndex +

            " button=" + button +

            " INVALID OUT=" + (out ? "[" + out.join(",") + "]" : "null")

        )

        // Feedback: play sit when blockly output is missing/invalid so player sees the failure.
        publishHeroSpecialPhase(heroIndex, "sit", SPECIAL_SIT_PHASE_DUR_MS, "SPECIAL_SIT", "_doHeroMoveValidateHookOut")

        return false

    }

    return true

}



function _doHeroMoveParseHookOut(out: any[], button: string): {

    family: number

    t1: number

    t2: number

    t3: number

    t4: number

    element: number

    traits: number[]

    animKey: string

    modeStr: string

} {

    const family = coerceFamily(out[0])



    const t1 = out[1] | 0

    const t2 = out[2] | 0

    const t3 = out[3] | 0

    const t4 = out[4] | 0



    const element = coerceElement(out[5])

    const traits = [0, t1, t2, t3, t4, element]



    const modeRaw = out[6]
    const modeStr = USE_OUT_MODE_STRING ? ((modeRaw == null) ? "" : String(modeRaw)) : ""

    // OUT[6] is reserved for a future mode string; ignore for anim for now.
    const animKey = coerceAnimKey(button)



    return { family, t1, t2, t3, t4, element, traits, animKey, modeStr }

}



