function _doHeroMoveGuardAndLogEarlyReturns(

    playerId: number,

    heroIndex: number,

    hero: Sprite,

    button: string,

    now: number

): boolean {



    if (_doHeroMoveShouldIgnoreDueToBusy(heroIndex, hero, now)) {

        if (_doHeroMoveDbgEnabledForPlayer(playerId)) {

            const busyUntil0 = _heroStateGetNum(heroBusyUntilByProfile, heroIndex, 0)

            const state0 = (sprites.readDataNumber(hero, HERO_DATA.AGI_STATE) | 0)

            const dashUntil0 = (sprites.readDataNumber(hero, HERO_DATA.AGI_DASH_UNTIL) | 0)

            console.log(

                DEBUG_FILTER_PHRASE +

                " IGNORE busyGate timeMs=" + now +

                " button=" + button +

                " heroIndex=" + heroIndex +

                " busyUntil=" + busyUntil0 +

                " agiState=" + state0 +

                " dashUntil=" + dashUntil0

            )

            _doHeroMoveDbgReset(playerId)

        }

        return true

    }



    if (sprites.readDataBoolean(hero, HERO_DATA.IS_CONTROLLING_SPELL)) {

        if (_doHeroMoveDbgEnabledForPlayer(playerId)) {

            console.log(DEBUG_FILTER_PHRASE + " IGNORE controllingSpell timeMs=" + now + " button=" + button + " heroIndex=" + heroIndex)

            _doHeroMoveDbgReset(playerId)

        }

        return true

    }



    if (supportPuzzleActive[heroIndex]) {

        if (_doHeroMoveDbgEnabledForPlayer(playerId)) {

            console.log(DEBUG_FILTER_PHRASE + " IGNORE supportPuzzleActive timeMs=" + now + " button=" + button + " heroIndex=" + heroIndex)

            _doHeroMoveDbgReset(playerId)

        }

        return true

    }



    if (sprites.readDataBoolean(hero, HERO_DATA.STR_CHARGING)) {

        if (_doHeroMoveDbgEnabledForPlayer(playerId)) {

            console.log(DEBUG_FILTER_PHRASE + " IGNORE strCharging timeMs=" + now + " button=" + button + " heroIndex=" + heroIndex)

            _doHeroMoveDbgReset(playerId)

        }

        return true

    }

    const hookState = sprites.readDataNumber(hero, HERO_DATA.AGI_HOOK_STATE) | 0
    if (hookState === AGI_HOOK_STATE.PENDING || hookState === AGI_HOOK_STATE.AIMING || hookState === AGI_HOOK_STATE.EXTEND || hookState === AGI_HOOK_STATE.RETRACT || hookState === AGI_HOOK_STATE.RECOVER) {
        if (_doHeroMoveDbgEnabledForPlayer(playerId)) {
            console.log(DEBUG_FILTER_PHRASE + " IGNORE agiHook timeMs=" + now + " button=" + button + " heroIndex=" + heroIndex + " hookState=" + hookState)
            _doHeroMoveDbgReset(playerId)
        }
        return true
    }



    return false

}



function _doHeroMoveTryGetParsedHookOutOrNull(

    playerId: number,

    heroIndex: number,

    button: string,

    now: number

): {

    family: number

    t1: number

    t2: number

    t3: number

    t4: number

    element: number

    traits: number[]

    animKey: string

    modeStr: string

} | null {



    const out = _doHeroMoveCallLogicHook(heroIndex, button)

    if (!out) {
        // Invalid/missing blockly output: play sit feedback instead of falling through to defaults.
        publishHeroSpecialPhase(heroIndex, "sit", SPECIAL_SIT_PHASE_DUR_MS, "SPECIAL_SIT", "doHeroMoveForPlayer.logicNull")
        _towerTrialRecordMove(heroIndex, button, null, now)

        if (_doHeroMoveDbgEnabledForPlayer(playerId)) {

            console.log(DEBUG_FILTER_PHRASE + " IGNORE hookNull timeMs=" + now + " button=" + button + " heroIndex=" + heroIndex)

            _doHeroMoveDbgReset(playerId)

        }

        return null

    }



    if (!_doHeroMoveValidateHookOut(heroIndex, button, out)) {
        // Invalid blockly output (or defaulted fields): play sit feedback and stop.
        publishHeroSpecialPhase(heroIndex, "sit", SPECIAL_SIT_PHASE_DUR_MS, "SPECIAL_SIT", "doHeroMoveForPlayer.invalidOut")
        _towerTrialRecordMove(heroIndex, button, null, now)

        if (_doHeroMoveDbgEnabledForPlayer(playerId)) {

            console.log(DEBUG_FILTER_PHRASE + " IGNORE invalidOut timeMs=" + now + " button=" + button + " heroIndex=" + heroIndex)

            _doHeroMoveDbgReset(playerId)

        }

        return null

    }



    // Sentinel array from host/Blockly indicating "invalid move; show sit".
    const isInvalidSentinel =
        typeof out[0] === "number" && (out[0] | 0) < 0 &&
        typeof out[5] === "number" && (out[5] | 0) < 0 &&
        typeof out[6] === "string" && out[6].trim().toLowerCase() === "invalid";
    if (isInvalidSentinel) {
        publishHeroSpecialPhase(heroIndex, "sit", SPECIAL_SIT_PHASE_DUR_MS, "SPECIAL_SIT", "doHeroMoveForPlayer.invalidSentinel");
        console.log(DEBUG_FILTER_PHRASE + " INVALID_SENTINEL timeMs=" + now + " button=" + button + " heroIndex=" + heroIndex);
        _doHeroMoveDbgReset(playerId);
        _towerTrialRecordMove(heroIndex, button, null, now);
        return null;
    }


    const parsed = _doHeroMoveParseHookOut(out, button)
    _towerTrialRecordMove(heroIndex, button, parsed, now)



    if (_doHeroMoveDbgEnabledForPlayer(playerId)) {

        console.log(

            DEBUG_FILTER_PHRASE +

            " OUT timeMs=" + now +

            " button=" + button +

            " family=" + parsed.family +

            " t1=" + parsed.t1 +

            " t2=" + parsed.t2 +

            " t3=" + parsed.t3 +

            " t4=" + parsed.t4 +

            " elem=" + (parsed.element | 0) +

            " animKey=" + parsed.animKey

        )

    }



    return parsed

}



