function doHeroMoveForPlayer(playerId: number, button: string) {



    const heroIndex = _doHeroMoveResolveHeroIndexSpawnOnDemand(playerId)



    const hero = _doHeroMoveTryGetHeroOrLogAndReturnNull(playerId, button, heroIndex)

    if (!hero) return



    const now = game.runtime()

    worldRuntimeMs = now



    _doHeroMoveDbgLogEnter(playerId, heroIndex, hero, button, now)



    // ------------------------------------------------------------

    // STEP 3: UI MODE / EXCLUSIVE INPUT (no UI rendering yet)

    // - A+B toggles level-up UI (only if safe AND has points)

    // - While uiMode != NONE, consume A/B intents and do not execute moves

    // ------------------------------------------------------------

    const uiMode0 = (sprites.readDataNumber(hero, HERO_UI_DATA.MODE) | 0)




    // If UI is open, consume A/B so we never fire moves while the DOM menu is up later

    if (uiMode0 !== HERO_UI_MODE.NONE) {

        if (button === "B") {

            _uiCloseAnyUi(heroIndex, playerId, "intent:B")

            _doHeroMoveDbgReset(playerId)

            return

        }



        if (button === "A") {

            if (uiMode0 === HERO_UI_MODE.LEVELUP) {

                const sel = _uiReadNum(hero, HERO_UI_DATA.SEL, 0) | 0

                const key = String(LVLUI_MENU_KEYS[sel] || "")



                if (key === "close") {

                    _uiCloseAnyUi(heroIndex, playerId, "intent:A")

                    _doHeroMoveDbgReset(playerId)

                    return

                }



                const safe = _uiGetSafeForSpend(heroIndex)

                if (!safe.ok) {

                    console.log("[LVLUI] spend denied (not safe)", { pid: playerId, hi: heroIndex, reason: safe.reason })

                    _doHeroMoveDbgReset(playerId)

                    return

                }



                const now2 = game.runtime() | 0

                const busyUntil = _uiReadNum(hero, HERO_DATA.BUSY_UNTIL, 0) | 0

                if (busyUntil > 0 && now2 < busyUntil) {

                    console.log("[LVLUI] spend denied (busy)", { pid: playerId, hi: heroIndex, now: now2, busyUntil })

                    _doHeroMoveDbgReset(playerId)

                    return

                }



                const locked = sprites.readDataBoolean(hero, HERO_DATA.INPUT_LOCKED)

                if (locked) {

                    console.log("[LVLUI] spend denied (locked)", { pid: playerId, hi: heroIndex })

                    _doHeroMoveDbgReset(playerId)

                    return

                }



                const ptsBefore = getHeroUnspentLevelPts(heroIndex) | 0

                if (ptsBefore <= 0) {

                    console.log("[LVLUI] spend denied (no pts)", { pid: playerId, hi: heroIndex })

                    _doHeroMoveDbgReset(playerId)

                    return

                }



                const ok = trySpendLevelUpPointOnCore(heroIndex, key)

                console.log("[LVLUI] spendCore(intent)", { pid: playerId, hi: heroIndex, ok, key, sel })

                _doHeroMoveDbgReset(playerId)

                return

            }



            if (uiMode0 === HERO_UI_MODE.SHOP) {

                const r = _uiShopTryBuySelected(heroIndex, playerId, "intent:A")

                if (!r.ok) {

                    logShop("[SHOP][UI_BUY] denied", { pid: playerId, hi: heroIndex, reason: r.reason })

                }

                _doHeroMoveDbgReset(playerId)

                return

            }

        }



        if (DEBUG_UI_LOGS) {
            console.log("[UI] blocked intent (ui open)", { pid: playerId, hi: heroIndex, button })
        }

        _doHeroMoveDbgReset(playerId)

        return

    }



    // ------------------------------------------------------------

    // NORMAL MOVE PIPELINE (unchanged)

    // ------------------------------------------------------------

    if (_doHeroMoveGuardAndLogEarlyReturns(playerId, heroIndex, hero, button, now)) {

        return

    }



    const parsed = _doHeroMoveTryGetParsedHookOutOrNull(playerId, heroIndex, button, now)

    if (!parsed) {

        return

    }



    const family = parsed.family

    const t1 = parsed.t1

    const t2 = parsed.t2

    const t3 = parsed.t3

    const t4 = parsed.t4

    const element = parsed.element

    const traits = parsed.traits

    const animKey = parsed.animKey
    const modeStr = parsed.modeStr



    _doHeroMoveApplyBaseHeroMoveData(hero, family, button, t1, t2, t3, t4)
    sprites.setDataString(hero, HERO_DATA.MOVE_MODE_STR, modeStr || "")



    const agi = _doHeroMoveUpdateAgilityComboState(heroIndex, hero, now, family)

    _doHeroMoveDbgLogAgiState(playerId, heroIndex, hero, now, agi)



    const traitsEff0 = applyDamageModsToTraits(heroIndex, family, traits)

    const traitsFinal = applyLevelUpBonusesToTraits(heroIndex, family, traitsEff0)



    const stats0 = calculateMoveStatsForFamily(family, button, traitsFinal)

    const stats = applyRelicModsToStats(heroIndex, family, button, traitsFinal, stats0)



    if (!_doHeroMoveTrySpendMana(heroIndex, hero, family, t1, t2, t3, t4)) {

        _doHeroMoveDbgLogNoManaAndReset(playerId, heroIndex, button, now, family)

        return

    }



    // Strength: execute after mana spend (skip AGI execute logic)
    if (family === FAMILY.STRENGTH) {

        // RELIC HOOK: move committed
        try {
            const ctx: RelicMoveCommittedContext = {
                now: now | 0,
                hi: heroIndex | 0,
                hero,
                family: family | 0,
                button,
            }
            relic_onMoveCommitted(ctx)
            _dunShrineOnMoveCommitted(ctx)
        } catch { }

        executeStrengthMove(heroIndex, hero, button, traitsFinal, stats, animKey)
        _doHeroMoveDbgReset(playerId)
        return
    }



    if (_doHeroMoveTryAgilityExecuteThisPress(

        heroIndex,

        hero,

        family,

        button,

        t1,

        t2,

        t3,

        t4,

        element | 0,

        stats,

        animKey,

        agi.agiDoExecuteThisPress,

        now

    )) {

        // RELIC HOOK: move committed

        try {

            const ctx: RelicMoveCommittedContext = {

                now: now | 0,

                hi: heroIndex | 0,

                hero,

                family: family | 0,

                button,

            }

            relic_onMoveCommitted(ctx)
            _dunShrineOnMoveCommitted(ctx)

        } catch { }



        _doHeroMoveDbgLogPathAndReset(

            playerId,

            DEBUG_FILTER_PHRASE + " PATH execute timeMs=" + now + " button=" + button + " heroIndex=" + heroIndex

        )

        return

    }



    if (_doHeroMoveTryAgilityBuildAfterLanding(

        heroIndex,

        hero,

        now,

        family,

        t1,

        animKey,

        agi.agiChainAfter,

        agi.agiZoneMult,

        agi.agiIsArmedThisPress

    )) {

        _doHeroMoveDbgLogPathAndReset(

            playerId,

            DEBUG_FILTER_PHRASE + " PATH build timeMs=" + now + " button=" + button + " heroIndex=" + heroIndex

        )

        return

    }



    _doHeroMoveBeginActionTimeline(heroIndex, hero, family, button, t1, t2, t3, t4, element | 0, now)



    // RELIC HOOK: move committed (generic path)

    try {

        const ctx: RelicMoveCommittedContext = {

            now: now | 0,

            hi: heroIndex | 0,

            hero,

            family: family | 0,

            button,

        }

        relic_onMoveCommitted(ctx)
        _dunShrineOnMoveCommitted(ctx)

    } catch { }



    const mv = _doHeroMoveApplyMovementScheduleAndVelocity(heroIndex, hero, family, now, stats)



    const moveDuration = mv.moveDuration | 0



    _doHeroMoveSetPhaseFromFamily(heroIndex, family)

    _doHeroMoveApplyControlLockAndBusy(heroIndex, hero, family, now, moveDuration)

    _doHeroMoveApplyAgilityDashTimers(heroIndex, hero, family, now, moveDuration, stats)



    if (family === FAMILY.AGILITY) {

        const btnId = encodeIntentToStrBtnId(button) | 0

        sprites.setDataNumber(hero, HERO_DATA.AGI_COMBO_LAST_AGI_BTN, btnId)



        const comboMode0 = sprites.readDataNumber(hero, HERO_DATA.AGI_COMBO_MODE) | 0

        if (!comboMode0) {

            if (AGI_ENABLE_EXECUTE_ENTRY_FROM_HOLD) {
                const dashUntilNew = sprites.readDataNumber(hero, HERO_DATA.AGI_DASH_UNTIL) | 0

                if (dashUntilNew > 0) {

                    sprites.setDataNumber(hero, HERO_DATA.AGI_COMBO_ENTRY_BTN, btnId)

                    sprites.setDataNumber(hero, HERO_DATA.AGI_COMBO_ENTRY_DASH_UNTIL, dashUntilNew)

                }
            } else {
                sprites.setDataNumber(hero, HERO_DATA.AGI_COMBO_ENTRY_BTN, 0)
                sprites.setDataNumber(hero, HERO_DATA.AGI_COMBO_ENTRY_DASH_UNTIL, 0)
            }

        }

    }



    _doHeroMoveDbgLogDashPath(playerId, heroIndex, hero, button, now, family, moveDuration, mv.lungeCapped | 0)



    _doHeroMovePlayAnimAndDispatch(heroIndex, hero, family, button, traitsFinal, stats, animKey, now, t3)



    _doHeroMoveDbgReset(playerId)

}







