function updateHeroOverlays() {

    const now = game.runtime() | 0

    // NEW (v4): publish weapon-as-meter contract keys (engine-side authoritative data)

    updateAgiChargeV4PublishedKeys(now)



    updateHeroAuras(now)

    updateHeroAimIndicators(now)
    updateHeroAgilityChargeFx(now)

    updateHeroMeters(now)

    updateHeroManaBlessIndicators(now)
    updateShrineBlessingHud(now)

    updateShopUi(now)   // <-- ADD THIS



}









function updateHeroAimIndicators(now: number) {
    if (AGI_DISABLE_LEGACY_AGI_TRAIL_FX) {
        for (let i = 0; i < heroes.length; i++) {
            const hero = heroes[i];
            if (!hero) continue;
            destroyAgiAimIndicator(i);
        }
        return;
    }

    for (let i = 0; i < heroes.length; i++) {

        const hero = heroes[i]; if (!hero) continue



        const ind = ensureAgiAimIndicator(i)

        if (!ind) continue

        const hookState = sprites.readDataNumber(hero, HERO_DATA.AGI_HOOK_STATE) | 0
        const disableIndicator = AGI_DISABLE_LEGACY_AGI_TRAIL_FX || hookState !== AGI_HOOK_STATE.NONE



        // Show only in Agility ARMED state after landing (not during dash)

        const agiState = sprites.readDataNumber(hero, HERO_DATA.AGI_STATE) | 0

        const dashUntil = sprites.readDataNumber(hero, HERO_DATA.AGI_DASH_UNTIL) | 0



        const show = (agiState === AGI_STATE.ARMED) && (dashUntil === 0 || now >= dashUntil)



        setAgiAimIndicatorVisible(i, show && !disableIndicator)

        if (hookState !== AGI_HOOK_STATE.NONE) {
            continue
        }

        _dbgAgiAimLog(i, now, "state=" + agiState + " dashUntil=" + dashUntil + " show=" + (show ? 1 : 0))



        const aim = computeHeroAimForIndicator(i, hero)

        // Publish aim to hero data so weapon overlays can rotate on diagonals.
        sprites.setDataNumber(hero, HERO_DATA.AIM_DIR_X1000, aim.dx1000 | 0)
        sprites.setDataNumber(hero, HERO_DATA.AIM_DIR_Y1000, aim.dy1000 | 0)
        sprites.setDataNumber(hero, HERO_DATA.AIM_ANGLE_MDEG, aim.angleMdeg | 0)

        if (!show || disableIndicator) continue



        // Publish direction

        sprites.setDataNumber(ind, UI_AIM_DIR_X1000_KEY, aim.dx1000 | 0)

        sprites.setDataNumber(ind, UI_AIM_DIR_Y1000_KEY, aim.dy1000 | 0)



        // ------------------------------------------------------------

        // Leading edge distance: MUST be silhouette/oval-based in Phaser

        // Use the same hook-backed visual info pipeline as Strength.

        // ------------------------------------------------------------

        let edgeDist = 0

        let edgeSrc = "none"



        {

            const vis = getHeroVisualInfoForStrength(hero, aim.nx, aim.ny)

            if (vis && vis.length > 1) {

                edgeDist = (vis[1] | 0) // leadEdge

                if (edgeDist > 0) edgeSrc = "visHook"

            }

        }



        // Size fallback if hook fails

        if (edgeDist <= 0) {

            edgeDist = findHeroLeadingEdgeDistance(hero, aim.nx, aim.ny) | 0
            if (edgeDist > 0) edgeSrc = "size"

        }



        // Final safety fallback: push to ~half-width

        if (edgeDist <= 0) {

            edgeDist = ((hero.width | 0) > 0) ? ((hero.width | 0) >> 1) : 16

            edgeSrc = "halfW"

        }



        // Side tuning

        const absNx = Math.abs(aim.nx)

        const sideWeight = absNx * absNx

        edgeDist = Math.max(0, edgeDist - Math.round(AGI_AIM_SIDE_EDGE_SHRINK_PX * sideWeight))

        const inset = Math.round(AGI_AIM_SIDE_INSET_PX * sideWeight)



        const tailDx = Math.round(aim.nx * Math.max(0, edgeDist - inset))

        const tailDy = Math.round(aim.ny * Math.max(0, edgeDist))



        // Stretch + shake while holding cancel

        let len = AGI_AIM_INDICATOR_LEN

        const cancelHoldMs = sprites.readDataNumber(hero, HERO_DATA.AGI_CANCEL_HOLD_MS) | 0

        if (cancelHoldMs > 0) {

            const t = Math.max(0, Math.min(1, cancelHoldMs / AGI_CANCEL_HOLD_THRESHOLD_MS))

            len += Math.round(AGI_BREAK_STRETCH_PX * t)



            const amp = Math.round(AGI_BREAK_SHAKE_PX * t)

            if (amp > 0) {

                const phase = now * 0.05

                const j = Math.round(Math.sin(phase) * amp)

                const px = -aim.ny

                const py = aim.nx

                ind.x = hero.x + tailDx + AGI_AIM_INDICATOR_OX + Math.round(px * j)

                ind.y = hero.y + tailDy + AGI_AIM_INDICATOR_OY + Math.round(py * j)

            } else {

                ind.x = hero.x + tailDx + AGI_AIM_INDICATOR_OX

                ind.y = hero.y + tailDy + AGI_AIM_INDICATOR_OY

            }

        } else {

            ind.x = hero.x + tailDx + AGI_AIM_INDICATOR_OX

            ind.y = hero.y + tailDy + AGI_AIM_INDICATOR_OY

        }



        // Safety: NaN guard (this is the “disappears silently” killer)

        if (!isFinite(ind.x as any) || !isFinite(ind.y as any)) {

            _dbgAgiAimLog(i, now,

                "ERROR NaN pos: ind=(" + ind.x + "," + ind.y + ") hero=(" + hero.x + "," + hero.y + ") nx=" + aim.nx + " ny=" + aim.ny + " edgeDist=" + edgeDist + " src=" + edgeSrc

            )

            ind.x = hero.x

            ind.y = hero.y

        }



        sprites.setDataNumber(ind, UI_AIM_LEN_KEY, len | 0)



        // Angle for phaser arrow if needed

        const ang = Math.atan2(aim.ny, aim.nx)

        sprites.setDataNumber(ind, UI_AIM_ANGLE_MDEG_KEY, Math.round(ang * 180000 / Math.PI))



        _dbgAgiAimLog(

            i,

            now,

            "visKey=" + (sprites.readDataNumber(ind, UI_AIM_VISIBLE_KEY) | 0) +

            " dir=(" + (sprites.readDataNumber(ind, UI_AIM_DIR_X1000_KEY) | 0) + "," + (sprites.readDataNumber(ind, UI_AIM_DIR_Y1000_KEY) | 0) + ")" +

            " len=" + (sprites.readDataNumber(ind, UI_AIM_LEN_KEY) | 0) +

            " pos=(" + ind.x + "," + ind.y + ")" +

            " edgeDist=" + edgeDist +

            " src=" + edgeSrc

        )

    }

}

function updateHeroAgilityChargeFx(now: number): void {
    for (let i = 0; i < heroes.length; i++) {
        const hero = heroes[i]; if (!hero) continue;

        const agiState = sprites.readDataNumber(hero, HERO_DATA.AGI_STATE) | 0;
        const dashUntil = sprites.readDataNumber(hero, HERO_DATA.AGI_DASH_UNTIL) | 0;
        const chargeActive =
            ((agiState === AGI_STATE.ARMED) && (dashUntil === 0 || now >= dashUntil)) ||
            (agiState === AGI_STATE.EXECUTING);

        let fx = sprites.readDataSprite(hero, AGI_CHARGE_FX_KEY);
        let spear = sprites.readDataSprite(hero, AGI_CHARGE_SPEAR_KEY);
        if (AGI_DISABLE_LEGACY_AGI_TRAIL_FX) {
            if (fx && !(fx.flags & sprites.Flag.Destroyed)) fx.destroy();
            sprites.setDataSprite(hero, AGI_CHARGE_FX_KEY, null as any);
            if (spear && !(spear.flags & sprites.Flag.Destroyed)) spear.destroy();
            sprites.setDataSprite(hero, AGI_CHARGE_SPEAR_KEY, null as any);
            continue;
        }
        if (!chargeActive) {
            if (fx && !(fx.flags & sprites.Flag.Destroyed)) fx.destroy();
            sprites.setDataSprite(hero, AGI_CHARGE_FX_KEY, null as any);
            if (spear && !(spear.flags & sprites.Flag.Destroyed)) spear.destroy();
            sprites.setDataSprite(hero, AGI_CHARGE_SPEAR_KEY, null as any);
            continue;
        }

        const aim = computeHeroAimForIndicator(i, hero);
        const thrustOff = _agiThrustOffsets(aim.nx, aim.ny);
        if (!fx || (fx.flags & sprites.Flag.Destroyed)) {
            const bodyFx = _spawnHeroBodyPaintFxForMove(i, hero, FAMILY.AGILITY, 0, aim.nx, aim.ny, 0, "agilityCharge");
            if (bodyFx) {
                sprites.setDataSprite(hero, AGI_CHARGE_FX_KEY, bodyFx);
                fx = bodyFx;
            }
        }

        if (!fx || (fx.flags & sprites.Flag.Destroyed)) continue;
        fx.x = hero.x;
        fx.y = hero.y;
        fx.z = (hero.z | 0) + (_heroBodyFxZBiasForFamily(FAMILY.AGILITY) | 0);
        _strengthFxUpdateDir(fx, _enemyDirFromVector(aim.nx, aim.ny));

        if (!spear || (spear.flags & sprites.Flag.Destroyed)) {
            const img = image.create(2, 2);
            img.fill(0);
            const s = sprites.create(img, SpriteKind.HeroWeapon);
            s.setFlag(SpriteFlag.Ghost, true);
            s.setFlag(SpriteFlag.Invisible, false);
            sprites.setDataNumber(s, PROJ_DATA.FAMILY, FAMILY.AGILITY | 0);
            sprites.setDataSprite(hero, AGI_CHARGE_SPEAR_KEY, s);
            spear = s;
        }

        if (!spear || (spear.flags & sprites.Flag.Destroyed)) continue;

        let attachPx = 0;
        {
            const vis = getHeroVisualInfoForStrength(hero, aim.nx, aim.ny);
            const wTipX = (vis[2] || 0);
            const wTipY = (vis[3] || 0);
            const wTipProj = (wTipX * aim.nx) + (wTipY * aim.ny);
            if (wTipProj > 0) attachPx = wTipProj;
            if (attachPx <= 0) attachPx = (vis[1] || 0);
        }
        if (attachPx <= 0) attachPx = findHeroLeadingEdgeDistance(hero, aim.nx, aim.ny);
        if (attachPx <= 0) {
            attachPx = 0.5 * (Math.abs(aim.nx) * hero.width + Math.abs(aim.ny) * hero.height);
        }

        let len = sprites.readDataNumber(hero, "AGI_L_EXEC") | 0;
        if (len <= 0) len = AGI_AIM_INDICATOR_LEN | 0;
        if (AGI_DEBUG_HUGE_TRAIL && len < AGI_DEBUG_CHARGE_LEN_PX) len = AGI_DEBUG_CHARGE_LEN_PX | 0;
        if (len < AGI_MIN_VISUAL_LEN) len = AGI_MIN_VISUAL_LEN | 0;

        const backLen = Math.max(0, Math.round(attachPx * AGI_TRAIL_BACK_PCT_X1000 / 1000));
        const sBack = -backLen;
        let sFront = attachPx + len;
        if (sFront <= sBack + 4) sFront = sBack + 4;

        const anchorOffX = thrustOff.ox;
        const anchorOffY = thrustOff.oy;
        const trail = _buildAgilityTrailImage(sBack, sFront, aim.nx, aim.ny, anchorOffX, anchorOffY);

        spear.setImage(trail.img);
        spear.vx = 0;
        spear.vy = 0;
        spear.x = hero.x + (trail.bounds.minX + trail.bounds.maxX) / 2;
        spear.y = hero.y + (trail.bounds.minY + trail.bounds.maxY) / 2;
        spear.z = hero.z + 12;
    }
}











function updateHeroMeters(now: number) {

    for (let i = 0; i < heroes.length; i++) {

        const hero = heroes[i]; if (!hero) continue



        // Charge relevance (same rule as before: ARMED + landed)

        const agiState = sprites.readDataNumber(hero, HERO_DATA.AGI_STATE) | 0

        const dashUntil = sprites.readDataNumber(hero, HERO_DATA.AGI_DASH_UNTIL) | 0

        const chargeRelevant = (agiState === AGI_STATE.ARMED) && (dashUntil === 0 || now >= dashUntil)



        const meter = _getHeroComboMeter(i)

        const counter = _getHeroAgiStoredCounter(i)



        // Stored hits: prefer v4 key if present, fallback to packet count

        let storedHits = sprites.readDataNumber(hero, HERO_DATA.AGI_STORED_HITS) | 0

        if (!storedHits && storedHits !== 0) storedHits = 0

        if ((storedHits | 0) === 0) {

            storedHits = sprites.readDataNumber(hero, HERO_DATA.AGI_PKT_COUNT) | 0

        }



        if (meter) {
            meter.setFlag(SpriteFlag.Invisible, true)
            sprites.setDataNumber(meter, UI_COMBO_VISIBLE_KEY, 0)
        }



        // ------------------------------------------------------------

        // Stored-hits counter: separate, above the hero’s head.

        // Show if there are stored hits OR charge is relevant.

        // ------------------------------------------------------------

        const showCounter = ((storedHits | 0) > 0) || chargeRelevant



        if (!showCounter) {

            if (counter) counter.setFlag(SpriteFlag.Invisible, true)

            continue

        }



        const tSprite = ensureAgiStoredCounter(i)

        if (tSprite) {

            ;(tSprite as any).setText("" + (storedHits | 0))

            tSprite.setFlag(SpriteFlag.Invisible, false)



            // Above head (near HP/mana area)

            tSprite.z = hero.z + 10

            tSprite.x = hero.x + 18

            tSprite.y = hero.y - (hero.height >> 1) - 10

        }

    }

}







const SHOW_MANA_REGEN_FLOATING_TEXT = false

function updateHeroManaBlessIndicators(now: number): void {
    if (!SHOW_MANA_REGEN_FLOATING_TEXT) {
        for (let i = 0; i < heroes.length; i++) {
            const t = _getHeroManaBlessIndicator(i)
            if (t) t.setFlag(SpriteFlag.Invisible, true)
        }
        return
    }
    const shrineActive =
        ((_dunShrineBlessingFloor | 0) === (_dunFloorIndex | 0)) &&
        ((_dunShrineBlessingUntilMs | 0) > (now | 0))

    const doDbg = DEBUG_TRAP_LOGS && ((now | 0) >= (manaBlessHudDebugNextMs | 0))
    if (doDbg) manaBlessHudDebugNextMs = (now + 1000) | 0

    for (let i = 0; i < heroes.length; i++) {
        const hero = heroes[i]; if (!hero) continue

        if (_isShopActor(hero)) {
            const t = _getHeroManaBlessIndicator(i)
            if (t) t.setFlag(SpriteFlag.Invisible, true)
            continue
        }

        const t = ensureHeroManaBlessIndicator(i)
        if (!t) continue
        t.setFlag(SpriteFlag.Invisible, false)
        t.z = (((hero.y | 0) * 100) + 5000) | 0
        t.x = hero.x - 18
        t.y = hero.y - (hero.height >> 1) - 14

        const regenPerSec = Math.max(0, _getHeroManaRegenPerSec(i) | 0)
        const label = "+" + regenPerSec + "/s"
        const nextFg = shrineActive ? AURA_COLOR_HEAL : 9
        const tAny = t as any
        let dirty = false
        if (tAny.text !== label) { tAny.text = label; dirty = true }
        if (tAny.fg !== nextFg) { tAny.fg = nextFg; dirty = true }
        if (dirty && typeof tAny.update === "function") tAny.update()

        if (shrineActive && i === 0) {
            _shrineObsMark(
                _dunShrineBlessingKey,
                _dunFloorIndex | 0,
                "blessing_active",
                true,
                `until=${_dunShrineBlessingUntilMs | 0} floor=${_dunFloorIndex | 0}`,
                now | 0
            )
            _shrineObsMark(
                _dunShrineBlessingKey,
                _dunFloorIndex | 0,
                "hud_indicator",
                true,
                `hero=${i | 0} regenPerSec=${regenPerSec | 0}`,
                now | 0
            )
        }

        if (doDbg && i === 0) {
            console.log("[SHRINE][HUD] mana", {
                hi: i | 0,
                regenPerSec: regenPerSec | 0,
                shrineActive: shrineActive ? 1 : 0,
                hasIndicator: !!t,
                flags: t ? (t.flags | 0) : -1,
                txt: sprites.readDataString(t, "__txt") || "",
                uiKind: sprites.readDataString(t, "__uiKind") || "",
            })
        }
    }
}

function ensureShrineBlessingHud(): Sprite {
    if (shrineBlessHud && !(shrineBlessHud.flags & sprites.Flag.Destroyed)) return shrineBlessHud
    const t = textsprite.create("BLESSING IS ACTIVE!!!!!!!!!!!!!", 0, AURA_COLOR_HEAL)
    t.setMaxFontHeight(10)
    t.setOutline(1, 15)
    t.setFlag(SpriteFlag.RelativeToCamera, true)
    t.z = 9999999
    shrineBlessHud = t
    shrineBlessHudDebugSeq = (shrineBlessHudDebugSeq + 1) | 0
    if (DEBUG_TRAP_LOGS) {
        console.log("[SHRINE][HUD] created", {
            seq: shrineBlessHudDebugSeq | 0,
            id: (t as any).id | 0,
            flags: t.flags | 0,
            uiKind: sprites.readDataString(t, "__uiKind") || "",
            txt: sprites.readDataString(t, "__txt") || "",
        })
    }
    return t
}

function updateShrineBlessingHud(now: number): void {
    const shrineActive =
        ((_dunShrineBlessingFloor | 0) === (_dunFloorIndex | 0)) &&
        ((_dunShrineBlessingUntilMs | 0) > (now | 0))

    const doDbg = DEBUG_TRAP_LOGS && ((now | 0) >= (shrineBlessHudDebugNextMs | 0))
    if (doDbg) shrineBlessHudDebugNextMs = (now + 1000) | 0

    if (!shrineActive) {
        if (shrineBlessHud) shrineBlessHud.setFlag(SpriteFlag.Invisible, true)
        if (shrineBlessHudWasActive) {
            shrineBlessHudWasActive = 0
            if (DEBUG_TRAP_LOGS) console.log("[SHRINE][HUD] inactive")
        }
        if (doDbg) {
            console.log("[SHRINE][HUD] tick", {
                active: 0,
                floor: _dunFloorIndex | 0,
                until: _dunShrineBlessingUntilMs | 0,
                hasHud: !!shrineBlessHud,
                wasActive: shrineBlessHudWasActive | 0,
            })
        }
        return
    }

    const t = ensureShrineBlessingHud()
    if (!t) return
    t.setFlag(SpriteFlag.Invisible, true)
    t.z = 9999999
    const w = scene.screenWidth() | 0
    t.x = Math.idiv(w, 2)
    t.y = 12
    if (doDbg) {
        const tAny = t as any
        let nativeInfo: any = null
        try {
            const n = tAny.native
            nativeInfo = n ? {
                hasNative: true,
                visible: !!n.visible,
                alpha: (n.alpha ?? null),
                depth: (n.depth ?? null),
                uiKind: (n.getData && n.getData("uiKind")) || "",
            } : { hasNative: false }
        } catch { nativeInfo = { hasNative: false } }
        console.log("[SHRINE][HUD] tick", {
            active: 1,
            floor: _dunFloorIndex | 0,
            until: _dunShrineBlessingUntilMs | 0,
            hasHud: !!t,
            wasActive: shrineBlessHudWasActive | 0,
        })
        console.log("[SHRINE][HUD] sprite", {
            id: (tAny.id | 0),
            x: t.x | 0,
            y: t.y | 0,
            z: t.z | 0,
            flags: t.flags | 0,
            uiKind: sprites.readDataString(t, "__uiKind") || "",
            txt: sprites.readDataString(t, "__txt") || "",
            native: nativeInfo,
        })
    }
    if (!shrineBlessHudWasActive) {
        shrineBlessHudWasActive = 1
        if (DEBUG_TRAP_LOGS) {
            console.log("[SHRINE][HUD] active", {
                floor: _dunFloorIndex | 0,
                until: _dunShrineBlessingUntilMs | 0,
            })
        }
        if (DEBUG_TRAP_LOGS) {
            const tAny = t as any
            let nativeInfo: any = null
            try {
                const n = tAny.native
                nativeInfo = n ? {
                    hasNative: true,
                    visible: !!n.visible,
                    alpha: (n.alpha ?? null),
                    depth: (n.depth ?? null),
                    uiKind: (n.getData && n.getData("uiKind")) || "",
                } : { hasNative: false }
            } catch { nativeInfo = { hasNative: false } }
            console.log("[SHRINE][HUD] sprite", {
                id: (tAny.id | 0),
                x: t.x | 0,
                y: t.y | 0,
                z: t.z | 0,
                flags: t.flags | 0,
                uiKind: sprites.readDataString(t, "__uiKind") || "",
                txt: sprites.readDataString(t, "__txt") || "",
                native: nativeInfo,
            })
        }
    }
}

function updateHeroAuras(now: number) {

    for (let i = 0; i < heroes.length; i++) {

        const hero = heroes[i]; if (!hero) continue



        let showAura = false

        let color = 0

        let auraGlow = 0
        let auraRadius = AURA_RADIUS_NEUTRAL
        const glowUntil = _heroStateGetNum(heroHealGlowUntilByProfile, i, 0)
        if (glowUntil > 0 && now < glowUntil) auraGlow = 1

        const family = sprites.readDataNumber(hero, HERO_DATA.FAMILY)

        const isStatue = _shopIsStatueHero(hero)

        if (family == FAMILY.STRENGTH) auraRadius = AURA_RADIUS_STRENGTH
        else if (family == FAMILY.AGILITY) auraRadius = AURA_RADIUS_AGILITY
        else if (family == FAMILY.INTELLECT) auraRadius = AURA_RADIUS_INTELLECT
        else if (family == FAMILY.HEAL) auraRadius = AURA_RADIUS_HEAL



        if (isStatue) {
            auraRadius = AURA_RADIUS_NEUTRAL

            if (DUNGEON_MODE_ACTIVE && _dunFloorKind === DUNGEON_KIND_SHOP) {

                if (_shopIsStatueFocused(hero, now)) {

                    showAura = true

                    color = AURA_COLOR_WHITE

                    auraGlow = 1

                }

            }

        } else {

            // Strength aura

            const strCharging = sprites.readDataBoolean(hero, HERO_DATA.STR_CHARGING)

            if (family == FAMILY.STRENGTH && (strCharging || (_heroStateGetNum(heroBusyUntilByProfile, i, 0) > now))) {

                showAura = true

                color = AURA_COLOR_STRENGTH

            }



            // Agility aura

            if (family == FAMILY.AGILITY) {

                const dashUntil0 = sprites.readDataNumber(hero, HERO_DATA.AGI_DASH_UNTIL)

                if (dashUntil0 > now) { showAura = true; color = AURA_COLOR_AGILITY }

            }



            // Intellect / Heal aura

            if (family == FAMILY.INTELLECT && sprites.readDataBoolean(hero, HERO_DATA.IS_CONTROLLING_SPELL)) {

                showAura = true

                color = AURA_COLOR_INTELLECT

            }

            if (family == FAMILY.HEAL && sprites.readDataBoolean(hero, HERO_DATA.IS_CONTROLLING_SPELL)) {

                showAura = true

                color = AURA_COLOR_HEAL

            }

            // Wisdom/support puzzle: keep heal aura on while puzzle UI is active (self-cast guaranteed)
            if (supportPuzzleActive && supportPuzzleActive[i]) {
                showAura = true;
                color = AURA_COLOR_HEAL;
                auraRadius = AURA_RADIUS_HEAL
            }

        }



        if (auraGlow && !showAura) {
            showAura = true
            if (!color) color = AURA_COLOR_HEAL
            auraRadius = AURA_RADIUS_HEAL
        }

        sprites.setDataBoolean(hero, HERO_DATA.AURA_ACTIVE, showAura)
        sprites.setDataNumber(hero, HERO_DATA.AURA_COLOR, color)
        sprites.setDataNumber(hero, HERO_DATA.AURA_GLOW, auraGlow)
        sprites.setDataNumber(hero, HERO_DATA.AURA_RADIUS, auraRadius)

    }

}















