// Overlap logic shared by STR/AGI/INT/HEAL effects.





// HeroWeapon ? Enemy (STR/AGI: normal; INTELLECT: detonate; HEAL: ignore enemies)

sprites.onOverlap(SpriteKind.HeroWeapon, SpriteKind.Enemy, function (weapon, enemy) {

    const family = sprites.readDataNumber(weapon, PROJ_DATA.FAMILY) | 0

    const heroIndex = sprites.readDataNumber(weapon, PROJ_DATA.HERO_INDEX) | 0



    // HEAL: ignore enemy overlaps entirely

    if (family == FAMILY.HEAL) return



    // INTELLECT:

    //   - first overlap: request detonate (so LAND happens via hero path)

    //   - during linger/detonated: apply pulsed damage (NOT every frame)

    if (family == FAMILY.INTELLECT) {

        const nowMs = game.runtime() | 0

        const detonated = sprites.readDataNumber(weapon, INT_DETONATED_KEY) | 0



        if (!detonated) {

            // (Optional) unified “terminus” semantics/logs

            sprites.setDataNumber(weapon, PROJ_DATA.TERMINUS_HIT, 2)



            detonateIntellectSpellForHero(

                heroIndex,

                weapon,

                nowMs,

                "INTELLECT_DETONATE_REQUEST_HIT_ENEMY",

                "sprites.onOverlap(HeroWeapon,Enemy)"

            )



            // IMPORTANT: capture a contract snapshot *after* this event-driven detonate,

            // otherwise WHY/TOUCH for detonation gets lost (onOverlap runs after onUpdate).

            if (DEBUG_CONTRACT_SNAPSHOT) {

                logHeroRuntimeContractAllHeroes(nowMs, "events", "overlap(HeroWeapon,Enemy)")

            }



            return

        }



        // ---- PULSE DAMAGE DURING DETONATION/LINGER -------------------------



        const winEnd = sprites.readDataNumber(weapon, INT_PULSE_WINDOW_END_MS_KEY) | 0

        if (winEnd <= 0 || nowMs > winEnd) return



        // Once per enemy per pulse

        const eIndex = getEnemyIndex(enemy)

        if (eIndex < 0) return



        if (eIndex < 31) {

            let mask = sprites.readDataNumber(weapon, INT_PULSE_HIT_MASK_KEY) | 0

            const bit = (1 << eIndex)

            if (mask & bit) return

            sprites.setDataNumber(weapon, INT_PULSE_HIT_MASK_KEY, mask | bit)

        }



        // Damage per pulse: default to projectile damage key (same place STR/AGI reads)

        let dmg = sprites.readDataNumber(weapon, PROJ_DATA.DAMAGE) | 0

        const weakenPct = sprites.readDataNumber(weapon, PROJ_DATA.WEAKEN_PCT) | 0

        const weakenMs = sprites.readDataNumber(weapon, PROJ_DATA.WEAKEN_DURATION_MS) | 0

        const element = sprites.readDataNumber(weapon, PROJ_DATA.ELEMENT) | 0

        if (dmg <= 0 && (weakenPct <= 0 || weakenMs <= 0)) return



        applyDamageToEnemyIndex(eIndex, dmg, heroIndex, {

            family: FAMILY.INTELLECT,

            sourceTag: "INT_PULSE",

            element,

            weakenPct,

            weakenMs

        })



        return

    }



    // ---------------- STR / AGI payload (unchanged) ------------------------



    const button = sprites.readDataString(weapon, PROJ_DATA.BUTTON)

    const isHeal = (sprites.readDataNumber(weapon, PROJ_DATA.IS_HEAL) | 0) == 1

    const slowPct = sprites.readDataNumber(weapon, PROJ_DATA.SLOW_PCT) | 0

    const slowDurationMs = sprites.readDataNumber(weapon, PROJ_DATA.SLOW_DURATION_MS) | 0

    const weakenPct = sprites.readDataNumber(weapon, PROJ_DATA.WEAKEN_PCT) | 0

    const weakenDurationMs = sprites.readDataNumber(weapon, PROJ_DATA.WEAKEN_DURATION_MS) | 0

    const knockbackPct = sprites.readDataNumber(weapon, PROJ_DATA.KNOCKBACK_PCT) | 0

    const element = sprites.readDataNumber(weapon, PROJ_DATA.ELEMENT) | 0

    const eIndex = getEnemyIndex(enemy); if (eIndex < 0 || heroIndex < 0 || heroIndex >= heroes.length) return

    const hero = heroes[heroIndex]; if (!hero) return

    const sharedHit = sprites.readDataNumber(weapon, PROJ_DATA.SHARED_HIT) | 0
    const bit = 1 << eIndex
    if (sharedHit) {
        let hitMask = sprites.readDataNumber(hero, HERO_DATA.STR_SWING_HIT_MASK) | 0
        if (hitMask & bit) return
        sprites.setDataNumber(hero, HERO_DATA.STR_SWING_HIT_MASK, hitMask | bit)
    } else {
        let hitMask = sprites.readDataNumber(weapon, PROJ_DATA.HIT_MASK) | 0
        if (hitMask & bit) return
        sprites.setDataNumber(weapon, PROJ_DATA.HIT_MASK, hitMask | bit)
    }

    const now = game.runtime()



    let dmg = sprites.readDataNumber(weapon, PROJ_DATA.DAMAGE) | 0



    if (dmg > 0 && family == FAMILY.AGILITY) {

        const comboMultPct = getComboDamageMultPct(heroIndex)

        dmg = Math.idiv(dmg * comboMultPct, 100)

        updateAgilityComboOnHit(heroIndex, button)

    }



    const hit: EnemyHitPacket = {

        family,

        button,

        sourceTag: "WEAPON_OVERLAP",

        slowPct,

        slowMs: slowDurationMs,

        weakenPct,

        weakenMs: weakenDurationMs,

        knockbackPct,

        element

    }



    // IMPORTANT: call even if dmg==0, because status/knockback may exist

    applyDamageToEnemyIndex(eIndex, dmg, heroIndex, hit)



    if (isHeal && dmg > 0) applyHealToHeroIndex(heroIndex, dmg)



})



// NEW: HeroWeapon ? Player (HEAL detonates on allies)

// Relic effect ring: damage enemies that touch the ring (once per ring).

sprites.onOverlap(SpriteKind.RelicEffect, SpriteKind.Enemy, function (flame, enemy) {

    if (!flame || (flame.flags & sprites.Flag.Destroyed)) return

    if (!enemy || (enemy.flags & sprites.Flag.Destroyed)) return

    const trapDmg = sprites.readDataNumber(flame, TRAP_TOTEM_DMG_KEY) | 0
    if (trapDmg > 0) {
        const eIndex = getEnemyIndex(enemy)
        if (eIndex < 0) return

        let mask = sprites.readDataNumber(flame, TRAP_TOTEM_HIT_MASK_KEY) | 0
        const bit = 1 << eIndex
        if (mask & bit) return
        sprites.setDataNumber(flame, TRAP_TOTEM_HIT_MASK_KEY, mask | bit)

        const hit: EnemyHitPacket = {
            family: FAMILY.INTELLECT,
            sourceTag: "TRAP_TOTEM",
        }
        applyDamageToEnemyIndex(eIndex, trapDmg | 0, -1, hit)
        return
    }



    const ringId = sprites.readDataNumber(flame, RELIC_EFFECT_RING_RING_ID_KEY) | 0

    if (ringId <= 0) return



    const dmg = sprites.readDataNumber(flame, RELIC_EFFECT_RING_DMG_KEY) | 0

    if (dmg <= 0) return



    const srcHi = sprites.readDataNumber(flame, RELIC_EFFECT_RING_SRC_HI_KEY) | 0

    const eIndex = getEnemyIndex(enemy)

    if (eIndex < 0) return



    _relicRingOfFireDamageEnemy(ringId, eIndex, enemy, srcHi, dmg)

})



