// MonsterEffect -> Hero (enemy slashes/projectiles). Single hit then destroy.
function _spawnPoisonGroundHazard(
    x: number,
    y: number,
    lifeMs?: number,
    sizePx?: number,
    dmg?: number,
    tickMs?: number
): void {
    const size = Math.max(4, (sizePx != null ? (sizePx | 0) : (POISON_GROUND_SIZE_PX | 0))) | 0
    const img = image.create(size, size)
    img.fill(0)
    const fill = 7
    const border = 5
    for (let iy = 0; iy < size; iy++) {
        for (let ix = 0; ix < size; ix++) {
            const isBorder = (ix === 0 || iy === 0 || ix === (size - 1) || iy === (size - 1))
            img.setPixel(ix, iy, isBorder ? border : fill)
        }
    }
    const hz = sprites.create(img, SpriteKind.MonsterEffect)
    hz.z = 2
    hz.x = x | 0
    hz.y = y | 0
    sprites.setDataNumber(hz, "__hazard", 1)
    sprites.setDataNumber(hz, "__hazardDmg", (dmg != null ? (dmg | 0) : (POISON_GROUND_DMG | 0)) | 0)
    sprites.setDataNumber(hz, "__hazardTickMs", (tickMs != null ? (tickMs | 0) : (POISON_GROUND_TICK_MS | 0)) | 0)
    sprites.setDataNumber(hz, "__hazardNextHitMs", 0)
    hz.lifespan = (lifeMs != null ? (lifeMs | 0) : (POISON_GROUND_LIFE_MS | 0)) | 0
}

sprites.onOverlap(SpriteKind.MonsterEffect, SpriteKind.Player, function (fx, hero) {
    if (!fx || (fx.flags & sprites.Flag.Destroyed)) return
    if (!hero || (hero.flags & sprites.Flag.Destroyed)) return

    const hi = heroes.indexOf(hero)
    if (hi < 0) return

    const isHazard = (sprites.readDataNumber(fx, "__hazard") | 0) !== 0
    if (isHazard) {
        const now = game.runtime() | 0
        const next = sprites.readDataNumber(fx, "__hazardNextHitMs") | 0
        if (now >= next) {
            const dmg = sprites.readDataNumber(fx, "__hazardDmg") | 0
            if (dmg > 0) {
                applyDamageToHeroIndex(hi, dmg, { kind: "hazard", x: fx.x, y: fx.y })
            }
            const tick = Math.max(100, sprites.readDataNumber(fx, "__hazardTickMs") | 0) | 0
            sprites.setDataNumber(fx, "__hazardNextHitMs", (now + tick) | 0)
        }
        return
    }

    const dmg = sprites.readDataNumber(fx, "dmg") | 0
    if (dmg > 0) {
        const maxHp = sprites.readDataNumber(hero, HERO_DATA.MAX_HP) | 0
        const cap = Math.max(1, Math.idiv((maxHp | 0) * (ENEMY_DAMAGE_CAP_PCT_OF_MAX_HP | 0), 100)) | 0
        const finalDmg = (cap > 0 && dmg > cap) ? cap : dmg
        const enemyIndex = sprites.readDataNumber(fx, "enemyIndex") | 0
        let srcX = fx.x
        let srcY = fx.y
        if (enemyIndex >= 0 && enemyIndex < enemies.length) {
            const srcEnemy = enemies[enemyIndex]
            if (srcEnemy && !(srcEnemy.flags & sprites.Flag.Destroyed)) {
                srcX = srcEnemy.x
                srcY = srcEnemy.y
            }
        }
        applyDamageToHeroIndex(hi, finalDmg, { kind: "projectile", enemyIndex, x: srcX, y: srcY })
    }

    if ((sprites.readDataNumber(fx, "__projPoison") | 0) !== 0) {
        _spawnPoisonGroundHazard(fx.x | 0, fx.y | 0)
    }

    fx.destroy()
})


function hasSignificantOverlap(hero: Sprite, enemy: Sprite, minHeroAreaPct: number): boolean {

    const heroDims = _readSpriteColliderDims(hero)
    const heroW = heroDims.w | 0
    const heroH = heroDims.h | 0
    let enemyW = enemy.width | 0
    let enemyH = enemy.height | 0
    if (enemy.kind === SpriteKind.Enemy) {
        const dims = _enemyGetColliderDims(enemy)
        enemyW = dims.w | 0
        enemyH = dims.h | 0
    }

    const halfHW = Math.idiv(heroW, 2), halfHH = Math.idiv(heroH, 2), halfEW = Math.idiv(enemyW, 2), halfEH = Math.idiv(enemyH, 2)

    const dy = Math.abs((hero.y + _heroCollisionOffsetY(hero)) - (enemy.y + _heroCollisionOffsetY(enemy)))

    const dx = Math.abs(hero.x - enemy.x)

    const overlapX = (halfHW + halfEW) - dx, overlapY = (halfHH + halfEH) - dy

    if (overlapX <= 0 || overlapY <= 0) return false

    const overlapArea = overlapX * overlapY, heroArea = heroW * heroH

    return overlapArea * 100 >= heroArea * minHeroAreaPct

}



// Player ? Enemy contact: block movement instead of touch-damaging.
sprites.onOverlap(SpriteKind.Player, SpriteKind.Enemy, function (hero, enemy) {
    if (!hero || !enemy) return
    // Keep the significant-overlap gate so tiny sprite jitter doesn't trigger pushes constantly.
    if (!hasSignificantOverlap(hero, enemy, HERO_CONTACT_MIN_OVERLAP_PCT)) return
    // Treat enemies like walls: move only the hero out of penetration; enemies stay put.
    _resolveSpriteOverlap(hero, enemy, true, false)
})



function _resolveSpriteOverlap(a: Sprite, b: Sprite, moveA: boolean, moveB: boolean): boolean {

    if (!a || !b) return false

    const ab = _boundsWithOffset(a, _heroCollisionOffsetY(a))

    const bb = _boundsWithOffset(b, _heroCollisionOffsetY(b))

    if ((ab.left >= bb.right) || (ab.right <= bb.left) || (ab.top >= bb.bottom) || (ab.bottom <= bb.top)) return false



    const acx = ((ab.left + ab.right) >> 1) | 0

    const acy = ((ab.top + ab.bottom) >> 1) | 0

    const bcx = ((bb.left + bb.right) >> 1) | 0

    const bcy = ((bb.top + bb.bottom) >> 1) | 0



    const penLeft = (ab.right - bb.left) | 0

    const penRight = (bb.right - ab.left) | 0

    const penUp = (ab.bottom - bb.top) | 0

    const penDown = (bb.bottom - ab.top) | 0



    const pushX = (acx < bcx) ? (-(penLeft | 0)) : (penRight | 0)

    const pushY = (acy < bcy) ? (-(penUp | 0)) : (penDown | 0)



    const magX = Math.abs(pushX) | 0

    const magY = Math.abs(pushY) | 0



    const useX = (magX > 0 && (magX <= magY || magY <= 0))

    const push = useX ? pushX : pushY



    if (moveA && moveB) {

        const half = Math.idiv(push, 2) | 0

        const rest = (push - half) | 0

        if (useX) {

            a.x = ((a.x | 0) + half) | 0

            b.x = ((b.x | 0) - rest) | 0

            try { (a.vx as any) = 0 } catch { }

            try { (b.vx as any) = 0 } catch { }

        } else {

            a.y = ((a.y | 0) + half) | 0

            b.y = ((b.y | 0) - rest) | 0

            try { (a.vy as any) = 0 } catch { }

            try { (b.vy as any) = 0 } catch { }

        }

        return true

    }



    const mover = moveA ? a : (moveB ? b : null)

    if (!mover) return false

    if (useX) {

        mover.x = ((mover.x | 0) + push) | 0

        try { (mover.vx as any) = 0 } catch { }

    } else {

        mover.y = ((mover.y | 0) + push) | 0

        try { (mover.vy as any) = 0 } catch { }

    }

    return true

}



sprites.onOverlap(SpriteKind.Player, SpriteKind.Player, function (a, b) {

    if (!a || !b || a === b) return

    const aOwner = sprites.readDataNumber(a, HERO_DATA.OWNER) | 0

    const bOwner = sprites.readDataNumber(b, HERO_DATA.OWNER) | 0

    const aIsShop = (aOwner | 0) === (SHOPKEEPER_PLAYER_ID | 0)

    const bIsShop = (bOwner | 0) === (SHOPKEEPER_PLAYER_ID | 0)



    if (aIsShop && bIsShop) return

    if (aIsShop || bIsShop) {

        const mover = aIsShop ? b : a

        const other = aIsShop ? a : b

        _resolveSpriteOverlap(mover, other, true, false)

        return

    }



    _resolveSpriteOverlap(a, b, true, true)

})



sprites.onOverlap(SpriteKind.Player, SpriteKind.StoryNpc, function (hero, npc) {

    _resolveSpriteOverlap(hero, npc, true, false)

})

sprites.onOverlap(SpriteKind.Player, (SpriteKind as any).NpcLpc, function (hero, npc) {
    const role = sprites.readDataString(npc, "_npcRole") || ""
    if (role !== "storyNpc") return
    _resolveSpriteOverlap(hero, npc, true, false)
})

sprites.onOverlap(SpriteKind.Player, SpriteKind.ShopNpc, function (hero, npc) {

    _resolveSpriteOverlap(hero, npc, true, false)

})





