function _strengthPrepMsFromFrames(maxMs: number): number {
    const mult = STR_DEBUG_FRAME_MS_MULT | 0;
    const frameMs = STR_SWING_WINDUP_FRAME_MS;
    let prep = 0;
    if (frameMs && frameMs.length) {
        for (let i = 0; i < frameMs.length; i++) {
            const base = Math.max(1, frameMs[i] | 0);
            prep += (mult > 1) ? Math.max(1, (base * mult) | 0) : base;
        }
    } else {
        prep = STR_PREP_VISIBLE_MS | 0;
        if (mult > 1 && prep > 0) prep = (prep * mult) | 0;
    }
    if (prep < 0) prep = 0;
    if ((maxMs | 0) > 0 && prep > (maxMs | 0)) prep = maxMs | 0;
    return prep | 0;
}

function _strengthPrepFrameCol(elapsedMs: number, prepMs: number): number {
    const frames = STR_SWING_WINDUP_FRAME_COLS;
    if (!frames || !frames.length) return 0;
    const frameMs = STR_SWING_WINDUP_FRAME_MS;
    const mult = STR_DEBUG_FRAME_MS_MULT | 0;
    const elapsed = clampInt(elapsedMs | 0, 0, Math.max(1, prepMs | 0));
    if (frameMs && frameMs.length === frames.length) {
        let acc = 0;
        for (let i = 0; i < frameMs.length; i++) {
            const base = Math.max(1, frameMs[i] | 0);
            const scaled = (mult > 1) ? Math.max(1, (base * mult) | 0) : base;
            acc += scaled;
            if (elapsed < acc || i === frameMs.length - 1) return frames[i] | 0;
        }
    }
    const slice = Math.max(1, Math.idiv(Math.max(1, prepMs | 0), Math.max(1, frames.length)));
    const idx = Math.min(frames.length - 1, Math.idiv(elapsed | 0, slice));
    return frames[idx] | 0;
}

function _strengthSwingSlashMinMs(): number {
    const frameMs = STR_SWING_FORWARD_FRAME_MS;
    if (frameMs && frameMs.length) {
        let sum = 0;
        for (let i = 0; i < frameMs.length; i++) {
            sum += Math.max(1, frameMs[i] | 0);
        }
        return Math.max(1, sum | 0);
    }
    return Math.max(1, STR_SWING_SEG_FORWARD_MIN_MS | 0);
}

function _strengthSwingResetMinMs(): number {
    const ms = STR_SWING_RETURN_FRAME_MS;
    if (ms && ms.length) {
        let sum = 0;
        for (let i = 0; i < ms.length; i++) sum += Math.max(1, ms[i] | 0);
        return Math.max(1, sum | 0);
    }
    return Math.max(1, 1);
}

function _strengthSwingResetTailMs(): number {
    const ms = STR_SWING_RESET_FRAME_MS;
    if (!ms || ms.length < 2) return Math.max(1, STR_SWING_RESET_OUTRO_MS | 0);
    const last = Math.max(1, ms[ms.length - 1] | 0);
    const prev = Math.max(1, ms[ms.length - 2] | 0);
    return (last + prev) | 0;
}

function _strengthArcTravelFrames(arcDeg: number, outerR: number): number {
    const halfArcRad = Math.abs(arcDeg) * 0.5 * (Math.PI / 180);
    const travelPx = Math.max(1, Math.round(Math.max(1, outerR | 0) * halfArcRad));
    const step = Math.max(1, STR_ARC_TRAVEL_STEP_PX | 0);
    return Math.max(STR_ARC_TRAVEL_MIN_FRAMES | 0, Math.ceil(travelPx / step));
}

function _strengthArcTravelFrameMs(frameCount: number): number {
    const base = Math.max(1, STR_ARC_TRAVEL_FRAME_MS | 0);
    const baseFrames = Math.max(1, STR_ARC_TRAVEL_BASE_FRAMES | 0);
    if (!(frameCount > baseFrames)) return base;
    const ratio = frameCount / baseFrames;
    const power = Math.max(0, Math.log2(ratio));
    const factor = Math.pow(STR_ARC_TRAVEL_SPEEDUP_BASE, power);
    const ms = Math.max(1, Math.round(base * factor));
    return Math.max(STR_ARC_TRAVEL_MIN_FRAME_MS | 0, ms);
}

function _estimateStrengthArcTravelMs(
    heroIndex: number,
    hero: Sprite,
    arcDeg: number,
    reachExtraPx: number
): number {
    if (!hero) return 0;
    if (!(arcDeg && Number.isFinite(arcDeg))) return 0;
    const aim = getAimVectorForHero(heroIndex);
    let nx = aim[0];
    let ny = aim[1];
    if (nx == 0 && ny == 0) { nx = 1; ny = 0; }
    const mag = Math.sqrt(nx * nx + ny * ny) || 1;
    nx /= mag;
    ny /= mag;

    const vis = getHeroVisualInfoForStrength(hero, nx, ny);
    let inner0 = (vis[0] || 0);
    let leadEdge = (vis[1] || 0);
    let wTipX = (vis[2] || 0);
    let wTipY = (vis[3] || 0);
    if (inner0 <= 0) inner0 = 35;
    if (leadEdge <= 0) leadEdge = 32;

    const AURA_THICKNESS = 1;
    const SPACING = 1;
    let frontStartR = leadEdge + AURA_THICKNESS + SPACING;
    if (frontStartR < 0) frontStartR = 0;
    if (frontStartR > inner0) frontStartR = inner0;
    const wTipProj = (wTipX * nx) + (wTipY * ny);
    if (wTipProj > 0) {
        const tipR = Math.round(wTipProj);
        if (tipR > frontStartR) frontStartR = tipR;
    }
    if (STR_USE_WPN_AURA_OUTLINE_ONLY) {
        const info = _getHeroWeaponFgInfo(hero);
        if (info) {
            const leadR0 = _weaponLeadingEdgeForFrameIndex(info, STR_WPN_AURA_OUTLINE_RADIUS | 0, nx, ny, 0);
            if (Number.isFinite(leadR0) && leadR0 > 0) {
                const leadRInt = Math.round(leadR0);
                if (leadRInt > frontStartR) frontStartR = leadRInt;
            }
        }
    }

    let reachFromInner = (reachExtraPx | 0);
    const minReach = Math.max(0, (frontStartR | 0) - (inner0 | 0));
    if (reachFromInner < minReach) reachFromInner = minReach;
    if (reachFromInner < 1) reachFromInner = 1;

    const outerBase = (frontStartR | 0) + (reachFromInner | 0);
    const outerR = (outerBase | 0) + 3;
    const frames = _strengthArcTravelFrames(arcDeg | 0, outerR | 0);
    const frameMs = _strengthArcTravelFrameMs(frames | 0);
    return Math.max(1, (frames | 0) * (frameMs | 0));
}



