            // Map monster labels ? a stat archetype key in ENEMY_KIND

            function pickEnemyKindForMonster(monsterId: string): string {

                const tags = (MONSTER_ARCHETYPE[monsterId] as string[]) || []



                // Explicit BOSS ? ELITE

                if (tags.indexOf("BOSS") >= 0) return "ELITE"



                // Big chunky / tanky things ? BRUTE

                if (tags.indexOf("SLOWSTRONG") >= 0 ||

                    tags.indexOf("TANK") >= 0 ||

                    tags.indexOf("STRONG") >= 0) {

                    return "BRUTE"

                }



                // Very fast / weak things ? RUNNER

                if (tags.indexOf("FASTWEAK") >= 0 ||

                    (tags.indexOf("FAST") >= 0 && tags.indexOf("WEAK") >= 0)) {

                    return "RUNNER"

                }



                // Generic weak ? GRUNT

                if (tags.indexOf("WEAK") >= 0) return "GRUNT"



                // Fallback by speed

                if (tags.indexOf("FAST") >= 0) return "RUNNER"

                if (tags.indexOf("SLOW") >= 0) return "BRUTE"



                // Default

                return "GRUNT"

            }



            // Keep this around in case anything else calls it.

            function resolveArchetypeForMonster(monsterId: string): string {

                return pickEnemyKindForMonster(monsterId)

            }



function enemyStatsForMonsterId(monsterId: string) {

    const md = _monsterDefById(monsterId)



    // Fallback baseline (your old behavior)

    const kindKey = pickEnemyKindForMonster(monsterId)

    const spec = (ENEMY_KIND as any)[kindKey] || ENEMY_KIND.GRUNT



    // If catalog entry exists, it wins for hp/speed/damage

    const hasCatalog = (md && (md.danger | 0) !== 999)



    const maxHP = hasCatalog ? (md.hp | 0) : ((spec as any).maxHP | 0)

    const speed = hasCatalog ? (md.speed | 0) : ((spec as any).speed | 0)

    const touchDamage = hasCatalog ? (md.damage | 0) : ((spec as any).touchDamage | 0)

    // Scale enemy power with floor so level/floor progression matters
    const floorIdx = Math.max(1, (_dunFloorIndex | 0)) | 0
    const scaleFloor = Math.max(0, (floorIdx - (ENEMY_POWER_SCALE_START_FLOOR | 0) + 1) | 0) | 0
    const powerPct = 100 + Math.max(0, (scaleFloor | 0) * (BALANCE.WAVES.ENEMY_POWER_PER_FLOOR_PCT | 0))
    const speedPct = 100 + Math.max(0, (scaleFloor | 0) * (BALANCE.WAVES.ENEMY_SPEED_PER_FLOOR_PCT | 0))

    const maxHPScaled = Math.max(1, Math.idiv(maxHP * powerPct, 100))
    const touchDamageScaled = Math.max(1, Math.idiv(touchDamage * powerPct, 100))
    const speedScaled = Math.max(1, Math.idiv(speed * speedPct, 100))



    // Optional knobs (catalog can override, otherwise spec defaults)

    const regenPct = hasCatalog ? ((md.regenPct || 0) | 0) : (((spec as any).regenPct || 0) | 0)

    const attackRatePct = hasCatalog

        ? (((md.attackRatePct || 100) | 0))

        : (((spec as any).attackRatePct || 100) | 0)

    const attackIntervalMs = hasCatalog ? ((md.attackIntervalMs || 0) | 0) : 0



    const advanceRangePx = hasCatalog ? (md.advanceRangePx | 0) : 0

    const projectileId = hasCatalog ? (md.projectileId || "") : ""



    return {

        maxHP: maxHPScaled,

        speed: speedScaled,

        touchDamage: touchDamageScaled,

        regenPct,

        attackRatePct,

        attackIntervalMs,

        advanceRangePx,

        projectileId

    }

}







            // Try to read LPC frame size for this monsterId from Phaser-side monsterAtlas.

            // Returns {w,h} or null if not available (Arcade / unknown id).

            function getLpcFrameSizeForMonster(monsterId: string): { w: number, h: number } {

                try {

                    const g: any = globalThis as any

                    const atlas = g && g.monsterAtlas

                    if (atlas && atlas[monsterId]) {

                        const entry = atlas[monsterId] as any

                        const fw = entry.frameWidth | 0

                        const fh = entry.frameHeight | 0

                        if (fw > 0 && fh > 0) {

                            return { w: fw, h: fh }

                        }

                    }

                } catch {

                    // In pure MakeCode Arcade, globalThis / monsterAtlas may not exist

                }

                return null

            }



            // Placeholder MakeCode image for a monster id.

            // In Phaser builds with monsterAtlas, we size this to match the LPC frame

            // so HP bars + collisions line up with the pretty art.

            // In plain Arcade (no monsterAtlas), we fall back to archetype art.

function enemyPlaceholderImageForMonster(monsterId: string): Image {

    const sizing = _monsterSizingForId(monsterId)



    // If Phaser is present, we always want collisions driven by collider size.

    // In pure Arcade, you can still fall back to the old pixel art if you prefer.

    const g: any = globalThis as any

    const hasAtlas = !!(g && g.monsterAtlas)



    if (hasAtlas) {
        const w = sizing.colliderW | 0
        const h = sizing.colliderH | 0
        return _enemyMakeColliderPlaceholderImage(w | 0, h | 0)
    }



    // Arcade fallback: your old archetype-specific art

    const kindKey = pickEnemyKindForMonster(monsterId)

    return enemyImageForKind(kindKey)

}

function _enemyMakeColliderPlaceholderImage(w: number, h: number): Image {
    const iw = Math.max(1, w | 0) | 0
    const ih = Math.max(1, h | 0) | 0
    const img = image.create(iw, ih)
    // Visible debug body (so you can "see" collision size)
    const fill = 1
    const border = 2
    for (let y = 0; y < ih; y++) {
        for (let x = 0; x < iw; x++) {
            const isBorder = (x === 0 || y === 0 || x === (iw - 1) || y === (ih - 1))
            img.setPixel(x, y, isBorder ? border : fill)
        }
    }
    return img
}

function _enemySetPlaceholderImageForCollider(enemy: Sprite, w: number, h: number): void {
    if (!enemy) return
    const img = _enemyMakeColliderPlaceholderImage(w | 0, h | 0)
    enemy.setImage(img)
}















