const _ENEMY_DIR_R: number[] = [-1, 1, 0, 0, -1, -1, 1, 1]

const _ENEMY_DIR_C: number[] = [0, 0, -1, 1, -1, 1, -1, 1]





// --------------------------------------------------------------

// Shared enemy navigation (flow-field) - one BFS per rebuild, all enemies reuse

// --------------------------------------------------------------

const ENEMY_NAV_LOG_FORMAT_TSV = true
const ENEMY_NAV_LOG_TSV_HEADER_EVERY_DUMP = true

// Candidate verbosity knobs
const ENEMY_NAV_LOG_CANDS_ON_FORCE_ONLY = true   // candidates only when logForce/force dump
const ENEMY_NAV_LOG_CANDS_MAX = 8                // cap candidates printed
const ENEMY_NAV_LOG_MAX_LINE_CHARS = 500         // split long lines deterministically


const ENEMY_NAV_INF = 0x3fff
const ENEMY_NAV_REBUILD_MS = 200   // KNOB: lower = more responsive, higher = cheaper
const ENEMY_PATHFINDING_FORCE = true // if true: use pathfinding.js A* only (no fallbacks)
const ENEMY_NAV_LOG_RING_SIZE = 192 // Bounded history per enemy
const ENEMY_NAV_LOG_MIN_MOVE_PX = 4
const ENEMY_NAV_LOG_MIN_MOVE_PX2 = ENEMY_NAV_LOG_MIN_MOVE_PX * ENEMY_NAV_LOG_MIN_MOVE_PX
const ENEMY_NAV_LOG_DUMP_COOLDOWN_MS = 800
const ENEMY_NAV_LOG_QUAD_STALE_MS = 1500
const ENEMY_NAV_LOG_TILE_CHANGE_ONLY = true
const ENEMY_STUCK_DEDUP_MS = 1200
const ENEMY_NAV_DEAD_END_MAX_CELLS = 64  // KNOB: cap pocket size we treat as "dead end" to avoid blocking real paths
const ENEMY_ASTAR_MAX_NODES = 5000
const ENEMY_STUCK_NUDGE_PX = 1
const ENEMY_NAV_FOOTPRINT_MAX_PX = 32  // clamp NAV footprint only (pathfinding size), not collision
const ENEMY_NAV_FOOTPRINT_BOSS_PX = 64 // boss nav footprint (must be tile-multiple: 2x32)
const ENEMY_STUCK_SLIDE_ENABLED = false  // toggle anti-stuck nudge if it interferes with A*

let _enginePaused = false
let _enginePausedReason = ""
let _enginePausedAtMs = 0
let _enemyNavLastMapDumpRev = -1



let _enemyNavDist: number[] = []

let _enemyNavDecorBlock: number[] = []

let _enemyNavDeadEnd: number[] = []

let _enemyNavTempDeg: number[] = []

let _enemyNavTempProtect: number[] = []

let _enemyNavTempSeen: number[] = []

let _enemyNavRows = 0

let _enemyNavCols = 0
let _enemyNavQuadOwner: number[] = [-1, -1, -1, -1]
let _enemyNavQuadSeenAt: number[] = [0, 0, 0, 0]
let _enemyNavQuadOwnerRev: number[] = [-1, -1, -1, -1]
let _enemyNavSpawnerLogger: number[] = []

// A* cache (rebuilt per world/decor rev)
let _enemyAstarRows = 0
let _enemyAstarCols = 0
let _enemyAstarBlocked: number[] = []
let _enemyAstarWorldRev = -1
let _enemyAstarDecorRev = -1
let _enemyAstarHeroHash = -1
let _enemyAstarG: number[] = []
let _enemyAstarCameFrom: number[] = []
let _enemyAstarSeen: number[] = []
let _enemyAstarClosed: number[] = []
let _enemyAstarSeenList: number[] = []
let _enemyAstarClosedList: number[] = []

// pathfinding.js cache
let _enemyPFGrid: PFGrid | null = null
let _enemyPFFinder: PFAStarFinder | null = null
let _enemyPFWorldRev = -1
let _enemyPFDecorRev = -1
let _enemyPFHeroHash = -1


function _navStr(v: any): string {
    if (v == null) return ""
    return String(v)
}

function _navNum(v: any, fallback = 0): number {
    const n = (v == null) ? fallback : (v | 0)
    return n
}

// Ensures NO console truncation by printing STRINGS only, and splitting long lines.
function _navPrint(prefix: string, line: string): void {
    const max = ENEMY_NAV_LOG_MAX_LINE_CHARS | 0
    if (!line) {
        console.log(prefix)
        return
    }

    if ((line.length | 0) <= max) {
        console.log(prefix + line)
        return
    }

    // Split into chunks with stable numbering so you can copy/paste and re-join.
    let i = 0
    let part = 0
    while (i < line.length) {
        const chunk = line.slice(i, i + max)
        console.log(`${prefix}[part ${part}] ${chunk}`)
        i += max
        part++
    }
}

function _enemyNavTsvHeader(): string {
    return [
        "eid","mid","step","tMs",
        "pr","pc","pIdx","px","py",
        "curD","mask","allowUp",
        "herR","herC","herEX","herEY",
        "pickR","pickC","pickD",
        "reason","phase",
        "lastIdx","stuckUntil","stuckMode",
        "speed","vx","vy",
        "tileBase","tileDecor","tileDead","ovWall",
        "hitAny","hitBase","hitDecor","hitDead","hitCap",
        "candsN"
    ].join("\t")
}

function _enemyNavCandFlags(c: any): number {
    let flags = 0
    if (c && c.blocked) flags |= 1       // blocked
    if (c && c.back) flags |= 2          // backtrack
    if (c && c.diag) flags |= 4          // diagonal
    if (c && c.blockReason === "fit") flags |= 8  // fitFail
    if (c && c.chosen) flags |= 16       // chosen
    return flags | 0
}

function _enemyNavFormatCandidatesCompact(cands: any[] | null, maxN: number): string {
    if (!cands || cands.length === 0) return ""
    const limit = Math.min(maxN | 0, cands.length | 0) | 0
    const parts: string[] = []
    for (let i = 0; i < limit; i++) {
        const c = cands[i] || {}
        const flags = _enemyNavCandFlags(c)
        const br = c.blockReason ? `:${c.blockReason}` : ""
        const align = (c.align == null) ? 0 : (Math.round((c.align || 0) * 100) / 100)
        const col = c.coll ? `,col=${c.coll}` : ""
        parts.push(`${c.r|0},${c.c|0},d=${(c.d==null?-1:c.d|0)},f=${flags}${br},a=${align}${col}`)
    }
    // single field; pipe-delimited candidates
    return parts.join("|")
}

function _enemyNavFormatEntryTsv(entry: any): { line: string, cands: string } {
    const pos = entry.pos || {}
    const dist = entry.dist || {}
    const nav = entry.nav || {}
    const pick = entry.pick || {}
    const stuck = entry.stuck || {}
    const vel = entry.vel || {}
    const hero = entry.hero || {}
    const cc = entry.coll || null
    const t = cc ? (cc.tile || {}) : {}
    const h = cc ? (cc.hits || {}) : {}

    const candsArr: any[] | null = entry.candidates || null
    const candsN = candsArr ? (candsArr.length | 0) : 0

    const line = [
        _navNum(entry.eid), _navStr(entry.mid || ""), _navNum(entry.step), _navNum(entry.t),

        _navNum(pos.r), _navNum(pos.c), _navNum(pos.idx), _navNum(pos.x), _navNum(pos.y),

        _navNum(dist.cur), _navNum(dist.mask), _navNum(dist.allowUp),

        _navNum(hero.r), _navNum(hero.c), _navNum(hero.ex), _navNum(hero.ey),

        _navNum(pick.r), _navNum(pick.c), _navNum(pick.d, -1),

        _navStr(entry.reason || ""), _navStr(entry.phase || ""),

        _navNum(nav.lastIdx), _navNum(stuck.until), _navNum(stuck.mode),

        _navNum(entry.speed), _navNum(vel.vx), _navNum(vel.vy),

        cc ? (_navNum(t.baseBlocked)) : "", cc ? (_navNum(t.decorBlocked)) : "", cc ? (_navNum(t.deadEndBlocked)) : "", cc ? (_navNum(cc.overlapsWall)) : "",

        cc ? (_navNum(h.anyBlockedHits)) : "", cc ? (_navNum(h.baseHits)) : "", cc ? (_navNum(h.decorHits)) : "", cc ? (_navNum(h.deadEndHits)) : "", cc ? (_navNum(h.capped)) : "",

        candsN
    ].join("\t")

    // Candidates as ONE extra field (pipe-delimited), capped
    const cands = _enemyNavFormatCandidatesCompact(candsArr, ENEMY_NAV_LOG_CANDS_MAX | 0)

    return { line, cands }
}


function _enemyNavDumpLocalSnapshot(r: number, c: number, enemy: Sprite): void {
    if (!DEBUG_ENEMY_NAV_LOG) return
    if (!_engineWorldTileMap || _engineWorldTileMap.length === 0) return

    const rows = _enemyNavRows | 0
    const cols = _enemyNavCols | 0
    const tr = sprites.readDataNumber(enemy, ENEMY_AI_NAV_TARGET_R) | 0
    const tc = sprites.readDataNumber(enemy, ENEMY_AI_NAV_TARGET_C) | 0
    const td = sprites.readDataNumber(enemy, ENEMY_AI_NAV_TARGET_D) | 0

    console.log(`[enemy][navlog][localsnap] eid=${getEnemyIndex(enemy)|0} at=(${r|0},${c|0}) target=(${tr|0},${tc|0},d=${td|0}) window=5x5`)

    for (let dr = -2; dr <= 2; dr++) {
        const rr = (r + dr) | 0
        let maskLine = ""
        let distParts: string[] = []
        for (let dc = -2; dc <= 2; dc++) {
            const cc = (c + dc) | 0
            let blocked = 1
            let d = ENEMY_NAV_INF

            if (rr >= 0 && rr < rows && cc >= 0 && cc < cols) {
                blocked = _enemyNavIsBaseBlocked(rr, cc) ? 1 : 0
                const idx = _enemyNavIdx(rr, cc) | 0
                if (_enemyNavDist && idx >= 0 && idx < _enemyNavDist.length) d = _enemyNavDist[idx] | 0
            }

            maskLine += blocked ? "1" : "0"
            distParts.push((d >= 0 && d < ENEMY_NAV_INF) ? d.toString() : "INF")
        }

        console.log(`[enemy][navlog][localsnap] r=${rr} mask=${maskLine} dist=${distParts.join(",")}`)
    }
}


function _engineSetPaused(flag: boolean, reason?: string): void {
    const now = (game && typeof game.runtime === "function") ? (game.runtime() | 0) : 0
    if (flag) {
        if (_enginePaused) return
        _enginePaused = true
        _enginePausedReason = reason || ""
        _enginePausedAtMs = now

        // Freeze movement immediately.
        for (let hi = 0; hi < heroes.length; hi++) {
            const h = heroes[hi]
            if (!h) continue
            h.vx = 0
            h.vy = 0
        }
        for (let ei = 0; ei < enemies.length; ei++) {
            const e = enemies[ei]
            if (!e) continue
            e.vx = 0
            e.vy = 0
        }
        return
    }

    if (!_enginePaused) return
    _enginePaused = false
    _enginePausedReason = ""
    _enginePausedAtMs = 0

    // Force nav rebuild on resume.
    _enemyNavBuiltAtMs = 0
    _enemyNavBuiltWorldRev = -1
    _enemyNavBuiltDecorRev = -1
    _enemyNavBuiltHeroHash = 0

    // Nudge intent dispatch to restart soon after resume.
    nextIntentDispatchMs = ((now + 80) | 0)
}

function _engineIsPaused(): boolean {
    return _enginePaused
}



let _enemyNavBuiltAtMs = 0

let _enemyNavBuiltWorldRev = -1

let _enemyNavBuiltDecorRev = -1

let _enemyNavBuiltHeroHash = 0



const _NAV4_DR: number[] = [-1, 1, 0, 0]

const _NAV4_DC: number[] = [0, 0, -1, 1]



// 8-neighbor steering (diagonals allowed with corner-guard)

const _NAV8_DR: number[] = [-1, 1, 0, 0, -1, -1, 1, 1]

const _NAV8_DC: number[] = [0, 0, -1, 1, -1, 1, -1, 1]





function _enemyNavCanOccupyCellForDims(
    colliderW: number,
    colliderH: number,
    r: number,
    c: number,
    maxFootprintPx?: number
): boolean {

    const tile = WORLD_TILE_SIZE | 0

    const maxPx = (maxFootprintPx != null ? (maxFootprintPx | 0) : (ENEMY_NAV_FOOTPRINT_MAX_PX | 0)) | 0
    const navW = Math.min(colliderW | 0, maxPx) | 0
    const navH = Math.min(colliderH | 0, maxPx) | 0

    // Interpret (r,c) as the tile containing the enemy's FOOTPRINT CENTER.
    const centerX = (c * tile + (tile >> 1)) | 0
    const centerY = (r * tile + (tile >> 1)) | 0

    const halfW = Math.idiv(navW, 2) | 0
    const halfH = Math.idiv(navH, 2) | 0

    const left = (centerX - halfW) | 0
    const top = (centerY - halfH) | 0
    const right = (left + navW - 1) | 0
    const bottom = (top + navH - 1) | 0

    let c0 = Math.idiv(left, tile) | 0
    let c1 = Math.idiv(right, tile) | 0
    let r0 = Math.idiv(top, tile) | 0
    let r1 = Math.idiv(bottom, tile) | 0

    if (r0 < 0 || c0 < 0 || r1 >= (_enemyNavRows | 0) || c1 >= (_enemyNavCols | 0)) return false

    for (let rr = r0; rr <= r1; rr++) {
        for (let cc = c0; cc <= c1; cc++) {
            if (_enemyNavIsBlocked(rr | 0, cc | 0)) return false
        }
    }

    return true
}



function _enemyGetColliderDims(enemy: Sprite): { w: number, h: number } {

    // Prefer aura bounds (direction-aware) if available.
    const auraFrameW = sprites.readDataNumber(enemy, "__monsterAuraFrameW") | 0
    const auraFrameH = sprites.readDataNumber(enemy, "__monsterAuraFrameH") | 0
    const auraMinX = sprites.readDataNumber(enemy, "__monsterAuraMinX") | 0
    const auraMinY = sprites.readDataNumber(enemy, "__monsterAuraMinY") | 0
    const auraMaxX = sprites.readDataNumber(enemy, "__monsterAuraMaxX") | 0
    const auraMaxY = sprites.readDataNumber(enemy, "__monsterAuraMaxY") | 0
    if (auraFrameW > 0 && auraFrameH > 0 && auraMaxX >= auraMinX && auraMaxY >= auraMinY) {
        const aw = ((auraMaxX - auraMinX + 1) | 0)
        const ah = ((auraMaxY - auraMinY + 1) | 0)
        if (aw > 0 && ah > 0) return { w: aw | 0, h: ah | 0 }
    }

    // Prefer the explicit collider dimensions so large art frames don't inflate nav footprint.

    let w = sprites.readDataNumber(enemy, ENEMY_DATA.COLLIDER_W) | 0

    let h = sprites.readDataNumber(enemy, ENEMY_DATA.COLLIDER_H) | 0



    if (w <= 0 || h <= 0) {

        const img: any = (enemy as any).image

        w = ((img && img.width) ? (img.width | 0) : w) | 0

        h = ((img && img.height) ? (img.height | 0) : h) | 0

    }



    return { w: (w > 0 ? w : WORLD_TILE_SIZE) | 0, h: (h > 0 ? h : WORLD_TILE_SIZE) | 0 }

}





function _enemyNavIdx(r: number, c: number): number {

    return ((r * _enemyNavCols) + c) | 0

}



function _enemyNavEnsureCapacity(rows: number, cols: number): void {

    rows |= 0

    cols |= 0

    const need = (rows * cols) | 0



    if (_enemyNavRows !== rows || _enemyNavCols !== cols || !_enemyNavDist || _enemyNavDist.length !== need) {

        _enemyNavRows = rows

        _enemyNavCols = cols

        _enemyNavDist = []

        _enemyNavDecorBlock = []

        _enemyNavDeadEnd = []

        _enemyNavTempDeg = []

        _enemyNavTempProtect = []

        _enemyNavTempSeen = []

        for (let i = 0; i < need; i++) {

            _enemyNavDist.push(ENEMY_NAV_INF)

            _enemyNavDecorBlock.push(0)

            _enemyNavDeadEnd.push(0)

            _enemyNavTempDeg.push(0)

            _enemyNavTempProtect.push(0)

            _enemyNavTempSeen.push(0)

        }

    } else if (!_enemyNavDeadEnd || _enemyNavDeadEnd.length !== need || !_enemyNavTempDeg || _enemyNavTempDeg.length !== need || !_enemyNavTempProtect || _enemyNavTempProtect.length !== need || !_enemyNavTempSeen || _enemyNavTempSeen.length !== need) {

        // Arrays got reset elsewhere; re-allocate to expected size.

        _enemyNavRows = rows

        _enemyNavCols = cols

        _enemyNavDeadEnd = []

        _enemyNavTempDeg = []

        _enemyNavTempProtect = []

        _enemyNavTempSeen = []

        for (let i = 0; i < need; i++) {

            _enemyNavDeadEnd.push(0)

            _enemyNavTempDeg.push(0)

            _enemyNavTempProtect.push(0)

            _enemyNavTempSeen.push(0)

        }

    }

}



function _enemyAstarEnsureScratch(need: number): void {
    if (!_enemyAstarG || _enemyAstarG.length < need) _enemyAstarG = new Array(need)
    if (!_enemyAstarCameFrom || _enemyAstarCameFrom.length < need) _enemyAstarCameFrom = new Array(need)
    if (!_enemyAstarSeen || _enemyAstarSeen.length < need) _enemyAstarSeen = new Array(need)
    if (!_enemyAstarClosed || _enemyAstarClosed.length < need) _enemyAstarClosed = new Array(need)
    if (!_enemyAstarSeenList) _enemyAstarSeenList = []
    if (!_enemyAstarClosedList) _enemyAstarClosedList = []
}

function _enemyAstarResetScratch(): void {
    if (_enemyAstarSeenList && _enemyAstarSeenList.length > 0) {
        for (let i = 0; i < _enemyAstarSeenList.length; i++) _enemyAstarSeen[_enemyAstarSeenList[i] | 0] = 0
        _enemyAstarSeenList.length = 0
    }
    if (_enemyAstarClosedList && _enemyAstarClosedList.length > 0) {
        for (let i = 0; i < _enemyAstarClosedList.length; i++) _enemyAstarClosed[_enemyAstarClosedList[i] | 0] = 0
        _enemyAstarClosedList.length = 0
    }
}

function _enemyAstarRebuildBlocked(rows: number, cols: number, heroHash: number): void {
    rows |= 0; cols |= 0
    const need = (rows * cols) | 0
    if (need <= 0) return

    _enemyAstarEnsureScratch(need)

    if (!_enemyAstarBlocked || _enemyAstarBlocked.length !== need) {
        _enemyAstarBlocked = []
        for (let i = 0; i < need; i++) _enemyAstarBlocked.push(0)
    }

    for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
            const idx = ((r * cols) + c) | 0
            _enemyAstarBlocked[idx] = _enemyNavIsBlocked(r, c) ? 1 : 0
        }
    }

    _enemyAstarRows = rows
    _enemyAstarCols = cols
    _enemyAstarWorldRev = _engineWorldRev | 0
    _enemyAstarDecorRev = _engineDecorRev | 0
    _enemyAstarHeroHash = heroHash | 0
}

function _enemyPfEnsureGrid(): void {
    if (!_engineWorldTileMap || _engineWorldTileMap.length === 0) return
    const rows = _engineWorldTileMap.length | 0
    const cols = _engineWorldTileMap[0].length | 0
    if (rows <= 0 || cols <= 0) return

    const worldRev = _engineWorldRev | 0
    const decorRev = _engineDecorRev | 0
    const heroHash = _enemyNavBuiltHeroHash | 0

    if (_enemyPFGrid && _enemyPFFinder && _enemyPFWorldRev === worldRev && _enemyPFDecorRev === decorRev && _enemyPFHeroHash === heroHash) {
        // Keep if dimensions still match
        const gw: any = (_enemyPFGrid as any)
        if (gw && (gw.width | 0) === (cols | 0) && (gw.height | 0) === (rows | 0)) return
    }

    const matrix: number[][] = []
    for (let r = 0; r < rows; r++) {
        const line: number[] = []
        for (let c = 0; c < cols; c++) {
            line.push(_enemyNavIsBlocked(r, c) ? 1 : 0)
        }
        matrix.push(line)
    }

    _enemyPFGrid = new PFGrid(matrix)
    _enemyPFWorldRev = worldRev
    _enemyPFDecorRev = decorRev
    _enemyPFHeroHash = heroHash
    _enemyPFFinder = new PFAStarFinder({
        diagonalMovement: PFDiagonalMovement.IfAtMostOneObstacle,
        heuristic: PFHeuristic.octile
    })
}


function _enemyNavComputeHeroHash(heroTargets: Sprite[]): number {

    if (!_engineWorldTileMap || _engineWorldTileMap.length === 0) return 0

    const rows = _engineWorldTileMap.length | 0
    const cols = _engineWorldTileMap[0].length | 0
    const tileSize = WORLD_TILE_SIZE | 0

    let h = 0

    for (let i = 0; i < heroTargets.length; i++) {

        const hero = heroTargets[i]
        if (!hero) continue

        // Use HERO COLLISION (feet), not sprite center.
        const hb = _boundsWithOffset(hero, _heroCollisionOffsetY(hero))
        const footX = hb.centerX | 0
        const footY = hb.bottom | 0

        let r = Math.idiv(footY, tileSize) | 0
        let c = Math.idiv(footX, tileSize) | 0

        if (r < 0) r = 0
        else if (r >= rows) r = rows - 1

        if (c < 0) c = 0
        else if (c >= cols) c = cols - 1

        const v = ((r * cols) + c) | 0
        h = (((h * 131) | 0) ^ v) | 0
    }

    return h | 0
}



function _enemyNavRebuildDecorBlocks(rows: number, cols: number): void {

    rows |= 0

    cols |= 0

    const need = (rows * cols) | 0

    if (!_enemyNavDecorBlock || _enemyNavDecorBlock.length !== need) return



    for (let i = 0; i < need; i++) _enemyNavDecorBlock[i] = 0

    if (!_engineDecorSolids || _engineDecorSolids.length === 0) return



    const tileSize = WORLD_TILE_SIZE | 0



    for (let i = 0; i < _engineDecorSolids.length; i++) {

        const s = _engineDecorSolids[i]

        if (!s || (s.flags & sprites.Flag.Destroyed)) continue



        const img: any = (s as any).image

        const w = ((img && img.width) ? (img.width | 0) : ((s as any).width | 0)) || tileSize

        const h = ((img && img.height) ? (img.height | 0) : ((s as any).height | 0)) || tileSize



        let left = ((s as any).left != null) ? (((s as any).left | 0)) : ((s.x | 0) - (w >> 1))

        let top = ((s as any).top != null) ? (((s as any).top | 0)) : ((s.y | 0) - (h >> 1))



        let right = ((s as any).right != null) ? (((s as any).right | 0)) : ((left + w) | 0)

        let bottom = ((s as any).bottom != null) ? (((s as any).bottom | 0)) : ((top + h) | 0)



        // Convert to tile rect

        let c0 = Math.idiv(left, tileSize) | 0

        let c1 = Math.idiv((right - 1) | 0, tileSize) | 0

        let r0 = Math.idiv(top, tileSize) | 0

        let r1 = Math.idiv((bottom - 1) | 0, tileSize) | 0



        if (c0 < 0) c0 = 0

        if (r0 < 0) r0 = 0

        if (c1 >= cols) c1 = cols - 1

        if (r1 >= rows) r1 = rows - 1



        const aabbUseAura = (sprites.readDataNumber(s, DECOR_SOLID_AABB_USE_AURA_KEY) | 0) !== 0
        if (aabbUseAura) {
            const aabbTex = sprites.readDataString(s, DECOR_SOLID_AABB_TEX_KEY) || ""
            const aabbFrame = sprites.readDataNumber(s, DECOR_SOLID_AABB_FRAME_KEY) | 0
            const rawX = sprites.readDataNumber(s, DECOR_SOLID_AABB_RAW_X_KEY) | 0
            const rawY = sprites.readDataNumber(s, DECOR_SOLID_AABB_RAW_Y_KEY) | 0
            const mode = sprites.readDataNumber(s, DECOR_SOLID_AABB_MODE_KEY) | 0
            const baseMinX = sprites.readDataNumber(s, DECOR_SOLID_BASE_MIN_X_KEY) | 0
            const baseMaxX = sprites.readDataNumber(s, DECOR_SOLID_BASE_MAX_X_KEY) | 0
            const baseH = sprites.readDataNumber(s, DECOR_SOLID_BASE_H_KEY) | 0
            const mask = getAuraMaskFrameView(aabbTex, aabbFrame)
            if (mask) {
                const frameLeft = ((left | 0) - (rawX | 0)) | 0
                const frameTop = ((top | 0) - (rawY | 0)) | 0
                for (let rr = r0; rr <= r1; rr++) {
                    for (let cc = c0; cc <= c1; cc++) {
                        const tileLeft = ((cc * tileSize) | 0)
                        const tileTop = ((rr * tileSize) | 0)
                        const tileRight = ((tileLeft + tileSize - 1) | 0)
                        const tileBottom = ((tileTop + tileSize - 1) | 0)
                        const hit = _auraMaskOverlapsBox(
                            mask,
                            frameLeft,
                            frameTop,
                            tileLeft,
                            tileRight,
                            tileTop,
                            tileBottom,
                            (mode | 0) === DECOR_SOLID_AABB_MODE_BASE,
                            baseMinX | 0,
                            baseMaxX | 0,
                            baseH | 0
                        )
                        if (hit) _enemyNavDecorBlock[_enemyNavIdx(rr, cc)] = 1
                    }
                }
                continue
            }
        }

        for (let rr = r0; rr <= r1; rr++) {
            for (let cc = c0; cc <= c1; cc++) {
                _enemyNavDecorBlock[_enemyNavIdx(rr, cc)] = 1
            }
        }

    }

}



function _enemyNavIsBaseBlocked(r: number, c: number): boolean {

    if (!_engineWorldTileMap || _engineWorldTileMap.length === 0) return true

    if (r < 0 || c < 0 || r >= _enemyNavRows || c >= _enemyNavCols) return true



    if (_tileIsSolidType(_engineWorldTileMap[r][c] | 0)) return true

    const idx = _enemyNavIdx(r, c)

    if (_enemyNavDecorBlock && _enemyNavDecorBlock.length > idx && (_enemyNavDecorBlock[idx] | 0) !== 0) return true



    return false

}



function _enemyNavIsBlocked(r: number, c: number): boolean {

    if (_enemyNavIsBaseBlocked(r, c)) return true



    const idx = _enemyNavIdx(r, c)

    if (_enemyNavDeadEnd && _enemyNavDeadEnd.length > idx && (_enemyNavDeadEnd[idx] | 0) !== 0) return true



    return false

}



function _enemyNavMarkDeadEnds(rows: number, cols: number, heroTargets: Sprite[]): void {

    rows |= 0; cols |= 0

    const need = (rows * cols) | 0

    if (need <= 0) return

    if (!_engineWorldTileMap || _engineWorldTileMap.length === 0) return

    if (!_enemyNavDeadEnd || _enemyNavDeadEnd.length !== need) return

    if (!_enemyNavTempDeg || _enemyNavTempDeg.length !== need) return

    if (!_enemyNavTempProtect || _enemyNavTempProtect.length !== need) return

    if (!_enemyNavTempSeen || _enemyNavTempSeen.length !== need) return



    for (let i = 0; i < need; i++) {

        _enemyNavDeadEnd[i] = 0

        _enemyNavTempDeg[i] = 0

        _enemyNavTempProtect[i] = 0

        _enemyNavTempSeen[i] = 0

    }



    const tileSize = WORLD_TILE_SIZE | 0

    const clampedIdx = (y: number, x: number): number => {

        let r = Math.idiv(y | 0, tileSize) | 0

        let c = Math.idiv(x | 0, tileSize) | 0

        if (r < 0) r = 0

        else if (r >= rows) r = rows - 1

        if (c < 0) c = 0

        else if (c >= cols) c = cols - 1

        return _enemyNavIdx(r, c) | 0

    }



    // Protect heroes, spawners, and any live enemies so we never wall off an active entity.

    if (heroTargets) {

        for (let i = 0; i < heroTargets.length; i++) {

            const h = heroTargets[i]

            if (!h) continue

            _enemyNavTempProtect[clampedIdx(h.y, h.x)] = 1

        }

    }

    if (enemySpawners) {

        for (let i = 0; i < enemySpawners.length; i++) {

            const s = enemySpawners[i]

            if (!s || (s.flags & sprites.Flag.Destroyed)) continue

            _enemyNavTempProtect[clampedIdx(s.y, s.x)] = 1

        }

    }

    if (enemies) {

        for (let i = 0; i < enemies.length; i++) {

            const e = enemies[i]

            if (!e || (e.flags & sprites.Flag.Destroyed)) continue

            _enemyNavTempProtect[clampedIdx(e.y, e.x)] = 1

        }

    }



    const leafQ: number[] = []

    let leafHead = 0



    // Compute degree for each passable cell and queue leaves that aren't protected.

    for (let r = 0; r < rows; r++) {

        for (let c = 0; c < cols; c++) {

            const idx = _enemyNavIdx(r, c) | 0

            if (_enemyNavIsBaseBlocked(r, c)) {

                _enemyNavTempDeg[idx] = -1

                continue

            }



            let deg = 0

            for (let k = 0; k < 4; k++) {

                const nr = (r + _NAV4_DR[k]) | 0

                const nc = (c + _NAV4_DC[k]) | 0

                if (!_enemyNavIsBaseBlocked(nr, nc)) deg++

            }

            _enemyNavTempDeg[idx] = deg

            if (deg <= 1 && (_enemyNavTempProtect[idx] | 0) === 0) {

                leafQ.push(idx)

            }

        }

    }



    // Iteratively peel cul-de-sacs that don't contain a protected entity.

    while (leafHead < leafQ.length) {

        const idx = leafQ[leafHead++] | 0

        if ((_enemyNavDeadEnd[idx] | 0) !== 0) continue

        _enemyNavDeadEnd[idx] = 1



        const r = Math.idiv(idx, cols) | 0

        const c = (idx - (r * cols)) | 0



        for (let k = 0; k < 4; k++) {

            const nr = (r + _NAV4_DR[k]) | 0

            const nc = (c + _NAV4_DC[k]) | 0

            if (_enemyNavIsBaseBlocked(nr, nc)) continue



            const nIdx = _enemyNavIdx(nr, nc) | 0

            if ((_enemyNavDeadEnd[nIdx] | 0) !== 0) continue



            _enemyNavTempDeg[nIdx] = ((_enemyNavTempDeg[nIdx] | 0) - 1) | 0

            if ((_enemyNavTempDeg[nIdx] | 0) <= 1 && (_enemyNavTempProtect[nIdx] | 0) === 0) {

                leafQ.push(nIdx)

            }

        }

    }



    // Discard oversized dead-end regions so we only suppress small pockets/indentations.

    if ((ENEMY_NAV_DEAD_END_MAX_CELLS | 0) > 0) {

        const compQ: number[] = []

        const compList: number[] = []



        for (let i = 0; i < need; i++) {

            if ((_enemyNavDeadEnd[i] | 0) === 0 || (_enemyNavTempSeen[i] | 0) !== 0) continue



            compQ.length = 0

            compList.length = 0

            compQ.push(i)

            _enemyNavTempSeen[i] = 1

            let compHead = 0



            while (compHead < compQ.length) {

                const idx = compQ[compHead++] | 0

                compList.push(idx)



                const r = Math.idiv(idx, cols) | 0

                const c = (idx - (r * cols)) | 0



                for (let k = 0; k < 4; k++) {

                    const nr = (r + _NAV4_DR[k]) | 0

                    const nc = (c + _NAV4_DC[k]) | 0

                    if (_enemyNavIsBaseBlocked(nr, nc)) continue



                    const nIdx = _enemyNavIdx(nr, nc) | 0

                    if ((_enemyNavDeadEnd[nIdx] | 0) === 0) continue

                    if ((_enemyNavTempSeen[nIdx] | 0) !== 0) continue



                    _enemyNavTempSeen[nIdx] = 1

                    compQ.push(nIdx)

                }

            }



            if (compList.length > (ENEMY_NAV_DEAD_END_MAX_CELLS | 0)) {

                for (let j = 0; j < compList.length; j++) {

                    _enemyNavDeadEnd[compList[j] | 0] = 0

                }

            }

        }

    }

}



function _enemyNavRebuildDistanceField(heroTargets: Sprite[], heroHash: number): void {

    if (!_engineWorldTileMap || _engineWorldTileMap.length === 0) return

    const map = _engineWorldTileMap
    const rows = map.length | 0
    const cols = map[0].length | 0
    const tileSize = WORLD_TILE_SIZE | 0

    _enemyNavEnsureCapacity(rows, cols)

    const need = (rows * cols) | 0

    // Reset dist to INF
    for (let i = 0; i < need; i++) _enemyNavDist[i] = ENEMY_NAV_INF

    // Rebuild decor blocking grid (so enemies avoid statue/chest solids too)
    _enemyNavRebuildDecorBlocks(rows, cols)
    _enemyNavMarkDeadEnds(rows, cols, heroTargets)
    _enemyAstarRebuildBlocked(rows, cols, heroHash | 0)

    const qr: number[] = []
    const qc: number[] = []
    let head = 0

    // Multi-source BFS: all heroes are sources with dist=0
    for (let i = 0; i < heroTargets.length; i++) {

        const hero = heroTargets[i]
        if (!hero) continue

        // Use HERO COLLISION (feet), not sprite center.
        const hb = _boundsWithOffset(hero, _heroCollisionOffsetY(hero))
        const footX = hb.centerX | 0
        const footY = hb.bottom | 0

        let sr = Math.idiv(footY, tileSize) | 0
        let sc = Math.idiv(footX, tileSize) | 0

        if (sr < 0) sr = 0
        else if (sr >= rows) sr = rows - 1

        if (sc < 0) sc = 0
        else if (sc >= cols) sc = cols - 1

        const sIdx = ((sr * cols) + sc) | 0

        if ((_enemyNavDist[sIdx] | 0) !== 0) {
            _enemyNavDist[sIdx] = 0
            qr.push(sr)
            qc.push(sc)
        }
    }

    if (qr.length === 0) return

    while (head < qr.length) {

        const r = qr[head] | 0
        const c = qc[head] | 0
        head++

        const baseIdx = ((r * cols) + c) | 0
        const baseD = _enemyNavDist[baseIdx] | 0
        const nextD = (baseD + 1) | 0

        for (let k = 0; k < 4; k++) {

            const nr = (r + _NAV4_DR[k]) | 0
            const nc = (c + _NAV4_DC[k]) | 0

            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue
            if (_enemyNavIsBlocked(nr, nc)) continue

            const nIdx = ((nr * cols) + nc) | 0
            const cur = _enemyNavDist[nIdx] | 0
            if (cur <= nextD) continue

            _enemyNavDist[nIdx] = nextD
            qr.push(nr)
            qc.push(nc)
        }
    }
}



function _enemyNavMaybeRebuild(nowMs: number, heroTargets: Sprite[]): void {

    if (!_engineWorldTileMap || _engineWorldTileMap.length === 0) return

    if (!heroTargets || heroTargets.length === 0) return



    const now = nowMs | 0

    const worldRev = _engineWorldRev | 0

    const decorRev = _engineDecorRev | 0

    const heroHash = _enemyNavComputeHeroHash(heroTargets) | 0



    const age = (now - (_enemyNavBuiltAtMs | 0)) | 0

    const needs =

        (worldRev !== (_enemyNavBuiltWorldRev | 0)) ||

        (decorRev !== (_enemyNavBuiltDecorRev | 0)) ||

        (heroHash !== (_enemyNavBuiltHeroHash | 0)) ||

        (age >= (ENEMY_NAV_REBUILD_MS | 0))



    if (!needs) return



    _enemyNavRebuildDistanceField(heroTargets, heroHash)



    _enemyNavBuiltAtMs = now

    _enemyNavBuiltWorldRev = worldRev

    _enemyNavBuiltDecorRev = decorRev

    _enemyNavBuiltHeroHash = heroHash

}



function _enemyNavShouldLog(enemy: Sprite, tileIdx: number, x: number, y: number, force: boolean): boolean {
    if (!DEBUG_ENEMY_NAV_LOG) return false

    const now = game.runtime() | 0
    const eid = getEnemyIndex(enemy)
    const spawnerId = sprites.readDataNumber(enemy, ENEMY_DATA.SPAWNER_ID) | 0
    const map = _engineWorldTileMap
    const tileSize = WORLD_TILE_SIZE | 0
    let worldW = 160
    let worldH = 120
    if (map && map.length > 0 && map[0].length > 0) {
        worldH = (map.length * tileSize) | 0
        worldW = (map[0].length * tileSize) | 0
    }

    // Spawner gating: only the first enemy spawned from each spawner logs until worldRev changes.
    if (!force && eid >= 0) {
        const worldRev = _engineWorldRev | 0
        if (!_enemyNavSpawnerLogger || _enemyNavSpawnerLogger.length < enemySpawners.length) {
            _enemyNavSpawnerLogger = []
            for (let i = 0; i < enemySpawners.length; i++) _enemyNavSpawnerLogger.push(-1)
        }

        if (_enemyNavQuadOwnerRev[0] !== worldRev) {
            for (let i = 0; i < _enemyNavSpawnerLogger.length; i++) _enemyNavSpawnerLogger[i] = -1
            _enemyNavQuadOwnerRev[0] = worldRev
        }

        if (spawnerId >= 0 && spawnerId < _enemyNavSpawnerLogger.length) {
            const owner = _enemyNavSpawnerLogger[spawnerId] | 0
            if (owner === -1) {
                _enemyNavSpawnerLogger[spawnerId] = eid | 0
            } else if (owner !== (eid | 0)) {
                return false
            }
        }
    }

    if (force) return true

    const e: any = enemy as any
    if (!e) return false

    if (ENEMY_NAV_LOG_TILE_CHANGE_ONLY) {
        if (e.__navLogLastTile == null) return true
        return tileIdx !== (e.__navLogLastTile | 0)
    }

    if (e.__navLogLastTile == null) return true
    if (tileIdx !== (e.__navLogLastTile | 0)) return true

    const lx = e.__navLogLastX
    const ly = e.__navLogLastY
    if (lx == null || ly == null) return true

    const dx = (x | 0) - (lx | 0)
    const dy = (y | 0) - (ly | 0)
    return (dx * dx + dy * dy) >= (ENEMY_NAV_LOG_MIN_MOVE_PX2 | 0)
}



function _enemyNavLogAdd(enemy: Sprite, entry: any, force?: boolean): void {
    if (!DEBUG_ENEMY_NAV_LOG) return
    if (!entry) return

    const pos = entry.pos || {}
    const tileIdx = (pos.idx == null) ? -1 : (pos.idx | 0)

    const px = (pos.x == null) ? 0 : (pos.x | 0)

    const py = (pos.y == null) ? 0 : (pos.y | 0)



    if (!_enemyNavShouldLog(enemy, tileIdx, px, py, !!force)) return


    const e: any = enemy as any
    const R = ENEMY_NAV_LOG_RING_SIZE | 0

    if (!e.__navLogRing) {
        e.__navLogRing = new Array(R)
        e.__navLogHead = 0
        e.__navLogSize = 0
        e.__navLogStep = 0
    }

    const step = ((e.__navLogStep | 0) + 1) | 0
    e.__navLogStep = step

    if (entry.step == null) entry.step = step
    if (force) entry.force = true


    const head = (e.__navLogHead | 0)
    const size = (e.__navLogSize | 0)
    e.__navLogRing[head] = entry
    e.__navLogHead = ((head + 1) % R) | 0
    e.__navLogSize = ((size + 1) > R) ? R : ((size + 1) | 0)


    e.__navLogLastTile = tileIdx

    e.__navLogLastX = px

    e.__navLogLastY = py

}



function _enemyNavDump(enemy: Sprite, reason: string): void {
    if (!DEBUG_ENEMY_NAV_LOG) return
    const e: any = enemy as any
    if (!e || !e.__navLogRing) return

    const size = (e.__navLogSize | 0)
    if (size <= 0) return

    const now = game.runtime() | 0
    const lastDump = (e.__navLogLastDump | 0)
    if (lastDump > 0 && (now - lastDump) < (ENEMY_NAV_LOG_DUMP_COOLDOWN_MS | 0)) return
    e.__navLogLastDump = now

    const head = (e.__navLogHead | 0)
    const start = (((head - size) % ENEMY_NAV_LOG_RING_SIZE) + ENEMY_NAV_LOG_RING_SIZE) % ENEMY_NAV_LOG_RING_SIZE
    const enemyIndex = getEnemyIndex(enemy)

    console.log(`[enemy][navlog][dump] reason=${reason} enemyIndex=${enemyIndex} size=${size} now=${now}`)

    // Map snapshot once per worldRev (string-only)
    if (_engineWorldTileMap && _engineWorldTileMap.length > 0 && _engineWorldTileMap[0].length > 0) {
        const rows = _engineWorldTileMap.length | 0
        const cols = _engineWorldTileMap[0].length | 0
        const worldRev = _engineWorldRev | 0
        const decorRev = _engineDecorRev | 0
        const floorIdx = ((_dunFloorIndex | 0) + 1) | 0

        if (_enemyNavLastMapDumpRev !== worldRev) {
            console.log(`[enemy][navlog][map] rows=${rows} cols=${cols} floor=${floorIdx} worldRev=${worldRev} decorRev=${decorRev} legend:1=blocked,0=open`)

            // Helpful ruler (mod 10) for visual alignment
            let ruler = ""
            for (let c = 0; c < cols; c++) ruler += ((c % 10) | 0).toString()
            console.log(`[enemy][navlog][mapcol] ${ruler}`)

            for (let r = 0; r < rows; r++) {
                let line = ""
                for (let c = 0; c < cols; c++) line += _enemyNavIsBaseBlocked(r, c) ? "1" : "0"
                console.log(`[enemy][navlog][maprow] r=${r} ${line}`)
            }

            _enemyNavLastMapDumpRev = worldRev
        } else {
            console.log(`[enemy][navlog][map] skipped (already dumped for worldRev=${worldRev}) floor=${floorIdx}`)
        }
    }

    // TSV header for copy/paste
    if (ENEMY_NAV_LOG_FORMAT_TSV) {
        if (ENEMY_NAV_LOG_TSV_HEADER_EVERY_DUMP) {
            console.log(`[enemy][navtsv][header]\n${_enemyNavTsvHeader()}`)
        } else {
            console.log(`[enemy][navtsv][header] ${_enemyNavTsvHeader()}`)
        }
    }

    for (let i = 0; i < size; i++) {
        const slot = ((start + i) % ENEMY_NAV_LOG_RING_SIZE) | 0
        const entry = e.__navLogRing[slot]
        if (!entry) continue

        const out = _enemyNavFormatEntryTsv(entry)
        const line = out.line
        const cands = out.cands

        // Always print one TSV line per entry (copy/paste friendly)
        if (ENEMY_NAV_LOG_FORMAT_TSV) {
            _navPrint(`[enemy][navtsv] `, line)

            // Print candidates only when useful (force/stuck), unless you disable this knob.
            const shouldShowCands =
                !ENEMY_NAV_LOG_CANDS_ON_FORCE_ONLY ||
                entry.reason === "no_neighbor" ||
                entry.reason === "stay" ||
                entry.reason === "curDistInf" ||
                entry.reason === "stuck" ||
                entry.force === true

            if (cands && shouldShowCands) {
                _navPrint(`[enemy][navtsv][cands] `, `eid=${_navNum(entry.eid)} step=${_navNum(entry.step)} ${cands}`)
            }
        } else {
            // fallback (shouldn't be used if TSV is on)
            console.log(`[enemy][navlog][entry] ${line}`)
        }
    }
}

function _enemyNavGetEnemyFeetPoint(enemy: Sprite, cw: number, ch: number) {
    const maxPx = _enemyNavMaxFootprintPx(enemy) | 0
    const footW = Math.min(cw | 0, maxPx) | 0
    const footH = Math.min(ch | 0, maxPx) | 0

    const auraFrameH = sprites.readDataNumber(enemy, "__monsterAuraFrameH") | 0
    if (auraFrameH > 0) {
        const auraMaxY = sprites.readDataNumber(enemy, "__monsterAuraMaxY") | 0
        const auraCenterY = sprites.readDataNumber(enemy, "__monsterAuraCenterY") | 0
        const auraFoot = sprites.readDataNumber(enemy, "__monsterAuraFootBottom") | 0

        const maxY = (auraMaxY > 0) ? (auraMaxY | 0) : ((auraFoot > 0) ? (auraFoot | 0) : ((auraFrameH - 1) | 0))
        const centerY = (auraCenterY > 0) ? (auraCenterY | 0) : (Math.round((auraFrameH - 1) / 2) | 0)

        const footX = enemy.x | 0
        const footY = (((enemy.y | 0) + (maxY - centerY)) | 0)
        const centerX = footX | 0
        const centerYWorld = ((footY - Math.idiv((footH - 1) | 0, 2)) | 0)
        return { footX, footY, centerX, centerY: centerYWorld, offY: 0, dispH: auraFrameH | 0, footW, footH }
    }

    const img: any = (enemy as any).image
    const dispH = (((img && img.height) ? (img.height | 0) : (((enemy as any).height | 0) || 0)) | 0) || (ch | 0)

    let offY = Math.idiv((dispH - (ch | 0)) | 0, 2) | 0
    if (offY < 0) offY = 0

    const footX = enemy.x | 0
    const footY = (((enemy.y | 0) + offY + (Math.idiv((ch | 0), 2) | 0) - 1) | 0)
    const centerX = footX | 0
    const centerY = ((footY - Math.idiv((footH - 1) | 0, 2)) | 0)
    return { footX, footY, centerX, centerY, offY, dispH, footW, footH }
}

function _enemyNavClampTileRC(r: number, c: number) {
    const rr = r | 0
    const cc = c | 0
    if (rr < 0 || cc < 0 || rr >= (_enemyNavRows | 0) || cc >= (_enemyNavCols | 0)) return null
    return { r: rr, c: cc }
}

function _enemyNavMaxFootprintPx(enemy: Sprite | null): number {
    if (enemy && _enemyIsBoss(enemy)) return ENEMY_NAV_FOOTPRINT_BOSS_PX | 0
    return ENEMY_NAV_FOOTPRINT_MAX_PX | 0
}

function _enemyNavClearNavTargetData(enemy: Sprite): void {
    sprites.setDataNumber(enemy, ENEMY_AI_NAV_TARGET_R, -1)
    sprites.setDataNumber(enemy, ENEMY_AI_NAV_TARGET_C, -1)
    sprites.setDataNumber(enemy, ENEMY_AI_NAV_TARGET_D, ENEMY_NAV_INF)
}

function _enemyNavGetAllowUp(nowMs: number, enemy: Sprite) {
    const stuckUntil = sprites.readDataNumber(enemy, ENEMY_AI_STUCK_UNTIL) | 0
    const allowUp = (stuckUntil > 0 && (nowMs | 0) < stuckUntil) ? 1 : 0
    return { stuckUntil, allowUp }
}

function _enemyNavGetLastIdx(enemy: Sprite, curIdx: number) {
    let lastNavIdx = sprites.readDataNumber(enemy, ENEMY_AI_LAST_NAV_IDX)
    if (lastNavIdx === 0 && (curIdx | 0) !== 0) lastNavIdx = -1
    return lastNavIdx | 0
}

function _enemyNavComputeAlign(dr: number, dc: number, vx: number, vy: number) {
    const vMag = Math.abs(vx) + Math.abs(vy)
    if (vMag <= 0.001) return 0
    return (((dr | 0) * vx) + ((dc | 0) * vy)) / vMag
}

function _enemyNavIsDiagBlockedForFootprint(
    r: number,
    c: number,
    nr: number,
    nc: number,
    cw: number,
    ch: number,
    maxFootprintPx?: number
) {
    // diag corner-cut guard (+ footprint guard on adjacent cardinals)
    if (_enemyNavIsBlocked(r | 0, nc | 0) || _enemyNavIsBlocked(nr | 0, c | 0)) return true
    if (!_enemyNavCanOccupyCellForDims(cw | 0, ch | 0, r | 0, nc | 0, maxFootprintPx)) return true
    if (!_enemyNavCanOccupyCellForDims(cw | 0, ch | 0, nr | 0, c | 0, maxFootprintPx)) return true
    return false
}

function _enemyNavMarkChosenCandidate(candidates: any[] | null, bestR: number, bestC: number): void {
    if (!candidates) return
    for (let i = 0; i < candidates.length; i++) {
        const cand = candidates[i]
        if (cand && (cand.r | 0) === (bestR | 0) && (cand.c | 0) === (bestC | 0)) cand.chosen = 1
    }
}

function _enemyNavApplyVelocityTowardTileCenter(enemy: Sprite, speed: number, originX: number, originY: number, bestR: number, bestC: number): void {
    const tileSize = WORLD_TILE_SIZE | 0
    const tx = (bestC * tileSize + (tileSize >> 1)) | 0
    const ty = (bestR * tileSize + (tileSize >> 1)) | 0

    const dx = (tx - (originX | 0)) | 0
    const dy = (ty - (originY | 0)) | 0

    let mag = Math.sqrt(dx * dx + dy * dy)
    if (mag <= 0.001) mag = 1

    enemy.vx = Math.idiv(dx * (speed | 0), mag)
    enemy.vy = Math.idiv(dy * (speed | 0), mag)
}


function _enemySteerTowardAStar(enemy: Sprite, targetX: number, targetY: number, speed: number): boolean {
    
    if (!_engineWorldTileMap || _engineWorldTileMap.length === 0) return false
    const rows = _engineWorldTileMap.length | 0
    const cols = _engineWorldTileMap[0].length | 0
    if (rows <= 0 || cols <= 0) return false

    const tileSize = WORLD_TILE_SIZE | 0
    const dims = _enemyGetColliderDims(enemy)
    const cw = dims.w | 0
    const ch = dims.h | 0
    const navMaxPx = _enemyNavMaxFootprintPx(enemy) | 0
    const feet = _enemyNavGetEnemyFeetPoint(enemy, cw, ch)
    const footX = feet.footX | 0
    const footY = feet.footY | 0
    const navX = (feet.centerX != null) ? (feet.centerX | 0) : footX
    const navY = (feet.centerY != null) ? (feet.centerY | 0) : footY

    let sr = Math.idiv(navY, tileSize) | 0
    let sc = Math.idiv(navX, tileSize) | 0
    if (sr < 0) sr = 0
    else if (sr >= rows) sr = rows - 1
    if (sc < 0) sc = 0
    else if (sc >= cols) sc = cols - 1

    let gr = Math.idiv(targetY | 0, tileSize) | 0
    let gc = Math.idiv(targetX | 0, tileSize) | 0
    if (gr < 0) gr = 0
    else if (gr >= rows) gr = rows - 1
    if (gc < 0) gc = 0
    else if (gc >= cols) gc = cols - 1

    const startIdx = ((sr * cols) + sc) | 0
    const heroR = sprites.readDataNumber(enemy, ENEMY_AI_NAV_HERO_R) | 0
    const heroC = sprites.readDataNumber(enemy, ENEMY_AI_NAV_HERO_C) | 0
    const heroEX = sprites.readDataNumber(enemy, ENEMY_AI_NAV_HERO_EX) | 0
    const heroEY = sprites.readDataNumber(enemy, ENEMY_AI_NAV_HERO_EY) | 0
    const phaseStr = (sprites.readDataString(enemy, "phase") || "walk") as string
    const monsterId = sprites.readDataString(enemy, "monsterId") || sprites.readDataString(enemy, "id") || ""
    const eid = getEnemyIndex(enemy) | 0
    const nowMs = game.runtime() | 0
    const lastNavIdx = sprites.readDataNumber(enemy, ENEMY_AI_LAST_NAV_IDX) | 0
    const stuckMode = sprites.readDataNumber(enemy, ENEMY_AI_STUCK_MODE) | 0
    const stuckUntil = sprites.readDataNumber(enemy, ENEMY_AI_STUCK_UNTIL) | 0
    const curMask = (_enemyNavDeadEnd && _enemyNavDeadEnd.length > startIdx) ? (_enemyNavDeadEnd[startIdx] | 0) : 0

    const wantLog = DEBUG_ENEMY_NAV_LOG && _enemyNavShouldLog(enemy, startIdx, navX, navY, false)

    _enemyPfEnsureGrid()
    if (!_enemyPFGrid || !_enemyPFFinder) return false

    const grid = _enemyPFGrid.clone()
    grid.setWalkableAt(sc, sr, true)
    grid.setWalkableAt(gc, gr, true)

    const path = _enemyPFFinder.findPath(sc, sr, gc, gr, grid) as number[][]
    const pathLen = path ? (path.length | 0) : 0

    if (!path || pathLen === 0) {
        _enemyNavClearNavTargetData(enemy)
        if (DEBUG_ENEMY_NAV_LOG && wantLog) {
            _enemyNavLogAdd(enemy, {
                eid,
                mid: monsterId,
                t: nowMs,
                reason: "pf_astar_fail",
                pos: { x: navX, y: navY, r: sr, c: sc, idx: startIdx },
                dist: { cur: 0, mask: curMask, allowUp: 0 },
                nav: { lastIdx: lastNavIdx, astar: { path: 0, goalR: gr, goalC: gc } },
                hero: { r: heroR || gr, c: heroC || gc, ex: heroEX || (targetX | 0), ey: heroEY || (targetY | 0) },
                phase: phaseStr,
                stuck: { until: stuckUntil, mode: stuckMode },
                speed,
                vel: { vx: enemy.vx | 0, vy: enemy.vy | 0 }
            }, true)
        }
        return false
    }

    let nextC = gc | 0
    let nextR = gr | 0
    if (pathLen >= 2) {
        nextC = path[1][0] | 0
        nextR = path[1][1] | 0
    }

    // Footprint guard for the chosen next tile; fall back if too tight.
    if (!_enemyNavCanOccupyCellForDims(cw, ch, nextR, nextC, navMaxPx)) {
        _enemyNavClearNavTargetData(enemy)
        return false
    }

    sprites.setDataNumber(enemy, ENEMY_AI_LAST_NAV_IDX, startIdx)
    sprites.setDataNumber(enemy, ENEMY_AI_NAV_TARGET_R, nextR)
    sprites.setDataNumber(enemy, ENEMY_AI_NAV_TARGET_C, nextC)
    sprites.setDataNumber(enemy, ENEMY_AI_NAV_TARGET_D, pathLen | 0)

    _enemyNavApplyVelocityTowardTileCenter(enemy, speed, navX, navY, nextR, nextC)

    if (DEBUG_ENEMY_NAV_LOG && wantLog) {
        _enemyNavLogAdd(enemy, {
            eid,
            mid: monsterId,
            t: nowMs,
            reason: "pf_astar",
            pos: { x: navX, y: navY, r: sr, c: sc, idx: startIdx },
            dist: { cur: 0, mask: curMask, allowUp: 0 },
            nav: { lastIdx: lastNavIdx, astar: { path: pathLen | 0, goalR: gr, goalC: gc } },
            pick: { r: nextR, c: nextC, d: pathLen | 0 },
            hero: { r: heroR || gr, c: heroC || gc, ex: heroEX || (targetX | 0), ey: heroEY || (targetY | 0) },
            phase: phaseStr,
            stuck: { until: stuckUntil, mode: stuckMode },
            speed,
            vel: { vx: enemy.vx | 0, vy: enemy.vy | 0 }
        }, false)
    }

    return true
}


function _enemySteerTowardNavField(enemy: Sprite, speed: number): boolean {

    if (!_enemyNavDist || _enemyNavRows <= 0 || _enemyNavCols <= 0) return false

    const tileSize = WORLD_TILE_SIZE | 0

    // --- Enemy FEET (collision) point ---
    const dims = _enemyGetColliderDims(enemy)
    const cw = dims.w | 0
    const ch = dims.h | 0
    const feet = _enemyNavGetEnemyFeetPoint(enemy, cw, ch)

    const footX = feet.footX | 0
    const footY = feet.footY | 0
    const navX = (feet.centerX != null) ? (feet.centerX | 0) : footX
    const navY = (feet.centerY != null) ? (feet.centerY | 0) : footY

    const r0 = Math.idiv(navY, tileSize) | 0
    const c0 = Math.idiv(navX, tileSize) | 0
    const rc = _enemyNavClampTileRC(r0, c0)
    if (!rc) return false

    const r = rc.r | 0
    const c = rc.c | 0

    const curIdx = _enemyNavIdx(r, c) | 0
    const curD = _enemyNavDist[curIdx] | 0
    const nowMs = game.runtime() | 0

    const curMask = (_enemyNavDeadEnd && _enemyNavDeadEnd.length > curIdx) ? (_enemyNavDeadEnd[curIdx] | 0) : 0

    const heroR = sprites.readDataNumber(enemy, ENEMY_AI_NAV_HERO_R) | 0
    const heroC = sprites.readDataNumber(enemy, ENEMY_AI_NAV_HERO_C) | 0
    const heroEX = sprites.readDataNumber(enemy, ENEMY_AI_NAV_HERO_EX) | 0
    const heroEY = sprites.readDataNumber(enemy, ENEMY_AI_NAV_HERO_EY) | 0

    const phaseStr = (sprites.readDataString(enemy, "phase") || "walk") as string
    const stuckMode = sprites.readDataNumber(enemy, ENEMY_AI_STUCK_MODE) | 0
    const monsterId = sprites.readDataString(enemy, "monsterId") || sprites.readDataString(enemy, "id") || ""
    const eid = getEnemyIndex(enemy) | 0

    const wantLog = DEBUG_ENEMY_NAV_LOG && _enemyNavShouldLog(enemy, curIdx, navX, navY, false)
    const candidates: any[] = DEBUG_ENEMY_NAV_LOG ? [] : null

    const collHere = _enemyNavMakeCollisionDebug(enemy, footX, footY, cw, ch, r, c)

    let pickReason = "descent"
    let logForce = false

    // --- Early INF bailout (kept) ---
    if (curD >= ENEMY_NAV_INF) {

        _enemyNavClearNavTargetData(enemy)

        if (DEBUG_ENEMY_NAV_LOG) {
            _enemyNavLogAdd(enemy, {
                t: nowMs,
                reason: "curDistInf",
                pos: { x: navX, y: navY, r, c, idx: curIdx },
                dist: { cur: curD, mask: curMask, allowUp: 0 },
                nav: { lastIdx: sprites.readDataNumber(enemy, ENEMY_AI_LAST_NAV_IDX) | 0 },
                vel: { vx: enemy.vx | 0, vy: enemy.vy | 0 },
                candidates,
                coll: collHere
            }, true)
        }

        return false
    }

    _enemyNavClearNavTargetData(enemy)

    const allowUpInfo = _enemyNavGetAllowUp(nowMs, enemy)
    const stuckUntil = allowUpInfo.stuckUntil | 0
    const allowUp = allowUpInfo.allowUp | 0

    const lastNavIdx = _enemyNavGetLastIdx(enemy, curIdx) | 0

    const vx = enemy.vx
    const vy = enemy.vy

    // --- Pick best neighbor by dist (same logic, factored by structure only) ---
    let bestR = r
    let bestC = c
    let bestD = ENEMY_NAV_INF
    let bestAlign = -999
    let bestIsBacktrack = false

    let bestAnyR = r
    let bestAnyC = c
    let bestAnyD = ENEMY_NAV_INF
    let bestAnyAlign = -999
    let bestAnyIsBacktrack = false

    for (let k = 0; k < 8; k++) {

        const nr = (r + _NAV8_DR[k]) | 0
        const nc = (c + _NAV8_DC[k]) | 0
        if (nr < 0 || nr >= _enemyNavRows || nc < 0 || nc >= _enemyNavCols) continue

        let cand: any = null
        if (candidates) cand = { r: nr, c: nc }

        const nIdx0 = _enemyNavIdx(nr, nc) | 0
        const baseBlocked = _enemyNavIsBaseBlocked(nr, nc) ? 1 : 0
        const deadBlocked = (_enemyNavDeadEnd && _enemyNavDeadEnd.length > nIdx0 && (_enemyNavDeadEnd[nIdx0] | 0) !== 0) ? 1 : 0

        if (_enemyNavIsBlocked(nr, nc)) {
            if (cand) {
                cand.blocked = 1
                cand.blockReason = baseBlocked ? "base" : (deadBlocked ? "deadEnd" : "blocked")
                cand.d = ENEMY_NAV_INF
                cand.coll = `B${cand.blockReason}`
                candidates.push(cand)
            }
            continue
        }

        const dr = _NAV8_DR[k] | 0
        const dc = _NAV8_DC[k] | 0

        if (dr !== 0 && dc !== 0) {
            if (_enemyNavIsDiagBlockedForFootprint(r, c, nr, nc, cw, ch, navMaxPx)) {
                if (cand) {
                    cand.blocked = 1
                    cand.blockReason = "diag"
                    cand.diag = 1
                    cand.coll = "Bdiag"
                    candidates.push(cand)
                }
                continue
            }
        }

        if (!_enemyNavCanOccupyCellForDims(cw, ch, nr, nc, navMaxPx)) {
            if (cand) {
                cand.blocked = 1
                cand.blockReason = "fit"
                cand.coll = "Bfit"
                candidates.push(cand)
            }
            continue
        }

        const nIdx = _enemyNavIdx(nr, nc) | 0
        const nd = _enemyNavDist[nIdx] | 0

        if (cand) cand.d = nd

        if (nd >= ENEMY_NAV_INF) {
            if (cand) {
                cand.blocked = 1
                cand.blockReason = "inf"
                cand.coll = "Binf"
                candidates.push(cand)
            }
            continue
        }

        const isBacktrack = (nIdx === lastNavIdx)
        const align = _enemyNavComputeAlign(dr, dc, vx, vy)

        if (cand) {
            cand.back = isBacktrack ? 1 : 0
            cand.align = align
            cand.diag = (dr !== 0 && dc !== 0) ? 1 : 0

            const probe = _enemyNavCandidateCollisionProbe(nr, nc, cw, ch, navMaxPx)
            if (probe) {
                const h = probe.hits
                cand.coll = `H(any=${h.anyBlockedHits|0},base=${h.baseHits|0},dead=${h.deadEndHits|0},cap=${h.capped|0})`
            }
        }

        // best-any (fallback)
        if (nd < bestAnyD) {
            bestAnyD = nd
            bestAnyR = nr
            bestAnyC = nc
            bestAnyAlign = align
            bestAnyIsBacktrack = isBacktrack
        } else if (nd === bestAnyD) {
            if (bestAnyIsBacktrack && !isBacktrack) {
                bestAnyR = nr
                bestAnyC = nc
                bestAnyAlign = align
                bestAnyIsBacktrack = isBacktrack
            } else if (bestAnyIsBacktrack === isBacktrack && align > bestAnyAlign) {
                bestAnyR = nr
                bestAnyC = nc
                bestAnyAlign = align
                bestAnyIsBacktrack = isBacktrack
            }
        }

        // strict descent unless we later fall back
        if (nd >= curD) {
            if (cand) candidates.push(cand)
            continue
        }

        if (nd < bestD) {
            bestD = nd
            bestR = nr
            bestC = nc
            bestAlign = align
            bestIsBacktrack = isBacktrack
        } else if (nd === bestD) {
            if (bestIsBacktrack && !isBacktrack) {
                bestR = nr
                bestC = nc
                bestAlign = align
                bestIsBacktrack = isBacktrack
            } else if (bestIsBacktrack === isBacktrack && align > bestAlign) {
                bestR = nr
                bestC = nc
                bestAlign = align
                bestIsBacktrack = isBacktrack
            }
        }

        if (cand) candidates.push(cand)
    }

    if (bestD >= ENEMY_NAV_INF && bestAnyD < ENEMY_NAV_INF && bestAnyD <= (curD + allowUp)) {
        bestD = bestAnyD
        bestR = bestAnyR
        bestC = bestAnyC
    }

    if (bestD >= ENEMY_NAV_INF) {
        pickReason = "no_neighbor"
        logForce = true
    } else if (bestR === r && bestC === c) {
        pickReason = "stay"
        logForce = true
    } else if (bestD === bestAnyD && bestD === curD) {
        pickReason = "flat"
    } else if (bestD === bestAnyD && bestD > curD) {
        pickReason = "uphill"
    }

    _enemyNavMarkChosenCandidate(candidates, bestR, bestC)

    const makeNavLogEntry = () => ({
        eid,
        mid: monsterId,
        t: nowMs,
        reason: pickReason,
        pos: { x: navX, y: navY, r, c, idx: curIdx },
        dist: { cur: curD, best: bestD, mask: curMask, allowUp },
        nav: { lastIdx: lastNavIdx, bestAny: { r: bestAnyR, c: bestAnyC, d: bestAnyD } },
        pick: { r: bestR, c: bestC, d: bestD },
        hero: { r: heroR, c: heroC, ex: heroEX, ey: heroEY },
        phase: phaseStr,
        stuck: { until: stuckUntil, mode: stuckMode },
        speed,
        vel: { vx: enemy.vx | 0, vy: enemy.vy | 0 },
        candidates,
        coll: collHere
    })

    if (bestD >= ENEMY_NAV_INF) {
        if (DEBUG_ENEMY_NAV_LOG) _enemyNavLogAdd(enemy, makeNavLogEntry(), true)
        return false
    }

    if (bestR === r && bestC === c) {
        if (DEBUG_ENEMY_NAV_LOG) _enemyNavLogAdd(enemy, makeNavLogEntry(), true)
        return false
    }

    // Avoid immediate backtrack next tick
    sprites.setDataNumber(enemy, ENEMY_AI_LAST_NAV_IDX, curIdx)

    sprites.setDataNumber(enemy, ENEMY_AI_NAV_TARGET_R, bestR)
    sprites.setDataNumber(enemy, ENEMY_AI_NAV_TARGET_C, bestC)
    sprites.setDataNumber(enemy, ENEMY_AI_NAV_TARGET_D, bestD)

    _enemyNavApplyVelocityTowardTileCenter(enemy, speed, navX, navY, bestR, bestC)

    if (DEBUG_ENEMY_NAV_LOG) _enemyNavLogAdd(enemy, makeNavLogEntry(), (logForce || wantLog))

    return true
}






// Compute a steering vector for enemy e toward hero h using the tilemap.

// Falls back to straight-line homing if map is missing or path not found.

function _enemySteerTowardHero(e: Sprite, h: Sprite, speed: number): void {

    if (!_engineWorldTileMap || _engineWorldTileMap.length === 0) {

        // Fallback: old behavior

        const dx0 = h.x - e.x

        const dy0 = h.y - e.y

        let mag0 = Math.sqrt(dx0 * dx0 + dy0 * dy0)

        if (mag0 === 0) mag0 = 1

        e.vx = Math.idiv(dx0 * speed, mag0)

        e.vy = Math.idiv(dy0 * speed, mag0)

        return

    }



    const map = _engineWorldTileMap

    const rows = map.length

    const cols = map[0].length

    const tileSize = WORLD_TILE_SIZE



    // Convert world coords to tile coords

    let startC = Math.idiv(e.x, tileSize)

    let startR = Math.idiv(e.y, tileSize)

    let goalC = Math.idiv(h.x, tileSize)

    let goalR = Math.idiv(h.y, tileSize)



    // Clamp into map bounds

    if (startR < 0) startR = 0

    if (startR >= rows) startR = rows - 1

    if (startC < 0) startC = 0

    if (startC >= cols) startC = cols - 1



    if (goalR < 0) goalR = 0

    if (goalR >= rows) goalR = rows - 1

    if (goalC < 0) goalC = 0

    if (goalC >= cols) goalC = cols - 1



    // If enemy and hero end up in the same tile, just home directly

    if (startR === goalR && startC === goalC) {

        const dxSame = h.x - e.x

        const dySame = h.y - e.y

        let magSame = Math.sqrt(dxSame * dxSame + dySame * dySame)

        if (magSame === 0) magSame = 1

        e.vx = Math.idiv(dxSame * speed, magSame)

        e.vy = Math.idiv(dySame * speed, magSame)

        return

    }



    // BFS setup

    const visited: number[][] = []

    const prevR: number[][] = []

    const prevC: number[][] = []

    for (let r = 0; r < rows; r++) {

        const vRow: number[] = []

        const prRow: number[] = []

        const pcRow: number[] = []

        for (let c = 0; c < cols; c++) {

            vRow.push(0)

            prRow.push(-1)

            pcRow.push(-1)

        }

        visited.push(vRow)

        prevR.push(prRow)

        prevC.push(pcRow)

    }



    const qr: number[] = []

    const qc: number[] = []

    let head = 0



    qr.push(startR)

    qc.push(startC)

    visited[startR][startC] = 1

    prevR[startR][startC] = startR

    prevC[startR][startC] = startC



    let found = false



    while (head < qr.length) {

        const r = qr[head]

        const c = qc[head]

        head++



        if (r === goalR && c === goalC) {

            found = true

            break

        }



        for (let k = 0; k < _ENEMY_DIR_R.length; k++) {

            const nr = r + _ENEMY_DIR_R[k]

            const nc = c + _ENEMY_DIR_C[k]



            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue

            if (visited[nr][nc]) continue



            // Treat walls as blocked, but allow goal tile even if hero is standing in/near it.

            if (_tileIsSolidType(map[nr][nc] | 0) && !(nr === goalR && nc === goalC)) continue



            visited[nr][nc] = 1

            prevR[nr][nc] = r

            prevC[nr][nc] = c

            qr.push(nr)

            qc.push(nc)

        }

    }



    if (!found) {

        // No path: fallback to straight-line homing

        const dxFail = h.x - e.x

        const dyFail = h.y - e.y

        let magFail = Math.sqrt(dxFail * dxFail + dyFail * dyFail)

        if (magFail === 0) magFail = 1

        e.vx = Math.idiv(dxFail * speed, magFail)

        e.vy = Math.idiv(dyFail * speed, magFail)

        return

    }



    // Backtrack from goal to find the next tile after the start

    let tr = goalR

    let tc = goalC



    while (!(prevR[tr][tc] === startR && prevC[tr][tc] === startC)) {

        const pr = prevR[tr][tc]

        const pc = prevC[tr][tc]

        // Safety: if something is weird, bail to straight-line

        if (pr < 0 || pc < 0) {

            const dxSafe = h.x - e.x

            const dySafe = h.y - e.y

            let magSafe = Math.sqrt(dxSafe * dxSafe + dySafe * dySafe)

            if (magSafe === 0) magSafe = 1

            e.vx = Math.idiv(dxSafe * speed, magSafe)

            e.vy = Math.idiv(dySafe * speed, magSafe)

            return

        }

        tr = pr

        tc = pc

    }



    // (tr, tc) is now the next tile on the path.

    const targetX = tc * tileSize + tileSize / 2

    const targetY = tr * tileSize + tileSize / 2



    const dx = targetX - e.x

    const dy = targetY - e.y

    let mag = Math.sqrt(dx * dx + dy * dy)

    if (mag === 0) mag = 1



    e.vx = Math.idiv(dx * speed, mag)

    e.vy = Math.idiv(dy * speed, mag)

}









