function getEnemyIndex(enemy: Sprite) { for (let i = 0; i < enemies.length; i++) if (enemies[i] == enemy) return i; return -1 }



function getHeroIndex(hero: Sprite) { for (let i = 0; i < heroes.length; i++) if (heroes[i] == hero) return i; return -1 }



// Enemy HP

function initEnemyHP(enemyIndex: number, enemy: Sprite, maxHPVal: number) {

    sprites.setDataNumber(enemy, ENEMY_DATA.MAX_HP, maxHPVal)

    sprites.setDataNumber(enemy, ENEMY_DATA.HP, maxHPVal)

    const bar = statusbars.create(18, 3, StatusBarKind.EnemyHealth)

    bar.attachToSprite(enemy); bar.setOffsetPadding(0, 2)

    bar.max = 100; bar.value = 100

    enemyHPBars[enemyIndex] = bar

}



function updateEnemyHPBar(enemyIndex: number) {

    const enemy = enemies[enemyIndex]; if (!enemy) return

    const bar = enemyHPBars[enemyIndex]; if (!bar) return

    const hp = sprites.readDataNumber(enemy, ENEMY_DATA.HP)

    let maxHp = sprites.readDataNumber(enemy, ENEMY_DATA.MAX_HP); if (maxHp <= 0) maxHp = 1

    bar.value = Math.max(0, Math.min(100, Math.idiv(hp * 100, maxHp)))

}







// ================================================================

// ON-HIT MASTER PIPELINE (centralizes status + knockback + relic hooks)

// ================================================================



interface EnemyHitPacket {

    // identity / gating (optional)

    family?: number;      // FAMILY.*

    button?: string;      // "A"/"B"/etc (optional)

    sourceTag?: string;   // debug label

    element?: number;     // ELEM.*



    // status intent (centralized here)

    slowPct?: number;

    slowMs?: number;



    weakenPct?: number;

    weakenMs?: number;



    // physics intent (centralized here)

    knockbackPct?: number;



    // UI

    suppressDamageNumber?: boolean;

}



// Effects queue for “weird” relic actions (teleport, mark, etc.)

type EnemyHitEffect =

    | { kind: "teleportEnemyTo"; x: number; y: number }

    | { kind: "setEnemyDataNumber"; key: any; value: number }

    | { kind: "setEnemyDataString"; key: any; value: string };



interface EnemyHitContext {

    now: number;



    eIndex: number;

    enemy: Sprite;



    sourceHeroIndex: number; // -1 allowed

    sourceHero: Sprite;      // null allowed



    family: number;          // -1 allowed

    element: number;         // ELEM.*

    button: string;

    sourceTag: string;



    // mutable payload

    damage: number;



    slowPct: number;

    slowMs: number;



    weakenPct: number;

    weakenMs: number;



    knockbackPct: number;



    suppressDamageNumber: boolean;



    // “weird” actions

    effects: EnemyHitEffect[];

}

function _enemyAggroNoteHit(ctx: EnemyHitContext): void {
    const enemy = ctx.enemy
    if (!enemy) return
    const srcHi = ctx.sourceHeroIndex | 0
    if (srcHi < 0) return

    const now = ctx.now | 0
    const st = _enemyAggroStateFor(enemy, now)
    _enemyAggroDecay(st, now)

    let threat = Number(st.threats[srcHi] || 0)
    let bonus = 0
    if ((ctx.slowPct | 0) > 0 && (ctx.slowMs | 0) > 0) bonus += (ENEMY_AGGRO_STATUS_BONUS | 0)
    if ((ctx.weakenPct | 0) > 0 && (ctx.weakenMs | 0) > 0) bonus += (ENEMY_AGGRO_STATUS_BONUS | 0)
    if ((ctx.knockbackPct | 0) > 0) bonus += (ENEMY_AGGRO_STATUS_BONUS | 0)

    if ((ctx.damage | 0) <= 0 && bonus <= 0) {
        if ((ctx.sourceTag || ctx.button) && (ENEMY_AGGRO_TOUCH_BONUS | 0) > 0) {
            bonus = (ENEMY_AGGRO_TOUCH_BONUS | 0)
        }
    }

    if ((ctx.damage | 0) <= 0 && bonus <= 0) return

    threat += ((ctx.damage | 0) * (ENEMY_AGGRO_DAMAGE_SCALE | 0)) + bonus
    st.threats[srcHi] = threat
    st.lastHitMs[srcHi] = now
}



// Supporting relic hook (NO-OP for now).

// Later: read hero relic inventory and mutate ctx.damage/status/effects.

function applyRelicOnHitToEnemy(ctx: EnemyHitContext): void {

    // RELIC DISPATCH: route to per-hero owned relic handlers via RELICS section

    relic_onHitEnemy(ctx)

}



function _enemyHitRunEffects(ctx: EnemyHitContext): void {

    const enemy = ctx.enemy;

    if (!enemy || (enemy.flags & sprites.Flag.Destroyed)) return;



    const fx = ctx.effects;

    if (!fx || fx.length <= 0) return;



    for (let i = 0; i < fx.length; i++) {

        const e = fx[i];

        if (!e) continue;



        if (e.kind === "teleportEnemyTo") {

            enemy.x = e.x;

            enemy.y = e.y;

        } else if (e.kind === "setEnemyDataNumber") {

            sprites.setDataNumber(enemy, e.key, e.value | 0);

        } else if (e.kind === "setEnemyDataString") {

            sprites.setDataString(enemy, e.key, "" + e.value);

        }

    }

}



const ENEMY_DEATH_MS_DEFAULT = 2

type StudentDropRoll = {
    itemId: string;
    count: number;
};

function _normalizeMonsterIdForDrops(raw: string): string {
    return String(raw || "").trim().toLowerCase().replace(/enemy$/i, "").trim();
}

function _buildStudentDropTableMap(): Map<string, StudentDropTable> {
    const map = new Map<string, StudentDropTable>();
    const tables = listStudentDropTables();
    for (let i = 0; i < tables.length; i++) {
        const def = tables[i];
        if (!def) continue;
        const id = String(def.id || "").trim();
        if (!id) continue;
        map.set(id, def);
    }
    return map;
}

function _rollStudentDropTable(table: StudentDropTable, rolls: number): StudentDropRoll[] {
    if (!table || !Array.isArray(table.entries)) return [];
    const entries: StudentDropEntry[] = [];
    let totalWeight = 0;
    for (let i = 0; i < table.entries.length; i++) {
        const entry = table.entries[i];
        if (!entry) continue;
        const itemId = String(entry.itemId || "").trim();
        if (!itemId) continue;
        const weight = Number(entry.weight);
        if (!(weight > 0)) continue;
        entries.push({ ...entry, itemId, weight });
        totalWeight += weight;
    }

    const rollCount = Math.max(0, rolls | 0);
    if (entries.length === 0 || !(totalWeight > 0) || rollCount <= 0) return [];

    const results = new Map<string, number>();

    for (let r = 0; r < rollCount; r++) {
        let pick = Math.random() * totalWeight;
        let chosen: StudentDropEntry | null = null;
        for (let i = 0; i < entries.length; i++) {
            const entry = entries[i];
            pick -= entry.weight;
            if (pick <= 0) {
                chosen = entry;
                break;
            }
        }
        if (!chosen) chosen = entries[entries.length - 1] || null;
        if (!chosen) continue;

        const min = chosen.min == null ? 1 : Math.max(0, chosen.min | 0);
        const max = chosen.max == null ? min : Math.max(min, chosen.max | 0);
        let count = min;
        if (max > min) {
            count = min + Math.floor(Math.random() * (max - min + 1));
        }
        if (count <= 0) continue;
        const key = String(chosen.itemId || "").trim();
        if (!key) continue;
        results.set(key, (results.get(key) || 0) + count);
    }

    const out: StudentDropRoll[] = [];
    for (const [itemId, count] of results) {
        out.push({ itemId, count });
    }
    return out;
}

function _resolveStudentMonsterDrops(monsterIdRaw: string): Array<{
    def: StudentMonsterDrop;
    dropTableId: string;
    drops: StudentDropRoll[];
}> {
    const monsterId = _normalizeMonsterIdForDrops(monsterIdRaw);
    if (!monsterId) return [];

    const defs = listStudentMonsterDrops();
    if (!defs || defs.length === 0) return [];

    const tableMap = _buildStudentDropTableMap();
    if (tableMap.size === 0) return [];

    const out: Array<{ def: StudentMonsterDrop; dropTableId: string; drops: StudentDropRoll[] }> = [];

    for (let i = 0; i < defs.length; i++) {
        const def = defs[i];
        if (!def) continue;
        const defMonsterId = _normalizeMonsterIdForDrops(def.monsterId);
        if (!defMonsterId || defMonsterId !== monsterId) continue;

        const dropTableId = String(def.dropTableId || "").trim();
        if (!dropTableId) continue;
        const table = tableMap.get(dropTableId);
        if (!table) continue;

        const chance = def.chancePct == null ? 100 : Number(def.chancePct);
        if (!(chance > 0)) continue;
        if (chance < 100 && (Math.random() * 100) >= chance) continue;

        const minRolls = def.minRolls == null ? 1 : Math.max(0, def.minRolls | 0);
        const maxRolls = def.maxRolls == null ? minRolls : Math.max(minRolls, def.maxRolls | 0);
        const rollCount = maxRolls > minRolls
            ? (minRolls + Math.floor(Math.random() * (maxRolls - minRolls + 1)))
            : minRolls;
        if (rollCount <= 0) continue;

        const drops = _rollStudentDropTable(table, rollCount);
        if (drops.length === 0) continue;

        out.push({ def, dropTableId, drops });
    }

    return out;
}

function _dispatchStudentMonsterDrops(params: {
    enemy: Sprite;
    eIndex: number;
    killerHi: number;
    now: number;
    dropX: number;
    dropY: number;
}): void {
    const hooks = getStudentDropHooks();
    if (!hooks || typeof hooks.onMonsterDrops !== "function") return;

    const profileKey = (params.killerHi >= 0) ? _heroProfileKeyForIndex(params.killerHi) : "";
    if (!isProfileAllowed(hooks, profileKey)) return;

    const monsterId = sprites.readDataString(params.enemy, ENEMY_DATA.MONSTER_ID) || "";
    if (!monsterId) return;

    const resolved = _resolveStudentMonsterDrops(monsterId);
    if (resolved.length === 0) return;

    for (let i = 0; i < resolved.length; i++) {
        const entry = resolved[i];
        const ctx = {
            now: params.now | 0,
            monsterId,
            dropTableId: entry.dropTableId,
            drops: entry.drops.map((drop) => ({ ...drop })),
            x: params.dropX | 0,
            y: params.dropY | 0,
            killerHi: params.killerHi | 0,
            eIndex: params.eIndex | 0,
            enemy: params.enemy,
            data: entry.def?.data,
        };
        try {
            hooks.onMonsterDrops(ctx);
        } catch { /* ignore */ }
    }
}



function handleEnemyKilledAndScheduleDeath(eIndex: number, enemy: Sprite, srcHi: number, now: number): void {

    if (!enemy) return;



    // Already dying? don't reschedule (and don't double-award)

    const existing = sprites.readDataNumber(enemy, ENEMY_DATA.DEATH_UNTIL) | 0;

    if (existing > 0) return;



    // ----------------------------

    // coin reward on kill (PER HERO)

    // ----------------------------

    let maxHp = sprites.readDataNumber(enemy, ENEMY_DATA.MAX_HP) | 0;

    if (maxHp <= 0) maxHp = 1;



    const coins = Math.max(

        COIN_REWARD_MIN,

        Math.idiv(maxHp + (COIN_REWARD_HP_DIV - 1), COIN_REWARD_HP_DIV)

    );



    const coinPopX = enemy.x;

    const coinPopY = enemy.y - 12;



    // Resolve killer similarly to XP logic

    let killerHi = (srcHi == null) ? -1 : (srcHi | 0)

    if (killerHi < 0 || killerHi >= heroes.length || !heroes[killerHi] || (heroes[killerHi].flags & sprites.Flag.Destroyed)) {

        killerHi = sprites.readDataNumber(enemy, ENEMY_LAST_HIT_HI_KEY) | 0

    }

    if (killerHi < 0 || killerHi >= heroes.length || !heroes[killerHi] || (heroes[killerHi].flags & sprites.Flag.Destroyed)) {

        killerHi = findNearestLivingPlayerHeroIndex(coinPopX, coinPopY) | 0

    }



    let coinsFinal = coins | 0

    let xpScaleFinal = 1



    if (killerHi >= 0) {

        // RELIC HOOK: enemy killed (pre rewards)

        try {

            const killCtx: RelicEnemyKilledContext = {

                now: now | 0,

                eIndex: eIndex | 0,

                enemy,

                srcHi: (srcHi == null ? -1 : (srcHi | 0)),

                killerHi: killerHi | 0,

                coins: coinsFinal | 0,

                xpScale: 1,

                coinPopX: coinPopX | 0,

                coinPopY: coinPopY | 0,

            };



            relic_onEnemyKilledPreRewards(killCtx);



            coinsFinal = (killCtx.coins | 0);

            if (coinsFinal < 0) coinsFinal = 0;



            const xs = (killCtx.xpScale == null) ? 1 : Number(killCtx.xpScale)

            xpScaleFinal = (xs >= 0) ? xs : 1



            if ((coinsFinal | 0) !== (coins | 0)) {

                console.log("[RELICHOOK] kill coins modified", { eIndex, killerHi, base: coins | 0, final: coinsFinal | 0 })

            }

        } catch { }



        addHeroCoins(killerHi, coinsFinal, coinPopX, coinPopY);

    } else {

        logCoins("[COINS] kill reward dropped (no hero)", { eIndex, srcHi: (srcHi == null ? -1 : (srcHi | 0)), lastHit: (sprites.readDataNumber(enemy, ENEMY_LAST_HIT_HI_KEY) | 0) })

    }

    // ----------------------------
    // Student drop tables (per monster)
    // ----------------------------
    _dispatchStudentMonsterDrops({
        enemy,
        eIndex: eIndex | 0,
        killerHi: killerHi | 0,
        now: now | 0,
        dropX: coinPopX | 0,
        dropY: coinPopY | 0,
    })



    // ----------------------------

    // XP reward on kill (now supports xpScaleFinal)

    // ----------------------------

    awardXpForEnemyDeath(enemy, killerHi, coinPopX, coinPopY, xpScaleFinal);



    // RELIC HOOK: enemy killed (post rewards)

    if (killerHi >= 0) {

        try {

            const postCtx: RelicEnemyKilledContext = {

                now: now | 0,

                eIndex: eIndex | 0,

                enemy,

                srcHi: (srcHi == null ? -1 : (srcHi | 0)),

                killerHi: killerHi | 0,

                coins: coinsFinal | 0,

                xpScale: xpScaleFinal,

                coinPopX: coinPopX | 0,

                coinPopY: coinPopY | 0,

            }

            relic_onEnemyKilledPostRewards(postCtx)

        } catch { }

    }

    const splitStage = sprites.readDataNumber(enemy, "__slimeSplitStage") | 0
    const splitOnDeath = (sprites.readDataNumber(enemy, "__slimeSplitOnDeath") | 0) !== 0
    if (splitStage > 0 || splitOnDeath) {
        const baseId = (sprites.readDataString(enemy, ENEMY_DATA.MONSTER_ID) || "slime").trim()
        let variant = ""
        if (splitStage >= 2) variant = "split_medium"
        else if (splitStage === 1) variant = "split_small"
        else if (splitOnDeath) variant = "baby"
        if (variant) {
            const offs = SLIME_SPLIT_OFFSET_PX | 0
            const points = [
                { x: (enemy.x | 0) - offs, y: (enemy.y | 0) },
                { x: (enemy.x | 0) + offs, y: (enemy.y | 0) }
            ]
            for (let i = 0; i < points.length; i++) {
                const p = points[i]
                const child = spawnEnemyOfKind(baseId, p.x | 0, p.y | 0, /*elite=*/ false)
                _applyEnemyVariant(child, baseId, variant)
            }
        }
    }



    // ----------------------------

    // Schedule death animation / cleanup

    // ----------------------------

    const deathDurationMs = (sprites.readDataNumber(enemy, "deathAnimMs") | 0) || ENEMY_DEATH_MS_DEFAULT



    // Tell Phaser how long the death animation should last

    sprites.setDataNumber(enemy, "deathAnimMs", deathDurationMs);



    // Clear attack state

    sprites.setDataNumber(enemy, ENEMY_DATA.ATK_PHASE, ENEMY_ATK_PHASE_IDLE);

    sprites.setDataNumber(enemy, ENEMY_DATA.ATK_UNTIL, 0);

    sprites.setDataNumber(enemy, ENEMY_DATA.ATK_COOLDOWN_UNTIL, 0);



    // Freeze motion (NOTE: knockback may reapply after this; matches prior call-site behavior)

    enemy.vx = 0;

    enemy.vy = 0;



    // Let updateEnemyHoming own the actual destroy timing

    sprites.setDataNumber(enemy, ENEMY_DATA.DEATH_UNTIL, (now + deathDurationMs) | 0);

}





function applyDamageToEnemyIndex(eIndex: number, amount: number, sourceHeroIndex?: number, hit?: EnemyHitPacket): void {

    if (eIndex < 0 || eIndex >= enemies.length) return;

    const enemy = enemies[eIndex];

    if (!enemy) return;

    if (enemy.flags & sprites.Flag.Destroyed) return;



    const now = game.runtime() | 0;



    // Track last hitter (backup if someone forgets to pass heroIndex)

    const srcHi = (sourceHeroIndex == null) ? -1 : (sourceHeroIndex | 0);

    const srcHero = (srcHi >= 0 && srcHi < heroes.length) ? heroes[srcHi] : null;



    // Build context (hit packet is optional)

    const ctx: EnemyHitContext = {

        now,



        eIndex,

        enemy,



        sourceHeroIndex: srcHi,

        sourceHero: srcHero,



        family: (hit && hit.family != null) ? (hit.family | 0) : -1,

        element: (hit && hit.element != null) ? (hit.element | 0) : (ELEM.NONE | 0),

        button: (hit && hit.button != null) ? ("" + hit.button) : "",

        sourceTag: (hit && hit.sourceTag != null) ? ("" + hit.sourceTag) : "",



        damage: Math.max(0, amount | 0),



        slowPct: (hit && hit.slowPct != null) ? (hit.slowPct | 0) : 0,

        slowMs:  (hit && hit.slowMs  != null) ? (hit.slowMs  | 0) : 0,



        weakenPct: (hit && hit.weakenPct != null) ? (hit.weakenPct | 0) : 0,

        weakenMs:  (hit && hit.weakenMs  != null) ? (hit.weakenMs  | 0) : 0,



        knockbackPct: (hit && hit.knockbackPct != null) ? (hit.knockbackPct | 0) : 0,



        suppressDamageNumber: (hit && hit.suppressDamageNumber) ? true : false,



        effects: []

    };



    // Record last hitter even for “0 damage but status/knockback” hits

    if (srcHi >= 0) {

        sprites.setDataNumber(enemy, ENEMY_LAST_HIT_HI_KEY, srcHi);

    }



    // If we truly have nothing to do, bail early

    const hasAnyWork =

        (ctx.damage > 0) ||

        (ctx.slowPct > 0 && ctx.slowMs > 0) ||

        (ctx.weakenPct > 0 && ctx.weakenMs > 0) ||

        (ctx.knockbackPct > 0) ||

        (ctx.effects && ctx.effects.length > 0) ||

        (!!hit);



    if (!hasAnyWork) return;



    // 1) Relics (and other “on-hit” rule mutations) run FIRST

    applyRelicOnHitToEnemy(ctx);



    // 2) Execute any queued “weird effects” (teleport, mark, etc.)

    _enemyHitRunEffects(ctx);



    // 2b) Elemental damage multiplier (only affects damage)
    if (ctx.damage > 0) {
        const monsterId = sprites.readDataString(enemy, ENEMY_DATA.MONSTER_ID) || ""
        const elems = _monsterElementsForId(monsterId)
        const mult = _elementDamageMultiplier(ctx.element, elems)
        if (mult !== 1) {
            ctx.damage = Math.max(0, Math.round(ctx.damage * mult))
        }
    }

    // 2c) Aggro (threat) update after final damage is known
    _enemyAggroNoteHit(ctx)



    // 3) Apply status effects (even if damage is 0)

    if (ctx.slowPct > 0 && ctx.slowMs > 0) {

        sprites.setDataNumber(enemy, ENEMY_DATA.SLOW_PCT, ctx.slowPct);

        sprites.setDataNumber(enemy, ENEMY_DATA.SLOW_UNTIL, (now + ctx.slowMs) | 0);

    }

    if (ctx.weakenPct > 0 && ctx.weakenMs > 0) {

        sprites.setDataNumber(enemy, ENEMY_DATA.WEAKEN_PCT, ctx.weakenPct);

        sprites.setDataNumber(enemy, ENEMY_DATA.WEAKEN_UNTIL, (now + ctx.weakenMs) | 0);

    }



    // 4) Apply damage (if any)

    if (ctx.damage > 0) {

        let hp = sprites.readDataNumber(enemy, ENEMY_DATA.HP) | 0;

        hp = Math.max(0, (hp - ctx.damage) | 0);



        if (!ctx.suppressDamageNumber) {

            showDamageNumber(enemy.x, enemy.y - 6, ctx.damage, "damage");

        }



        sprites.setDataNumber(enemy, ENEMY_DATA.HP, hp);

        updateEnemyHPBar(eIndex);

        flashEnemyOnDamage(enemy);



        if (hp <= 0) {

            handleEnemyKilledAndScheduleDeath(eIndex, enemy, srcHi, now);

        }

    }



    // 5) Apply knockback LAST (matches prior call-site ordering; may override death “freeze”)

    if (ctx.knockbackPct > 0) {

        // Prefer hero position if we have it; otherwise knockback from enemy center (no-op direction)

        const hx = (srcHero) ? srcHero.x : enemy.x;

        const hy = (srcHero) ? srcHero.y : enemy.y;

        applyPctKnockbackToEnemy(enemy, hx, hy, ctx.knockbackPct);

    }

}







