function updateHeroTimelineProgressAll(nowMs: number): void {

    const now = nowMs | 0



    // Phases that should "cycle" visually (loop progress).

    // Everything else clamps (0?max and stays).

    const ph = (s: Sprite) => (sprites.readDataString(s, HERO_DATA.PhaseName) || "")

    const isAmbientPhase = (phaseName: string): boolean => {

        switch (phaseName) {

            case "idle":

            case "run":

            case "walk":

            case "combatIdle":

            case "sit":

            case "watering":

            case "emote":

            case "climb":

                return true

            default:

                return false

        }

    }



    const clampProg = (p: number): number => {

        let x = p | 0

        if (x < 0) x = 0

        if (x > PHASE_PROGRESS_MAX) x = PHASE_PROGRESS_MAX

        return x

    }



    for (let hi = 0; hi < heroes.length; hi++) {

        const hero = heroes[hi]

        if (!hero) continue

        if (hero.flags & sprites.Flag.Destroyed) continue



        // -------------------------

        // Whole-phase progress

        // -------------------------

        const phaseName = ph(hero)

        const ps = sprites.readDataNumber(hero, HERO_DATA.PhaseStartMs) | 0

        let pd = sprites.readDataNumber(hero, HERO_DATA.PhaseDurationMs) | 0

        if (pd <= 0) pd = 1



        if (ps > 0) {

            const elapsed = (now - ps) | 0



            // Loop only for ambient phases; clamp for action phases.

            // (This matches your goal: phases own rendering; actions don't "replay" because progress loops.)

            let e = elapsed

            if (e < 0) e = 0



            if (isAmbientPhase(phaseName)) {

                // loop

                const eMod = (pd > 0) ? (e % pd) : 0

                const pInt = clampProg(Math.idiv(PHASE_PROGRESS_MAX * eMod, pd))

                sprites.setDataNumber(hero, HERO_DATA.PhaseProgressInt, pInt)

            } else {

                // clamp

                let eClamp = e

                if (eClamp > pd) eClamp = pd

                const pInt = clampProg(Math.idiv(PHASE_PROGRESS_MAX * eClamp, pd))

                sprites.setDataNumber(hero, HERO_DATA.PhaseProgressInt, pInt)

            }

        }



        // -------------------------

        // Phase-part progress (only if part is active)

        // -------------------------

        const partName = sprites.readDataString(hero, HERO_DATA.PhasePartName) || ""

        if (partName && partName.length > 0) {

            const partS = sprites.readDataNumber(hero, HERO_DATA.PhasePartStartMs) | 0

            let partD = sprites.readDataNumber(hero, HERO_DATA.PhasePartDurationMs) | 0

            if (partD <= 0) partD = 1



            if (partS > 0) {

                let pe = (now - partS) | 0

                if (pe < 0) pe = 0

                if (pe > partD) pe = partD

                const pPart = clampProg(Math.idiv(PHASE_PROGRESS_MAX * pe, partD))

                sprites.setDataNumber(hero, HERO_DATA.PhasePartProgress, pPart)

            }

        }

    }

}







function updateHeroProjectiles() {

    const now = game.runtime()



    // 1) STR/AGI/SUPPORT projectiles in heroProjectiles[]

    for (let i = heroProjectiles.length - 1; i >= 0; i--) {

        const proj = heroProjectiles[i]

        if (!proj || (proj.flags & sprites.Flag.Destroyed)) {

            if (proj) _destroyHeroBodyPaintFxForProj(proj)
            if (proj) _destroyProjectileMaskSpriteForProj(proj)
            if (proj) _destroyAgilityTrailFxSegments(proj)
            if (proj) _destroyAgilityCometFx(proj)
            if (proj) _destroyStrengthArcFxForProj(proj)
            if (proj) _destroyStrengthSwingFxSegments(proj)
            heroProjectiles.removeAt(i)

            continue

        }



        const heroIndex = sprites.readDataNumber(proj, PROJ_DATA.HERO_INDEX) | 0

        const hero = heroes[heroIndex]

        if (!hero || (hero.flags & sprites.Flag.Destroyed)) {

            _destroyHeroBodyPaintFxForProj(proj)
            _destroyProjectileMaskSpriteForProj(proj)
            _destroyAgilityTrailFxSegments(proj)
            _destroyAgilityCometFx(proj)
            _destroyStrengthArcFxForProj(proj)
            _destroyStrengthSwingFxSegments(proj)
            proj.destroy()

            heroProjectiles.removeAt(i)

            continue

        }



        const mvType = (sprites.readDataString(proj, PROJ_DATA.MOVE_TYPE) || "").toLowerCase()



        if (mvType === "agilitystab" || mvType === "agilitystablow") {

            if (!updateAgilityProjectilesMotionFor(proj, hero, heroIndex, now, i)) {

                continue

            }

        } else if (mvType === "strengthswing") {

            if (!updateStrengthProjectilesMotionFor(proj, hero, heroIndex, now, i)) {

                continue

            }

        } else if (mvType === "supportbeam") {

            if (!updateSupportBeamFor(proj, heroIndex, now, i)) {

                heroProjectiles.removeAt(i)

                continue

            }

        } else {

            continue

        }

    }



    // 2) INT spells

    updateIntellectSpellsControl()



    // NEW: grid-based wall hit ? detonate request (Phaser has no wall sprites)

    maybeDetonateIntellectSpellsOnWall(now | 0)



    processIntellectLingers()



    // 3) NEW (C4): Agility execute slashes (no projectiles required)

    updateAgilityExecuteAll(now)

    // Debug: weapon aura overlay (visual verify).
    _updateWeaponAuraDebugAll();

}











// Cleanup for timed destroy set by runIntellectDetonation

function updateProjectilesCleanup() {

    const now = game.runtime()

    

    for (let i = heroProjectiles.length - 1; i >= 0; i--) {

        const proj = heroProjectiles[i]

        if (!proj || (proj.flags & sprites.Flag.Destroyed)) continue

        const destroyAt = sprites.readDataNumber(proj, PROJ_DATA.DESTROY_AT) | 0

        if (destroyAt > 0 && now >= destroyAt) {
            _destroyProjectileMaskFxForProj(proj)
            _destroyProjectileMaskSpriteForProj(proj)
            proj.destroy()
        }

    }

}









function encodeIntentToStrBtnId(intent: string): number {

    if (intent === "A") return STR_BTN_A

    if (intent === "B") return STR_BTN_B

    if (intent === "A+B") return STR_BTN_AB

    if (intent === "R") return STR_BTN_R

    return STR_BTN_NONE

}



function isStrBtnIdPressedForOwner(ownerId: number, btnId: number): boolean {

    const st = _getInputStateForOwnerId(ownerId)
    if (!st) return false
    const a = !!st.A
    const b = !!st.B
    const ab = !!st.AB
    const r = !!st.R



    if (btnId === STR_BTN_A) return a

    if (btnId === STR_BTN_B) return b

    if (btnId === STR_BTN_AB) return ab || (a && b)

    if (btnId === STR_BTN_R) return r

    return false

}







function consumePlayerIntent(playerId: number): string {

    const pid = playerId | 0
    if (pid <= 0) return ""
    let profile = playerIdToProfile[pid] || ""
    if (!profile) {
        try {
            const g: any = globalThis as any
            if (g && g.__netProfileByPid && typeof g.__netProfileByPid[pid] === "string") {
                profile = g.__netProfileByPid[pid]
            }
        } catch { }
    }
    if (!profile) return ""
    return _consumeIntentForProfile(profile)

}









function updatePlayerInputs() {

    const nowMs = game.runtime() | 0

    const connectedMap = (isPhaserRuntime() && (globalThis as any).__netProfileConnected)
        ? ((globalThis as any).__netProfileConnected as Record<string, boolean>)
        : null

    const seen: Record<string, boolean> = Object.create(null)

    const localProfile = _getLocalProfileKey()
    if (localProfile) {
        _syncLocalInputState(localProfile)
        const stLocal = _getInputStateForProfile(localProfile)
        _updateIntentStateForProfile(localProfile, stLocal, nowMs, true)
        seen[localProfile] = true
    }

    for (let hi = 0; hi < heroes.length; hi++) {
        const hero = heroes[hi]
        if (!hero || (hero.flags & sprites.Flag.Destroyed)) continue
        const profileKey = _heroProfileKeyForIndex(hi)
        if (!profileKey) continue
        if (seen[profileKey]) continue
        if (connectedMap && connectedMap[profileKey] === false) continue
        const st = _getInputStateForProfile(profileKey)
        _updateIntentStateForProfile(profileKey, st, nowMs, false)
        seen[profileKey] = true
    }

}











// Agility/Strength projectile motion (unchanged)

function updateMeleeProjectilesMotion() {

    const now = game.runtime()

    for (let i = heroProjectiles.length - 1; i >= 0; i--) {

        const proj = heroProjectiles[i]

        if (!proj || proj.flags & sprites.Flag.Destroyed) { heroProjectiles.removeAt(i); continue }

        const heroIndex = sprites.readDataNumber(proj, PROJ_DATA.HERO_INDEX) | 0

        const hero = heroes[heroIndex]

        if (!hero || (hero.flags & sprites.Flag.Destroyed)) { proj.destroy(); heroProjectiles.removeAt(i); continue }

        const mvType = (sprites.readDataString(proj, PROJ_DATA.MOVE_TYPE) || "").toLowerCase()

        if (mvType === "agilitystab" || mvType === "agilitystablow") {

            if (!updateAgilityProjectilesMotionFor(proj, hero, heroIndex, now, i)) continue

        } else if (mvType === "strengthswing") {

            if (!updateStrengthProjectilesMotionFor(proj, hero, heroIndex, now, i)) continue

        } else {

            // (driven spells handled elsewhere)

        }

    }

}







function _heroDeath_pickTileRC(hero: Sprite): { r: number; c: number } {
    const tileSize = WORLD_TILE_SIZE | 0
    let r = sprites.readDataNumber(hero, HERO_DATA.TILE_R) | 0
    let c = sprites.readDataNumber(hero, HERO_DATA.TILE_C) | 0

    if (r < 0 || c < 0) {
        if (tileSize > 0) {
            r = Math.idiv((hero.y | 0), tileSize) | 0
            c = Math.idiv((hero.x | 0), tileSize) | 0
        } else {
            r = 0
            c = 0
        }
    }

    if (_engineWorldTileMap && _engineWorldTileMap.length > 0) {
        const rows = _engineWorldTileMap.length | 0
        const cols = _engineWorldTileMap[0] ? (_engineWorldTileMap[0].length | 0) : 0
        if (rows > 0 && cols > 0) {
            if (r < 0) r = 0
            else if (r >= rows) r = (rows - 1) | 0
            if (c < 0) c = 0
            else if (c >= cols) c = (cols - 1) | 0
        }
    }

    return { r, c }
}

function _heroDeath_spawnHeadstoneInteractable(tileR: number, tileC: number, profileKey: string): Sprite | null {
    const key = _death_normProfileKey(profileKey)
    if (!key) return null

    const img = image.create(1, 1)
    img.fill(0)

    const it = sprites.create(img, (SpriteKind as any).FloorInteractable)
    it.setFlag(SpriteFlag.Ghost, true)
    it.setFlag(SpriteFlag.Invisible, true)
    it.setPosition(_dunColToX(tileC | 0), _dunRowToY(tileR | 0))
    it.z = 6

    sprites.setDataString(it, DECOR_DATA.NAME, HERO_DEATH_HEADSTONE_PROP)
    sprites.setDataNumber(it, "decorTileR", tileR | 0)
    sprites.setDataNumber(it, "decorTileC", tileC | 0)
    sprites.setDataString(it, INTERACT_DATA.KIND, INTERACT_ACTION_PROP)
    sprites.setDataString(it, INTERACT_DATA.ACTION, INTERACT_ACTION_HEADSTONE)
    sprites.setDataNumber(it, INTERACT_DATA.USED, 0)
    sprites.setDataNumber(it, INTERACT_DATA.OPENED, 0)
    sprites.setDataNumber(it, INTERACT_DATA.FOCUSABLE, 1)
    sprites.setDataString(it, "headstoneProfile", key)

    _dunInteractables.push(it)
    return it
}

function _heroDeath_clearHeadstone(profileKey: string): void {
    const key = _death_normProfileKey(profileKey)
    if (!key) return

    const decor = _deathHeadstoneByProfile[key]
    if (decor && !(decor.flags & sprites.Flag.Destroyed)) _dunDestroySprite(decor)
    _deathHeadstoneByProfile[key] = null

    const it = _deathHeadstoneInteractByProfile[key]
    if (it && !(it.flags & sprites.Flag.Destroyed)) _dunDestroySprite(it)
    _deathHeadstoneInteractByProfile[key] = null
}

function _heroDeath_clearAllHeadstones(): void {
    for (const key of Object.keys(_deathHeadstoneByProfile)) {
        _heroDeath_clearHeadstone(key)
    }
}

function _heroDeath_spawnHeadstone(hero: Sprite, profileKey?: string): void {
    if (!hero) return
    if (sprites.readDataBoolean(hero, HERO_DATA.DEAD_MARKER)) return

    const key = _death_normProfileKey(profileKey || sprites.readDataString(hero, HERO_DATA.NAME) || "")
    if (!key) return

    const existing = _deathHeadstoneByProfile[key]
    if (existing && !(existing.flags & sprites.Flag.Destroyed)) {
        sprites.setDataBoolean(hero, HERO_DATA.DEAD_MARKER, true)
        return
    }

    const pick = _heroDeath_pickTileRC(hero)
    const decor = _dunDecor_spawnAtTile({
        name: HERO_DEATH_HEADSTONE_PROP,
        role: DECOR_ROLE.TRIGGER,
        tileR: pick.r | 0,
        tileC: pick.c | 0,
        pxW: WORLD_TILE_SIZE | 0,
        pxH: WORLD_TILE_SIZE | 0
    })
    sprites.setDataString(decor, "headstoneProfile", key)

    _deathHeadstoneByProfile[key] = decor
    _deathHeadstoneInteractByProfile[key] = _heroDeath_spawnHeadstoneInteractable(pick.r | 0, pick.c | 0, key)

    sprites.setDataBoolean(hero, HERO_DATA.DEAD_MARKER, true)
}

function _heroDeath_showDialog(hero: Sprite, pid: number, profileKey: string, ownerPrefix?: string, force?: boolean): void {
    if (!hero) return
    if ((pid | 0) <= 0) return
    const prefix = ownerPrefix || HERO_DEATH_DIALOG_OWNER_PREFIX
    const isHeadstone = prefix === HERO_DEATH_HEADSTONE_OWNER_PREFIX
    if (!force && !isHeadstone && sprites.readDataBoolean(hero, HERO_DATA.DEAD_DIALOG)) return

    const g: any = globalThis as any
    const dlg = g ? g.__heDialog : null
    const net: any = g ? g.__net : null
    const localPid = (net && typeof net.playerId === "number") ? (net.playerId | 0) : 0
    const owner = `${prefix}:${profileKey || pid}:${pid | 0}`
    const cost = _death_respawnCostForProfile(profileKey || "")
    const fund = _death_getRespawnFund(profileKey || "")
    const need = Math.max(0, (cost | 0) - (fund | 0)) | 0
    const respawnLabel = need > 0
        ? `Respawn (${cost} gold, need ${need})`
        : `Respawn (${cost} gold)`
    const viewerHi = _uiResolveHeroIndexForPid(pid | 0)
    const coins = (viewerHi >= 0) ? (getHeroCoins(viewerHi) | 0) : 0
    const contributeLabel = `Contribute all (${coins} gold)`
    const hint = need > 0
        ? `Respawn costs ${cost}g. Fund has ${fund}g (${need} short).`
        : `Respawn ready: ${fund}g of ${cost}g.`
    const payload = {
        speaker: "YOU DIED!",
        text: "Your spirit lingers by your headstone.",
        hint,
        choices: [
            { id: HERO_DEATH_DIALOG_CHOICE_RESPAWN, label: respawnLabel },
            { id: HERO_DEATH_DIALOG_CHOICE_CONTRIBUTE, label: contributeLabel },
            { id: HERO_DEATH_DIALOG_CHOICE_LOAD, label: "Load most recent floor" },
            { id: HERO_DEATH_DIALOG_CHOICE_START_OVER, label: "Start over" },
            { id: HERO_DEATH_DIALOG_CHOICE_STAY, label: "Stay here" }
        ],
        owner
    }

    if (dlg && typeof dlg.show === "function" && (pid | 0) === (localPid | 0)) {
        try { dlg.show(payload) } catch { }
    }

    if (g && g.__isHost && net && typeof net.sendDialog === "function") {
        if ((pid | 0) !== (localPid | 0)) {
            try { net.sendDialog("show", payload, pid | 0) } catch { }
        }
    }

    if (!isHeadstone) {
        sprites.setDataBoolean(hero, HERO_DATA.DEAD_DIALOG, true)
    }
}

function _heroDeath_enterGhost(heroIndex: number, hero: Sprite, now: number): void {
    if (!hero) return
    if (sprites.readDataBoolean(hero, HERO_DATA.DEAD_GHOST)) return

    hero.vx = 0
    hero.vy = 0
    sprites.setDataNumber(hero, HERO_DATA.STORED_VX, 0)
    sprites.setDataNumber(hero, HERO_DATA.STORED_VY, 0)

    const wasLocked = sprites.readDataBoolean(hero, HERO_DATA.INPUT_LOCKED)
    if (!wasLocked) lockHeroControls(heroIndex)
    else sprites.setDataBoolean(hero, HERO_DATA.INPUT_LOCKED, true)
    sprites.setDataNumber(hero, HERO_DATA.BUSY_UNTIL, 0)
    sprites.setDataString(hero, HERO_DATA.ActionKind, "deadGhost")
    hero.setFlag(SpriteFlag.Ghost, true)

    const pick = _heroDeath_pickTileRC(hero)
    const anchorX = _dunColToX(pick.c | 0)
    const anchorY = _dunRowToY(pick.r | 0)
    hero.x = anchorX | 0
    hero.y = anchorY | 0
    sprites.setDataNumber(hero, HERO_DATA.DEAD_ANCHOR_X, anchorX | 0)
    sprites.setDataNumber(hero, HERO_DATA.DEAD_ANCHOR_Y, anchorY | 0)
    sprites.setDataNumber(hero, HERO_DATA.DEAD_LEASH_PX, HERO_DEATH_LEASH_PX | 0)
    sprites.setDataNumber(hero, HERO_DATA.GHOST_ALPHA, HERO_DEATH_GHOST_ALPHA)
    sprites.setDataNumber(hero, HERO_DATA.GHOST_TINT, HERO_DEATH_GHOST_TINT | 0)
    sprites.setDataBoolean(hero, HERO_DATA.GHOST_ACTIVE, true)

    const idleDur = _ambientPhaseWindowMs("idle") | 0
    setHeroPhaseString(heroIndex, "idle", "heroDeathGhost")
    _animKeys_stampPhaseWindow(heroIndex, hero, "idle", now | 0, idleDur, "HERO_DEATH_GHOST", "heroDeathGhost")

    sprites.setDataBoolean(hero, HERO_DATA.DEAD_GHOST, true)
    sprites.setDataNumber(hero, HERO_DATA.DEATH_UNTIL, 0)
}

function _heroDeath_parseDialogOwner(owner: string): { prefix: string; profile: string; pid: number } {
    const raw = String(owner || "")
    const idx = raw.indexOf(":")
    if (idx <= 0) return { prefix: "", profile: "", pid: 0 }
    const prefix = raw.slice(0, idx)
    const rest = raw.slice(idx + 1)
    if (!rest) return { prefix, profile: "", pid: 0 }
    const parts = rest.split(":")
    let pid = 0
    if (parts.length > 1) {
        const last = parts[parts.length - 1]
        if (/^\d+$/.test(last)) {
            pid = parseInt(last, 10) | 0
            parts.pop()
        }
    }
    const profile = parts.join(":")
    return { prefix, profile, pid }
}

function _heroDeath_applyGhostLeash(): void {
    for (let hi = 0; hi < heroes.length; hi++) {
        const hero = heroes[hi]
        if (!hero || (hero.flags & sprites.Flag.Destroyed)) continue
        if (!sprites.readDataBoolean(hero, HERO_DATA.DEAD_GHOST)) continue

        const profileKey = _heroProfileKeyForIndex(hi)
        if (profileKey) {
            const st = _getInputStateForProfile(profileKey)
            if (st) {
                let fx = sprites.readDataNumber(hero, HERO_DATA.FACING_X) | 0
                let fy = sprites.readDataNumber(hero, HERO_DATA.FACING_Y) | 0
                if (st.left) fx = -1
                else if (st.right) fx = 1
                if (st.up) fy = -1
                else if (st.down) fy = 1
                _setHeroFacingX(hi, fx)
                _setHeroFacingY(hi, fy)
                syncHeroDirData(hi)
            }
        }

        const anchorX = sprites.readDataNumber(hero, HERO_DATA.DEAD_ANCHOR_X) | 0
        const anchorY = sprites.readDataNumber(hero, HERO_DATA.DEAD_ANCHOR_Y) | 0
        let leash = sprites.readDataNumber(hero, HERO_DATA.DEAD_LEASH_PX) | 0
        if (leash <= 0) leash = HERO_DEATH_LEASH_PX | 0

        hero.vx = 0
        hero.vy = 0

        const dx = (hero.x | 0) - (anchorX | 0)
        const dy = (hero.y | 0) - (anchorY | 0)
        const dist2 = (dx * dx + dy * dy) | 0
        const leash2 = (leash * leash) | 0
        if (dist2 <= leash2 || leash <= 0) continue

        const dist = Math.sqrt(dist2)
        if (dist <= 0) continue
        const nx = dx / dist
        const ny = dy / dist
        hero.x = Math.round(anchorX + nx * leash)
        hero.y = Math.round(anchorY + ny * leash)
    }
}

function _heroDeath_requestLoadLatestSave(profileKey: string, pid: number, mode?: "latest" | "floor0"): void {
    const g: any = globalThis as any
    if (!g) return
    if (g.__deathLoadInFlight) return

    const net: any = g.__net
    const isHost = (typeof g.__isHost === "boolean") ? !!g.__isHost : true
    const loadMode = mode === "floor0" ? "floor0" : "latest"

    if (!isHost) {
        if (net && typeof net.sendUiCommand === "function") {
            const type = loadMode === "floor0" ? "loadStartOver" : "loadRecentSave"
            try { net.sendUiCommand({ type, profile: profileKey || "", reason: "death", playerId: pid | 0 }) } catch { }
        }
        return
    }

    const fn = g.__hero_requestLoadLatestSave
    if (typeof fn !== "function") return

    g.__deathLoadInFlight = true
    let out: any = null
    try {
        out = fn({ profile: profileKey || "", reason: "death", pid: pid | 0, mode: loadMode })
    } catch {
        g.__deathLoadInFlight = false
        return
    }
    if (out && typeof out.finally === "function") {
        out.finally(() => { g.__deathLoadInFlight = false })
    } else {
        g.__deathLoadInFlight = false
    }
}

function _dunRestartCurrentFloor(reason: string): boolean {
    if (!DUNGEON_MODE_ACTIVE) return false
    const g: any = globalThis as any
    if (g && g.__isHost === false) return false
    try { if (g) g.__forceScreenFlashOnNextTilemap = true } catch { }
    _dunTeleportCommitAtMs = 0
    _dunAllReadySinceMs = 0
    _dunRuneSpinSinceMs = 0
    relic_cancelNextFloorChoiceIfPending(`respawn:${reason || "restart"}`)
    _dunEnterFloor(_dunFloorIndex | 0, String(_dunFloorKind || DUNGEON_KIND_COMBAT), game.runtime() | 0)
    return true
}

function _heroDeath_tryRespawn(profileKey: string): { ok: boolean; reason: string } {
    const key = _death_normProfileKey(profileKey)
    if (!key) return { ok: false, reason: "no-profile" }
    const cost = _death_respawnCostForProfile(key)
    if (!_death_spendRespawnFund(key, cost)) {
        return { ok: false, reason: "insufficient-fund" }
    }
    const hi = (profileToHeroIndex[key] | 0)
    if (hi < 0 || hi >= heroes.length) return { ok: false, reason: "no-hero" }
    const hero = heroes[hi]
    if (!hero || (hero.flags & sprites.Flag.Destroyed)) return { ok: false, reason: "no-hero" }

    sprites.setDataBoolean(hero, HERO_DATA.IS_DEAD, false)
    sprites.setDataNumber(hero, HERO_DATA.DEATH_UNTIL, 0)
    sprites.setDataBoolean(hero, HERO_DATA.DEAD_GHOST, false)
    sprites.setDataBoolean(hero, HERO_DATA.DEAD_DIALOG, false)
    sprites.setDataBoolean(hero, HERO_DATA.DEAD_MARKER, false)
    sprites.setDataBoolean(hero, HERO_DATA.GHOST_ACTIVE, false)
    sprites.setDataNumber(hero, HERO_DATA.GHOST_ALPHA, 0)
    sprites.setDataNumber(hero, HERO_DATA.GHOST_TINT, 0)
    sprites.setDataNumber(hero, HERO_DATA.DEAD_ANCHOR_X, 0)
    sprites.setDataNumber(hero, HERO_DATA.DEAD_ANCHOR_Y, 0)
    sprites.setDataNumber(hero, HERO_DATA.DEAD_LEASH_PX, 0)
    sprites.setDataString(hero, HERO_DATA.ActionKind, "none")
    sprites.setDataNumber(hero, HERO_DATA.ActionVariantBtnId, 0)
    sprites.setDataNumber(hero, HERO_DATA.ActionSeed, 0)
    sprites.setDataNumber(hero, HERO_DATA.ActionTargetSpriteId, 0)

    hero.setFlag(SpriteFlag.Ghost, false)

    const maxHp = sprites.readDataNumber(hero, HERO_DATA.MAX_HP) | 0
    const newHp = maxHp > 0 ? maxHp : 1
    sprites.setDataNumber(hero, HERO_DATA.HP, newHp)
    const hpBar = _getHeroHPBar(hi)
    if (!hpBar || (hpBar.flags & sprites.Flag.Destroyed)) {
        initHeroHP(hi, hero, (maxHp > 0 ? maxHp : newHp) | 0)
    } else {
        updateHeroHPBar(hi)
    }

    unlockHeroControls(hi)
    setHeroPhaseString(hi, "idle")
    _animKeys_stampPhaseWindow(hi, hero, "idle", game.runtime() | 0, _ambientPhaseWindowMs("idle"), "respawn")

    _heroDeath_clearHeadstone(key)
    _dunRestartCurrentFloor("respawn")
    _beginHeroTeleportFx(hi, hero, 1, key, "respawn")
    return { ok: true, reason: "respawned" }
}

function _heroDeath_contribute(profileKey: string, contributorPid: number): { ok: boolean; reason: string } {
    const key = _death_normProfileKey(profileKey)
    if (!key) return { ok: false, reason: "no-profile" }
    const hi = _uiResolveHeroIndexForPid(contributorPid | 0)
    if (hi < 0) return { ok: false, reason: "no-hero" }
    const coins = getHeroCoins(hi) | 0
    if (coins <= 0) return { ok: false, reason: "no-coins" }
    setHeroCoins(hi, 0)
    _death_addRespawnFund(key, coins | 0)
    return { ok: true, reason: "contributed" }
}

// New helper: clean up heroes after their death animation finishes

function updateHeroDeaths(now: number) {

    const g: any = globalThis as any
    const isHost = (g && typeof g.__isHost === "boolean") ? !!g.__isHost : true
    if (!isHost) return

    for (let i = 0; i < heroes.length; i++) {

        const hero = heroes[i];

        if (!hero) continue;



        if (!sprites.readDataBoolean(hero, HERO_DATA.IS_DEAD)) {
            const hp = sprites.readDataNumber(hero, HERO_DATA.HP) | 0;
            if (hp <= 0) {
                applyDamageToHeroIndex(i, 0);
            }
        }

        if (!sprites.readDataBoolean(hero, HERO_DATA.IS_DEAD)) continue;



        if (sprites.readDataBoolean(hero, HERO_DATA.DEAD_GHOST)) continue

        const deathUntil = sprites.readDataNumber(hero, HERO_DATA.DEATH_UNTIL) | 0;
        if (deathUntil > 0 && now < deathUntil) continue

        // RELIC HOOK: hero death finalization (after death anim window)
        try {
            const ctx: RelicHeroDeathFinalContext = {
                now: now | 0,
                hi: i | 0,
                hero,
            }
            relic_onHeroDeathFinal(ctx)
        } catch { }

        _heroDeath_spawnHeadstone(hero)

        const pid = sprites.readDataNumber(hero, HERO_DATA.OWNER) | 0
        let profileKey = _heroProfileKeyForIndex(i)
        if (!profileKey) profileKey = sprites.readDataString(hero, HERO_DATA.NAME) || ""
        _heroDeath_showDialog(hero, pid | 0, profileKey || "")

        _heroDeath_enterGhost(i, hero, now)

    }

}





function updateHeroMovementPhase(now: number) {

    const nowMs = now | 0



    for (let hi = 0; hi < heroes.length; hi++) {

        const hero = heroes[hi]

        if (!hero) continue



        // Don't stomp death visuals

        if (sprites.readDataBoolean(hero, HERO_DATA.IS_DEAD)) {

            _dbgContract_noteWhy(hi, "AMBIENT_SKIP_DEAD", "updateHeroMovementPhase")

            continue

        }

        const teleMode = sprites.readDataNumber(hero, HERO_TELE_FX_MODE_KEY) | 0
        if (teleMode) {
            _dbgContract_noteWhy(hi, "AMBIENT_SKIP_TELEPORT", "updateHeroMovementPhase")
            continue
        }



        // Optional: avoid stomping NPC-ish actors (shopkeeper, announcer, etc.)

        const pIndex = sprites.readDataNumber(hero, HERO_DATA.PLAYER_INDEX) | 0

        const heroName0 = (sprites.readDataString(hero, "heroName") || "")

        if (pIndex >= 90 || heroName0 === "Shopkeeper") {

            _dbgContract_noteWhy(hi, "AMBIENT_SKIP_NPC", "updateHeroMovementPhase")

            continue

        }



        // Intellect LAND owns the phase until finishIntellectSpellForHero runs.

        const landEnd = sprites.readDataNumber(hero, INT_CAST_LAND_END_MS_KEY) | 0

        if (landEnd > 0 && nowMs < landEnd) {

            _dbgContract_noteWhy(hi, "AMBIENT_SKIP_INT_LAND", "updateHeroMovementPhase")

            _dbgMovePipeTick("AMB_SKIP", hi, hero, nowMs, `reason=INT_LAND now=${nowMs} landEnd=${landEnd}`)

            continue

        }



        // Intellect "controlling spell" owns the phase entirely (cast / control visuals)

        if (sprites.readDataBoolean(hero, HERO_DATA.IS_CONTROLLING_SPELL)) {

            _dbgContract_noteWhy(hi, "AMBIENT_SKIP_CTRL_SPELL", "updateHeroMovementPhase")

            _dbgMovePipeTick("AMB_SKIP", hi, hero, nowMs, "reason=CTRL_SPELL")

            continue

        }



        // Agility execute owns the phase entirely

        const agiState = sprites.readDataNumber(hero, HERO_DATA.AGI_STATE) | 0
        const hookState = sprites.readDataNumber(hero, HERO_DATA.AGI_HOOK_STATE) | 0

        if (agiState === AGI_STATE.EXECUTING) {

            _dbgContract_noteWhy(hi, "AMBIENT_SKIP_AGI_EXEC", "updateHeroMovementPhase")

            _dbgMovePipeTick("AMB_SKIP", hi, hero, nowMs, "reason=AGI_EXECUTING")

            continue

        }

        if (hookState === AGI_HOOK_STATE.AIMING || hookState === AGI_HOOK_STATE.EXTEND || hookState === AGI_HOOK_STATE.RETRACT || hookState === AGI_HOOK_STATE.RECOVER) {
            _dbgContract_noteWhy(hi, "AMBIENT_SKIP_AGI_EXEC", "updateHeroMovementPhase(hookshot)")
            _dbgMovePipeTick("AMB_SKIP", hi, hero, nowMs, "reason=AGI_HOOKSHOT")
            continue
        }



        // Strength charging owns the phase ("slash")

        if (sprites.readDataBoolean(hero, HERO_DATA.STR_CHARGING)) {

            _dbgContract_noteWhy(hi, "AMBIENT_SKIP_STR_CHARGING", "updateHeroMovementPhase")

            _dbgMovePipeTick("AMB_SKIP", hi, hero, nowMs, "reason=STR_CHARGING")

            continue

        }



        // If a hold-frame / override is active, don't stomp phase either

        const fco = sprites.readDataNumber(hero, HERO_DATA.FRAME_COL_OVERRIDE) | 0

        if (fco >= 0) {

            _dbgContract_noteWhy(hi, "AMBIENT_SKIP_FRAME_COL_OVERRIDE", "updateHeroMovementPhase")

            _dbgMovePipeTick("AMB_SKIP", hi, hero, nowMs, "reason=FRAME_COL_OVERRIDE")

            continue

        }



        // If we're busy (attack/cast/death window), do not override the phase

        const busyUntil = sprites.readDataNumber(hero, HERO_DATA.BUSY_UNTIL) | 0

        if (busyUntil > 0 && nowMs < busyUntil) {

            _dbgContract_noteWhy(hi, "AMBIENT_SKIP_BUSY", "updateHeroMovementPhase")

            _dbgMovePipeTick("AMB_SKIP", hi, hero, nowMs, `reason=BUSY now=${nowMs} busyUntil=${busyUntil}`)

            continue

        }



        // Decide ambient phase (PRESERVE OLD BEHAVIOR)

        let desiredPhase = "idle"



        const RUN_THRESH_SQ = 50

        const WALK_THRESH_SQ = 10



        // Agility combo build mode: show combat idle pose

        if (agiState === AGI_STATE.ARMED) {

            desiredPhase = "combatIdle"

        } else {

            const speedSq = (hero.vx * hero.vx) + (hero.vy * hero.vy)

            if (speedSq > RUN_THRESH_SQ) desiredPhase = "run"

            else if (speedSq > WALK_THRESH_SQ) desiredPhase = "walk"

            else desiredPhase = "idle"

        }



        // Unified contract: ambient is NOT segmented

        _animKeys_clearPhasePart(

            hi,

            hero,

            nowMs,

            "AMBIENT_CLEAR_PHASE_PART",

            "updateHeroMovementPhase(ambient:clearPart)"

        )



        // If ambient owns the hero, ActionKind MUST be "none".

        const ak = sprites.readDataString(hero, HERO_DATA.ActionKind) || "none"

        if (ak !== "none") {

            _dbgContract_noteWhy(hi, "AMBIENT_CLEAR_ACTION_KIND", "updateHeroMovementPhase")



            sprites.setDataString(hero, HERO_DATA.ActionKind, "none")

            sprites.setDataNumber(hero, HERO_DATA.ActionVariantBtnId, 0)

            sprites.setDataNumber(hero, HERO_DATA.ActionSeed, 0)

            sprites.setDataNumber(hero, HERO_DATA.ActionTargetSpriteId, 0)



            _dbgMovePipeTick("AMB_CLR_AK", hi, hero, nowMs, `prevActionKind=${ak} -> none`)

        }



        const wantDur = _ambientPhaseWindowMs(desiredPhase) | 0



        // Current phase window state (authoritative keys)

        const curPhaseName = sprites.readDataString(hero, HERO_DATA.PhaseName) || ""

        const curStart = sprites.readDataNumber(hero, HERO_DATA.PhaseStartMs) | 0

        const curDur = sprites.readDataNumber(hero, HERO_DATA.PhaseDurationMs) | 0

        // Let special feedback phases (sit/emote/jump) live out their stamped window without being stomped.
        if ((curPhaseName === "sit" || curPhaseName === "emote" || curPhaseName === "jump") && curStart > 0 && curDur > 0 && nowMs < (curStart + curDur)) {
            _dbgContract_noteWhy(hi, "AMBIENT_SKIP_SPECIAL", "updateHeroMovementPhase")
            continue
        }



        // If PhaseName differs, switch immediately and stamp a valid non-zero window.

        if (curPhaseName !== desiredPhase) {

            _dbgContract_noteWhy(hi, "AMBIENT_SET_PHASE_CHANGE", "updateHeroMovementPhase")

            setHeroPhaseString(hi, desiredPhase)

            _animKeys_stampPhaseWindow(hi, hero, desiredPhase, nowMs, wantDur, "updateHeroMovementPhase(ambient:change)")

            continue

        }



        // If window is invalid, repair it.

        if (curStart <= 0 || curDur <= 0) {

            _dbgContract_noteWhy(hi, "AMBIENT_SET_PHASE_REPAIR_WINDOW", "updateHeroMovementPhase")

            _animKeys_stampPhaseWindow(hi, hero, desiredPhase, nowMs, wantDur, "updateHeroMovementPhase(ambient:repair)")

            continue

        }



        // Window is valid and PhaseName matches desired ambient.

        // Update PhaseProgressInt continuously so Phaser can animate idle/run/combatIdle via progress.

        _dbgContract_noteWhy(hi, "AMBIENT_SET_PHASE_PROGRESS", "updateHeroMovementPhase")

        const elapsed = ((nowMs - curStart) % curDur) | 0

        const e = elapsed < 0 ? 0 : elapsed

        const pInt = clampInt(Math.idiv(PHASE_PROGRESS_MAX * e, curDur), 0, PHASE_PROGRESS_MAX)

        sprites.setDataNumber(hero, HERO_DATA.PhaseProgressInt, pInt)

    }

}









// LOCK/UNLOCK HYGIENE (ALLOWED CLEARER)

// Allowed: clearing PhaseFlags and EventMask on unlock to prevent stale visuals.

// NOT allowed: incrementing ActionSequence or changing ActionKind.

// Events: never touch EventSequence here (emitters only).

function updateHeroControlLocks(now: number) {

    const nowMs = now | 0



    for (let i = 0; i < heroes.length; i++) {

        const hero = heroes[i]

        if (!hero) continue



        const agiState = sprites.readDataNumber(hero, HERO_DATA.AGI_STATE) | 0
        const hookState = sprites.readDataNumber(hero, HERO_DATA.AGI_HOOK_STATE) | 0

        const isAgiBuildMode = (agiState === AGI_STATE.ARMED)

        const isAgiExecuting = (agiState === AGI_STATE.EXECUTING)
        const isHookActive = (hookState === AGI_HOOK_STATE.AIMING || hookState === AGI_HOOK_STATE.EXTEND || hookState === AGI_HOOK_STATE.RETRACT || hookState === AGI_HOOK_STATE.RECOVER)



        const isCtrlSpell = sprites.readDataBoolean(hero, HERO_DATA.IS_CONTROLLING_SPELL)

        const isStrCharging = sprites.readDataBoolean(hero, HERO_DATA.STR_CHARGING)

        const isSupportPuzzle = (supportPuzzleActive && supportPuzzleActive[i]) ? true : false



        // If we are in Agility build mode but somehow not locked, lock now.

        // Critical: combo build must stay locked after dash ends.

        const locked0 = sprites.readDataBoolean(hero, HERO_DATA.INPUT_LOCKED)

        if (!isCtrlSpell && isAgiBuildMode && !locked0) {

            lockHeroControls(i)

            sprites.setDataNumber(hero, HERO_DATA.STORED_VX, 0)

            sprites.setDataNumber(hero, HERO_DATA.STORED_VY, 0)

            hero.vx = 0

            hero.vy = 0

        }



        // IMPORTANT: declare lockedNow BEFORE any branch that uses it

        const lockedNow = sprites.readDataBoolean(hero, HERO_DATA.INPUT_LOCKED)



        // Mirror from HERO_DATA (canonical) into heroBusyUntil[] for consistency

        const busyUntil = getHeroBusyUntil(i) | 0



        // ------------------------------------------------------------

        // LOCK OWNERSHIP CASES (do NOT auto-unlock here)

        // ------------------------------------------------------------



        // Intellect “controlling spell” owns the lock window (often not busyUntil-driven).

        // Keep hero frozen and do NOT auto-unlock based on busyUntil.

        if (isCtrlSpell) {

            if (!lockedNow) lockHeroControls(i)

            hero.vx = 0

            hero.vy = 0

            sprites.setDataNumber(hero, HERO_DATA.STORED_VX, 0)

            sprites.setDataNumber(hero, HERO_DATA.STORED_VY, 0)

            continue

        }



        // NEW: Intellect LAND owns the lock window until landEnd expires.

        // Prevent generic busyUntil unlock from firing during land.

        const landEnd = sprites.readDataNumber(hero, INT_CAST_LAND_END_MS_KEY) | 0

        if (landEnd > 0 && nowMs < landEnd) {

            if (!lockedNow) lockHeroControls(i)

            hero.vx = 0

            hero.vy = 0

            sprites.setDataNumber(hero, HERO_DATA.STORED_VX, 0)

            sprites.setDataNumber(hero, HERO_DATA.STORED_VY, 0)

            continue

        }



        // Support puzzle owns the lock (busyUntil is huge; cleared on solve).

        if (isSupportPuzzle) {

            if (!lockedNow) lockHeroControls(i)

            hero.vx = 0

            hero.vy = 0

            sprites.setDataNumber(hero, HERO_DATA.STORED_VX, 0)

            sprites.setDataNumber(hero, HERO_DATA.STORED_VY, 0)

            continue

        }

        const bossKnock = (sprites.readDataNumber(hero, HERO_BOSS_KNOCK_ACTIVE_KEY) | 0) !== 0
        if (bossKnock) {

            if (!lockedNow) lockHeroControls(i)

            hero.vx = 0

            hero.vy = 0

            sprites.setDataNumber(hero, HERO_DATA.STORED_VX, 0)

            sprites.setDataNumber(hero, HERO_DATA.STORED_VY, 0)

            continue

        }

        const bossIntroLock = (sprites.readDataNumber(hero, HERO_BOSS_INTRO_LOCK_KEY) | 0) !== 0
        if (bossIntroLock) {

            if (!lockedNow) lockHeroControls(i)

            hero.vx = 0

            hero.vy = 0

            sprites.setDataNumber(hero, HERO_DATA.STORED_VX, 0)

            sprites.setDataNumber(hero, HERO_DATA.STORED_VY, 0)

            continue

        }



        // Strength charging owns the lock. Never auto-unlock, never allow velocity.

        if (isStrCharging) {

            if (!lockedNow) lockHeroControls(i)

            hero.vx = 0

            hero.vy = 0

            sprites.setDataNumber(hero, HERO_DATA.STORED_VX, 0)

            sprites.setDataNumber(hero, HERO_DATA.STORED_VY, 0)

            continue

        }



        // During ARMED/EXECUTING: allow aim changes, but DO NOT allow velocity changes.

        // Unlock is handled by cancel or execute finish.

        if (isAgiBuildMode || isAgiExecuting) {

            if (!lockedNow) lockHeroControls(i)

            hero.vx = 0

            hero.vy = 0

            sprites.setDataNumber(hero, HERO_DATA.STORED_VX, 0)

            sprites.setDataNumber(hero, HERO_DATA.STORED_VY, 0)

            continue

        }

        // Agility hookshot owns the lock while aiming/extend/retract
        if (isHookActive) {
            if (!lockedNow) lockHeroControls(i)
            hero.vx = 0
            hero.vy = 0
            sprites.setDataNumber(hero, HERO_DATA.STORED_VX, 0)
            sprites.setDataNumber(hero, HERO_DATA.STORED_VY, 0)
            continue
        }



        // ------------------------------------------------------------

        // STRANDED LOCK REPAIR

        // If we are locked but have NO busy window and no ownership case,

        // we are in a broken state (this matches your Strength symptom).

        // ------------------------------------------------------------

        if (lockedNow && busyUntil <= 0) {

            sprites.setDataNumber(hero, HERO_DATA.STORED_VX, 0)

            sprites.setDataNumber(hero, HERO_DATA.STORED_VY, 0)

            hero.vx = 0

            hero.vy = 0



            sprites.setDataNumber(hero, HERO_DATA.PhaseFlags, 0)



            // Correct signature (this was your crash)

            _animEvent_clear(

                i,

                hero,

                "AMBIENT_SET_PHASE_REPAIR_WINDOW",

                "updateHeroControlLocks(repair:clearEvent)"

            )



            _animKeys_clearPhasePart(

                i,

                hero,

                nowMs | 0,

                "AMBIENT_SET_PHASE_REPAIR_WINDOW",

                "updateHeroControlLocks(repair:clearPart)"

            )



            if (DEBUG_ANIM_KEYS) console.log(_dbgAnimKeysLine(i, hero, "UNLOCK_REPAIR"))

            unlockHeroControls(i)

            continue

        }



        // ------------------------------------------------------------

        // NORMAL LOCK BEHAVIOR (dash / cast travel / etc.)

        // Preserve stored velocity until busyUntil ends.

        // ------------------------------------------------------------



        if (lockedNow) {

            _dbgMovePipeTick("LOCK_TICK", i, hero, nowMs, "")

            hero.vx = sprites.readDataNumber(hero, HERO_DATA.STORED_VX)

            hero.vy = sprites.readDataNumber(hero, HERO_DATA.STORED_VY)

        }



        // IMPORTANT: do NOT auto-unlock when busyUntil is 0.

        // Only unlock when an actual busy window expires.

        if (busyUntil > 0 && nowMs >= busyUntil) {



            // End of busy window

            clearHeroBusyUntil(i)

            sprites.setDataNumber(hero, HERO_DATA.PhaseFlags, 0)



            // Events: never touch EventSequence here (emitters only).

            // Correct signature (this was your crash)

            _animEvent_clear(

                i,

                hero,

                "AMBIENT_CLEAR_PHASE_PART",

                "updateHeroControlLocks(busyEnd:clearEvent)"

            )



            // Clear phase-part segmentation so we don't stay "windup"/"aim"/"puzzle" while idle

            _animKeys_clearPhasePart(

                i,

                hero,

                nowMs | 0,

                "AMBIENT_CLEAR_PHASE_PART",

                "updateHeroControlLocks(busyEnd:clearPart)"

            )



            // RenderStyle policy:

            // Keep RenderStyleMask as-is (persists until next action edge overwrites it).

            // If you want "style only during an action", uncomment the next line:

            // sprites.setDataNumber(hero, HERO_DATA.RenderStyleMask, 0)



            if (DEBUG_ANIM_KEYS) console.log(_dbgAnimKeysLine(i, hero, "UNLOCK"))

            const fco = sprites.readDataNumber(hero, HERO_DATA.FRAME_COL_OVERRIDE) | 0
            if (fco >= 0) {
                clearHeroFrameColOverride(i)
                sprites.setDataNumber(hero, STR_SWING_RETURN_FCO_KEY, 0)
                sprites.setDataNumber(hero, STR_SWING_SKIP_WINDUP_KEY, 0)
            }

            unlockHeroControls(i)



            // Return to ambient phase selection; do not force a phase here.

            // updateHeroMovementPhase() will decide idle/run/combatIdle.

        }

    }

}







// New helper: clear expired enemy effects (knockback, slow, etc.)

function updateEnemyEffects(now: number) {

    for (let j = 0; j < enemies.length; j++) {

        const e = enemies[j]

        if (!e) continue



        const kbUntil = sprites.readDataNumber(e, ENEMY_DATA.KNOCKBACK_UNTIL)

        if (kbUntil > 0 && now >= kbUntil) {

            e.vx = 0

            e.vy = 0

            sprites.setDataNumber(e, ENEMY_DATA.KNOCKBACK_UNTIL, 0)

        }



        const slowUntil = sprites.readDataNumber(e, ENEMY_DATA.SLOW_UNTIL)

        const slowPct = sprites.readDataNumber(e, ENEMY_DATA.SLOW_PCT)

        if (slowPct > 0 && slowUntil <= now) {

            sprites.setDataNumber(e, ENEMY_DATA.SLOW_PCT, 0)

        }

    }

}







function consumeAndDispatchPlayerIntents(nowMs: number): void {

    if (!HeroEngine._isStarted()) return

    if (SHOP_MODE_ACTIVE) return



    // NEW: dungeon can temporarily block intent dispatch (story/treasure/interact floors)

    // (This must exist as a global set by your dungeon system.)

    let blockIntents = false

    if (typeof (globalThis as any).DUNGEON_BLOCK_INTENTS === "boolean") {

        if ((globalThis as any).DUNGEON_BLOCK_INTENTS) blockIntents = true

    } else {

        // If you implemented DUNGEON_BLOCK_INTENTS as a normal variable, this line is harmless

        // because TS will resolve it at compile time. If not, it avoids breaking builds.

        // @ts-ignore

        if (typeof DUNGEON_BLOCK_INTENTS !== "undefined" && DUNGEON_BLOCK_INTENTS) blockIntents = true

    }



    const connectedMap = (isPhaserRuntime() && (globalThis as any).__netProfileConnected)
        ? ((globalThis as any).__netProfileConnected as Record<string, boolean>)
        : null

    const active: { hi: number; hero: Sprite; profile: string }[] = []
    for (let hi = 0; hi < heroes.length; hi++) {
        const hero = heroes[hi]
        if (!hero || (hero.flags & sprites.Flag.Destroyed)) continue
        if (sprites.readDataBoolean(hero, HERO_DATA.IS_DEAD)) continue
        const profile = _heroProfileKeyForIndex(hi)
        if (!profile) continue
        if (connectedMap && connectedMap[profile] === false) continue
        active.push({ hi, hero, profile })
    }

    if (blockIntents) {
        const uiAllowsAForHero = (hero: Sprite): boolean => {
            const uiMode = _uiReadNum(hero, HERO_UI_DATA.MODE, HERO_UI_MODE.NONE) | 0
            return uiMode === HERO_UI_MODE.LEVELUP || uiMode === HERO_UI_MODE.SHOP
        }

        for (const entry of active) {
            const allowA = uiAllowsAForHero(entry.hero)
            const pid = sprites.readDataNumber(entry.hero, HERO_DATA.OWNER) | 0
            if (pid <= 0) continue
            for (let i = 0; i < 2; i++) {
                const intent = _consumeIntentForProfile(entry.profile)
                if (!intent) break
                if (intent === "A+B" || intent === "B" || (allowA && intent === "A")) {
                    doHeroMoveForPlayer(pid, intent)
                }
            }
        }
        return
    }

    try {
        const now = nowMs | 0
        for (const entry of active) {
            const pid = sprites.readDataNumber(entry.hero, HERO_DATA.OWNER) | 0
            if (pid <= 0) continue
            const intent = _consumeIntentForProfile(entry.profile)
            if (!intent) continue
            if (DEBUG_HERO_LOGIC) console.log("[TIMER80] BEFORE pid=" + pid + " intent=" + intent + " timeMs=" + now)
            doHeroMoveForPlayer(pid, intent)
            if (DEBUG_HERO_LOGIC) console.log("[TIMER80] AFTER pid=" + pid + " intent=" + intent + " timeMs=" + now)
        }
    } catch (e) {
        console.log("[TIMER80] ERROR in doHeroMoveForPlayer:" + e)
    }

}

function _snapshotHeroPrevPositions(): void {
    for (let hi = 0; hi < heroes.length; hi++) {
        const h = heroes[hi]
        if (!h) continue
        sprites.setDataNumber(h, HERO_DATA.PREV_X, h.x)
        sprites.setDataNumber(h, HERO_DATA.PREV_Y, h.y)
    }
}

function _snapshotEnemyPrevPositions(): void {
    for (let ei = 0; ei < enemies.length; ei++) {
        const e = enemies[ei]
        if (!e) continue
        sprites.setDataNumber(e, ENEMY_DATA.PREV_X, e.x)
        sprites.setDataNumber(e, ENEMY_DATA.PREV_Y, e.y)
    }
}

