let _dunWavePlan: GenWaveDef[] = []







const DEFAULT_MONSTER_FRAME_W = BALANCE.MONSTERS.DEFAULT_FRAME_W

const DEFAULT_MONSTER_FRAME_H = BALANCE.MONSTERS.DEFAULT_FRAME_H



// Default collider rule: for most frames < 96px, treat as 1-tile footprint (32×32).

// For big frames (>=96px), default to 2-tile footprint (64×64).

const MONSTER_COLLIDER_BIG_THRESHOLD_PX = BALANCE.MONSTERS.COLLIDER_BIG_THRESHOLD_PX



interface MonsterSizing {

    frameW: number

    frameH: number

    colliderW: number

    colliderH: number

    renderOffsX: number

    renderOffsY: number

}



function _monsterFrameSizeForId(monsterId: string): { w: number, h: number } {

    const md = _monsterDefById(monsterId)

    if (md && (md.frameW || md.frameH)) {

        const w = (md.frameW || DEFAULT_MONSTER_FRAME_W) | 0

        const h = (md.frameH || DEFAULT_MONSTER_FRAME_H) | 0

        return { w, h }

    }



    const atlasSize = getLpcFrameSizeForMonster(monsterId)

    if (atlasSize) return { w: atlasSize.w | 0, h: atlasSize.h | 0 }



    return { w: DEFAULT_MONSTER_FRAME_W, h: DEFAULT_MONSTER_FRAME_H }

}



function _defaultColliderFromFrame(frameW: number, frameH: number): { cw: number, ch: number } {

    const tile = WORLD_TILE_SIZE | 0



    let cw = tile

    let ch = tile



    if ((frameW | 0) <= tile) cw = frameW | 0

    else if ((frameW | 0) >= (MONSTER_COLLIDER_BIG_THRESHOLD_PX | 0)) cw = (tile * 2) | 0



    if ((frameH | 0) <= tile) ch = frameH | 0

    else if ((frameH | 0) >= (MONSTER_COLLIDER_BIG_THRESHOLD_PX | 0)) ch = (tile * 2) | 0



    if (cw < 1) cw = 1

    if (ch < 1) ch = 1

    return { cw, ch }

}

const MONSTER_AURA_ALIAS: Record<string, string> = {
    // Use horse body bounds for pegasus so wings don't block collisions.
    "pegasus": "horse-white",
    "worm small": "small worm",
    "worm big": "big worm"
}

function _monsterAuraAliasForId(monsterId: string): string {
    const key = String(monsterId || "").toLowerCase()
    return MONSTER_AURA_ALIAS[key] || key
}

function _monsterAuraForDir(monsterId: string, dir: string): any {
    const auraId = _monsterAuraAliasForId(monsterId)
    const aura = (MONSTER_AURA_FEET as any)[auraId] as any
    if (!aura) return null
    const key = (dir || "").toLowerCase()
    const byDir = aura && aura.dirs
    if (byDir && byDir[key]) return byDir[key]
    return aura
}

function _enemyApplyAuraForDir(enemy: Sprite, dir: string): void {
    const monsterId = sprites.readDataString(enemy, ENEMY_DATA.MONSTER_ID) || ""
    if (!monsterId) return
    const aura = _monsterAuraForDir(monsterId, dir)
    if (!aura) return

    const scaleX1000 = sprites.readDataNumber(enemy, "__monsterScaleX1000") | 0
    const scaleY1000 = sprites.readDataNumber(enemy, "__monsterScaleY1000") | 0
    const scaleX = (scaleX1000 > 0 ? (scaleX1000 / 1000) : 1)
    const scaleY = (scaleY1000 > 0 ? (scaleY1000 / 1000) : 1)

    const baseFrameW = (aura.frameW | 0) || 0
    const baseFrameH = (aura.frameH | 0) || 0
    const baseMinX = (aura.minX | 0) || 0
    const baseMinY = (aura.minY | 0) || 0
    const baseMaxX = (aura.maxX | 0) || 0
    const baseMaxY = (aura.maxY | 0) || 0
    const baseCenterX = (aura.centerX | 0) || 0
    const baseCenterY = (aura.centerY | 0) || 0
    const baseFoot = (aura.footBottom | 0) || 0

    const baseW = Math.max(1, (baseMaxX - baseMinX + 1) | 0) | 0
    const baseH = Math.max(1, (baseMaxY - baseMinY + 1) | 0) | 0
    const scaledW = Math.max(1, Math.round(baseW * scaleX)) | 0
    const scaledH = Math.max(1, Math.round(baseH * scaleY)) | 0
    const scaledMinX = Math.round(baseMinX * scaleX) | 0
    const scaledMinY = Math.round(baseMinY * scaleY) | 0
    const centerOffX = (baseCenterX - baseMinX) | 0
    const centerOffY = (baseCenterY - baseMinY) | 0
    const scaledCenterX = (scaledMinX + Math.round(centerOffX * scaleX)) | 0
    const scaledCenterY = (scaledMinY + Math.round(centerOffY * scaleY)) | 0
    const scaledMaxX = (scaledMinX + scaledW - 1) | 0
    const scaledMaxY = (scaledMinY + scaledH - 1) | 0

    const frameW = Math.max(1, Math.round(baseFrameW * scaleX)) | 0
    const frameH = Math.max(1, Math.round(baseFrameH * scaleY)) | 0
    const footBottom = Math.round(baseFoot * scaleY) | 0

    sprites.setDataNumber(enemy, "__monsterAuraFrameW", frameW | 0)
    sprites.setDataNumber(enemy, "__monsterAuraFrameH", frameH | 0)
    sprites.setDataNumber(enemy, "__monsterAuraFootBottom", footBottom | 0)
    sprites.setDataNumber(enemy, "__monsterAuraOutlineSides", (aura.outlineSides | 0) || 0)
    sprites.setDataNumber(enemy, "__monsterAuraMinX", scaledMinX | 0)
    sprites.setDataNumber(enemy, "__monsterAuraMinY", scaledMinY | 0)
    sprites.setDataNumber(enemy, "__monsterAuraMaxX", scaledMaxX | 0)
    sprites.setDataNumber(enemy, "__monsterAuraMaxY", scaledMaxY | 0)
    sprites.setDataNumber(enemy, "__monsterAuraCenterX", scaledCenterX | 0)
    sprites.setDataNumber(enemy, "__monsterAuraCenterY", scaledCenterY | 0)
    if (Array.isArray(aura.outline)) {
        const anyEnemy: any = enemy as any
        if (!anyEnemy.data) anyEnemy.data = {}
        if (scaleX === 1 && scaleY === 1) {
            anyEnemy.data.__monsterAuraOutline = aura.outline
        } else {
            const scaledOutline: number[][] = []
            for (let i = 0; i < aura.outline.length; i++) {
                const p = aura.outline[i]
                if (!p || p.length < 2) continue
                const sx = Math.round((p[0] | 0) * scaleX) | 0
                const sy = Math.round((p[1] | 0) * scaleY) | 0
                scaledOutline.push([sx, sy])
            }
            anyEnemy.data.__monsterAuraOutline = scaledOutline
        }
    }

    if (scaledW > 0) sprites.setDataNumber(enemy, ENEMY_DATA.COLLIDER_W, scaledW | 0)
    if (scaledH > 0) sprites.setDataNumber(enemy, ENEMY_DATA.COLLIDER_H, scaledH | 0)

    if (frameW > 0 && frameH > 0) {
        const frameCenterX = Math.round((frameW - 1) / 2) | 0
        const frameCenterY = Math.round((frameH - 1) / 2) | 0
        const renderOffsX = (frameCenterX - scaledCenterX) | 0
        const renderOffsY = (frameCenterY - scaledCenterY) | 0
        sprites.setDataNumber(enemy, ENEMY_DATA.RENDER_OFFS_X, renderOffsX)
        sprites.setDataNumber(enemy, ENEMY_DATA.RENDER_OFFS_Y, renderOffsY)
    }
}

const ENEMY_LPC_WALK_MS = 800
const ENEMY_LPC_IDLE_MS = 1100
const ENEMY_LPC_HURT_MS = 350

function _enemyInitLpcVisuals(enemy: Sprite, def: EnemyLpcDef, nowMs: number): void {
    if (!enemy || !def) return

    const heroName = String(def.heroName || "")
    const fam = String(def.family || "base").toLowerCase()

    sprites.setDataBoolean(enemy, ENEMY_LPC_FLAG_KEY, true)
    sprites.setDataString(enemy, HERO_DATA.NAME, heroName)
    sprites.setDataString(enemy, "heroName", heroName)
    sprites.setDataString(enemy, HERO_DATA.FAMILY, fam)
    sprites.setDataString(enemy, "heroFamily", fam)
    sprites.setDataNumber(enemy, "heroIndex", ENEMY_LPC_HERO_INDEX_BASE + ((enemy.id | 0) & 0xffff))

    sprites.setDataString(enemy, HERO_DATA.DIR, "down")
    sprites.setDataString(enemy, "dir", "down")
    sprites.setDataString(enemy, HERO_DATA.PHASE, "walk")
    sprites.setDataString(enemy, "phase", "walk")
    sprites.setDataNumber(enemy, HERO_DATA.FRAME_COL_OVERRIDE, -1)

    // Weapon overlay slots (match NPC pipeline shape)
    const w = def.weapons || {}
    if (w.slash != null) sprites.setDataString(enemy, HERO_DATA.WEAPON_SLASH_ID, w.slash || "")
    if (w.thrust != null) sprites.setDataString(enemy, HERO_DATA.WEAPON_THRUST_ID, w.thrust || "")
    if (w.cast != null) sprites.setDataString(enemy, HERO_DATA.WEAPON_CAST_ID, w.cast || "")
    if (w.exec != null) sprites.setDataString(enemy, HERO_DATA.WEAPON_EXEC_ID, w.exec || "")
    if (w.combo != null) sprites.setDataString(enemy, HERO_DATA.WEAPON_COMBO_ID, w.combo || "")
    if (w.int != null) sprites.setDataString(enemy, HERO_DATA_WEAPON_INTELLIGENCE_ID, w.int || "")
    if (w.sup != null) sprites.setDataString(enemy, HERO_DATA_WEAPON_SUPPORT_ID, w.sup || "")

    // LPC enemies should align to their collider feet; ignore monster render offsets.
    sprites.setDataNumber(enemy, ENEMY_DATA.RENDER_OFFS_X, 0)
    sprites.setDataNumber(enemy, ENEMY_DATA.RENDER_OFFS_Y, 0)

    _stampHumanoidPhaseForSprite(enemy, "walk", nowMs, ENEMY_LPC_WALK_MS)
}

function _enemySyncLpcRenderPhase(enemy: Sprite, nowMs: number): void {
    if (!enemy || (enemy.flags & sprites.Flag.Destroyed)) return
    if (!_enemyIsLpc(enemy)) return

    const monsterId = sprites.readDataString(enemy, ENEMY_DATA.MONSTER_ID) || ""
    const def = _enemyLpcDefForId(monsterId)
    const attackPhase = (def && def.attackPhase) ? def.attackPhase : "slash"

    const deathUntil = sprites.readDataNumber(enemy, ENEMY_DATA.DEATH_UNTIL) | 0
    const aiPhase = (sprites.readDataString(enemy, "phase") || "walk").toLowerCase()

    let renderPhase = "idle"
    let durMs = ENEMY_LPC_IDLE_MS | 0

    if (deathUntil > 0) {
        renderPhase = "hurt"
        const deathMs = (sprites.readDataNumber(enemy, "deathAnimMs") | 0) || ENEMY_LPC_HURT_MS
        durMs = Math.max(1, deathMs | 0)
    } else if (aiPhase === "attack") {
        renderPhase = attackPhase
        const atkMs = (sprites.readDataNumber(enemy, "attackAnimMs") | 0) || 350
        durMs = Math.max(1, atkMs | 0)
    } else {
        const moving = (Math.abs(enemy.vx) + Math.abs(enemy.vy)) > 0.01
        renderPhase = moving ? "walk" : "idle"
        durMs = moving ? ENEMY_LPC_WALK_MS : ENEMY_LPC_IDLE_MS
    }

    const cur = (sprites.readDataString(enemy, HERO_DATA.PhaseName) || "").toLowerCase()
    if (cur !== renderPhase) {
        _stampHumanoidPhaseForSprite(enemy, renderPhase, nowMs, durMs | 0)
    }
}



function _monsterSizingForId(monsterId: string): MonsterSizing {

    const md = _monsterDefById(monsterId)

    const fs = _monsterFrameSizeForId(monsterId)

    const frameW = fs.w | 0

    const frameH = fs.h | 0

    const aura = _monsterAuraForDir(monsterId, "down")
    const auraMinX = aura && typeof aura.minX === "number" ? (aura.minX | 0) : 0
    const auraMinY = aura && typeof aura.minY === "number" ? (aura.minY | 0) : 0
    const auraMaxX = aura && typeof aura.maxX === "number" ? (aura.maxX | 0) : (frameW - 1)
    const auraMaxY = aura && typeof aura.maxY === "number" ? (aura.maxY | 0) : (frameH - 1)
    const auraCenterX = aura && typeof aura.centerX === "number" ? (aura.centerX | 0) : Math.round((frameW - 1) / 2)
    const auraCenterY = aura && typeof aura.centerY === "number" ? (aura.centerY | 0) : Math.round((frameH - 1) / 2)
    const hasAuraBounds = aura && typeof aura.minX === "number" && typeof aura.maxX === "number" && typeof aura.minY === "number" && typeof aura.maxY === "number"



    const defCol = _defaultColliderFromFrame(frameW, frameH)

    // Use aura/base frame size for collisions so monsters block at their visible footprint.
    let colliderW = ((md && md.colliderW) ? (md.colliderW | 0) : (frameW | 0)) | 0

    let colliderH = ((md && md.colliderH) ? (md.colliderH | 0) : (frameH | 0)) | 0

    if (hasAuraBounds) {
        colliderW = ((auraMaxX - auraMinX + 1) | 0)
        colliderH = ((auraMaxY - auraMinY + 1) | 0)
    }

    if (colliderW <= 0) colliderW = defCol.cw | 0

    if (colliderH <= 0) colliderH = defCol.ch | 0



    // Phaser sprite should be shifted UP so the "feet" sit on the collider

    // (centered collider vs centered art)

    let renderOffsX = 0
    let renderOffsY = 0

    if (hasAuraBounds) {
        const frameCenterX = Math.round((frameW - 1) / 2) | 0
        const frameCenterY = Math.round((frameH - 1) / 2) | 0
        renderOffsX = (frameCenterX - auraCenterX) | 0
        renderOffsY = (frameCenterY - auraCenterY) | 0
    } else if ((frameH | 0) > (colliderH | 0)) {
        renderOffsY = Math.idiv((frameH - colliderH) | 0, 2) | 0
    }



    return { frameW, frameH, colliderW, colliderH, renderOffsX, renderOffsY }

}





function _monsterDefById(id: string): MonsterDef {

    for (let i = 0; i < MONSTER_CATALOG.length; i++) {

        const d = MONSTER_CATALOG[i]

        if (d.id === id) return d

    }

    if (!_monsterMissingWarned.has(id)) {
        _monsterMissingWarned.add(id)
        console.warn(`[MONSTER] new monster "${id}" missing catalog entry (NEED TO CODE)`)
    }


    // fallback: unknown monsters still spawn but have "danger" = 999 so generator won't pick them

    return {

        id,

        danger: 999,

        hp: 1,

        damage: 1,

        speed: 1,

        xp: 1,

        advanceRangePx: 0

    }

}



function _clamp(n: number, lo: number, hi: number): number {

    if (n < lo) return lo

    if (n > hi) return hi

    return n

}



function _calcAdvanceRangePxForDanger(danger: number): number {
    const base = 60
    const step = 2
    const d = Math.max(0, danger | 0)
    const range = base + (step * d)
    return _clamp(range, 32, RANGED_ADVANCE_RANGE_CAP_PX)
}

function _floorDangerBase(floor1: number): number {

    // floor1 = 1..100

    // This is THE pacing knob. Keep it linear-ish for now.

    return BALANCE.WAVES.DANGER_BASE + (floor1 * BALANCE.WAVES.DANGER_PER_FLOOR)

}



function _pickArchetype(floor1: number, waveIndex: number, waveCount: number): WaveArchetype {

    // Early floors: more swarms. Later: more elites/mixed.

    const t = _clamp(floor1 / 100, 0, 1)



    const r = Math.random()

    const swarmW = (BALANCE.WAVES.ARCHETYPE_SWARM_WEIGHT_BASE + BALANCE.WAVES.ARCHETYPE_SWARM_WEIGHT_DELTA * t)

    const elitesW = (BALANCE.WAVES.ARCHETYPE_ELITES_WEIGHT_BASE + BALANCE.WAVES.ARCHETYPE_ELITES_WEIGHT_DELTA * t)

    // remainder = mixed



    if (r < swarmW) return "swarm"

    if (r < (swarmW + elitesW)) return "elites"

    return "mixed"

}



function _buildPoolForTarget(targetAvgDanger: number, maxDangerAllowed: number): { id: string, w: number }[] {

    const out: { id: string, w: number }[] = []

    for (let i = 0; i < MONSTER_CATALOG.length; i++) {

        const m = MONSTER_CATALOG[i]

        if ((m.danger | 0) <= 0) continue

        if (m.danger > maxDangerAllowed) continue



        // Weight by closeness to targetAvgDanger (closer = heavier weight)

        const d = Math.abs(m.danger - targetAvgDanger)

        const w = 1 / (1 + d) // simple, stable

        out.push({ id: m.id, w })

    }

    return out

}



function _sumWeights(pool: { id: string, w: number }[]): number {

    let s = 0

    for (let i = 0; i < pool.length; i++) s += pool[i].w

    return s

}



function _pickFromPool(pool: { id: string, w: number }[]): string {

    if (!pool || pool.length == 0) return MONSTER_CATALOG[0]?.id || "eyeball"

    const total = _sumWeights(pool)

    let r = Math.random() * total

    for (let i = 0; i < pool.length; i++) {

        r -= pool[i].w

        if (r <= 0) return pool[i].id

    }

    return pool[pool.length - 1].id

}

function _minMonsterDanger(slimeOnly: boolean): number {
    let min = 999999
    for (let i = 0; i < MONSTER_CATALOG.length; i++) {
        const m = MONSTER_CATALOG[i]
        if (slimeOnly && m.id !== "slime") continue
        if ((m.danger | 0) <= 0) continue
        if ((m.danger | 0) < min) min = m.danger | 0
    }
    if (min === 999999) return 1
    return min | 0
}

function _cheapestMonsterId(slimeOnly: boolean): string {
    let min = 999999
    let id = MONSTER_CATALOG[0]?.id || "eyeball"
    for (let i = 0; i < MONSTER_CATALOG.length; i++) {
        const m = MONSTER_CATALOG[i]
        if (slimeOnly && m.id !== "slime") continue
        if ((m.danger | 0) <= 0) continue
        if ((m.danger | 0) < min) {
            min = m.danger | 0
            id = m.id
        }
    }
    return id
}

function _parseMonsterSpawnId(rawId: string): { baseId: string; variant: string } {
    const raw = String(rawId || "").trim()
    if (!raw) return { baseId: "", variant: "" }
    const parts = raw.split(MONSTER_SPAWN_VARIANT_SEP)
    const baseId = String(parts[0] || "").trim()
    const variant = (parts.length > 1) ? String(parts.slice(1).join(MONSTER_SPAWN_VARIANT_SEP) || "").trim().toLowerCase() : ""
    return { baseId: baseId || raw, variant }
}

function _slimeRangedSpawnId(baseId: string, baby: boolean): string {
    const v = baby ? "baby_ranged" : "ranged"
    return `${baseId}${MONSTER_SPAWN_VARIANT_SEP}${v}`
}

function _monsterDangerForSpawnId(rawId: string): number {
    const parsed = _parseMonsterSpawnId(rawId)
    const base = parsed.baseId || rawId
    let danger = Math.max(1, (_monsterDefById(base).danger | 0)) | 0
    const v = parsed.variant || ""
    if (v === "baby" || v === "baby_ranged" || v === "split_small") {
        danger = Math.max(1, Math.round(danger * 0.5)) | 0
    } else if (v === "split_medium") {
        danger = Math.max(1, Math.round(danger * 2)) | 0
    } else if (v === "boss_giant") {
        danger = Math.max(1, Math.round(danger * 4)) | 0
    }
    return danger | 0
}

function _monsterTotalDangerForPool(monsters: string[]): number {
    let total = 0
    for (let i = 0; i < monsters.length; i++) {
        total = (total + (_monsterDangerForSpawnId(monsters[i]) | 0)) | 0
    }
    return Math.max(1, total | 0) | 0
}

function _scaleMonsterPoolByPlayerCount(basePool: string[], scale: number): string[] {
    const src = basePool || []
    if (src.length === 0) return []
    if (!(scale > 1)) return src.slice()
    const targetCount = Math.max(1, Math.round(src.length * scale)) | 0
    const out = src.slice()
    let i = 0
    while (out.length < targetCount) {
        out.push(src[i % src.length])
        i++
    }
    return out
}

function _buildCustomMonsterPoolForFloor(floor1: number): string[] | null {
    if (floor1 <= 0) return null
    if (floor1 === 1) {
        return ["slime", "slime", "slime", "slime"]
    }
    if (floor1 === 2) {
        const baby = _slimeRangedSpawnId("slime green", true)
        return ["slime", "slime", "slime", "slime", baby, baby]
    }
    if (floor1 === 3) {
        const baby = _slimeRangedSpawnId("slime green", true)
        return ["slime", "slime", "slime", "slime", baby, baby, baby, baby]
    }
    if (floor1 === 4) {
        const baby = _slimeRangedSpawnId("slime green", true)
        return ["slime", "slime", "slime", "slime", "slime", "slime", baby, baby, baby, baby]
    }
    if (floor1 === 5) {
        const ranged = _slimeRangedSpawnId("slime green", false)
        return [
            `slime${MONSTER_SPAWN_VARIANT_SEP}boss_giant`,
            ranged,
            ranged
        ]
    }
    if (floor1 === 6) {
        const rangedGreen = _slimeRangedSpawnId("slime green", false)
        const rangedRed = _slimeRangedSpawnId("slime red", false)
        const rangedBlue = _slimeRangedSpawnId("slime blue", false)
        return [
            "slime",
            "slime red",
            "slime blue",
            "slime black",
            "slime",
            "slime red",
            rangedGreen,
            rangedRed,
            rangedBlue,
            rangedGreen
        ]
    }
    return null
}

function _buildMonsterPoolForFloor(floorIndex0: number, playerCount: number): { monsters: string[], totalDanger: number } {
    const floor1 = Math.max(1, floorIndex0 | 0) | 0
    const countScale = _dunGetMonsterCountScale(playerCount | 0)
    const custom = _buildCustomMonsterPoolForFloor(floor1 | 0)
    if (custom && custom.length > 0) {
        const scaled = _scaleMonsterPoolByPlayerCount(custom, countScale)
        return { monsters: scaled, totalDanger: _monsterTotalDangerForPool(scaled) | 0 }
    }
    const slimeOnly = (floor1 | 0) == 1
    const baseDanger = Math.max(1, Math.round(_floorDangerBase(floor1) * countScale)) | 0
    const targetCount = _clamp(
        Math.max(1, Math.round(
            (BALANCE.WAVES.POOL_TARGET_COUNT_BASE + Math.idiv(floor1, BALANCE.WAVES.POOL_TARGET_COUNT_FLOOR_DIV)) * countScale
        )),
        BALANCE.WAVES.POOL_TARGET_COUNT_MIN,
        BALANCE.WAVES.POOL_TARGET_COUNT_MAX
    )

    const minDanger = _minMonsterDanger(slimeOnly) | 0
    let remaining = baseDanger | 0
    let totalDanger = 0
    const monsters: string[] = []

    let safety = 0
    while ((remaining | 0) >= (minDanger | 0) && safety < 1000) {
        const remainingSlots = Math.max(1, (targetCount | 0) - monsters.length) | 0
        const targetAvgDanger = _clamp(
            Math.idiv(remaining | 0, remainingSlots | 0),
            BALANCE.WAVES.TARGET_AVG_DANGER_MIN,
            BALANCE.WAVES.TARGET_AVG_DANGER_MAX
        )

        const pool = slimeOnly ? [{ id: "slime", w: 1 }] : _buildPoolForTarget(targetAvgDanger, remaining)
        if (!pool || pool.length == 0) break

        const id = _pickFromPool(pool)
        const md = _monsterDefById(id)
        const danger = Math.max(1, md.danger | 0) | 0

        monsters.push(id)
        totalDanger = (totalDanger + danger) | 0
        remaining = (remaining - danger) | 0
        safety++
    }

    const minCount = Math.max(1, enemySpawners.length | 0) | 0
    if (monsters.length < minCount) {
        const fillerId = _cheapestMonsterId(slimeOnly)
        const fillerDanger = Math.max(1, _monsterDefById(fillerId).danger | 0) | 0
        while (monsters.length < minCount) {
            monsters.push(fillerId)
            totalDanger = (totalDanger + fillerDanger) | 0
        }
    }

    return { monsters, totalDanger }
}

function _calcSpawnIntervalMs(totalCount: number, floor1: number, dangerBudget: number): number {
    const count = Math.max(1, totalCount | 0) | 0
    const f1 = Math.max(1, floor1 | 0) | 0
    const danger = Math.max(1, dangerBudget | 0) | 0

    const durationMs =
        (BALANCE.WAVES.POOL_DURATION_BASE_MS | 0) +
        Math.idiv((f1 | 0) * (BALANCE.WAVES.POOL_DURATION_PER_FLOOR_MS | 0), 1) +
        Math.idiv((danger | 0) * (BALANCE.WAVES.POOL_DURATION_PER_DANGER_MS | 0), 1)

    const interval = Math.idiv(durationMs | 0, count | 0) | 0
    return _clamp(interval, BALANCE.WAVES.SPAWN_INTERVAL_MIN_MS, BALANCE.WAVES.SPAWN_INTERVAL_MAX_MS) | 0
}

function _pickNextSpawnerIndex(): number {
    const n = enemySpawners ? enemySpawners.length | 0 : 0
    if (n <= 0) return -1

    if (_enemySpawnerBag.length == 0) {
        for (let i = 0; i < n; i++) {
            if ((i | 0) === (_enemySpawnerLast | 0)) continue
            _enemySpawnerBag.push(i | 0)
        }
        if (_enemySpawnerBag.length == 0) {
            _enemySpawnerBag.push(0)
        }
    }

    const pick = randint(0, _enemySpawnerBag.length - 1) | 0
    const spawnerId = _enemySpawnerBag[pick] | 0
    _enemySpawnerBag.splice(pick, 1)
    _enemySpawnerLast = spawnerId | 0
    return spawnerId | 0
}

function _spawnFromMonsterPool(spawnerIndex: number): boolean {
    if (!_dunMonsterPool || _dunMonsterPool.length == 0) return false
    if (!enemySpawners || enemySpawners.length == 0) return false
    if (spawnerIndex < 0 || spawnerIndex >= enemySpawners.length) return false

    const pick = randint(0, _dunMonsterPool.length - 1) | 0
    const rawId = _dunMonsterPool[pick]
    _dunMonsterPool.splice(pick, 1)

    const parsed = _parseMonsterSpawnId(rawId)
    const monsterId = parsed.baseId || rawId

    const spawner = enemySpawners[spawnerIndex]
    const enemy = spawnEnemyOfKind(monsterId, spawner.x, spawner.y, /*elite=*/ false)
    sprites.setDataNumber(enemy, ENEMY_DATA.SPAWNER_ID, spawnerIndex | 0)
    if (parsed.variant) _applyEnemyVariant(enemy, monsterId, parsed.variant)
    return true
}



function _buildWavePlanForFloor(floorIndex0: number, spawnIntervalMs: number, playerCount: number): GenWaveDef[] {

    const floor1 = Math.max(1, floorIndex0 | 0) | 0

    const slimeOnly = (floor1 | 0) == 1



    const countScale = _dunGetMonsterCountScale(playerCount | 0)
    const baseDanger = Math.max(1, Math.round(_floorDangerBase(floor1) * countScale)) | 0



    // 3..7 waves up to floor 100

    const waveCount = _clamp(

        BALANCE.WAVES.WAVE_COUNT_BASE + Math.idiv(floor1, BALANCE.WAVES.WAVE_COUNT_FLOOR_DIV),

        BALANCE.WAVES.WAVE_COUNT_MIN,

        BALANCE.WAVES.WAVE_COUNT_MAX

    )



    // Split danger across waves so later waves are heavier

    const weights: number[] = []

    let wsum = 0

    for (let i = 0; i < waveCount; i++) {

        const w = Math.pow(i + 1, BALANCE.WAVES.WAVE_WEIGHT_EXP)

        weights.push(w)

        wsum += w

    }



    const plan: GenWaveDef[] = []

    for (let i = 0; i < waveCount; i++) {

        const archetype = _pickArchetype(floor1, i, waveCount)

        const waveBudget = (baseDanger * (weights[i] / wsum)) | 0



        // Choose “how many spawns we want” based on archetype

        let desiredCount = BALANCE.WAVES.DESIRED_COUNT_BASE + Math.idiv(floor1, BALANCE.WAVES.DESIRED_COUNT_FLOOR_DIV)

        if (archetype === "swarm") {

            desiredCount = BALANCE.WAVES.SWARM_COUNT_BASE + Math.idiv(floor1, BALANCE.WAVES.SWARM_COUNT_FLOOR_DIV)

        } else if (archetype === "elites") {

            desiredCount = BALANCE.WAVES.ELITES_COUNT_BASE + Math.idiv(floor1, BALANCE.WAVES.ELITES_COUNT_FLOOR_DIV)

        }

        desiredCount = Math.max(1, Math.round((desiredCount | 0) * countScale)) | 0



        desiredCount = _clamp(desiredCount, BALANCE.WAVES.DESIRED_COUNT_MIN, BALANCE.WAVES.DESIRED_COUNT_MAX)



        // Target average danger determines which monsters are preferred

        const targetAvgDanger = _clamp(

            waveBudget / Math.max(1, desiredCount),

            BALANCE.WAVES.TARGET_AVG_DANGER_MIN,

            BALANCE.WAVES.TARGET_AVG_DANGER_MAX

        )



        // Eligible monsters must have danger <= waveBudget (your exact rule)

        const pool = slimeOnly ? [{ id: "slime", w: 1 }] : _buildPoolForTarget(targetAvgDanger, waveBudget)



        // Spawn chance & duration from desired count

        let spawnChance = BALANCE.WAVES.SPAWN_CHANCE_DEFAULT

        if (archetype === "swarm") spawnChance = BALANCE.WAVES.SPAWN_CHANCE_SWARM

        else if (archetype === "elites") spawnChance = BALANCE.WAVES.SPAWN_CHANCE_ELITES



        const expectedTicks = Math.ceil(desiredCount / Math.max(0.05, spawnChance))

        const durationMs = (expectedTicks * spawnIntervalMs) | 0



        // Breaks: short; you can tune later

        const breakMs = (BALANCE.WAVES.BREAK_BASE_MS + Math.idiv(floor1, BALANCE.WAVES.BREAK_PER_FLOOR_DIV)) | 0



        // Cap alive count so testing doesn’t explode

        const maxAlive = _clamp(

            BALANCE.WAVES.MAX_ALIVE_BASE + Math.idiv(floor1, BALANCE.WAVES.MAX_ALIVE_FLOOR_DIV),

            BALANCE.WAVES.MAX_ALIVE_MIN,

            BALANCE.WAVES.MAX_ALIVE_MAX

        )



        plan.push({

            archetype,

            dangerBudget: waveBudget,

            spawnChance,

            durationMs,

            breakMs,

            maxAlive,

            pool

        })

    }



    return plan

}



function pickEnemyKindForWave(waveIndex: number): string {

    const wi = waveIndex | 0

    if (!_dunWavePlan || _dunWavePlan.length == 0) {

        return MONSTER_CATALOG[0]?.id || "eyeball"

    }

    const w = _dunWavePlan[_clamp(wi, 0, _dunWavePlan.length - 1)]

    return _pickFromPool(w.pool)

}







game.onUpdateInterval(ENEMY_SPAWN_TICK_MS, function () {

    if (!HeroEngine._isStarted()) return
    if (_engineIsPaused()) return
    if (SHOP_MODE_ACTIVE) return
    if (!enemySpawners || enemySpawners.length == 0) return

    if (!_dunCombatWavesActive || _dunCombatWavesComplete) return

    if (!_dunMonsterPool || _dunMonsterPool.length == 0) {
        _dunCombatWavesActive = false
        _dunCombatWavesComplete = true
        return
    }

    const now = game.runtime() | 0
    if ((now | 0) < (_dunNextEnemySpawnAtMs | 0)) return

    const spawnerIdx = _pickNextSpawnerIndex() | 0
    if (spawnerIdx < 0) return

    const spawned = _spawnFromMonsterPool(spawnerIdx | 0)
    if (!spawned) {
        _dunCombatWavesActive = false
        _dunCombatWavesComplete = true
        return
    }

    if (!_dunMonsterPool || _dunMonsterPool.length == 0) {
        _dunCombatWavesActive = false
        _dunCombatWavesComplete = true
        return
    }

    _dunNextEnemySpawnAtMs = (now + (_dunSpawnIntervalMs | 0)) | 0
})

















// Apply a saved snapshot to any sprite (position/data/image).
function _applySnapshotToSprite(target: Sprite, snap: any): void {
    if (!target || !snap) return
    try {
        target.x = snap.x || 0
        target.y = snap.y || 0
        target.vx = snap.vx || 0
        target.vy = snap.vy || 0
        if (typeof (snap as any).flags === "number") {
            target.flags = (snap as any).flags | 0
        }

        if (!(target as any).data) (target as any).data = {}
        const d: any = (target as any).data
        for (const k of Object.keys(d)) delete d[k]
        if (snap.data) {
            for (const k of Object.keys(snap.data)) {
                d[k] = (snap.data as any)[k]
            }
        }

        if (snap.pixels && snap.width > 0 && snap.height > 0) {
            const w = snap.width | 0
            const h = snap.height | 0
            let img: any = (target as any).image
            if (!img || img.width !== w || img.height !== h) {
                img = (Image as any).fromJSON(w, h, snap.pixels)
                if (typeof (target as any).setImage === "function") {
                    (target as any).setImage(img)
                } else {
                    (target as any).image = img
                }
            } else if (typeof (img as any).fromJSONPixels === "function") {
                img.fromJSONPixels(snap.pixels)
            }
        }
    } catch { }
}

// Apply snapshot DATA only (no position/velocity/pixels).
function _applySnapshotDataOnly(target: Sprite, snap: any, applyFlags?: boolean): void {
    if (!target || !snap) return
    try {
        if (applyFlags && typeof (snap as any).flags === "number") {
            target.flags = (snap as any).flags | 0
        }
        if (!(target as any).data) (target as any).data = {}
        const d: any = (target as any).data
        for (const k of Object.keys(d)) delete d[k]
        if (snap.data) {
            for (const k of Object.keys(snap.data)) {
                d[k] = (snap.data as any)[k]
            }
        }
    } catch { }
}

