// WITHOUT changing namespace HeroEngine.

// ----------------------------------------------------------

// ----------------------------------------------------------

// Phaser-only side channel: expose tile + decor internals via global

// WITHOUT changing namespace HeroEngine.

// ----------------------------------------------------------

(() => {

    try {

        const g: any = globalThis as any

        g.__HeroEnginePhaserInternals = g.__HeroEnginePhaserInternals || {}



        const internals: any = g.__HeroEnginePhaserInternals



        if (DEBUG_DECOR_ENGINE_LOGS) {
            console.log("[DECOR][ENGINE] __HeroEnginePhaserInternals keys (before):", Object.keys(internals || {}))
            console.log("[DECOR][ENGINE] has getDecorRev? (before)", typeof internals?.getDecorRev)
        }



        // ----------------------------------------------------------

        // WORLD TILEMAP

        // ----------------------------------------------------------

        internals.getWorldTileMap = function (): number[][] {

            return _engineWorldTileMap

        }



        internals.getWorldTileSize = function (): number {

            return WORLD_TILE_SIZE

        }



        // NEW: lets Phaser know when to re-apply / broadcast the map

        internals.getWorldRev = function (): number {

            return _engineWorldRev | 0

        }



        // HERO collision offset (used by Phaser wrapper for overlap math)

        internals.getHeroCollisionOffsetY = function (): number {

            return _heroFeetOffsetForDims(HERO_SPRITE_PX, HERO_COLLIDER_H_PX) | 0

        }



        // HERO collision bounds (engine-authoritative AABB for overlaps)

        internals.getCollisionBoundsForSprite = function (s: Sprite) {

            if (!s) return null

            return _boundsWithOffset(s, _heroCollisionOffsetY(s))

        }



        // NEW: theme hooks (main.ts will also fall back to globals)

        internals.getFloorBaseFamily = function (): string {

            return _dunBaseFamily

        }



        internals.getFloorWallFamily = function (): string {

            return _dunWallFamily

        }

        internals.getFloorThemePalette = function (): string {

            return _dunThemePalette

        }

        internals.getFloorTextureSeed = function (): number {

            return _dunFloorTextureSeed | 0

        }



        internals.getFloorIndex = function (): number {

            return _dunFloorIndex | 0

        }



        internals.getFloorKind = function (): string {

            return String(_dunFloorKind || "")

        }

        internals.resetFloorFromSave = function (index: number, kind: string, theme?: { baseFamily?: string; wallFamily?: string; palette?: string; textureSeed?: number }): boolean {
            try {
                const idx = (index | 0)
                const k = String(kind || "")
                const baseFamily = theme && typeof theme.baseFamily === "string" ? theme.baseFamily : ""
                const wallFamily = theme && typeof theme.wallFamily === "string" ? theme.wallFamily : ""
                const palette = theme && typeof theme.palette === "string" ? theme.palette : ""
                const textureSeed = theme && typeof theme.textureSeed === "number" ? (theme.textureSeed | 0) : 0
                if (baseFamily || wallFamily || palette || textureSeed) {
                    _dunThemeOverride = {
                        base: baseFamily || _dunBaseFamily,
                        wall: wallFamily || _dunWallFamily,
                        palette: palette || _dunThemePalette,
                        textureSeed: textureSeed || undefined,
                    }
                }
                DUNGEON_MODE_ACTIVE = true
                _dunEnterFloor(idx, k, game.runtime() | 0)
                return true
            } catch { }
            return false
        }

        internals.getFloorSaveFlags = function (): any {
            const kind = String(_dunFloorKind || "")
            let safe = true
            if (DUNGEON_MODE_ACTIVE && kind === DUNGEON_KIND_COMBAT) {
                const doorReady = _dunFloorUsesDoorExit() && _dunDoorState === "open"
                const padReady = _dunIsPadPowered() || doorReady
                safe = !!_dunObjectiveDone && !!padReady && ((_dunCountLiveEnemies() | 0) === 0)
            }
            return {
                floorIndex: _dunFloorIndex | 0,
                floorKind: kind,
                safe: !!safe,
                objectiveDone: !!_dunObjectiveDone,
                padPowered: !!_dunIsPadPowered(),
                doorState: String(_dunDoorState || ""),
                combatWavesComplete: !!_dunCombatWavesComplete,
            }
        }

        internals.applyFloorSaveFlags = function (flags: any): boolean {
            if (!flags) return false
            const kind = String(_dunFloorKind || "")
            const wantDone =
                (typeof flags.objectiveDone === "boolean") ? flags.objectiveDone : !!flags.safe

            if (wantDone) {
                _dunObjectiveDone = true
                if (kind === DUNGEON_KIND_COMBAT) {
                    _dunCombatWavesActive = false
                    _dunCombatWavesComplete = true
                    try { _dunClearList(enemies) } catch { }
                }
                if (_dunFloorUsesDoorExit()) {
                    _dunDoorBeginOpen(game.runtime() | 0)
                } else {
                    _dunSetPadPowered(true)
                }
            }

            return true
        }

        internals.applySavedSnapshots = function (): { heroesApplied: number; npcsApplied: number } {
            const g: any = globalThis as any
            let heroesApplied = 0
            let npcsApplied = 0

            try {
                const heroMap = g && g.__heroSavedSnapshotByProfile
                if (heroMap && typeof heroMap === "object") {
                    for (let hi = 0; hi < heroes.length; hi++) {
                        const hero = heroes[hi]
                        if (!hero || (hero.flags & sprites.Flag.Destroyed)) continue
                        if (sprites.readDataBoolean(hero, HERO_DATA.IS_NPC)) continue
                        const profileKey =
                            _heroProfileKeyForIndex(hi) ||
                            sprites.readDataString(hero, HERO_DATA.NAME) ||
                            sprites.readDataString(hero, "heroName") ||
                            ""
                        if (!profileKey) continue
                        const snap = heroMap[profileKey]
                        if (!snap) continue
                        _applySnapshotDataOnly(hero, snap, false)
                        _resetHeroTransientStateForLoad(hi, hero)
                        delete heroMap[profileKey]
                        heroesApplied++
                    }
                }
            } catch { }

            try {
                const npcMap = g && g.__npcSavedSnapshotByKey
                if (npcMap && typeof npcMap === "object") {
                    for (let i = 0; i < npcActors.length; i++) {
                        const npc = npcActors[i]
                        if (!npc || (npc.flags & sprites.Flag.Destroyed)) continue
                        const role = sprites.readDataString(npc, "_npcRole") || ""
                        const heroName = sprites.readDataString(npc, "heroName") || sprites.readDataString(npc, HERO_DATA.NAME) || ""
                        const family = sprites.readDataString(npc, "heroFamily") || sprites.readDataString(npc, HERO_DATA.FAMILY) || ""
                        const key = _npcSnapshotKeyFromParts(role, heroName, family)
                        if (!key) continue
                        const snap = npcMap[key]
                        if (!snap) continue
                        _applySnapshotDataOnly(npc, snap, false)
                        delete npcMap[key]
                        npcsApplied++
                    }
                }
            } catch { }

            return { heroesApplied, npcsApplied }
        }



        // ----------------------------------------------------------

        // DECOR (engine-owned, art-agnostic) — NAMES EXPECTED BY arcadeCompat.ts

        // ----------------------------------------------------------

        internals.getDecorRev = function (): number {

            return _engineDecorRev | 0

        }



        // Decal grid (tile-aligned signaling layer; students query underfoot too)

        internals.getDecalGrid = function (): number[][] {

            return _engineDecalGrid

        }



        // Optional alias (in case you/older code says "decor grid")

        internals.getDecorGrid = function (): number[][] {

            return _engineDecalGrid

        }



        // Decor collider sprites (invisible; used for overlap proof and later blocking)

        internals.getDecorTriggerSprites = function (): Sprite[] {

            return _engineDecorTriggers

        }



        internals.getDecorSolidSprites = function (): Sprite[] {

            return _engineDecorSolids

        }



        // ----------------------------------------------------------

        // LEGACY / EXISTING DECOR CHANNEL (keep for compatibility)

        // ----------------------------------------------------------

        internals.getWorldDecorRev = function (): number {

            return _engineDecorRev | 0

        }



        internals.getWorldDecorCells = function () {

            return _engineDecorCells

        }



        internals.getWorldDecorDecals = function () {

            return _engineDecorDecals

        }



        // Helper to restore a hero sprite from a saved snapshot (position/data/image)
        function _applyHeroSnapshotToSprite(hero: Sprite, snap: any) {
            if (snap && (snap as any).__loadDataOnly) {
                _applySnapshotDataOnly(hero, snap, false)
                const hi = sprites.readDataNumber(hero, HERO_DATA.HERO_INDEX) | 0
                _resetHeroTransientStateForLoad(hi, hero)
                return
            }
            _applySnapshotToSprite(hero, snap)
        }

        function _computeDefaultHeroSpawnCoords(): number[][] {
            let W = userconfig.ARCADE_SCREEN_WIDTH
            let H = userconfig.ARCADE_SCREEN_HEIGHT

            if (_engineWorldTileMap && _engineWorldTileMap.length > 0 && _engineWorldTileMap[0].length > 0) {
                const rows = _engineWorldTileMap.length
                const cols = _engineWorldTileMap[0].length
                W = cols * WORLD_TILE_SIZE
                H = rows * WORLD_TILE_SIZE
            }

            const centerW = W / 2
            const centerH = H / 2
            const offset = 40

            return [
                [centerW + offset, centerH + offset],
                [centerW - offset, centerH + offset],
                [centerW + offset, centerH - offset],
                [centerW - offset, centerH - offset],
            ]
        }

        function _pickSpawnCoords(slotIndex: number): number[] {
            const coords = _computeDefaultHeroSpawnCoords()
            if (slotIndex >= 0 && slotIndex < coords.length) return coords[slotIndex]
            if (coords.length <= 0) return [userconfig.ARCADE_SCREEN_WIDTH / 2, userconfig.ARCADE_SCREEN_HEIGHT / 2]
            const idx = Math.max(0, heroes.length | 0) % coords.length
            return coords[idx]
        }

        function _resolveProfileForPlayerId(pid: number): string {
            return _resolveProfileKeyForPlayerId(pid)
        }

        internals.getHeroIndexForProfile = function (profile: string): number {
            return _resolveHeroIndexForProfile(profile)
        }

        internals.ensureHeroForProfile = function (profile: string, playerId?: number): number {
            const key = _normalizeProfileKey(profile)
            if (!key) {
                if (DEBUG_NET_IDENTITY) console.warn("[profile.identity] ensure rejected: empty profile", { profile })
                return -1
            }

        const existing = _resolveHeroIndexForProfile(key)
        if (existing >= 0) {
            const deduped = _dedupeHeroesForProfile(key, playerId, existing, "ensureHeroForProfile")
            const heroIndex = (deduped >= 0) ? deduped : existing
            const hero = heroes[heroIndex]
            if (hero && !(hero.flags & sprites.Flag.Destroyed)) {
                const mode = sprites.readDataNumber(hero, HERO_TELE_FX_MODE_KEY) | 0
                if (mode === 2) {
                    if (DEBUG_NET_IDENTITY) {
                        console.log("[profile.identity] reconnect; cancel teleport-out", { profile: key, heroIndex })
                    }
                    _beginHeroTeleportFx(heroIndex, hero, 1, key, "reconnect")
                }
            }
            return heroIndex
        }

        const repaired = _dedupeHeroesForProfile(key, playerId, -1, "ensureHeroForProfile:repair")
        if (repaired >= 0) return repaired

        const pid = (typeof playerId === "number") ? (playerId | 0) : 0
        if (DEBUG_NET_IDENTITY) {
            console.log("[profile.identity] spawn request", { profile: key, pid })
        }
            const coords = _pickSpawnCoords(pid > 0 ? (pid - 1) : -1)
            createHeroForPlayer(pid, coords[0], coords[1], key, undefined, undefined, undefined, "ensureHeroForProfile")

            const after = _resolveHeroIndexForProfile(key)
            if (after >= 0 && after < heroes.length && heroes[after]) {
                let restored = false
                try {
                    const g: any = (globalThis as any)
                    const restore: any = g.__heroSavedSnapshotByProfile
                    if (restore && restore[key]) {
                        const hero = heroes[after]
                        _applyHeroSnapshotToSprite(hero, restore[key])
                        delete restore[key]
                        restored = true
                        console.log(">>> [HeroEngineInPhaser] restored hero from save profile=", key)
                    }
                } catch { }
                const hero = heroes[after]
                if (hero) {
                    _beginHeroTeleportFx(after, hero, 1, key, restored ? "restore" : "spawn")
                }
                if (DEBUG_NET_IDENTITY) {
                    console.log("[profile.identity]", restored ? "WELCOME_BACK" : "WELCOME", {
                        profile: key,
                        pid,
                        heroIndex: after
                    })
                }
            }

            return after >= 0 && after < heroes.length && heroes[after] ? after : -1
        }

        internals.applyProfileInput = function (profile: string, btn: string, pressed: boolean): void {
            _applyNetInputForProfile(profile, btn, pressed)
        }

        internals.despawnHeroForProfile = function (profile: string): boolean {
            const key = _normalizeProfileKey(profile)
            if (!key) return false
            const hi = _resolveHeroIndexForProfile(key)
            if (hi < 0 || hi >= heroes.length) return false
            const hero = heroes[hi]
            if (!hero || (hero.flags & sprites.Flag.Destroyed)) return false
            const mode = sprites.readDataNumber(hero, HERO_TELE_FX_MODE_KEY) | 0
            if (mode === 2) return true
            const pid = sprites.readDataNumber(hero, HERO_DATA.OWNER) | 0
            if (DEBUG_NET_IDENTITY) {
                console.log("[profile.identity] despawn request", { profile: key, pid, heroIndex: hi })
            }
            try {
                const g: any = globalThis as any
                if (!g.__heroSavedSnapshotByProfile) g.__heroSavedSnapshotByProfile = {}
                g.__heroSavedSnapshotByProfile[key] = _captureSnapshotFromSprite(hero)
                if (DEBUG_NET_IDENTITY) {
                    console.log("[profile.identity] snapshot saved", { profile: key, pid, heroIndex: hi })
                }
            } catch { }
            _beginHeroTeleportFx(hi, hero, 2, key, "disconnect")
            return true
        }


        // ------------------------------------------------------------

        // STEP 6: spawn-on-demand hook for the Phaser host.

        // ------------------------------------------------------------

        internals.ensureHeroForPlayer = function (playerId: number): number {

            const pid = playerId | 0

            if (pid <= 0) return -1

            const profileKey = _resolveProfileForPlayerId(pid)
            if (!profileKey) {
                if (DEBUG_NET_IDENTITY) console.warn("[profile.identity] ensure rejected: missing profile", { pid })
                return -1
            }
            return internals.ensureHeroForProfile(profileKey, pid)

        }

        // Despawn hero for a player (legacy wrapper; profile-centric path preferred)
        internals.despawnHeroForPlayer = function (playerId: number): boolean {
            const pid = playerId | 0
            if (pid <= 0) return false
            const prof = _resolveProfileForPlayerId(pid)
            if (prof) return internals.despawnHeroForProfile(prof)
            return false
        }

        // Remove stray heroes that do not map to any connected profile.
        internals.pruneUnconnectedHeroes = function (reason?: string): number {
            try {
                const g: any = globalThis as any
                const allowed: Record<string, boolean> = Object.create(null)

                const connected = g.__netProfileConnected
                if (connected && typeof connected === "object") {
                    for (const k of Object.keys(connected)) {
                        if (!connected[k]) continue
                        const key = _normalizeProfileKey(k)
                        if (key) allowed[key] = true
                    }
                }

                const byPid = g.__netProfileByPid
                if (!Object.keys(allowed).length && byPid && typeof byPid === "object") {
                    for (const k of Object.keys(byPid)) {
                        const key = _normalizeProfileKey(byPid[k])
                        if (key) allowed[key] = true
                    }
                }

                if (!Object.keys(allowed).length) {
                    const local =
                        (typeof g.__localHeroProfileName === "string" && g.__localHeroProfileName.trim())
                            ? g.__localHeroProfileName.trim()
                            : (typeof g.__netHelloProfile === "string" && g.__netHelloProfile.trim())
                                ? g.__netHelloProfile.trim()
                                : ""
                    const key = _normalizeProfileKey(local)
                    if (key) allowed[key] = true
                }

                if (!Object.keys(allowed).length) return 0

                let removed = 0
                for (let hi = 0; hi < heroes.length; hi++) {
                    const hero = heroes[hi]
                    if (!hero || (hero.flags & sprites.Flag.Destroyed)) continue
                    if (sprites.readDataBoolean(hero, HERO_DATA.IS_NPC)) continue

                    const profile = _normalizeProfileKey(_getProfileFromHeroSprite(hero))
                    const owner = sprites.readDataNumber(hero, HERO_DATA.OWNER) | 0

                    let keep = false
                    if (profile && allowed[profile]) {
                        keep = true
                    } else if (owner > 0 && byPid && typeof byPid[owner] === "string") {
                        const byPidKey = _normalizeProfileKey(byPid[owner])
                        if (byPidKey && allowed[byPidKey]) keep = true
                    }

                    if (keep) continue

                    if (profile) _clearHeroProfile(profile, hi)
                    if (owner > 0) {
                        const mapped = playerIdToProfile[owner]
                        if (typeof mapped === "string") {
                            const mappedKey = _normalizeProfileKey(mapped)
                            if (!mappedKey || !allowed[mappedKey] || mappedKey === profile) {
                                delete playerIdToProfile[owner]
                            }
                        }
                    }

                    hero.destroy()
                    removed++
                }

                // Also dedupe any remaining connected profiles.
                for (const prof of Object.keys(allowed)) {
                    if (!allowed[prof]) continue
                    _dedupeHeroesForProfile(prof, _findPidForProfileKey(prof), -1, "prune:dedupe")
                }

                if (DEBUG_NET_IDENTITY && removed > 0) {
                    console.log("[profile.identity] pruned unconnected heroes", {
                        removed,
                        reason: reason || ""
                    })
                }
                return removed
            } catch (e) {
                if (DEBUG_NET_IDENTITY) console.warn("[profile.identity] prune failed", e)
                return 0
            }
        }

        // NPC LPC helpers (Phaser-only convenience API)
        internals.spawnNpcLpc = HeroEngine.spawnNpcLpc
        internals.registerNpcLpc = HeroEngine.registerNpcLpc
        internals.despawnNpcLpc = HeroEngine.despawnNpcLpc
        internals.listNpcLpc = HeroEngine.listNpcLpc
        internals.findNpcLpcByRole = HeroEngine.findNpcLpcByRole
        internals.setNpcLpcDir = HeroEngine.setNpcLpcDir
        internals.setNpcLpcPhase = HeroEngine.setNpcLpcPhase
        internals.setNpcLpcWeapons = HeroEngine.setNpcLpcWeapons
        internals.isNpcLpc = HeroEngine.isNpcLpc

        internals.spawnEnemy = function (monsterId: string, x?: number, y?: number, elite?: boolean): Sprite | null {
            const id = String(monsterId || "").trim()
            if (!id) return null

            let sx = (typeof x === "number" && Number.isFinite(x)) ? (x | 0) : NaN
            let sy = (typeof y === "number" && Number.isFinite(y)) ? (y | 0) : NaN

            if (!Number.isFinite(sx) || !Number.isFinite(sy)) {
                let hero: Sprite | null = null
                for (let i = 0; i < heroes.length; i++) {
                    const h = heroes[i]
                    if (!h || (h.flags & sprites.Flag.Destroyed)) continue
                    if (sprites.readDataBoolean(h, HERO_DATA.IS_NPC)) continue
                    hero = h
                    break
                }
                if (hero) {
                    sx = (hero.x | 0) + 40
                    sy = (hero.y | 0)
                } else if ((_dunPadTileR | 0) >= 0 && (_dunPadTileC | 0) >= 0) {
                    sx = _dunColToX(_dunPadTileC | 0)
                    sy = _dunRowToY(_dunPadTileR | 0)
                } else {
                    sx = userconfig.ARCADE_SCREEN_WIDTH >> 1
                    sy = userconfig.ARCADE_SCREEN_HEIGHT >> 1
                }
            }

            return spawnEnemyOfKind(id, sx | 0, sy | 0, !!elite)
        }

        internals.consumeBossIntroEvent = function (): any {
            const evt = _dunBossIntroEvent
            if (evt) _dunBossIntroEvent = null
            return evt || null
        }

        internals.setEnginePaused = function (flag: boolean, reason?: string): void {
            _engineSetPaused(!!flag, reason)
        }

        internals.startBossIntroJump = function (evt: any): any {
            return _enemyBossStartIntroJumpForEvent(evt)
        }

        internals.setBossIntroHeroLock = function (flag: boolean): void {
            _bossIntroSetHeroLock(!!flag)
        }

        internals.getBossIntroCameraHoldInfo = function (): any {
            return _bossIntroCameraHoldInfo()
        }

        internals.getTrialCameraHoldInfo = function (): any {
            return _towerTrialCameraHoldInfo()
        }



        if (DEBUG_DECOR_ENGINE_LOGS) {
            console.log("[DECOR][ENGINE] __HeroEnginePhaserInternals keys (after):", Object.keys(internals || {}))
            console.log("[DECOR][ENGINE] has getDecorRev? (after)", typeof internals?.getDecorRev)
            console.log(">>> [HeroEngineInPhaser] exposed __HeroEnginePhaserInternals (tile map + size + decor + ensureHeroForPlayer)")
        }

    } catch {

        // If globalThis isn't available (e.g., PXT runtime), just silently skip.

    }

})()









