const RELIC_SHOP_OFFER_COUNT = 3
const RELIC_SHOP_PRICE_DEFAULT = 10

const RELIC_RARITY_RANK: { [key: string]: number } = {
    common: 1,
    uncommon: 2,
    rare: 3,
    boss: 4,
    legendary: 5,
}

function _relicRarityRank(rarity: string): number {
    const key = String(rarity || "").toLowerCase()
    return (RELIC_RARITY_RANK[key] | 0) || 0
}

function _relicCatalogIds(): string[] {
    const out: string[] = []
    for (const k of Object.keys(RELIC_CATALOG)) {
        if (!k) continue
        out.push(String(k))
    }
    return out
}

function _relicStarterOfferPool(): string[] {
    return _relicCatalogIds()
}

function _relicBossOfferPool(): string[] {
    return _relicCatalogIds()
}

function _relicFilterIdsByRarity(ids: string[], minRarity: string, maxRarity: string): string[] {
    const minRank = _relicRarityRank(String(minRarity || ""))
    const maxRank = _relicRarityRank(String(maxRarity || ""))
    if (minRank <= 0 && maxRank <= 0) return ids.slice(0)

    const out: string[] = []
    for (let i = 0; i < ids.length; i++) {
        const rid = String(ids[i] || "")
        if (!rid) continue
        const def = RELIC_CATALOG[rid]
        const rank = _relicRarityRank(def && def.rarity ? def.rarity : "")
        if (minRank > 0 && rank < minRank) continue
        if (maxRank > 0 && rank > maxRank) continue
        out.push(rid)
    }
    return out
}



// Handler table (v3.1 proof-of-concept for the starter relics).

// NOTE: Handlers must be pure engine-side logic; DOM gets only ids + UI state.

const RELIC_EFFECTS: { [effectKey: string]: RelicEffectHandler } = {

    ethereal_shroud: {

        effectKey: "ethereal_shroud",

        beforeHeroDamage: (ctx: RelicHeroDamageContext) => {

            if (!ctx) return

            const pid = _relicResolvePidFromHeroIndex(ctx.hi) | 0

            if (pid <= 0) return



            // Only intercept real damage

            const dmg = ctx.damage | 0

            if (dmg <= 0) return



            const st = _relicEnsureRuntimeForPid(pid)

            const now = ctx.now | 0



            // Ready => prevent this instance of damage and start cooldown

            if ((st.shroudReadyAtMs | 0) <= now) {

                ctx.damage = 0

                ctx.preventDamage = true

                st.shroudReadyAtMs = (now + RELIC_SHROUD_COOLDOWN_MS) | 0

                const dir = _heroDamageDirForContext(ctx)
                _spawnEtherealShroudFx(ctx.hero, now, dir)

                console.log("[RELICHOOK][SHROUD] prevented damage", { pid, hi: ctx.hi | 0, now, nextReady: st.shroudReadyAtMs | 0 })

            }

        },

    },



    energy_shield: {

        effectKey: "energy_shield",

        beforeHeroDamage: (ctx: RelicHeroDamageContext) => {

            if (!ctx) return

            const pid = _relicResolvePidFromHeroIndex(ctx.hi) | 0

            if (pid <= 0) return



            const dmg = ctx.damage | 0

            if (dmg <= 0) return



            const now = ctx.now | 0

            const shieldNow = _relicUpdateEnergyShield(pid, now) | 0

            if (shieldNow <= 0) return



            const absorbed = Math.min(shieldNow, dmg) | 0

            const remaining = (dmg - absorbed) | 0



            const st = _relicEnsureRuntimeForPid(pid)

            st.energyShieldValue = (shieldNow - absorbed) | 0

            if (st.energyShieldValue < 0) st.energyShieldValue = 0

            if (absorbed > 0) {
                _spawnEnergyShieldFx(ctx.hero, now)
            }

            ctx.damage = remaining

            if (remaining <= 0) ctx.preventDamage = true

        },

    },



    ring_of_fire: {

        effectKey: "ring_of_fire",

        onFloorEnter: (ctx: RelicFloorEnterContext) => {

            if (!ctx) return

            const pid = ctx.pid | 0

            if (pid <= 0) return

            const st = _relicEnsureRuntimeForPid(pid)

            st.ringOfFireReady = true

        },

        afterHeroDamage: (ctx: RelicHeroAfterDamageContext) => {

            if (!ctx) return

            const pid = _relicResolvePidFromHeroIndex(ctx.hi) | 0

            if (pid <= 0) return

            if ((ctx.damageApplied | 0) <= 0) return



            const st = _relicEnsureRuntimeForPid(pid)

            if (!st.ringOfFireReady) return

            st.ringOfFireReady = false



            _relicSpawnRingOfFire(ctx.hi | 0, ctx.hero)

        },

    },



    rainbow_scepter: {

        effectKey: "rainbow_scepter",



        // Tracks committed moves to advance the S?A?I?W sequence.

        onMoveCommitted: (ctx: RelicMoveCommittedContext) => {

            if (!ctx) return

            const pid = _relicResolvePidFromHeroIndex(ctx.hi) | 0

            if (pid <= 0) return



            const st = _relicEnsureRuntimeForPid(pid)

            if (st.rainbowArmed) return // armed until consumed by next move



            const nextStep = _relicRainbowAdvanceStep(st.rainbowStep | 0, ctx.family | 0) | 0

            st.rainbowStep = nextStep

            if ((st.rainbowStep | 0) >= 4) {

                st.rainbowStep = 4

                st.rainbowArmed = true

                console.log("[RELICHOOK][RAINBOW] armed", { pid, hi: ctx.hi | 0 })

            }

        },



        // When armed, multiplies DAMAGE_MULT by 4 on the next move and consumes itself.

        modifyMoveStats: (ctx: RelicModifyMoveStatsContext) => {

            if (!ctx) return

            const pid = _relicResolvePidFromHeroIndex(ctx.hi) | 0

            if (pid <= 0) return



            const st = _relicEnsureRuntimeForPid(pid)

            if (!st.rainbowArmed) return



            try {

                if (ctx.stats && ctx.stats.length > (STAT.DAMAGE_MULT | 0)) {

                    const i = STAT.DAMAGE_MULT | 0

                    const prev = ctx.stats[i] | 0

                    ctx.stats[i] = (prev * 4) | 0

                }

            } catch { }



            st.rainbowArmed = false

            st.rainbowStep = 0

            console.log("[RELICHOOK][RAINBOW] consumed", { pid, hi: ctx.hi | 0 })

        },

    },



    lantern_of_life: {

        effectKey: "lantern_of_life",

        beforeHeroDeath: (ctx: RelicHeroDeathContext) => {

            if (!ctx) return

            const pid = _relicResolvePidFromHeroIndex(ctx.hi) | 0

            if (pid <= 0) return



            const st = _relicEnsureRuntimeForPid(pid)

            if ((st.lanternCharges | 0) <= 0) return



            // Consume charge and prevent death; set HP to half max.

            st.lanternCharges = 0

            ctx.preventDeath = true

            const half = Math.idiv((ctx.maxHp | 0), 2) | 0

            ctx.setHpTo = (half > 0 ? half : 1) | 0

            console.log("[RELICHOOK][LANTERN] prevented death", { pid, hi: ctx.hi | 0, setHpTo: ctx.setHpTo | 0 })

        },

    },

}



// ----------------------------------------------------------

// RELIC DISPATCH (v2.2)

// One loop for all relic calls; engine call-sites stay 1-liners.

// ----------------------------------------------------------



function _relicResolvePidFromHeroIndex(hi: number): number {

    if ((hi | 0) < 0 || (hi | 0) >= heroes.length) return 0

    const hero = heroes[hi]

    if (!hero || (hero.flags & sprites.Flag.Destroyed)) return 0

    try {

        return (sprites.readDataNumber(hero, HERO_DATA.OWNER) | 0) || 0

    } catch {

        return 0

    }

}



function _relicEffectKeyForRelicId(relicId: string): string {

    const def = RELIC_CATALOG[relicId]

    const k = def && def.effectKey ? String(def.effectKey) : String(relicId || "")

    return k

}



function _withHeroRelicHandlers(hi: number, visit: (handler: RelicEffectHandler, relicId: string, effectKey: string) => void): void {

    const pid = _relicResolvePidFromHeroIndex(hi)

    if ((pid | 0) <= 0) return



    const owned = getOwnedRelicIdsForPid(pid)

    if (!owned || owned.length === 0) return



    for (let i = 0; i < owned.length; i++) {

        const relicId = owned[i]

        if (!relicId) continue

        const effectKey = _relicEffectKeyForRelicId(relicId)

        const handler = RELIC_EFFECTS[effectKey]

        if (!handler) continue

        visit(handler, relicId, effectKey)

    }

}







type RelicNextFloorChoiceSession = {

    active: boolean

    activePid: number

    nextFloorIndex: number

    title: string

    options: string[]

    selectedIndex: number

    chosenKind: string

}



const _relicNextFloorChoice: RelicNextFloorChoiceSession = {

    active: false,

    activePid: 0,

    nextFloorIndex: 0,

    title: "Choose Next Floor",

    options: [],

    selectedIndex: 0,

    chosenKind: "",

}

type RelicOfferSession = {
    active: boolean
    activePid: number
    title: string
    flavorText: string
    theme: string
    source: string
    options: string[]
    openedAtMs: number
}

const _relicOfferSession: RelicOfferSession = {
    active: false,
    activePid: 0,
    title: "Choose a Relic",
    flavorText: "",
    theme: "",
    source: "",
    options: [],
    openedAtMs: 0,
}

function _relicOfferClear(reason: string, pidMaybe?: number): void {
    if (!_relicOfferSession.active) return
    if ((pidMaybe | 0) > 0 && (_relicOfferSession.activePid | 0) !== (pidMaybe | 0)) return

    const pid = _relicOfferSession.activePid | 0
    _relicOfferSession.active = false
    _relicOfferSession.activePid = 0
    _relicOfferSession.options = []
    _relicOfferSession.title = "Choose a Relic"
    _relicOfferSession.flavorText = ""
    _relicOfferSession.theme = ""
    _relicOfferSession.source = ""
    _relicOfferSession.openedAtMs = 0

    if (pid > 0) {
        const hi = _relicResolveHeroIndexForPid(pid | 0)
        if (hi >= 0 && hi < heroes.length) {
            const hero = heroes[hi]
            if (hero && !(hero.flags & sprites.Flag.Destroyed)) {
                const uiMode = sprites.readDataNumber(hero, HERO_UI_DATA.MODE) | 0
                if ((uiMode | 0) === (HERO_UI_MODE.RELIC_PICKUP | 0)) {
                    sprites.setDataNumber(hero, HERO_UI_DATA.MODE, HERO_UI_MODE.NONE)
                    sprites.setDataNumber(hero, HERO_UI_DATA.OPENED_AT, 0)
                    unlockHeroControls(hi)
                }
            }
        }
    }

    if (DEBUG_RELIC_LOGS) {
        console.log("[RELIC][OFFER] clear", { reason, pid })
    }
}

function _relicOfferPickRandomOptions(pool: string[], count: number): string[] {
    const work: string[] = []
    for (let i = 0; i < pool.length; i++) {
        const rid = String(pool[i] || "")
        if (rid) work.push(rid)
    }
    const out: string[] = []
    let remaining = Math.min(count | 0, work.length | 0) | 0
    while (remaining > 0 && work.length > 0) {
        // TODO: add weighted rolls per relic/rarity here.
        const idx = randint(0, (work.length - 1) | 0) | 0
        out.push(work[idx])
        work.splice(idx, 1)
        remaining--
    }
    return out
}

type RelicChestOfferConfig = {
    poolIds?: string[]
    fixedRelicId?: string
    minRarity?: string
    maxRarity?: string
    title?: string
    flavorText?: string
    theme?: string
    count?: number
}

function _relicOfferOptionsFromPool(pid: number, pool: string[], count: number, minRarity: string, maxRarity: string): string[] {
    const filtered = _relicFilterIdsByRarity(pool || [], minRarity, maxRarity)
    const available: string[] = []
    for (let i = 0; i < filtered.length; i++) {
        const rid = String(filtered[i] || "")
        if (!rid) continue
        if (_relicHasPid(pid | 0, rid)) continue
        available.push(rid)
    }
    return _relicOfferPickRandomOptions(available, count | 0)
}

function _relicStarterOfferOptions(pid: number, count: number): string[] {
    return _relicOfferOptionsFromPool(pid | 0, _relicStarterOfferPool(), count | 0, "", "")
}

function _relicOfferStart(pid: number, hi: number, options: string[], nowMs: number, title: string, flavorText: string, theme: string, source: string): boolean {
    if (!options || options.length <= 0) return false
    if (_relicOfferSession.active) return false

    const hero = (hi >= 0 && hi < heroes.length) ? heroes[hi] : null
    if (!hero || (hero.flags & sprites.Flag.Destroyed)) return false

    if (DEBUG_RELIC_LOGS) {
        console.log("[RELIC][OFFER] start request", {
            pid: pid | 0,
            hi: hi | 0,
            options: options.slice(0),
            title: title || "",
            theme: theme || "",
            source: source || "",
        })
    }

    _relicOfferSession.active = true
    _relicOfferSession.activePid = pid | 0
    _relicOfferSession.options = options.slice(0, options.length)
    _relicOfferSession.title = String(title || "Choose a Relic")
    _relicOfferSession.flavorText = String(flavorText || "")
    _relicOfferSession.theme = String(theme || "")
    _relicOfferSession.source = String(source || "")
    _relicOfferSession.openedAtMs = nowMs | 0

    sprites.setDataNumber(hero, HERO_UI_DATA.MODE, HERO_UI_MODE.RELIC_PICKUP)
    sprites.setDataNumber(hero, HERO_UI_DATA.SEL, 0)
    sprites.setDataNumber(hero, HERO_UI_DATA.OPENED_AT, nowMs | 0)
    lockHeroControls(hi)

    if (DEBUG_RELIC_LOGS) {
        console.log("[RELIC][OFFER] open", { pid: pid | 0, options: _relicOfferSession.options.slice(0), title: _relicOfferSession.title, theme: _relicOfferSession.theme, source: _relicOfferSession.source })
    }
    return true
}

function _relicOfferStartStarterChoice(pid: number, hi: number, nowMs: number, source: string): boolean {
    const options = _relicStarterOfferOptions(pid | 0, RELIC_STARTER_OFFER_COUNT | 0)
    return _relicOfferStart(pid | 0, hi | 0, options, nowMs | 0, "Choose Your Relic", "Choose one to begin your journey.", "starter", source)
}

function _relicOfferConfigFromChest(chest: Sprite): RelicChestOfferConfig | null {
    if (!chest || (chest.flags & sprites.Flag.Destroyed)) return null
    const poolRaw = sprites.readDataString(chest, INTERACT_DATA.RELIC_POOL)
    const fixed = sprites.readDataString(chest, INTERACT_DATA.RELIC_FIXED)
    const minRarity = sprites.readDataString(chest, INTERACT_DATA.RELIC_MIN_RARITY)
    const maxRarity = sprites.readDataString(chest, INTERACT_DATA.RELIC_MAX_RARITY)
    const title = sprites.readDataString(chest, INTERACT_DATA.RELIC_TITLE)
    const flavorText = sprites.readDataString(chest, INTERACT_DATA.RELIC_FLAVOR)
    const theme = sprites.readDataString(chest, INTERACT_DATA.RELIC_THEME)
    const count = sprites.readDataNumber(chest, INTERACT_DATA.RELIC_COUNT) | 0

    let poolIds: string[] = []
    if (poolRaw) {
        const parts = String(poolRaw || "").split(",")
        for (let i = 0; i < parts.length; i++) {
            const rid = String(parts[i] || "").trim()
            if (rid) poolIds.push(rid)
        }
    }

    if (!fixed && poolIds.length === 0 && !minRarity && !maxRarity && !title && !flavorText && !theme && count <= 0) {
        return null
    }

    return {
        poolIds: poolIds.length ? poolIds : undefined,
        fixedRelicId: fixed || undefined,
        minRarity: minRarity || undefined,
        maxRarity: maxRarity || undefined,
        title: title || undefined,
        flavorText: flavorText || undefined,
        theme: theme || undefined,
        count: count > 0 ? count : undefined,
    }
}

function _relicOfferStartFromChest(pid: number, hi: number, nowMs: number, chest: Sprite, source: string): { ok: boolean, reason: string } {
    const cfg = _relicOfferConfigFromChest(chest)
    if (!cfg) {
        if (DEBUG_RELIC_LOGS) {
            console.log("[RELIC][OFFER] chest config missing", { pid: pid | 0, hi: hi | 0, source })
        }
        return { ok: false, reason: "no-config" }
    }

    const count = (cfg.count != null ? (cfg.count | 0) : (RELIC_STARTER_OFFER_COUNT | 0)) | 0
    const title = String(cfg.title || "Choose a Relic")
    const flavorText = String(cfg.flavorText || "")
    const theme = String(cfg.theme || "")

    let options: string[] = []
    if (cfg.fixedRelicId) {
        const rid = String(cfg.fixedRelicId || "")
        if (rid && !_relicHasPid(pid | 0, rid)) options = [rid]
        else {
            if (DEBUG_RELIC_LOGS) {
                console.log("[RELIC][OFFER] chest fixed relic skipped", { pid: pid | 0, hi: hi | 0, rid, reason: rid ? "owned-fixed" : "bad-fixed" })
            }
            return { ok: false, reason: rid ? "owned-fixed" : "bad-fixed" }
        }
    } else {
        const pool = (cfg.poolIds && cfg.poolIds.length) ? cfg.poolIds : _relicCatalogIds()
        options = _relicOfferOptionsFromPool(pid | 0, pool, count | 0, String(cfg.minRarity || ""), String(cfg.maxRarity || ""))
    }

    if (!options || options.length <= 0) {
        if (DEBUG_RELIC_LOGS) {
            console.log("[RELIC][OFFER] chest had no options", { pid: pid | 0, hi: hi | 0, source, pool: cfg.poolIds, min: cfg.minRarity, max: cfg.maxRarity })
        }
        return { ok: false, reason: "no-options" }
    }

    const started = _relicOfferStart(pid | 0, hi | 0, options, nowMs | 0, title, flavorText, theme, source)
    if (!started) {
        if (DEBUG_RELIC_LOGS) {
            console.log("[RELIC][OFFER] start failed", { pid: pid | 0, hi: hi | 0, source, reason: "start-failed" })
        }
    }
    return { ok: !!started, reason: started ? "started" : "start-failed" }
}

function _relicOfferTryPickIndex(hi: number, pid: number, index: number, where: string): { ok: boolean, reason: string } {
    if (!_relicOfferSession.active) return { ok: false, reason: "no-offer" }
    if ((_relicOfferSession.activePid | 0) !== (pid | 0)) return { ok: false, reason: "not-your-offer" }
    const opts = _relicOfferSession.options || []
    if (opts.length <= 0) return { ok: false, reason: "no-options" }

    let idx = index | 0
    if (idx < 0) idx = 0
    if (idx >= opts.length) idx = (opts.length - 1) | 0
    const relicId = String(opts[idx] || "")
    if (!relicId) return { ok: false, reason: "bad-relic" }
    if (_relicHasPid(pid | 0, relicId)) return { ok: false, reason: "owned" }

    const granted = _relicGrantToPid(pid | 0, relicId, "relic-offer")
    if (!granted) return { ok: false, reason: "grant-failed" }

    _relicOfferClear("picked:" + String(where || ""), pid | 0)
    return { ok: true, reason: "picked" }
}



function relic_cancelNextFloorChoiceIfPending(reason: string): void {

    if (!_relicNextFloorChoice.active) return

    console.log("[RELICHOOK][FLOORCHOICE] cancel", { reason, pid: _relicNextFloorChoice.activePid, next: _relicNextFloorChoice.nextFloorIndex })

    _relicNextFloorChoice.active = false

    _relicNextFloorChoice.activePid = 0

    _relicNextFloorChoice.nextFloorIndex = 0

    _relicNextFloorChoice.options = []

    _relicNextFloorChoice.selectedIndex = 0

    _relicNextFloorChoice.chosenKind = ""

    _relicNextFloorChoice.title = "Choose Next Floor"

}



function _relicResolveHeroIndexForPid(pid: number): number {

    if ((pid | 0) <= 0) return -1

    try {
        const prof = _resolveProfileKeyForPlayerId(pid)
        if (prof) {
            const hi = _resolveHeroIndexForProfile(prof)
            if (hi >= 0) return hi | 0
        }
    } catch { }

    for (let i = 0; i < heroes.length; i++) {

        const h = heroes[i]

        if (!h) continue

        if (h.flags & sprites.Flag.Destroyed) continue

        let owner = 0

        try { owner = sprites.readDataNumber(h, HERO_DATA.OWNER) | 0 } catch { owner = 0 }

        if ((owner | 0) === (pid | 0)) return i | 0

    }



    return -1

}



function _relicAltFloorKind(defaultKind: string, nextFloorIndex: number): string {

    const opts = [DUNGEON_KIND_COMBAT, DUNGEON_KIND_TREASURE, DUNGEON_KIND_STORY, DUNGEON_KIND_SHOP]

    let pick = opts[Math.abs(nextFloorIndex | 0) % opts.length] || DUNGEON_KIND_COMBAT

    if (pick === defaultKind) {

        pick = opts[(Math.abs((nextFloorIndex | 0) + 1) % opts.length)] || DUNGEON_KIND_COMBAT

        if (pick === defaultKind) pick = DUNGEON_KIND_COMBAT

    }

    return String(pick || defaultKind || "")

}



function _relicNormalizeTwoUniqueKinds(defaultKind: string, options: string[]): string[] {

    const out: string[] = []

    const seen: any = {}



    const push = (k: string) => {

        const kk = String(k || "")

        if (!kk) return

        if (seen[kk]) return

        seen[kk] = 1

        out.push(kk)

    }



    // Prefer provided order, but guarantee defaultKind is included if possible

    for (let i = 0; i < options.length; i++) push(options[i])



    if (!seen[String(defaultKind || "")]) push(String(defaultKind || ""))



    // Ensure length >= 2

    if (out.length < 2) push(_relicAltFloorKind(String(defaultKind || ""), (_relicNextFloorChoice.nextFloorIndex | 0) || 0))



    // Truncate to 2 (UI spec: show two possibilities)

    return out.slice(0, 2)

}



/**

 * Called from teleport-commit.

 * - If a relic wants to take over next-floor choice: opens a session and returns {hold:true}.

 * - While session active and no choice made: returns {hold:true}.

 * - Once chosen: returns {hold:false, kind:<chosen>} and clears session.

 */

function relic_resolveNextFloorKindOrHold(

    now: number,

    nextFloorIndex: number,

    defaultKind: string,

    readyMask: number

): { hold: boolean, kind: string } {



    // Existing session for this next floor: hold until chosen.

    if (_relicNextFloorChoice.active && (_relicNextFloorChoice.nextFloorIndex | 0) === (nextFloorIndex | 0)) {

        if (_relicNextFloorChoice.chosenKind) {

            const chosen = String(_relicNextFloorChoice.chosenKind || defaultKind || "")

            console.log("[RELICHOOK][FLOORCHOICE] chosen -> proceed", { pid: _relicNextFloorChoice.activePid, next: nextFloorIndex, chosen })

            relic_cancelNextFloorChoiceIfPending("chosen")

            return { hold: false, kind: chosen }

        }

        return { hold: true, kind: String(defaultKind || "") }

    }



    // If session is for a different nextFloorIndex, clear it.

    if (_relicNextFloorChoice.active && (_relicNextFloorChoice.nextFloorIndex | 0) !== (nextFloorIndex | 0)) {

        relic_cancelNextFloorChoiceIfPending("stale-next-index")

    }



    // Try to open a session: first eligible pid in readyMask who has a relic that requests takeover.

    const baseOptions = [String(defaultKind || ""), _relicAltFloorKind(String(defaultKind || ""), nextFloorIndex | 0)]



    for (let hi = 0; hi < heroes.length; hi++) {
        const bit = (hi >= 0 && hi < 31) ? (1 << hi) : 0
        if (bit === 0) continue
        if (((readyMask | 0) & bit) === 0) continue

        const hero = heroes[hi]
        if (!hero || (hero.flags & sprites.Flag.Destroyed)) continue
        const pid = sprites.readDataNumber(hero, HERO_DATA.OWNER) | 0
        if (pid <= 0) continue



        const ctx: RelicChooseNextFloorContext = {

            now: now | 0,

            pid: pid | 0,

            hi: hi | 0,

            hero,

            nextFloorIndex: nextFloorIndex | 0,

            defaultKind: String(defaultKind || ""),

            options: baseOptions.slice(),

            requestChoice: false,

            title: "Choose Next Floor",

        }



        // Dispatch to this hero's relics; any one may request takeover.

        _withHeroRelicHandlers(hi, (handler) => {

            if (ctx.requestChoice) return

            if (handler.chooseNextFloor) handler.chooseNextFloor(ctx)

        })



        if (ctx.requestChoice) {

            const two = _relicNormalizeTwoUniqueKinds(ctx.defaultKind, ctx.options)



            _relicNextFloorChoice.active = true

            _relicNextFloorChoice.activePid = pid | 0

            _relicNextFloorChoice.nextFloorIndex = nextFloorIndex | 0

            _relicNextFloorChoice.title = String(ctx.title || "Choose Next Floor")

            _relicNextFloorChoice.options = two

            _relicNextFloorChoice.selectedIndex = 0

            _relicNextFloorChoice.chosenKind = ""



            console.log("[RELICHOOK][FLOORCHOICE] opened", {

                pid,

                next: nextFloorIndex,

                defaultKind,

                options: two

            })



            return { hold: true, kind: String(defaultKind || "") }

        }

    }



    // No relic requested takeover

    return { hold: false, kind: String(defaultKind || "") }

}





